Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
    if (kIsWeb) {
      await FirebaseAuth.instance.setPersistence(Persistence.LOCAL);
    } else {
      unawaited(
        RewardedAdsService.initialize().catchError(
          (Object error, StackTrace stackTrace) {
            debugPrint('No se pudo inicializar AdMob: $error');
            debugPrintStack(stackTrace: stackTrace);
          },
        ),
      );
    }
    runApp(const WolvesClubApp());
  } on FirebaseException catch (error, stackTrace) {
    debugPrint(
        'No se pudo inicializar Firebase: ${error.code} ${error.message}');
    debugPrintStack(stackTrace: stackTrace);
    runApp(FirebaseStartupFailure(message: error.message ?? error.code));
  } on UnsupportedError catch (error, stackTrace) {
    debugPrint('Plataforma sin configuración de Firebase: $error');
    debugPrintStack(stackTrace: stackTrace);
    runApp(FirebaseStartupFailure(message: error.message ?? error.toString()));
  } catch (error, stackTrace) {
    debugPrint('Error inesperado al inicializar Firebase: $error');
    debugPrintStack(stackTrace: stackTrace);
    runApp(FirebaseStartupFailure(message: error.toString()));
  }
}

class FirebaseStartupFailure extends StatelessWidget {
  const FirebaseStartupFailure({super.key, required this.message});

  final String message;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        backgroundColor: const Color(0xFF171411),
        body: SafeArea(
          child: Center(
            child: Padding(
              padding: const EdgeInsets.all(28),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Icon(
                    Icons.cloud_off_outlined,
                    color: Color(0xFFC6A06A),
                    size: 44,
                  ),
                  const SizedBox(height: 18),
                  const Text(
                    'No se pudo iniciar Coffee Wolves',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: Color(0xFFC6A574),
                      fontSize: 20,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 10),
                  const Text(
                    'Firebase no está disponible para esta configuración. '
                    'Verifica firebase_options.dart y vuelve a cargar la app.',
                    textAlign: TextAlign.center,
                    style: TextStyle(color: Color(0xFFB7AA9D)),
                  ),
                  const SizedBox(height: 14),
                  SelectableText(
                    message,
                    textAlign: TextAlign.center,
                    style: const TextStyle(
                      color: Color(0xFFB7AA9D),
                      fontSize: 12,
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

