    );
  }
}

class _SocialTexturePainter extends CustomPainter {
  const _SocialTexturePainter();

  @override
  void paint(Canvas canvas, Size size) {
    final line = Paint()
      ..color = const Color(0xFFB49A70).withValues(alpha: 0.055)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 0.7;
    for (var index = -size.height; index < size.width; index += 18) {
      canvas.drawLine(
        Offset(index.toDouble(), 0),
        Offset(index + size.height, size.height),
        line,
      );
    }
    final glow = Paint()
      ..shader = RadialGradient(
        colors: [
          const Color(0xFFB49A70).withValues(alpha: 0.07),
          const Color(0xFFB49A70).withValues(alpha: 0),
        ],
      ).createShader(
        Rect.fromCircle(
          center: Offset(size.width / 2, size.height / 2),
          radius: size.width * 0.55,
        ),
      );
    canvas.drawRect(Offset.zero & size, glow);
  }

  @override
  bool shouldRepaint(covariant _SocialTexturePainter oldDelegate) => false;
}

