String _normalizeCafeLabel(String value) => value
    .toLowerCase()
    .replaceAll('á', 'a')
    .replaceAll('é', 'e')
    .replaceAll('í', 'i')
    .replaceAll('ó', 'o')
    .replaceAll('ú', 'u')
    .replaceAll('ü', 'u')
    .replaceAll('ñ', 'n')
    .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
    .trim();

String _cafeFamilyIdentity(String value) {
  final normalized = _normalizeCafeLabel(value);
  if (const {
    'speciality coffee',
    'specialty coffee',
    'speciality coffees',
    'specialty coffees',
    'brewing',
  }.contains(normalized)) {
    return 'speciality-coffee';
  }
  return normalized.replaceAll(' ', '-');
}

String _staffShiftLabel(String? shift) => switch (shift) {
      'morning' => 'Mañana',
      'afternoon' => 'Tarde',
      'night' => 'Noche',
      _ => 'Sin turno',
    };

String _canonicalCafeCategory(
  String category,
  String name, [
  String description = '',
]) {
  final rawCategory = _normalizeCafeLabel(category);
  final productText = _normalizeCafeLabel('$name $description');
  if (rawCategory == 'tazas coleccionables') return 'TAZAS COLECCIONABLES';
  if (rawCategory == 'brewing' ||
      rawCategory.startsWith('speciality') ||
      rawCategory.startsWith('specialty')) {
    return 'SPECIALITY COFFEE';
  }
  if (rawCategory.startsWith('presur') || rawCategory.startsWith('pressur')) {
    return 'PRESURIZADOS Y DESTILADOS';
  }
  if (rawCategory == 'cafe y calientes' || rawCategory == 'hot drinks') {
    return 'HOT DRINKS';
  }
  if (rawCategory == 'matcha' || rawCategory == 'ice matcha') {
    return 'ICE MATCHA';
  }
  if (rawCategory == 'panaderia' || rawCategory == 'bakery') return 'BAKERY';
  if (rawCategory == 'desayuno' || rawCategory == 'breakfast') {
    return 'BREAKFAST';
  }
  if (rawCategory == 'pet friendly') return 'PET FRIENDLY';
  if (rawCategory == 'combos' || rawCategory == 'combos packs') {
    return 'COMBOS PACKS';
  }
  if (rawCategory == 'ensaladas' ||
      rawCategory == 'vegetable salad' ||
      rawCategory == 'fruit salad') {
    final fruitProducts = RegExp(
      r'\b(exotic wolves|yogufruit|fruit pump|fruit waffle|parfait|morango do amor)\b',
    );
    return fruitProducts.hasMatch(productText) || rawCategory == 'fruit salad'
        ? 'FRUIT SALAD'
        : 'VEGETABLE SALAD';
  }
  if (rawCategory == 'packs dulces' || rawCategory == 'crumbles') {
    return productText.contains('crumble') ? 'CRUMBLES' : 'DESSERTS';
  }
  if (rawCategory == 'postres' ||
      rawCategory == 'tortas grandes' ||
      rawCategory == 'desserts') {
    return productText.contains('crumble') ? 'CRUMBLES' : 'DESSERTS';
  }
  if (rawCategory == 'helados' || rawCategory == 'ice cream fruit') {
    return 'ICE CREAM FRUIT';
  }
  if (rawCategory == 'bebidas' || rawCategory == 'beverages') {
    return 'BEVERAGES';
  }
  if (rawCategory == 'milkshakes' ||
      productText.contains('milkshake') ||
      productText.contains('frappe')) {
    return 'MILKSHAKES';
  }
  if (rawCategory == 'smoothie with milk' ||
      (productText.contains('smoothie') && productText.contains('milk'))) {
    return 'SMOOTHIE WITH MILK';
  }
  if (rawCategory == 'smoothie with water' ||
      (productText.contains('smoothie') && productText.contains('water'))) {
    return 'SMOOTHIE WITH WATER';
  }
  if (rawCategory == 'fríos y frappés' ||
      rawCategory == 'frios y frappes' ||
      rawCategory == 'ice') {
    if (productText.contains('ice cream') || productText.contains('affogato')) {
      return 'ICE CREAM FRUIT';
    }
    if (productText.contains('sultana')) return 'BEVERAGES';
    return 'ICE';
  }
  if (rawCategory == 'bebidas' || rawCategory == 'beverages') {
    return 'BEVERAGES';
  }
  return category.toUpperCase();
}

String _inventoryFamilyLabel(String category) {
  final key = _normalizeCafeLabel(category).replaceAll(' ', '_');
  if (const {
    'bebida',
    'bebidas',
    'comida',
    'food',
    'beverage',
    'beverages',
    'smoothies',
    'combos_pack',
    'combos_packs',
    'pet_friendly',
  }.contains(key)) {
    return 'DISPONIBILIDAD DEL MENÚ';
  }
  if (const {
    'moda_alfa',
    'accesorios',
    'merch',
    'estilo_de_vida',
    'tazas_coleccionables',
  }.contains(key)) {
    return 'WOLVES SHOP';
  }
  return key.replaceAll('_', ' ').toUpperCase();
}

bool _isMerchInventoryCategory(String category) {
  final key = _normalizeCafeLabel(category).replaceAll(' ', '_');
  return wolvesShopProductCategories.contains(key);
}

String _shopCategoryLabel(String category) => switch (category) {
      'moda_alfa' => 'Moda Alfa',
