enum ShopItemStatus {
  available('Disponible'),
  soldOut('Agotado'),
  comingSoon('Próximamente');

  const ShopItemStatus(this.label);

  final String label;
}

class ShopVariant {
  ShopVariant({
    required this.size,
    required int stock,
  }) : _stock = stock < 0 ? 0 : stock;

  final String size;
  int _stock;
  ShopItemStatus _status = ShopItemStatus.available;

  int get stock => _stock;

  set stock(int value) {
    _stock = value < 0 ? 0 : value;
    if (_stock == 0) {
      _status = ShopItemStatus.soldOut;
    } else if (_status == ShopItemStatus.soldOut) {
      _status = ShopItemStatus.available;
    }
  }

  ShopItemStatus get status => _stock == 0 ? ShopItemStatus.soldOut : _status;

  set status(ShopItemStatus value) {
    _status = _stock == 0 && value == ShopItemStatus.available
        ? ShopItemStatus.soldOut
        : value;
  }
}

class ShopProduct {
  ShopProduct({
    required this.id,
    required this.category,
    required this.name,
    required this.description,
    required this.icon,
    required this.price,
    required int stock,
    Map<String, int> sizes = const {},
    this.sku = '',
    this.imageAsset,
    this.imageUrl,
    this.status = ShopItemStatus.available,
  })  : _stock = stock < 0 ? 0 : stock,
        variants = {
          for (final entry in sizes.entries)
            entry.key: ShopVariant(size: entry.key, stock: entry.value),
        };

  final String id;
  String category;
  String name;
  String description;
  String sku;
  IconData icon;
  double price;
  final String? imageAsset;
  String? imageUrl;
  final Map<String, ShopVariant> variants;
  int _stock;
  ShopItemStatus status;

  bool get hasSizes => variants.isNotEmpty;

  int get stock => hasSizes
      ? variants.values.fold(0, (total, variant) => total + variant.stock)
      : _stock;

  set stock(int value) {
    final normalized = value < 0 ? 0 : value;
    if (hasSizes) {
      for (final variant in variants.values) {
        variant.stock = normalized;
      }
    } else {
      _stock = normalized;
      if (_stock == 0) {
        status = ShopItemStatus.soldOut;
      } else if (status == ShopItemStatus.soldOut) {
        status = ShopItemStatus.available;
      }
    }
  }

  ShopItemStatus get effectiveStatus {
    if (hasSizes) {
      if (variants.values.every(
        (variant) => variant.status == ShopItemStatus.soldOut,
      )) {
        return ShopItemStatus.soldOut;
      }
      if (variants.values.any(
        (variant) => variant.status == ShopItemStatus.available,
      )) {
        return ShopItemStatus.available;
      }
      return ShopItemStatus.comingSoon;
    }
    if (_stock == 0) return ShopItemStatus.soldOut;
    return status;
  }
}

