/// Una pieza registrada en la bitácora personal de un miembro.
///
/// Los datos de autenticidad vienen del inventario oficial; el miembro solo
/// puede personalizar el apodo, las notas y el estado de favorito.
class Coleccionable {
  const Coleccionable({
    required this.code,
    required this.modelCode,
    required this.character,
    required this.serial,
    required this.edition,
    this.adoptedAt,
    this.nickname = '',
    this.notes = '',
    this.isFavorite = false,
    this.isInBitacora = false,
  });

  final String code;
  final String modelCode;
  final String character;
  final String serial;
  final String edition;
  final DateTime? adoptedAt;
  final String nickname;
  final String notes;
  final bool isFavorite;
  final bool isInBitacora;

  factory Coleccionable.fromMap(
    String code,
    Map<String, dynamic> data, {
    bool isInBitacora = false,
  }) {
    final rawSerial = data['serial'];
    final serial = rawSerial is int
        ? rawSerial.toString().padLeft(4, '0')
        : rawSerial is String
            ? rawSerial
            : '';
    final rawAdoptedAt = data['claimedAt'] ?? data['adoptedAt'];
    final adoptedAt = rawAdoptedAt is Timestamp
        ? rawAdoptedAt.toDate()
        : rawAdoptedAt is DateTime
            ? rawAdoptedAt
            : null;

    return Coleccionable(
      code: code,
      modelCode: data['modelCode'] as String? ?? '',
      character: data['character'] as String? ?? 'Peluche Wolves',
      serial: serial,
      edition: data['edition'] as String? ?? 'Original Collection',
      adoptedAt: adoptedAt,
      nickname: data['nickname'] as String? ?? '',
      notes: data['notes'] as String? ?? '',
      isFavorite: data['isFavorite'] as bool? ?? false,
      isInBitacora: isInBitacora,
    );
  }

  /// Serializa los datos de identidad junto con las anotaciones personales.
  Map<String, dynamic> toMap() => {
        'code': code,
        'modelCode': modelCode,
        'character': character,
        'serial': serial,
        'edition': edition,
        if (adoptedAt != null) 'adoptedAt': Timestamp.fromDate(adoptedAt!),
        'nickname': nickname,
        'notes': notes,
        'isFavorite': isFavorite,
      };

  Map<String, dynamic> toPersonalMap() => {
        'nickname': nickname.trim(),
        'notes': notes.trim(),
        'isFavorite': isFavorite,
      };

  Coleccionable copyWith({
    String? nickname,
    String? notes,
    bool? isFavorite,
    bool? isInBitacora,
  }) {
    return Coleccionable(
      code: code,
      modelCode: modelCode,
      character: character,
      serial: serial,
      edition: edition,
      adoptedAt: adoptedAt,
      nickname: nickname ?? this.nickname,
      notes: notes ?? this.notes,
      isFavorite: isFavorite ?? this.isFavorite,
      isInBitacora: isInBitacora ?? this.isInBitacora,
    );
  }
}

/// Bitácora inmutable: sus operaciones devuelven una nueva instancia.
class Bitacora {
  Bitacora({
    required this.ownerUid,
    List<Coleccionable> coleccionables = const [],
    DateTime? updatedAt,
  })  : coleccionables = List.unmodifiable(coleccionables),
        updatedAt = updatedAt ?? DateTime.now();

  final String ownerUid;
  final List<Coleccionable> coleccionables;
  final DateTime updatedAt;

  Map<String, dynamic> toMap() => {
        'ownerUid': ownerUid,
        'coleccionables':
            coleccionables.map((item) => item.toMap()).toList(growable: false),
        'updatedAt': Timestamp.fromDate(updatedAt),
      };

  Bitacora copyWith({
    List<Coleccionable>? coleccionables,
    DateTime? updatedAt,
  }) {
    return Bitacora(
      ownerUid: ownerUid,
      coleccionables: coleccionables ?? this.coleccionables,
      updatedAt: updatedAt ?? this.updatedAt,
    );
  }

  Bitacora agregarColeccionable(Coleccionable coleccionable) {
    if (coleccionables.any((item) => item.code == coleccionable.code)) {
      throw StateError('El coleccionable ya está en la bitácora.');
    }
    return copyWith(
      coleccionables: [...coleccionables, coleccionable],
      updatedAt: DateTime.now(),
    );
  }

  Bitacora actualizarColeccionable(Coleccionable coleccionable) {
    final index =
        coleccionables.indexWhere((item) => item.code == coleccionable.code);
    if (index < 0) {
      throw StateError('No se encontró el coleccionable en la bitácora.');
    }
    final updated = [...coleccionables]..[index] = coleccionable;
    return copyWith(coleccionables: updated, updatedAt: DateTime.now());
  }
}

/// Lee la propiedad desde el registro oficial y guarda solo metadatos privados.
///
/// Así, agregar algo a la bitácora nunca concede ni transfiere la propiedad de
/// una pieza: Firestore comprueba que el usuario ya sea su titular.
class BitacoraService {
  BitacoraService(this._firestore);

  final FirebaseFirestore _firestore;

  CollectionReference<Map<String, dynamic>> _ownedCollection() =>
      _firestore.collection('collectiblePlushes');

  CollectionReference<Map<String, dynamic>> _personalCollection(String uid) =>
      _firestore.collection('users').doc(uid).collection('bitacora');

  Stream<Bitacora> watchForOwner(String uid) {
    _requireAccount(uid);
    return Stream<Bitacora>.multi(
      (controller) {
        QuerySnapshot<Map<String, dynamic>>? ownedSnapshot;
        QuerySnapshot<Map<String, dynamic>>? personalSnapshot;

        void publishWhenReady() {
          if (controller.isClosed ||
              ownedSnapshot == null ||
              personalSnapshot == null) {
            return;
          }
          final personalByCode = {
            for (final document in personalSnapshot!.docs)
              document.id: document.data(),
          };
          final collectibles = ownedSnapshot!.docs.map((document) {
            final personalData = personalByCode[document.id];
            return Coleccionable.fromMap(
              document.id,
              {
                ...document.data(),
                if (personalData != null) ...personalData,
              },
              isInBitacora: personalData != null,
            );
          }).toList()
            ..sort((first, second) {
              final firstAdoptedAt =
                  first.adoptedAt ?? DateTime.fromMillisecondsSinceEpoch(0);
              final secondAdoptedAt =
                  second.adoptedAt ?? DateTime.fromMillisecondsSinceEpoch(0);
              return secondAdoptedAt.compareTo(firstAdoptedAt);
            });
          controller.add(Bitacora(ownerUid: uid, coleccionables: collectibles));
        }

        final ownedSubscription = _ownedCollection()
            .where('claimedBy', isEqualTo: uid)
            .snapshots()
            .listen(
          (snapshot) {
            ownedSnapshot = snapshot;
            publishWhenReady();
          },
          onError: controller.addError,
        );
        final personalSubscription =
            _personalCollection(uid).snapshots().listen(
          (snapshot) {
            personalSnapshot = snapshot;
            publishWhenReady();
          },
          onError: controller.addError,
        );
        controller.onCancel = () async {
          await ownedSubscription.cancel();
          await personalSubscription.cancel();
        };
      },
      isBroadcast: true,
    );
  }

  Future<Bitacora> listarColeccionables(String uid) async {
    _requireAccount(uid);
    final owned =
        await _ownedCollection().where('claimedBy', isEqualTo: uid).get();
    final personal = await _personalCollection(uid).get();
    final personalByCode = {
      for (final document in personal.docs) document.id: document.data(),
    };
    final collectibles = owned.docs.map((document) {
      final personalData = personalByCode[document.id];
      return Coleccionable.fromMap(
        document.id,
        {
          ...document.data(),
          if (personalData != null) ...personalData,
        },
        isInBitacora: personalData != null,
      );
    }).toList()
      ..sort((first, second) {
        final firstAdoptedAt =
            first.adoptedAt ?? DateTime.fromMillisecondsSinceEpoch(0);
        final secondAdoptedAt =
            second.adoptedAt ?? DateTime.fromMillisecondsSinceEpoch(0);
        return secondAdoptedAt.compareTo(firstAdoptedAt);
      });
    return Bitacora(ownerUid: uid, coleccionables: collectibles);
  }

  Future<void> agregarColeccionable(
    String uid,
    Coleccionable coleccionable,
  ) async {
    _requireOwner(uid);
    _validatePersonalData(coleccionable);
    final collectibleRef = _ownedCollection().doc(coleccionable.code);
    final personalRef = _personalCollection(uid).doc(coleccionable.code);
    await _firestore.runTransaction((transaction) async {
      final collectible = await transaction.get(collectibleRef);
      final personal = await transaction.get(personalRef);
      if (!collectible.exists || collectible.data()?['claimedBy'] != uid) {
        throw StateError('Solo puedes agregar piezas de tu propiedad.');
      }
      if (personal.exists) {
        throw StateError('El coleccionable ya está agregado a tu bitácora.');
      }
      transaction.set(personalRef, {
        ...coleccionable.toPersonalMap(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
    });
  }

  Future<void> actualizarColeccionable(
    String uid,
    Coleccionable coleccionable,
  ) async {
    _requireOwner(uid);
    _validatePersonalData(coleccionable);
    final collectibleRef = _ownedCollection().doc(coleccionable.code);
    final personalRef = _personalCollection(uid).doc(coleccionable.code);
    await _firestore.runTransaction((transaction) async {
      final collectible = await transaction.get(collectibleRef);
      final personal = await transaction.get(personalRef);
      if (!collectible.exists || collectible.data()?['claimedBy'] != uid) {
        throw StateError('Ya no eres titular de este coleccionable.');
      }
      if (!personal.exists) {
        throw StateError('Agrega el coleccionable antes de actualizarlo.');
      }
      transaction.update(personalRef, {
        ...coleccionable.toPersonalMap(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
    });
  }

  void _requireOwner(String uid) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || user.isAnonymous || user.uid != uid) {
      throw StateError('Inicia sesión con la cuenta propietaria.');
    }
  }

  void _requireAccount(String uid) {
    if (FirebaseAuth.instance.currentUser?.uid != uid) {
      throw StateError('La bitácora solo está disponible para esta cuenta.');
    }
  }

  void _validatePersonalData(Coleccionable coleccionable) {
    if (coleccionable.nickname.trim().length > 40 ||
        coleccionable.notes.trim().length > 500) {
      throw ArgumentError(
        'El apodo admite hasta 40 caracteres y las notas hasta 500.',
      );
    }
  }
}

