class _OfficialCafeProduct {
  const _OfficialCafeProduct(
    this.name,
    this.category,
    this.price,
    this.description,
  );

  final String name;
  final String category;
  final double? price;
  final String description;
}

const _officialCafeProductAliases = <String, List<String>>{
  'Ristreto': ['Ristretto'],
  'Doble Macchiato': ['Macchiato Doble'],
  'Café Cortado': ['Cortado'],
  'Doble Americano': ['Americano Doble'],
  'Caramel Latte': ['Latte Caramelizado'],
  'Bombon Coffee': ['Bombón Coffee'],
  'Bomb Cake (10 Personas)': ['Bomb Cake (10 porciones)'],
  'Tiramisu (20 Porciones)': ['Tiramisú (20 porciones)'],
  'Sandwich Francés': ['Sandwich Frances'],
};

String _normalizeCafeProductName(String name) => name
    .toLowerCase()
    .replaceAll('á', 'a')
    .replaceAll('é', 'e')
    .replaceAll('í', 'i')
    .replaceAll('ó', 'o')
    .replaceAll('ú', 'u')
    .replaceAll('ü', 'u')
    .replaceAll('ñ', 'n')
    .replaceAll(RegExp(r'[^a-z0-9]'), '');

_OfficialCafeProduct? _officialCafeProductForName(String name) {
  final normalizedName = _normalizeCafeProductName(name);
  for (final product in _officialCafeProducts) {
    if (_normalizeCafeProductName(product.name) == normalizedName ||
        (_officialCafeProductAliases[product.name] ?? const []).any(
            (alias) => _normalizeCafeProductName(alias) == normalizedName)) {
      return product;
    }
  }
  return null;
}

double? _knownCafeMenuPrice(String name, {String? productId}) {
  final officialPrice = _officialCafeProductForName(name)?.price;
  if (officialPrice != null && officialPrice > 0) return officialPrice;

  final normalizedName = _normalizeCafeProductName(name);
  for (final product in _defaultCafeMenuItems) {
    if ((productId != null && product.id == productId) ||
        _normalizeCafeProductName(product.name) == normalizedName) {
      if (product.price > 0) return product.price;
    }
  }

  if (normalizedName == _normalizeCafeProductName('Latte Mint')) {
    for (final product in _defaultCafeMenuItems) {
      if (_normalizeCafeProductName(product.name) ==
          _normalizeCafeProductName('Mint Latte')) {
        if (product.price > 0) return product.price;
      }
    }
  }
  return null;
}

Uint8List _compressCafeImageBytes(Uint8List sourceBytes) {
  final decoded = image_codec.decodeImage(sourceBytes);
  if (decoded == null) {
    throw const FormatException('El archivo seleccionado no es una imagen.');
  }
  final scale = min(1.0, min(1000 / decoded.width, 1000 / decoded.height));
  final resized = image_codec.copyResize(
    decoded,
    width: max(1, (decoded.width * scale).round()),
    height: max(1, (decoded.height * scale).round()),
  );
  for (final quality in [78, 68, 58, 48, 38]) {
    final jpegBytes = image_codec.encodeJpg(resized, quality: quality);
    if (jpegBytes.length <= 500000) {
      return Uint8List.fromList(jpegBytes);
    }
  }
  throw ArgumentError(
    'La imagen no se puede comprimir al límite permitido de 500 KB.',
  );
}

Uint8List _compressSupportScreenshotBytes(Uint8List sourceBytes) {
  final decoded = image_codec.decodeImage(sourceBytes);
  if (decoded == null) {
    throw const FormatException('El archivo seleccionado no es una imagen.');
  }
  final scale = min(1.0, min(1200 / decoded.width, 1200 / decoded.height));
  final resized = image_codec.copyResize(
    decoded,
    width: max(1, (decoded.width * scale).round()),
    height: max(1, (decoded.height * scale).round()),
  );
  for (final quality in [76, 64, 52, 40, 30]) {
    final jpegBytes = image_codec.encodeJpg(resized, quality: quality);
    if (jpegBytes.length <= 400000) return Uint8List.fromList(jpegBytes);
  }
  throw ArgumentError(
    'La captura es demasiado grande incluso después de optimizarla.',
  );
}

