  String get _currentLevel {
    if (xp >= 1000) return 'Legendary Wolf';
    if (xp >= 750) return 'Pet Lover';
    if (xp >= 500) return 'Coffee Lover';
    return 'New Wolf';
  }

  int get _levelStartXp {
    if (xp >= 750) return 750;
    if (xp >= 500) return 500;
    return 0;
  }

  int get _levelEndXp {
    if (xp >= 1000) return 1000;
    if (xp >= 750) return 1000;
    if (xp >= 500) return 750;
    return 500;
  }

  double get _levelProgress {
    final levelSpan = _levelEndXp - _levelStartXp;
    if (levelSpan <= 0) return 1;
    return ((xp - _levelStartXp) / levelSpan).clamp(0.0, 1.0).toDouble();
  }

