  @override
  void initState() {
    super.initState();
    final authenticityCode = Uri.base.queryParameters['authenticity'];
    if (authenticityCode != null &&
        isValidCollectibleModelUnit(authenticityCode.toUpperCase())) {
      _publicAuthenticityCode = authenticityCode.toUpperCase();
      page = 'plushAuthenticity';
    }
    _applyOfficialCafeCatalogUpdates();
    if (kDebugMode) _seedDemoCollectibles();
    _menuSearchController = TextEditingController();
    _chatMessageController = TextEditingController();
    _posSearchController = TextEditingController();
    _posPaymentReceivedController = TextEditingController();
    _posCustomerUidController = TextEditingController();
    _passportCustomerUidController = TextEditingController();
    for (final method in methods) {
      _passportTastingNoteControllers[method.name] = TextEditingController();
    }
    _rewardAuditService = RewardAuditService(FirebaseFirestore.instance);
    _businessOperationsService =
        BusinessOperationsService(FirebaseFirestore.instance);
    _memberCardService = MemberCardService(FirebaseFirestore.instance);
    _productCatalogService = ProductCatalogService(FirebaseFirestore.instance);
    _bitacoraService = BitacoraService(FirebaseFirestore.instance);
    _orderNotificationService =
        OrderNotificationService(FirebaseFirestore.instance);
    _paymentApiService = PaymentApiService(auth: FirebaseAuth.instance);
    _chatCreditService = ChatCreditService();
    _authStateStream = FirebaseAuth.instance.authStateChanges();
    _authSubscription = _authStateStream.listen(
      (user) => unawaited(_handleAuthState(user)),
      onError: (Object error, StackTrace stackTrace) {
        debugPrint('No se pudo observar la sesión de Firebase: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (!mounted) return;
        setState(() {
          _authStateReady = true;
          _authStateError = error;
        });
      },
    );
    unawaited(_initializeRemoteConfig());
    _splashController = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 5),
    );
    const startOffsets = [
      Offset(-0.62, -0.34),
      Offset(0.62, -0.34),
      Offset(-0.70, 0.05),
      Offset(0.70, 0.05),
      Offset(-0.52, 0.48),
      Offset(0.52, 0.48),
    ];
    _wolfMotions = List.generate(6, (index) {
      final runIn = CurvedAnimation(
        parent: _splashController,
        curve: const Interval(0, 0.68, curve: Curves.easeOutCubic),
      );
      final angle = -pi / 2 + index * pi / 3;
      return Tween<Offset>(
        begin: startOffsets[index],
        end: Offset(cos(angle) * 0.31, sin(angle) * 0.23),
      ).animate(runIn);
    }, growable: false);
    _splashLogoFade = CurvedAnimation(
      parent: _splashController,
      curve: const Interval(0.48, 0.67, curve: Curves.easeIn),
    );
    _splashLogoScale = Tween<double>(begin: 0.78, end: 1).animate(
      CurvedAnimation(
        parent: _splashController,
        curve: const Interval(0.48, 0.70, curve: Curves.easeOutBack),
      ),
    );
    _splashController.addStatusListener((status) {
      if (status == AnimationStatus.completed && mounted && page == 'splash') {
        go(_isStaffRole
            ? 'pos'
            : _userRole == 'admin'
                ? 'admin'
                : 'home');
      }
    });
    _inactivityTimer = Timer.periodic(
      const Duration(minutes: 1),
      (_) => _checkInactivityReminder(),
    );
  }

  @override
  void dispose() {
    _menuSearchController.dispose();
    _chatMessageController.dispose();
    _posSearchController.dispose();
    _posPaymentReceivedController.dispose();
    _posCustomerUidController.dispose();
    _passportCustomerUidController.dispose();
    for (final controller in _passportTastingNoteControllers.values) {
      controller.dispose();
    }
    unawaited(_cafeCatalogSubscription?.cancel());
    unawaited(_cafeOrdersSubscription?.cancel());
    unawaited(_passportProgressSubscription?.cancel());
    unawaited(_authSubscription?.cancel());
    unawaited(_orderNotificationService.dispose());
    _remoteConfigRefreshTimer?.cancel();
    _baristaQrTimer?.cancel();
    _inactivityTimer?.cancel();
    _adminFinanceTimeout?.cancel();
    _paymentGeneration++;
    unawaited(_cafeFamiliesSubscription?.cancel());
    _paymentApiService.close();
    _splashController.dispose();
    unawaited(_musicPlayer.dispose());
    super.dispose();
  }

  Future<void> _startSplashSequence() async {
    if (!widget.enableMusic || !_musicPlayer.isSupported) {
      _splashController.duration = _minimumSplashDuration;
      setState(() => _splashNeedsGesture = false);
      _splashController.forward();
      return;
    }
    if (_splashAudioStarting || _splashController.isAnimating) return;
    setState(() {
      _splashAudioStarting = true;
      _splashNeedsGesture = false;
    });
    _splashController.duration = _minimumSplashDuration;
    _splashController.forward();
    try {
      await _musicPlayer.playHowl();
    } catch (error, stackTrace) {
      debugPrint('No se pudo iniciar el aullido de la Splash Screen: $error');
      debugPrintStack(stackTrace: stackTrace);
    } finally {
      if (mounted) {
        setState(() => _splashAudioStarting = false);
      }
    }
  }

  Future<void> _playMusic() async {
    if (_musicStarting ||
        _musicPlaying ||
        !widget.enableMusic ||
        !_musicPlayer.isSupported) {
      return;
    }
    _musicStarting = true;
    try {
      await _musicPlayer.play();
      if (mounted) {
        setState(() {
          _musicEnabled = true;
          _musicPlaying = true;
        });
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo reproducir la música de Coffee Wolves: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        setState(() {
          _musicEnabled = false;
          _musicPlaying = false;
        });
        _scaffoldMessengerKey.currentState?.showSnackBar(
          const SnackBar(
            content: Text(
              'No se pudo iniciar la música. Toca la nota para volver a intentarlo.',
            ),
          ),
        );
      }
    } finally {
      _musicStarting = false;
    }
  }

  Future<void> _toggleMusic() async {
    if (_musicEnabled) {
      setState(() {
        _musicEnabled = false;
        _musicPlaying = false;
      });
      try {
        await _musicPlayer.stop();
      } catch (error, stackTrace) {
        debugPrint('No se pudo silenciar la música de Coffee Wolves: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _scaffoldMessengerKey.currentState?.showSnackBar(
            const SnackBar(
              content:
                  Text('No se pudo detener la música. Inténtalo de nuevo.'),
            ),
          );
        }
      }
      return;
    }

    await _playMusic();
  }

  // ----------------------------------------------------------
  // NAVEGACIÓN
  // ----------------------------------------------------------

  void go(String destination) {
    if (page == 'splash' &&
        _splashController.status != AnimationStatus.completed) {
      return;
    }
    if (_isStaffRole && destination != 'pos') {
      _showSnackBar(
          'Las cuentas de barra y caja solo pueden operar en el TPV.');
      return;
    }
    if (destination == 'baristaAudit' && !_isStaffRole) {
      _showSnackBar('El registro está reservado al personal de barra.');
      return;
    }
    if (destination == 'barista') {
      _showSnackBar(
          'Ese módulo ya no está disponible para cuentas de barista.');
      return;
    }
    final isBaristaRoute = destination == 'pos';
    if (isBaristaRoute && _isLoadingRole) {
      _showSnackBar('Verificando los permisos de esta cuenta.');
      return;
    }
    if (isBaristaRoute &&
        (!_canAccessPos ||
            (_userRole == 'admin' &&
                (page != 'admin' || !_adminPosAccessEnabled)))) {
      _showSnackBar(
        _firebaseUser == null
            ? 'Inicia sesión con una cuenta autorizada de gerencia, barista o cajero.'
            : 'Tu cuenta no tiene permiso para usar el punto de venta.',
      );
      return;
    }
    if (destination == 'admin' &&
        (_userRole != 'admin' || !_adminFinanceUnlocked)) {
      _showSnackBar('Esta sección está reservada a gerencia.');
      return;
    }
    if (_userRole == 'admin' &&
        destination != 'admin' &&
        destination != 'pos') {
      _showSnackBar(
          'La cuenta de gerencia solo puede acceder a administración o al TPV.');
      return;
    }
    if (destination == 'shopProductDetail' &&
        selectedShopProduct?.category == 'Coleccionables' &&
        !_showPlushes) {
      _showSnackBar('La sección de coleccionables no está disponible.');
      return;
    }
    if (page == 'payment' &&
        destination != 'payment' &&
        _paymentStatus == 'pending') {
      _paymentGeneration++;
    }
    if (destination == 'menu' && page != 'menu') {
      _menuReturnPage = page;
      _menuReturnPreviousPage = previousPage;
    }
    _recordCurrentPageForBack(destination);
    setState(() {
      previousPage = page;
      page = destination;
    });
    if (destination == 'passport') _checkInactivityReminder();
    if (destination == 'admin') _resetAdminFinanceTimeout();
  }

  void back() {
    if (page == 'splash' &&
        _splashController.status != AnimationStatus.completed) {
      return;
    }
    final currentPage = page;
    var destination = previousPage;
    while (_pageHistory.isNotEmpty) {
      final candidate = _pageHistory.removeLast();
      if (candidate != currentPage) {
        destination = candidate;
        break;
      }
    }
    if (destination == currentPage) destination = 'home';
    setState(() {
      previousPage = currentPage;
      page = destination;
    });
  }

  void _recordCurrentPageForBack(String destination) {
    if (destination == page) return;
    _pageHistory.add(page);
    if (_pageHistory.length > 50) _pageHistory.removeAt(0);
  }

  String? get _sharedLostPetMissionId {
    if (!kIsWeb || _sharedLostPetMissionOpened) return null;
    final parameters = Uri.base.queryParameters;
    final missionId = parameters['mission']?.trim();
    if (parameters['module'] != 'lost-pet' ||
        missionId == null ||
        !RegExp(r'^[A-Za-z0-9_-]{20,80}$').hasMatch(missionId)) {
      return null;
    }
    return missionId;
  }

  void _closeSideMenu() {
    final destination = _menuReturnPage == 'menu' ? 'home' : _menuReturnPage;
    if (destination == page) return;
    while (_pageHistory.isNotEmpty && _pageHistory.last == 'menu') {
      _pageHistory.removeLast();
    }
    if (_pageHistory.isNotEmpty && _pageHistory.last == destination) {
      _pageHistory.removeLast();
    }
    setState(() {
      page = destination;
      previousPage = _pageHistory.isEmpty
          ? (_menuReturnPreviousPage == 'menu'
              ? 'home'
              : _menuReturnPreviousPage)
          : _pageHistory.last;
    });
  }

  Future<void> _handleAuthState(User? user) async {
    if (!mounted) return;
    if (_staffLoginDialogOpen) return;
    if (_passportTastingNotesUid != user?.uid) {
      _resetPassportTastingNotes(user?.uid);
    }
    final authGeneration = ++_authStateGeneration;
    unawaited(_cafeCatalogSubscription?.cancel());
    unawaited(_cafeFamiliesSubscription?.cancel());
    _cafeCatalogSubscription = null;
    _cafeFamiliesSubscription = null;
    _clearCafeOrders();
    setState(() {
      _authStateReady = true;
      _authStateError = null;
      if (_firebaseUser?.uid != user?.uid) {
        _profilePhotoBytes = null;
        _userGender = null;
      }
      _firebaseUser = user;
      _userRole = 'user';
      _isLoadingRole = user != null;
      _debugRoleBypassActive = false;
      _firestoreCafeProductIds.clear();
      _walletBalance = 0;
      final displayName = user?.displayName?.trim() ?? '';
      final emailName = user?.email?.split('@').first ?? '';
      userName = user == null
          ? ''
          : (displayName.isNotEmpty ? displayName : emailName);
      userHandle = user == null
          ? ''
          : '@${userName.toLowerCase().replaceAll(RegExp(r'\s+'), '')}';
      if (user == null &&
          const {'pos', 'barista', 'baristaAudit', 'admin', 'emailVerification'}
              .contains(page)) {
        page = 'login';
      }
    });
    if (user == null) {
      _adminFinanceTimeout?.cancel();
      _adminFinanceUnlocked = false;
      _adminPosAccessEnabled = false;
      _clearPassportProgress();
      _clearCafeOrders();
      return;
    }

    try {
      await user.reload();
      final activeUser = FirebaseAuth.instance.currentUser;
      if (activeUser == null ||
          activeUser.uid != user.uid ||
          authGeneration != _authStateGeneration) {
        return;
      }
      if (!activeUser.isAnonymous && !activeUser.emailVerified) {
        _clearPassportProgress();
        _clearCafeOrders();
        _adminFinanceTimeout?.cancel();
        _adminFinanceUnlocked = false;
        _adminPosAccessEnabled = false;
        if (mounted &&
            authGeneration == _authStateGeneration &&
            _firebaseUser?.uid == activeUser.uid) {
          setState(() {
            _firebaseUser = activeUser;
            _userRole = 'user';
            _isLoadingRole = false;
            _debugRoleBypassActive = false;
            _walletBalance = 0;
            if (page != 'plushAuthenticity') {
              page = 'emailVerification';
            }
          });
        }
        return;
      }
      _subscribeCafeCatalog();
      final role = await _readAuthorizedRole(activeUser);
      final authorizedRole = activeUser.emailVerified ? role : 'user';
      const debugRoleBypassActive = false;
      if (authorizedRole == 'admin') {
        _prepareAdminSession(demoMode: debugRoleBypassActive);
      }
      if (!mounted ||
          authGeneration != _authStateGeneration ||
          _firebaseUser?.uid != activeUser.uid) {
        return;
      }
      setState(() {
        _firebaseUser = activeUser;
        _userRole = authorizedRole;
        _isLoadingRole = false;
        _debugRoleBypassActive = debugRoleBypassActive;
        if (const {'barista', 'cajero'}.contains(authorizedRole) &&
            page != 'plushAuthenticity') {
          _pageHistory.clear();
          page = 'pos';
        }
        if (authorizedRole == 'admin' && page != 'plushAuthenticity') {
          _pageHistory.clear();
          page = 'admin';
        }
        if (authorizedRole == 'user' &&
            page != 'plushAuthenticity' &&
            (page != 'splash' || _sharedLostPetMissionId != null)) {
          _pageHistory.clear();
          page = _sharedLostPetMissionId == null ? 'home' : 'lostPet';
        }
      });
      if (authorizedRole == 'user') {
        unawaited(_refreshWalletBalance(activeUser.uid));
      } else {
        _walletBalance = 0;
      }
      if (authorizedRole == 'user') {
        _subscribePassportProgress(activeUser);
      } else {
        _clearPassportProgress();
      }
      if (_canAccessPos && !debugRoleBypassActive) {
        _subscribeCafeOrders(activeUser);
      } else {
        _clearCafeOrders();
      }
      if (authorizedRole == 'admin') _resetAdminFinanceTimeout();
      if (authorizedRole == 'user' && !activeUser.isAnonymous) {
        try {
          await _ensureCustomerProfile(activeUser);
        } on FirebaseException catch (error, stackTrace) {
          debugPrint(
              'No se pudo asegurar el perfil del cliente: ${error.code}');
          debugPrintStack(stackTrace: stackTrace);
          if (mounted && _firebaseUser?.uid == activeUser.uid) {
            _showSnackBar(
                'No se pudo preparar tu perfil para registrar recompensas.');
          }
        } catch (error, stackTrace) {
          debugPrint('Error al asegurar el perfil del cliente: $error');
          debugPrintStack(stackTrace: stackTrace);
          if (mounted && _firebaseUser?.uid == activeUser.uid) {
            _showSnackBar(
                'No se pudo preparar tu perfil para registrar recompensas.');
          }
        }
        await _loadUserGender(activeUser, authGeneration);
        await _loadProfilePhoto(activeUser, authGeneration);
      }
      if (const {'barista', 'baristaAudit', 'pos'}.contains(page) &&
          !const {'barista', 'cajero'}.contains(authorizedRole)) {
        setState(() => page = 'home');
        _showSnackBar(
            'Tu cuenta no tiene permiso para las herramientas de barra.');
      }
    } on FirebaseAuthException catch (error, stackTrace) {
      debugPrint('No se pudo verificar el rol de la cuenta: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted ||
          authGeneration != _authStateGeneration ||
          _firebaseUser?.uid != user.uid) {
        return;
      }
      setState(() {
        _userRole = 'user';
        _isLoadingRole = false;
        _debugRoleBypassActive = false;
        if (const {'barista', 'baristaAudit', 'pos', 'admin'}.contains(page)) {
          page = 'login';
        }
      });
      _showSnackBar(
          'No se pudo verificar tu rol. Se bloquearon las funciones administrativas.');
    } catch (error, stackTrace) {
      debugPrint('Error al verificar el rol de la cuenta: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted ||
          authGeneration != _authStateGeneration ||
          _firebaseUser?.uid != user.uid) {
        return;
      }
      setState(() {
        _userRole = 'user';
        _isLoadingRole = false;
        _debugRoleBypassActive = false;
        if (const {'barista', 'baristaAudit', 'pos', 'admin'}.contains(page)) {
          page = 'login';
        }
      });
      _showSnackBar(
          'No se pudo verificar tu rol. Se bloquearon las funciones administrativas.');
    }
  }

  Future<void> _ensureCustomerProfile(User user) async {
    final profileRef =
        FirebaseFirestore.instance.collection('users').doc(user.uid);
    await FirebaseFirestore.instance.runTransaction((transaction) async {
      final profile = await transaction.get(profileRef);
      if (profile.exists) return;

      transaction.set(profileRef, {
        'email': user.email?.trim(),
        'displayName': user.displayName?.trim() ?? '',
        'role': 'user',
        'createdAt': FieldValue.serverTimestamp(),
        'isVerified': false,
      });
    });
  }

  Future<void> _loadProfilePhoto(User user, int authGeneration) async {
    try {
      final profile = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final encodedPhoto = profile.data()?['profilePhotoBase64'];
      Uint8List? photoBytes;
      if (encodedPhoto is String && encodedPhoto.isNotEmpty) {
        try {
          photoBytes = base64Decode(encodedPhoto);
        } on FormatException catch (error, stackTrace) {
          debugPrint('La foto del perfil guardada no es válida: $error');
          debugPrintStack(stackTrace: stackTrace);
        }
      }
      if (!mounted ||
          authGeneration != _authStateGeneration ||
          _firebaseUser?.uid != user.uid) {
        return;
      }
      setState(() => _profilePhotoBytes = photoBytes);
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cargar la foto del perfil: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
    }
  }

  Future<void> _loadUserGender(User user, int authGeneration) async {
    try {
      final profile = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();
      final gender = profile.data()?['gender'];
      if (!mounted ||
          authGeneration != _authStateGeneration ||
          _firebaseUser?.uid != user.uid) {
        return;
      }
      setState(() {
        _userGender =
            gender is String && (gender == 'male' || gender == 'female')
                ? gender
                : null;
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cargar el género del perfil: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
    }
  }

  void _subscribePassportProgress(User user) {
    if (_debugRoleBypassActive || _passportProgressUid == user.uid) return;
    unawaited(_passportProgressSubscription?.cancel());
    _passportProgressUid = user.uid;
    _passportProgressSubscription = FirebaseFirestore.instance
        .collection('passportProgress')
        .doc(user.uid)
        .snapshots()
        .listen(
      (snapshot) {
        final data = snapshot.data();
        final completed =
            (data?['completedMethods'] as List<dynamic>? ?? const <dynamic>[])
                .whereType<String>()
                .toSet();
        if (!mounted || _passportProgressUid != user.uid) return;
        setState(() {
          for (final method in methods) {
            method.completed = completed.contains(method.name);
          }
          _passportRewardClaimed = data?['rewardClaimed'] == true;
        });
      },
      onError: (Object error, StackTrace stackTrace) {
        debugPrint('No se pudo cargar el Passport: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _showSnackBar('No se pudo sincronizar el progreso del Passport.');
        }
      },
    );
  }

  void _clearPassportProgress() {
    unawaited(_passportProgressSubscription?.cancel());
    _passportProgressSubscription = null;
    _passportProgressUid = null;
    _passportRewardClaimed = false;
    _resetPassportTastingNotes(null);
    for (final method in methods) {
      method.completed = false;
    }
  }

  void _resetPassportTastingNotes(String? ownerUid) {
    _passportTastingNotesUid = ownerUid;
    _isSavingPassportTastingNote = false;
    _loadedPassportTastingNotes.clear();
    _passportTastingNoteMessage = null;
    for (final controller in _passportTastingNoteControllers.values) {
      controller.clear();
    }
  }

  Future<void> _loadPassportTastingNote(PassportMethod method) async {
    final user = _firebaseUser;
    if (user == null || _loadedPassportTastingNotes.contains(method.name)) {
      return;
    }

    try {
      final note = await FirebaseFirestore.instance
          .collection('passportTastingNotes')
          .doc('${user.uid}__${method.name}')
          .get();
      if (!mounted || _firebaseUser?.uid != user.uid) return;
      final text = note.data()?['notes'];
      if (text is String) {
        _passportTastingNoteControllers[method.name]?.text = text;
      }
      _loadedPassportTastingNotes.add(method.name);
    } catch (error, stackTrace) {
      debugPrint('No se pudieron cargar las notas del Passport: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted && _firebaseUser?.uid == user.uid) {
        _showSnackBar('No se pudieron cargar las notas de este método.');
      }
    }
  }

  Future<void> _savePassportTastingNote(PassportMethod method) async {
    final user = _firebaseUser;
    if (user == null || _isSavingPassportTastingNote) return;

    setState(() {
      _isSavingPassportTastingNote = true;
      _passportTastingNoteMessage = null;
    });
    try {
      await FirebaseFirestore.instance
          .collection('passportTastingNotes')
          .doc('${user.uid}__${method.name}')
          .set({
        'ownerUid': user.uid,
        'methodName': method.name,
        'notes': _passportTastingNoteControllers[method.name]!.text.trim(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
      if (!mounted || _firebaseUser?.uid != user.uid) return;
      setState(() {
        _isSavingPassportTastingNote = false;
        _passportTastingNoteMessage = 'Notas guardadas en tu bitácora.';
      });
    } catch (error, stackTrace) {
      debugPrint('No se pudieron guardar las notas del Passport: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted || _firebaseUser?.uid != user.uid) return;
      setState(() {
        _isSavingPassportTastingNote = false;
        _passportTastingNoteMessage =
            'No se pudieron guardar las notas. Inténtalo de nuevo.';
      });
    }
  }

  void _subscribeCafeOrders(User user) {
    if (_cafeOrdersUid == user.uid) return;
    unawaited(_cafeOrdersSubscription?.cancel());
    _cafeOrdersUid = user.uid;
    _cafeOrdersSubscription = FirebaseFirestore.instance
        .collection('pedidos_internos')
        .where('status', isEqualTo: 'pending')
        .snapshots()
        .listen(
      (snapshot) {
        if (!mounted || _cafeOrdersUid != user.uid) return;
        final orders = [...snapshot.docs]..sort((left, right) {
            final leftCreatedAt = left.data()['createdAt'];
            final rightCreatedAt = right.data()['createdAt'];
            final leftDate = leftCreatedAt is Timestamp
                ? leftCreatedAt.toDate()
                : DateTime.fromMillisecondsSinceEpoch(0);
            final rightDate = rightCreatedAt is Timestamp
                ? rightCreatedAt.toDate()
                : DateTime.fromMillisecondsSinceEpoch(0);
            return leftDate.compareTo(rightDate);
          });
        setState(() => _pendingCafeOrders = orders);
        if (orders.isEmpty) {
          _cafeOrderAlarmPlaying = false;
          unawaited(_musicPlayer.stopOrderAlarm());
        } else if (_cafeOrderSoundEnabled) {
          unawaited(_startCafeOrderAlarm());
        }
      },
      onError: (Object error, StackTrace stackTrace) {
        debugPrint('No se pudieron escuchar las comandas de cocina: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted && _cafeOrdersUid == user.uid) {
          _showSnackBar(
            'No se pudo conectar la alarma de cocina. Revisa tu acceso al TPV.',
          );
        }
      },
    );
  }

  void _clearCafeOrders() {
    unawaited(_cafeOrdersSubscription?.cancel());
    _cafeOrdersSubscription = null;
    _cafeOrdersUid = null;
    _cafeOrderSoundEnabled = false;
    _cafeOrderAlarmPlaying = false;
    _cafePushEnabled = false;
    _pendingCafeOrders = [];
    unawaited(_musicPlayer.stopOrderAlarm());
  }

  Future<void> _activateCafeOrderSound() async {
    try {
      final user = _firebaseUser;
      if (user == null || !_canAccessPos || _debugRoleBypassActive) {
        throw StateError(
          'Inicia sesión con una cuenta verificada de gerencia, barista o cajero.',
        );
      }
      final pushSetup =
          _orderNotificationService.activateForAuthorizedUser(user.uid);
      await _musicPlayer.playOrderBell();
      if (!mounted) return;
      setState(() {
        _cafeOrderSoundEnabled = true;
      });
      if (_pendingCafeOrders.isNotEmpty) {
        await _startCafeOrderAlarm();
      }
      await pushSetup;
      if (mounted) setState(() => _cafePushEnabled = true);
      _showSnackBar(
        _pendingCafeOrders.isEmpty
            ? 'Sonido y notificaciones activados en este dispositivo.'
            : 'Alarma activa. Se repetirá hasta que cocina reconozca la comanda.',
      );
    } catch (error, stackTrace) {
      debugPrint('No se pudo activar la alarma de cocina: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          error is StateError
              ? error.message.toString()
              : 'No se pudo activar el sonido/push. Revisa permisos y conexión.',
        );
      }
    }
  }

  Future<void> _activateStockNotifications() async {
    final manager = _firebaseUser;
    if (!_canManageCafeCatalog || manager == null) {
      _showSnackBar('Inicia sesión con una cuenta verificada de Gerencia.');
      return;
    }
    if (_isEnablingStockNotifications) return;
    setState(() => _isEnablingStockNotifications = true);
    try {
      await _orderNotificationService.activateForAuthorizedUser(
        manager.uid,
        onForegroundMessage: (message) {
          if (FirebaseAuth.instance.currentUser?.uid != manager.uid ||
              message.data['productId'] is! String) {
            return;
          }
          _showSnackBar(
            message.data['body'] as String? ??
                'Un producto del menú llegó a cero unidades.',
          );
        },
      );
      if (!mounted) return;
      setState(() => _stockNotificationsUid = manager.uid);
      _showSnackBar(
        'Notificaciones de productos agotados activadas en este dispositivo.',
      );
    } catch (error, stackTrace) {
      debugPrint('No se pudieron activar las notificaciones de stock: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          error is StateError
              ? error.message.toString()
              : 'No se pudieron activar las notificaciones de stock. '
                  'Revisa permisos, VAPID y las reglas de Firestore.',
        );
      }
    } finally {
      if (mounted) setState(() => _isEnablingStockNotifications = false);
    }
  }

  Future<void> _startCafeOrderAlarm() async {
    if (_cafeOrderAlarmPlaying || !_cafeOrderSoundEnabled) return;
    _cafeOrderAlarmPlaying = true;
    try {
      await _musicPlayer.startOrderAlarm();
    } catch (error, stackTrace) {
      _cafeOrderAlarmPlaying = false;
      debugPrint('No se pudo repetir la alarma de cocina: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'La comanda llegó, pero no se pudo iniciar el sonido de alarma.',
        );
      }
    }
  }

  Future<void> _acknowledgeCafeOrder(
    QueryDocumentSnapshot<Map<String, dynamic>> order,
  ) async {
    final user = _firebaseUser;
    if (user == null || !_canAccessPos) return;
    try {
      await order.reference.update({
        'status': 'acknowledged',
        'acknowledgedBy': user.uid,
        'acknowledgedAt': FieldValue.serverTimestamp(),
      });
      _showSnackBar(
          'Comanda ${order.id.substring(0, 6)} reconocida por cocina.');
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo reconocer la comanda (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      _showSnackBar('No se pudo reconocer la comanda (${error.code}).');
    } catch (error, stackTrace) {
      debugPrint('Error al reconocer la comanda: $error');
      debugPrintStack(stackTrace: stackTrace);
      _showSnackBar('No se pudo reconocer la comanda.');
    }
  }

