  CafeMenuItem? _cafeImageSourceFor(String productId, String productName) {
    for (final item in _cafeMenuItems) {
      if (item.id == productId ||
          _cafeProductIdentity(item.name) ==
              _cafeProductIdentity(productName)) {
        return item;
      }
    }
    for (final item in _defaultCafeMenuItems) {
      if (item.id == productId ||
          _cafeProductIdentity(item.name) ==
              _cafeProductIdentity(productName)) {
        return item;
      }
    }
    return null;
  }

  void _subscribeCafeCatalog() {
    _cafeCatalogSubscription ??=
        FirebaseFirestore.instance.collection('cafeCatalog').snapshots().listen(
      (snapshot) {
        final inventoryCatalogMode = snapshot.docs.any(
          (document) => document.data()['inventorySource'] == 'products',
        );
        final items = inventoryCatalogMode
            ? <CafeMenuItem>[]
            : _defaultCafeMenuItems.map((item) => item.copy()).toList();
        for (final item in items) {
          if (item.price <= 0) {
            final knownPrice = _knownCafeMenuPrice(
              item.name,
              productId: item.id,
            );
            if (knownPrice != null) item.price = knownPrice;
          }
          if (item.price > 0) item.isAvailable = true;
          final family = _familyForCafeCategory(item.category);
          item.familyId = family?.id;
        }
        final unavailable =
            inventoryCatalogMode ? <String>{} : <String>{..._unavailableItems};
        final persistedIds = <String>{};
        for (final document in snapshot.docs) {
          final data = document.data();
          if (inventoryCatalogMode && data['inventorySource'] != 'products') {
            continue;
          }
          final productName = data['name'] as String? ?? '';
          final index = items.indexWhere(
            (item) =>
                item.id == document.id ||
                _cafeProductIdentity(item.name) ==
                    _cafeProductIdentity(productName),
          );
          final imageSource = _cafeImageSourceFor(document.id, productName);
          final localItem = index >= 0 ? items[index] : imageSource;
          final isKnownMenuProduct = index >= 0 ||
              imageSource != null ||
              _officialCafeProductForName(productName) != null;
          if (data['isDeleted'] == true) {
            if (index >= 0) items.removeAt(index);
            continue;
          }
          final rawCategory = data['category'] as String? ?? '';
          if (!isKnownMenuProduct &&
              (_isMerchInventoryCategory(rawCategory) ||
                  data['family'] == wolvesShopRootFamily)) {
            if (index >= 0) items.removeAt(index);
            continue;
          }
          persistedIds.add(document.id);
          final canonicalCategory = _canonicalCafeCategory(
            rawCategory,
            data['name'] as String,
            data['description'] as String? ?? '',
          );
          final officialCategory =
              _officialCafeProductForName(data['name'] as String)?.category;
          final storedFamilyId = data['familyId'] as String?;
          PosFamily? storedFamily;
          for (final candidate in _posFamilies) {
            if (candidate.id == storedFamilyId) {
              storedFamily = candidate;
              break;
            }
          }
          final family = (officialCategory == null
                  ? null
                  : _familyForCafeCategory(officialCategory)) ??
              _familyForCafeFamilyId(storedFamilyId) ??
              _familyForCafeCategory(canonicalCategory) ??
              storedFamily;
          final item = CafeMenuItem(
            id: document.id,
            name: productName,
            category: family?.name ?? canonicalCategory,
            description: data['description'] as String,
            icon: imageSource?.icon ?? localItem?.icon ?? Icons.local_cafe,
            price: (data['price'] as num?)?.toDouble() ?? 0,
            stock: (data['stock'] as num?)?.toInt() ?? 0,
            stockTracked: data['stockTracked'] == true,
            imageAsset: localItem?.imageAsset ?? imageSource?.imageAsset,
            imageUrl: data['imageUrl'] as String?,
            hasImage: data['hasImage'] == true,
            familyId: family?.id ?? storedFamilyId,
            isAvailable: data['isAvailable'] == true,
            isVisible: data['isVisible'] as bool? ?? true,
          );
          if (item.price <= 0) {
            final knownPrice = _knownCafeMenuPrice(
              item.name,
              productId: document.id,
            );
            if (knownPrice != null) item.price = knownPrice;
          }
          if (index >= 0) {
            items[index] = item;
          } else {
            items.add(item);
          }
          if (item.isAvailable) {
            unavailable.remove(item.name);
          } else {
            unavailable.add(item.name);
          }
        }
        _sortCafeMenuItemsByMenuOrder(items);
        if (!mounted) return;
        setState(() {
          _inventoryCatalogMode = inventoryCatalogMode;
          _cafeMenuItems
            ..clear()
            ..addAll(items);
          _firestoreCafeProductIds
            ..clear()
            ..addAll(persistedIds);
          _unavailableItems
            ..clear()
            ..addAll(unavailable);
        });
      },
      onError: (Object error, StackTrace stackTrace) {
        debugPrint('No se pudo sincronizar el catálogo TPV: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _showSnackBar('No se pudo sincronizar el catálogo de productos.');
        }
      },
    );
  }

  PosFamily? _familyForCafeCategory(String category) {
    final normalized = _normalizeCafeLabel(category);
    if (const {
      'speciality coffee',
      'specialty coffee',
      'speciality coffees',
      'specialty coffees',
      'brewing',
    }.contains(normalized)) {
      for (final family in _posFamilies) {
        if (_familyIsSpecialityCoffee(family)) return family;
      }
      return _defaultPosFamilies.firstWhere(
        _familyIsSpecialityCoffee,
      );
    }
    if (normalized.startsWith('presur') || normalized.startsWith('pressur')) {
      for (final family in _posFamilies) {
        if (family.id == 'pressurized-coffee' ||
            family.categories.any((candidate) {
              final candidateLabel = _normalizeCafeLabel(candidate);
              return candidateLabel.startsWith('presur') ||
                  candidateLabel.startsWith('pressur');
            })) {
          return family;
        }
      }
      return _defaultPosFamilies.firstWhere(
        (family) => family.id == 'pressurized-coffee',
      );
    }
    for (final family in _posFamilies) {
      if (family.categories.any(
        (candidate) => _normalizeCafeLabel(candidate) == normalized,
      )) {
        return family;
      }
    }
    for (final defaultFamily in _defaultPosFamilies) {
      if (defaultFamily.categories.any(
        (candidate) => _normalizeCafeLabel(candidate) == normalized,
      )) {
        for (final family in _posFamilies) {
          if (family.id == defaultFamily.id) return family;
        }
      }
    }
    return null;
  }

  bool _familyIsSpecialityCoffee(PosFamily family) {
    final normalizedId = _normalizeCafeLabel(family.id);
    final normalizedName = _normalizeCafeLabel(family.name);
    return const {
          'speciality coffee',
          'specialty coffee',
          'speciality coffees',
          'specialty coffees',
          'brewing',
        }.contains(normalizedId) ||
        const {
          'speciality coffee',
          'specialty coffee',
          'speciality coffees',
          'specialty coffees',
          'brewing',
        }.contains(normalizedName) ||
        family.categories.any(
          (category) => const {
            'speciality coffee',
            'specialty coffee',
            'speciality coffees',
            'specialty coffees',
            'brewing',
          }.contains(_normalizeCafeLabel(category)),
        );
  }

  PosFamily? _familyForCafeFamilyId(String? familyId) {
    if (familyId == null || familyId.trim().isEmpty) return null;
    final normalizedId = _normalizeCafeLabel(familyId);
    for (final family in _posFamilies) {
      if (family.id == familyId ||
          _cafeFamilyIdentity(family.id) == _cafeFamilyIdentity(familyId) ||
          _normalizeCafeLabel(family.name) == normalizedId) {
        return family;
      }
    }
    if (const {
      'speciality coffee',
      'specialty coffee',
      'speciality coffees',
      'specialty coffees',
      'brewing',
    }.contains(normalizedId)) {
      for (final family in _posFamilies) {
        if (_familyIsSpecialityCoffee(family)) return family;
      }
      return _defaultPosFamilies.firstWhere(_familyIsSpecialityCoffee);
    }
    return null;
  }

  PosFamily? _familyForCafeItem(CafeMenuItem item) {
    final categoryFamily = _familyForCafeCategory(
      _canonicalCafeCategory(item.category, item.name, item.description),
    );
    if (categoryFamily != null) return categoryFamily;
    final officialCategory = _officialCafeProductForName(item.name)?.category;
    final officialFamily = officialCategory == null
        ? null
        : _familyForCafeCategory(officialCategory);
    return officialFamily ?? _familyForCafeFamilyId(item.familyId);
  }

  void _sortCafeMenuItemsByMenuOrder(List<CafeMenuItem> items) {
    final menuOrder = <String, int>{
      for (var index = 0; index < _defaultCafeMenuItems.length; index++)
        _cafeProductIdentity(_defaultCafeMenuItems[index].name): index,
    };
    items.sort((first, second) {
      final firstFamilyOrder = _defaultPosFamilies.indexWhere(
        (family) => family.id == _familyForCafeItem(first)?.id,
      );
      final secondFamilyOrder = _defaultPosFamilies.indexWhere(
        (family) => family.id == _familyForCafeItem(second)?.id,
      );
      final firstFamilyIndex =
          firstFamilyOrder < 0 ? _defaultPosFamilies.length : firstFamilyOrder;
      final secondFamilyIndex = secondFamilyOrder < 0
          ? _defaultPosFamilies.length
          : secondFamilyOrder;
      if (firstFamilyIndex != secondFamilyIndex) {
        return firstFamilyIndex.compareTo(secondFamilyIndex);
      }
      final firstOrder = menuOrder[_cafeProductIdentity(first.name)];
      final secondOrder = menuOrder[_cafeProductIdentity(second.name)];
      if (firstOrder != null && secondOrder != null) {
        return firstOrder.compareTo(secondOrder);
      }
      if (firstOrder != null) return -1;
      if (secondOrder != null) return 1;
      return first.name.toLowerCase().compareTo(second.name.toLowerCase());
    });
  }

  void _subscribeCafeFamilies() {
    _cafeFamiliesSubscription ??= FirebaseFirestore.instance
        .collection('cafeFamilies')
        .snapshots()
        .listen(
      (snapshot) {
        final activeFamilyDocuments = snapshot.docs
            .where((document) => document.data()['isDeleted'] != true)
            .toList(growable: false);
        final persistedFamilyIds = activeFamilyDocuments
            .map((document) => _cafeFamilyIdentity(document.id))
            .toSet();
        final families = activeFamilyDocuments.map((document) {
          final data = document.data();
          final name = data['name'] as String? ?? document.id;
          return PosFamily(
            id: document.id,
            name: name,
            icon: Icons.category_outlined,
            categories: [name],
          );
        }).toList()
          ..addAll(
            _defaultPosFamilies.where(
              (family) =>
                  !persistedFamilyIds.contains(_cafeFamilyIdentity(family.id)),
            ),
          )
          ..sort((first, second) {
            final firstIndex = _defaultPosFamilies
                .indexWhere((candidate) => candidate.id == first.id);
            final secondIndex = _defaultPosFamilies
                .indexWhere((candidate) => candidate.id == second.id);
            if (firstIndex >= 0 && secondIndex >= 0) {
              return firstIndex.compareTo(secondIndex);
            }
            if (firstIndex >= 0) return -1;
            if (secondIndex >= 0) return 1;
            return first.name.compareTo(second.name);
          });
        if (!mounted) return;
        setState(() {
          _posFamilies
            ..clear()
            ..addAll(families.isEmpty ? _defaultPosFamilies : families);
          for (final item in _cafeMenuItems) {
            for (final family in _posFamilies) {
              if (_cafeFamilyIdentity(family.id) ==
                  _cafeFamilyIdentity(item.familyId ?? '')) {
                item.category = family.name;
                break;
              }
            }
          }
          _selectedPosFamilyId = _posFamilies
              .firstWhere(
                (family) =>
                    _cafeFamilyIdentity(family.id) ==
                    _cafeFamilyIdentity(_selectedPosFamilyId),
                orElse: () => _posFamilies.first,
              )
              .id;
          _selectedAdminPosFamilyId = _posFamilies
              .firstWhere(
                (family) =>
                    _cafeFamilyIdentity(family.id) ==
                    _cafeFamilyIdentity(_selectedAdminPosFamilyId),
                orElse: () => _posFamilies.first,
              )
              .id;
        });
      },
      onError: (Object error, StackTrace stackTrace) {
        debugPrint('No se pudieron cargar las familias del menú: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _showSnackBar('No se pudieron cargar las familias del catálogo TPV.');
        }
      },
    );
  }

  Future<String> _readRoleFromFirestore(
    FirebaseFirestore firestore,
    User user,
  ) async {
    final managementSnapshot =
        await firestore.collection('management').doc(user.uid).get();
    final managementData = managementSnapshot.data();
    final managementRole = normalizeUserRole(
      managementData?['role'] ?? managementData?['rol'],
    );
    if (managementRole == 'admin') return managementRole;

    final staffSnapshot =
        await firestore.collection('pos_staff').doc(user.uid).get();
    final staffData = staffSnapshot.data();
    final staffRole = normalizeUserRole(
      staffData?['role'] ?? staffData?['rol'],
    );
    if (const {'barista', 'cajero'}.contains(staffRole)) return staffRole;

    final snapshot = await firestore.collection('users').doc(user.uid).get();
    final profile = snapshot.data();
    final storedRole = profile?['role'] ?? profile?['rol'];
    return normalizeUserRole(storedRole);
  }

  Future<String> _readDatabaseRole(User user) {
    return _readRoleFromFirestore(FirebaseFirestore.instance, user);
  }

  Future<String> _readAuthorizedRole(User user) async {
    return _readDatabaseRole(user);
  }

  void _onAuthenticated(User user) {
    unawaited(_completeAuthentication(user));
  }

  Future<void> _handleEmailVerification({required bool resend}) async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null || user.isAnonymous) {
      _showSnackBar('Inicia sesión con tu correo para verificar la cuenta.');
      return;
    }
    setState(() {
      _emailVerificationActionInProgress = true;
      _emailVerificationMessage = null;
    });
    try {
      await user.reload();
      final refreshedUser = FirebaseAuth.instance.currentUser;
      if (refreshedUser == null || refreshedUser.uid != user.uid) {
        throw StateError('La sesión terminó. Inicia sesión nuevamente.');
      }
      if (refreshedUser.emailVerified) {
        await _handleAuthState(refreshedUser);
        if (mounted) {
          setState(() {
            _emailVerificationActionInProgress = false;
            _emailVerificationMessage =
                'Correo verificado. Ya puedes usar Coffee Wolves.';
          });
        }
        return;
      }
      if (resend) {
        await refreshedUser.sendEmailVerification();
        if (mounted) {
          setState(() {
            _emailVerificationActionInProgress = false;
            _emailVerificationMessage =
                'Enviamos el correo de verificación. Revisa también Spam.';
          });
        }
      } else if (mounted) {
        setState(() {
          _emailVerificationActionInProgress = false;
          _emailVerificationMessage =
              'Todavía no aparece la confirmación. Abre el enlace que te '
              'enviamos y vuelve a comprobar.';
        });
      }
    } on FirebaseAuthException catch (error, stackTrace) {
      debugPrint(
        'No se pudo enviar o comprobar el correo de verificación '
        '(${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        setState(() {
          _emailVerificationActionInProgress = false;
          _emailVerificationMessage =
              'No se pudo completar la verificación (${error.code}). '
              'Espera un momento e inténtalo de nuevo.';
        });
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo comprobar el correo verificado: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        setState(() {
          _emailVerificationActionInProgress = false;
          _emailVerificationMessage =
              'No se pudo comprobar la cuenta. Inténtalo de nuevo.';
        });
      }
    }
  }

  void _onProfilePhotoSelected(Uint8List bytes) {
    if (!mounted) return;
    setState(() => _profilePhotoBytes = bytes);
  }

  Future<void> _completeAuthentication(User user) async {
    await _handleAuthState(user);
    if (!mounted || FirebaseAuth.instance.currentUser?.uid != user.uid) return;
    if (_isLoadingRole) return;
    if (!_firebaseUser!.isAnonymous && !_firebaseUser!.emailVerified) return;
    setState(() {
      if (const {'barista', 'cajero'}.contains(_userRole)) {
        _authenticatedBarista = user.displayName?.trim().isNotEmpty == true
            ? user.displayName!.trim()
            : (user.email?.split('@').first ?? 'Personal');
        userName = _authenticatedBarista;
        page = 'pos';
      } else if (_userRole == 'admin') {
        _prepareAdminSession(demoMode: _debugRoleBypassActive);
        page = 'admin';
      } else {
        page = _sharedLostPetMissionId == null ? 'home' : 'lostPet';
      }
    });
    if (_userRole == 'admin') _resetAdminFinanceTimeout();
  }

  Future<void> _initializeRemoteConfig() async {
    try {
      final remoteConfig = FirebaseRemoteConfig.instance;
      _remoteConfig = remoteConfig;
      await remoteConfig.setConfigSettings(
        RemoteConfigSettings(
          fetchTimeout: const Duration(seconds: 10),
          minimumFetchInterval: const Duration(minutes: 1),
        ),
      );
      await remoteConfig.setDefaults(const {'mostrar_peluches': false});
      await _refreshRemoteConfig();
      _remoteConfigRefreshTimer = Timer.periodic(
        const Duration(minutes: 1),
        (_) => unawaited(_refreshRemoteConfig()),
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo iniciar Firebase Remote Config: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
    } catch (error, stackTrace) {
      debugPrint('Error al iniciar Firebase Remote Config: $error');
      debugPrintStack(stackTrace: stackTrace);
    }
  }

  Future<void> _refreshRemoteConfig() async {
    final remoteConfig = _remoteConfig;
    if (remoteConfig == null) return;
    try {
      await remoteConfig.fetchAndActivate();
      if (!mounted) return;
      final showPlushes = remoteConfig.getBool('mostrar_peluches');
      if (_showPlushes == showPlushes) return;
      var removedPlushFromCart = false;
      setState(() {
        _showPlushes = showPlushes;
        if (!showPlushes) {
          if (selectedShopCategory == 'Coleccionables') {
            selectedShopCategory = 'Moda Alfa';
          }
          if (page == 'shopProductDetail' &&
              selectedShopProduct?.category == 'Coleccionables') {
            page = 'shop';
          }
          final cartLength = cart.length;
          cart.removeWhere((item) {
            final productId = item['shopProductId'] as String?;
            return productId != null &&
                _shopProducts.any(
                  (product) =>
                      product.id == productId &&
                      product.category == 'Coleccionables',
                );
          });
          removedPlushFromCart = cart.length < cartLength;
        }
      });
      if (removedPlushFromCart) {
        _showSnackBar(
          'Los coleccionables se desactivaron y se retiraron del carrito.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
          'No se pudo actualizar la configuración remota: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
    } catch (error, stackTrace) {
      debugPrint('Error al actualizar la configuración remota: $error');
      debugPrintStack(stackTrace: stackTrace);
    }
  }

  Future<void> _signOut() async {
