  Future<void> _recordPosSale() async {
    final user = _firebaseUser;
    if (user == null || !_canAccessPos || _activePosBarista == null) {
      _showSnackBar('Inicia el turno de barra antes de cobrar.');
      return;
    }
    if (cart.isEmpty) {
      _showSnackBar('Agrega productos antes de confirmar el cobro.');
      return;
    }
    final shift = _selectedShiftForStaff;
    if (shift == null) {
      _showSnackBar('Espera a que se cargue tu turno asignado.');
      return;
    }

    final total = cart.fold<double>(
      0,
      (sum, item) =>
          sum + (item['price'] as num).toDouble() * (item['qty'] as int),
    );
    final received = _selectedPaymentMethod == 'cash'
        ? double.tryParse(_posPaymentReceivedController.text.trim()) ?? 0
        : 0.0;
    if (_selectedPaymentMethod == 'cash' && received < total) {
      _showSnackBar('El efectivo recibido no cubre el total de la venta.');
      return;
    }
    final paymentMethod = _selectedPaymentMethod;
    var saleCustomerUid = _customerUidForSale?.trim();
    if (paymentMethod == 'wallet') {
      if (saleCustomerUid == null || saleCustomerUid.isEmpty) {
        _showSnackBar('Ingresa el UID o Wolves Member Card del cliente.');
        return;
      }
      try {
        saleCustomerUid =
            await _memberCardService.resolveUserUid(saleCustomerUid);
      } on FirebaseException catch (error, stackTrace) {
        debugPrint('No se pudo validar la Member Card: ${error.code}');
        debugPrintStack(stackTrace: stackTrace);
        _showSnackBar('No se pudo validar la tarjeta del cliente.');
        return;
      } on StateError catch (error) {
        _showSnackBar(error.message);
        return;
      }
      if (saleCustomerUid.isEmpty || saleCustomerUid.contains('/')) {
        _showSnackBar('El ID de cliente no es válido.');
        return;
      }
    }

    final trackedProducts = <String, int>{};
    final trackedShopProducts = <String, int>{};
    final trackedShopVariants = <String, Map<String, int>>{};
    final saleItems = <Map<String, dynamic>>[];
    for (final cartItem in cart) {
      final name = cartItem['name'] as String;
      final isShopProduct = cartItem['catalogCollection'] == 'products';
      final tracksStock = isShopProduct || cartItem['stockTracked'] == true;
      final matchingProducts = isShopProduct
          ? <CafeMenuItem>[]
          : _cafeMenuItems.where((item) => item.name == name).toList();
      final product = matchingProducts.isEmpty ? null : matchingProducts.first;
      final productId =
          cartItem['catalogId'] as String? ?? _catalogIdFromName(name);
      final quantity = cartItem['qty'] as int;
      final size = cartItem['size'] as String?;
      saleItems.add({
        'productId': productId,
        'catalogCollection': isShopProduct ? 'products' : 'cafeCatalog',
        'name': name,
        if (size != null) 'size': size,
        'category': product == null
            ? _canonicalCafeCategory(
                cartItem['category'] as String? ?? '',
                name,
              )
            : _canonicalCafeCategory(
                product.category,
                product.name,
                product.description,
              ),
        'quantity': quantity,
        'unitPrice': (cartItem['price'] as num).toDouble(),
        'lineTotal': (cartItem['price'] as num).toDouble() * quantity,
      });
      if (tracksStock) {
        (isShopProduct ? trackedShopProducts : trackedProducts).update(
          productId,
          (current) => current + quantity,
          ifAbsent: () => quantity,
        );
      }
      if (isShopProduct && size != null) {
        trackedShopVariants
            .putIfAbsent(productId, () => <String, int>{})
            .update(
              size,
              (current) => current + quantity,
              ifAbsent: () => quantity,
            );
      }
    }

    setState(() => _isRecordingSale = true);
    try {
      final paidAt = DateTime.now();
      final saleAttemptId = _posSaleAttemptId ??=
          FirebaseFirestore.instance.collection('cafeSales').doc().id;
      final saleId = await _businessOperationsService.recordSale(
        saleId: saleAttemptId,
        employeeUid: user.uid,
        employeeEmail: user.email ?? '',
        date: paidAt,
        shift: shift,
        paymentMethod: paymentMethod,
        total: total,
        cashReceived: received,
        changeDue: received >= total ? received - total : 0,
        items: saleItems,
        trackedProducts: trackedProducts,
        trackedShopProducts: trackedShopProducts,
        trackedShopVariants: trackedShopVariants,
        customerUid: saleCustomerUid,
        tableNumber: _selectedPosTableNumber,
      );
      if (!mounted) return;
      setState(() {
        for (final entry in trackedProducts.entries) {
          final product =
              _cafeMenuItems.where((item) => item.id == entry.key).toList();
          if (product.isNotEmpty) {
            product.first.stock -= entry.value;
          }
        }
        cart.clear();
        _posPaymentReceivedController.clear();
        _posCustomerUidController.clear();
        _customerUidForSale = null;
        _selectedPaymentMethod = 'cash';
        _lastPosSaleId = saleId;
        _posSaleAttemptId = null;
      });
      try {
        final sellerName = (_activePosBarista ?? _authenticatedBarista).trim();
        final receiptPrinted = await CafeReceiptPrinter.printSaleReceipt(
          saleId: saleId,
          sellerName:
              sellerName.isEmpty ? (user.email ?? user.uid) : sellerName,
          paidAt: paidAt,
          lines: saleItems
              .map(
                (item) => CafeReceiptLine(
                  quantity: item['quantity'] as int,
                  description:
                      '${item['name']}${item['size'] == null ? '' : ' · Talle ${item['size']}'}',
                  unitPrice: (item['unitPrice'] as num).toDouble(),
                  amount: (item['lineTotal'] as num).toDouble(),
                ),
              )
              .toList(growable: false),
          total: total,
          paymentMethod: paymentMethod,
          cashReceived: received,
          changeDue: received >= total ? received - total : 0,
        );
        if (mounted) {
          _showSnackBar(
            receiptPrinted
                ? 'Venta guardada. Comprobante enviado a impresión.'
                : 'Venta guardada; se canceló la impresión del comprobante.',
          );
        }
      } catch (error, stackTrace) {
        debugPrint('Venta $saleId guardada, pero falló la impresión: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _showSnackBar(
            'Venta guardada, pero no se pudo abrir la impresión del comprobante.',
          );
        }
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo registrar la venta (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          paymentMethod == 'wallet' && error.code == 'permission-denied'
              ? 'No se pudo cobrar: la billetera no tiene saldo suficiente '
                  'o no está disponible. No se registró la venta.'
              : 'No se pudo guardar la venta (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo registrar la venta: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) _showSnackBar(error.toString());
    } finally {
      if (mounted) setState(() => _isRecordingSale = false);
    }
  }

  String? get _selectedShiftForStaff {
    final user = _firebaseUser;
    return user == null ? null : _cachedStaffShift;
  }

  String? _cachedStaffShift;

  Future<double?> _requestCashAmount({
    required String title,
    required String fieldLabel,
  }) async {
    final controller = TextEditingController();
    String? error;
    try {
      return await showDialog<double>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(title, style: const TextStyle(color: cream)),
            content: TextField(
              controller: controller,
              autofocus: true,
              keyboardType:
                  const TextInputType.numberWithOptions(decimal: true),
              decoration: InputDecoration(
                labelText: fieldLabel,
                prefixText: 'Bs ',
                errorText: error,
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  final amount = double.tryParse(controller.text.trim());
                  if (amount == null || !amount.isFinite || amount < 0) {
                    setDialogState(
                      () => error = 'Ingresa un monto igual o mayor a cero.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, amount);
                },
                child: const Text('CONTINUAR'),
              ),
            ],
          ),
        ),
      );
    } finally {
      controller.dispose();
    }
  }

