  Future<void> _closePosShift() async {
    if (_userRole == 'admin' || _activePosBarista == null) {
      await _exitPosToCustomerHome();
      return;
    }
    final user = _firebaseUser;
    if (user == null) {
      _showSnackBar('La sesión del personal ya no está activa.');
      return;
    }

    final date = DateTime.now();
    final dateKey = _businessOperationsService.dateKey(date);
    final attendanceRef = FirebaseFirestore.instance
        .collection('staffAttendance')
        .doc(_businessOperationsService.attendanceId(dateKey, user.uid));
    try {
      final attendance = await attendanceRef.get();
      final shift = attendance.data()?['shift'] as String?;
      if (!attendance.exists || shift == null) {
        _showSnackBar('No hay una entrada de turno abierta para hoy.');
        return;
      }

      final cashRef = FirebaseFirestore.instance
          .collection('cashSessions')
          .doc(_businessOperationsService.cashSessionId(
            dateKey,
            user.uid,
            shift,
          ));
      var cashSession = await cashRef.get();
      if (!cashSession.exists || cashSession.data()?['status'] != 'closed') {
        if (cashSession.data()?['status'] != 'open') {
          _showSnackBar(
            'No hay una caja cerrada para este turno. Abre la caja y '
            'registra el efectivo contado antes de salir.',
          );
          return;
        }
        await _closeCashForShift(shift);
        cashSession = await cashRef.get();
        if (!cashSession.exists || cashSession.data()?['status'] != 'closed') {
          return;
        }
      }

      if (!await _clockOutForShift()) return;
      await _exitPosToCustomerHome();
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cerrar el turno (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo cerrar el turno (${error.code}).');
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo cerrar el turno: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) _showSnackBar('No se pudo cerrar el turno: $error');
    }
  }

  Future<void> _showStaffLoginDialog({
    required String requiredRole,
    required BuildContext hostContext,
  }) async {
    final emailController = TextEditingController();
    final passwordController = TextEditingController();
    final firstNameController = TextEditingController();
    final lastNameController = TextEditingController();
    final usernameController = TextEditingController();
    DateTime? requestedBirthDate;
    String? authenticatedStaffUid;
    String? authenticatedStaffEmail;
    String? authenticatedStaffName;
    String? authenticatedStaffRole;
    String? completionMessage;
    var isLoading = false;
    var obscurePassword = true;
    var isRequestingAccount = false;
    var requestSubmitted = false;
    String? requestSuccessMessage;
    var requestedRole = requiredRole == 'admin' ? 'admin' : 'barista';
    String? errorMessage;
    final targetName =
        requiredRole == 'admin' ? 'GERENCIA' : 'SERVICIO · CAJA Y BARRA';
    ModalRoute<dynamic>? staffDialogRoute;

    String formatBirthDate(DateTime date) =>
        '${date.year.toString().padLeft(4, '0')}-'
        '${date.month.toString().padLeft(2, '0')}-'
        '${date.day.toString().padLeft(2, '0')}';

    bool isAdult(DateTime birthDate) {
      final today = DateTime.now();
      var age = today.year - birthDate.year;
      if (today.month < birthDate.month ||
          (today.month == birthDate.month && today.day < birthDate.day)) {
        age--;
      }
      return age >= 18;
    }

    Future<void> authenticate(
      StateSetter setDialogState,
      BuildContext dialogContext,
    ) async {
      if (!dialogContext.mounted) return;
      if (requiredRole == 'admin' && isRequestingAccount) {
        setDialogState(() {
          isRequestingAccount = false;
          errorMessage =
              'Las cuentas de Gerencia las configura el administrador.';
        });
        return;
      }
      final email = emailController.text.trim();
      final password = passwordController.text;
      if (email.isEmpty || password.isEmpty) {
        setDialogState(() => errorMessage = 'Completa correo y contraseña.');
        return;
      }
      if (!email.contains('@')) {
        setDialogState(
          () => errorMessage = 'Ingresa un correo que incluya @.',
        );
        return;
      }
      if (isRequestingAccount && requestSubmitted) return;
      if (isRequestingAccount &&
          (password.length < 8 ||
              firstNameController.text.trim().isEmpty ||
              lastNameController.text.trim().isEmpty ||
              firstNameController.text.trim().length > 60 ||
              lastNameController.text.trim().length > 60 ||
              UsernameRegistryService.validate(usernameController.text) !=
                  null)) {
        setDialogState(
          () => errorMessage =
              'Ingresa nombre y apellido, un Username válido y una contraseña '
                  'de al menos 8 caracteres.',
        );
        return;
      }
      if (isRequestingAccount &&
          (requestedBirthDate == null || !isAdult(requestedBirthDate!))) {
        setDialogState(
          () => errorMessage =
              'Selecciona tu fecha de nacimiento. Debes tener al menos 18 años.',
        );
        return;
      }
      setDialogState(() {
        isLoading = true;
        errorMessage = null;
      });
      _staffLoginDialogInitialUser = FirebaseAuth.instance.currentUser;
      _staffLoginDialogOpen = true;
      var staffRequestStep = 'crear o iniciar sesión';
      String? accountUidForDiagnostics;
      FirebaseApp? staffRequestApp;
      try {
        staffRequestApp = await Firebase.initializeApp(
          name: 'staff-access-${DateTime.now().microsecondsSinceEpoch}',
          options: Firebase.app().options,
        );
        final auth = FirebaseAuth.instanceFor(app: staffRequestApp);
        final firestore = FirebaseFirestore.instanceFor(app: staffRequestApp);
        if (kIsWeb) {
          await auth.setPersistence(Persistence.NONE);
        }
        UserCredential credential;
        var createdStaffAccount = false;
        if (isRequestingAccount) {
          try {
            credential = await auth.createUserWithEmailAndPassword(
              email: email,
              password: password,
            );
            createdStaffAccount = true;
          } on FirebaseAuthException catch (error) {
            if (error.code != 'email-already-in-use') rethrow;
            credential = await auth.signInWithEmailAndPassword(
              email: email,
              password: password,
            );
          }
        } else {
          credential = await auth.signInWithEmailAndPassword(
            email: email,
            password: password,
          );
        }
        final staffUser = credential.user;
        if (staffUser == null) {
          throw FirebaseAuthException(
            code: 'missing-user',
            message: 'No se pudo verificar la cuenta.',
          );
        }
        accountUidForDiagnostics = staffUser.uid;
        if (isRequestingAccount) {
          await staffUser.reload();
          await staffUser.getIdToken(true);
          final refreshedStaffUser = auth.currentUser;
          if (refreshedStaffUser == null ||
              refreshedStaffUser.uid != staffUser.uid) {
            throw FirebaseAuthException(
              code: 'session-ended',
              message: 'La sesión terminó antes de enviar la solicitud.',
            );
          }
          staffRequestStep = 'guardar la solicitud de acceso';
          final requestReference = firestore
              .collection('staffAccessRequests')
              .doc(refreshedStaffUser.uid);
          await firestore.runTransaction<void>((transaction) async {
            final existingRequest = await transaction.get(requestReference);
            final requestData = {
              'email': refreshedStaffUser.email,
              'displayName':
                  '${firstNameController.text.trim()} ${lastNameController.text.trim()}',
              'username': usernameController.text.trim(),
              'birthDate': formatBirthDate(requestedBirthDate!),
              'requestedRole': requestedRole,
              'status': 'pending',
              'createdAt': FieldValue.serverTimestamp(),
            };
            await UsernameRegistryService.reserveInTransaction(
              transaction: transaction,
              firestore: firestore,
              uid: refreshedStaffUser.uid,
              username: usernameController.text,
              role: 'staff',
              previousUsername: existingRequest.data()?['username'] as String?,
            );
            transaction.set(requestReference, requestData);
          });
          var verificationEmailSent = refreshedStaffUser.emailVerified;
          String? emailWarning;
          if (!verificationEmailSent && createdStaffAccount) {
            try {
              await refreshedStaffUser.sendEmailVerification();
              verificationEmailSent = true;
            } on FirebaseAuthException catch (error, stackTrace) {
              debugPrint(
                'Solicitud guardada; no se pudo enviar el correo de '
                'verificación (${error.code}).',
              );
              debugPrintStack(stackTrace: stackTrace);
              emailWarning =
                  'La solicitud sí llegó a Gerencia, pero no se pudo enviar '
                  'el correo de verificación. Solicita que te lo reenvíen.';
            }
          } else if (!verificationEmailSent) {
            emailWarning = 'Si aún no verificaste tu correo, usa el mensaje de '
                'verificación que ya recibiste. No enviamos otro correo.';
          }
          if (!dialogContext.mounted) return;
          setDialogState(() {
            isLoading = false;
            requestSubmitted = true;
            requestSuccessMessage = verificationEmailSent
                ? 'Tu solicitud ha sido enviada a Gerencia. Ya pueden '
                    'aprobarla.'
                : 'Tu solicitud ha sido enviada a Gerencia. Ya pueden '
                    'aprobarla. $emailWarning';
            errorMessage = null;
          });
          return;
        }
        await staffUser.reload();
        await staffUser.getIdToken(true);
        final activeStaffUser = auth.currentUser;
        if (activeStaffUser == null || activeStaffUser.uid != staffUser.uid) {
          throw FirebaseAuthException(
            code: 'session-ended',
            message: 'La sesión terminó antes de validar los permisos.',
          );
        }
        final role = await _readRoleFromFirestore(firestore, activeStaffUser);
        final hasRequiredRole = requiredRole == 'personal'
            ? const {'barista', 'cajero'}.contains(role)
            : role == requiredRole;
        if (!activeStaffUser.emailVerified || !hasRequiredRole) {
          await auth.signOut();
          if (!dialogContext.mounted) return;
          setDialogState(() {
            isLoading = false;
            errorMessage = !activeStaffUser.emailVerified
                ? 'Firebase todavía marca este correo como no verificado. '
                    'Abre el enlace del correo de verificación que ya recibiste '
                    'y vuelve a iniciar sesión. No enviaremos otro correo '
                    'automáticamente.'
                : requiredRole == 'admin'
                    ? 'El correo o contraseña es válido, pero esta cuenta no '
                        'tiene un registro de Gerencia con role: "admin" o '
                        '"gerente" en management/${activeStaffUser.uid} '
                        '(o en el perfil anterior users).'
                    : 'El correo o contraseña es válido, pero esta cuenta no '
                        'tiene el rol "barista" o "cajero" en '
                        'pos_staff/${activeStaffUser.uid} ni en el perfil '
                        'anterior users/${activeStaffUser.uid}.';
          });
          return;
        }
        authenticatedStaffUid = activeStaffUser.uid;
        authenticatedStaffEmail = email;
        authenticatedStaffName = activeStaffUser.displayName;
        authenticatedStaffRole = role;
        await auth.signOut();
        if (dialogContext.mounted) {
          Navigator.of(dialogContext).pop();
        }
      } on FirebaseAuthException catch (error) {
        if (!dialogContext.mounted) return;
        setDialogState(() {
          isLoading = false;
          errorMessage = switch (error.code) {
            'invalid-credential' ||
            'invalid-login-credentials' ||
            'wrong-password' ||
            'user-not-found' =>
              'Correo o contraseña incorrectos.',
            'email-already-in-use' =>
              'Ese correo ya tiene una cuenta. Pulsa «YA TENGO CUENTA» e '
                  'inicia sesión.',
            'weak-password' =>
              'La contraseña debe tener al menos 8 caracteres.',
            'invalid-email' => 'El formato del correo no es válido.',
            'network-request-failed' =>
              'No hay conexión con Firebase. Revisa Internet y vuelve a '
                  'intentar.',
            'operation-not-allowed' =>
              'Firebase no tiene habilitado el acceso con correo y contraseña. '
                  'El administrador debe activarlo en Authentication.',
            'configuration-not-found' =>
              'Firebase Authentication no está configurado para este proyecto '
                  'o no tiene habilitado el proveedor Correo/contraseña. '
                  'Revisa el proyecto wolves-club-fb24a en Firebase Console.',
            'too-many-requests' =>
              'Demasiados intentos. Espera un momento y vuelve a intentar.',
            _ => isRequestingAccount
                ? 'Firebase no pudo crear la cuenta (código: ${error.code}). '
                    'Revisa la conexión, que el acceso por correo esté '
                    'habilitado y que el dominio esté autorizado.'
                : 'Firebase no pudo iniciar sesión (código: ${error.code}). '
                    'Revisa la conexión y los datos de acceso.',
          };
        });
      } on StateError catch (error) {
        if (!dialogContext.mounted) return;
        setDialogState(() {
          isLoading = false;
          errorMessage = error.message.toString();
        });
      } on UsernameAlreadyTakenException catch (error) {
        if (!dialogContext.mounted) return;
        setDialogState(() {
          isLoading = false;
          errorMessage = error.toString();
        });
      } on FirebaseException catch (error, stackTrace) {
        debugPrint(
          'Error al $staffRequestStep (${error.code}).',
        );
        debugPrintStack(stackTrace: stackTrace);
        if (!dialogContext.mounted) return;
        setDialogState(() {
          isLoading = false;
          errorMessage = isRequestingAccount
              ? 'No se pudo enviar la solicitud a Gerencia '
                  '(${error.code}). No se confirmó el envío; inténtalo '
                  'de nuevo.'
              : error.code == 'permission-denied'
                  ? 'Firebase validó la cuenta, pero Firestore no permite leer '
                      'su rol de Gerencia. Publica las reglas actuales con '
                      '`firebase deploy --only firestore:rules --project '
                      'wolves-club-fb24a` y confirma que el documento '
                      'management/${accountUidForDiagnostics ?? 'UID de la cuenta'} '
                      'tenga role: admin.'
                  : 'Firebase autenticó el correo, pero no se pudo leer el rol '
                      'en management/{uid}, pos_staff/{uid} o users/{uid} '
                      '(${error.code}). Verifica las reglas Firestore.';
        });
      } catch (error, stackTrace) {
        debugPrint(
          'Error al $staffRequestStep durante el acceso de personal: $error',
        );
        debugPrintStack(stackTrace: stackTrace);
        if (!dialogContext.mounted) return;
        setDialogState(() {
          isLoading = false;
          errorMessage = isRequestingAccount
              ? 'No se pudo enviar la solicitud a Gerencia: $error'
              : 'No se pudo validar el acceso: $error';
        });
      } finally {
        if (staffRequestApp != null) {
          try {
            await staffRequestApp.delete();
          } catch (error, stackTrace) {
            debugPrint('No se pudo liberar Firebase temporal: $error');
            debugPrintStack(stackTrace: stackTrace);
          }
        }
      }
    }

    try {
      if (!hostContext.mounted) {
        _showSnackBar('No se pudo abrir el acceso de personal.');
        return;
      }
      await showDialog<void>(
        context: hostContext,
        barrierDismissible: false,
        builder: (dialogContext) {
          staffDialogRoute = ModalRoute.of(dialogContext);
          return StatefulBuilder(
            builder: (dialogContext, setDialogState) => AlertDialog(
              backgroundColor: card,
              scrollable: true,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(20),
                side: BorderSide(color: gold.withValues(alpha: 0.65)),
              ),
              title: Row(
                children: [
                  WolvesIcon(
                    icon: requiredRole == 'admin'
                        ? BrandIcons.garra
                        : Icons.point_of_sale,
                    color: gold,
                  ),
                  const SizedBox(width: 10),
                  Text(
                    targetName,
                    style: const TextStyle(
                      color: cream,
                      fontSize: 16,
                      letterSpacing: 1.2,
                    ),
                  ),
                ],
              ),
              content: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 380),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (requiredRole == 'admin') ...[
                      const Text(
                        'Gerencia puede acceder desde cualquier Wi-Fi o datos '
                        'móviles con conexión a internet.',
                        textAlign: TextAlign.center,
                        style:
                            TextStyle(color: muted, fontSize: 12, height: 1.4),
                      ),
                      const SizedBox(height: 14),
                    ],
                    if (isRequestingAccount) ...[
                      TextField(
                        controller: firstNameController,
                        textCapitalization: TextCapitalization.words,
                        decoration: const InputDecoration(
                          labelText: 'Nombre *',
                          prefixIcon: Icon(Icons.badge_outlined),
                        ),
                      ),
                      const SizedBox(height: 12),
                      TextField(
                        controller: lastNameController,
                        textCapitalization: TextCapitalization.words,
                        decoration: const InputDecoration(
                          labelText: 'Apellido *',
                          prefixIcon: Icon(Icons.badge_outlined),
                        ),
                      ),
                      const SizedBox(height: 12),
                      TextField(
                        controller: usernameController,
                        textCapitalization: TextCapitalization.none,
                        autocorrect: false,
                        decoration: const InputDecoration(
                          labelText: 'Username',
                          helperText:
                              'Único en la app; usa letras, números, . _ -',
                          prefixIcon: Icon(Icons.alternate_email),
                        ),
                      ),
                      const SizedBox(height: 12),
                      OutlinedButton.icon(
                        onPressed: isLoading
                            ? null
                            : () async {
                                final today = DateTime.now();
                                final selected = await showDatePicker(
                                  context:
                                      _navigatorKey.currentContext ?? context,
                                  initialDate: requestedBirthDate ??
                                      DateTime(
                                        today.year - 18,
                                        today.month,
                                        today.day,
                                      ),
                                  firstDate: DateTime(1900),
                                  lastDate: today,
                                  helpText: 'FECHA DE NACIMIENTO',
                                );
                                if (selected == null ||
                                    !dialogContext.mounted) {
                                  return;
                                }
                                setDialogState(() {
                                  requestedBirthDate = selected;
                                  errorMessage = null;
                                });
                              },
                        icon: const Icon(Icons.cake_outlined),
                        label: Text(
                          requestedBirthDate == null
                              ? 'FECHA DE NACIMIENTO (OBLIGATORIA)'
                              : 'NACIMIENTO: '
                                  '${requestedBirthDate!.day.toString().padLeft(2, '0')}/'
                                  '${requestedBirthDate!.month.toString().padLeft(2, '0')}/'
                                  '${requestedBirthDate!.year}',
                        ),
                      ),
                      const SizedBox(height: 12),
                      DropdownButtonFormField<String>(
                        value: requestedRole,
                        decoration: const InputDecoration(
                          labelText: 'Rol solicitado',
                          prefixIcon: Icon(Icons.work_outline),
                        ),
                        items: (requiredRole == 'admin'
                                ? const ['admin']
                                : const ['barista', 'cajero'])
                            .map(
                              (role) => DropdownMenuItem(
                                value: role,
                                child: Text(
                                  switch (role) {
                                    'admin' => 'Gerencia',
                                    'cajero' => 'Caja',
                                    _ => 'Barista',
                                  },
                                ),
                              ),
                            )
                            .toList(),
                        onChanged: isLoading
                            ? null
                            : (role) {
                                if (role == null) return;
                                setDialogState(() {
                                  requestedRole = role;
                                  errorMessage = null;
                                });
                              },
                      ),
                      const SizedBox(height: 10),
                      const Text(
                        'La cuenta queda pendiente. Solo gerencia puede '
                        'aprobar el rol; esta solicitud no concede acceso. '
                        'Usa un correo al que puedas acceder para verificarlo.',
                        textAlign: TextAlign.center,
                        style:
                            TextStyle(color: muted, fontSize: 12, height: 1.4),
                      ),
                      const SizedBox(height: 12),
                    ],
                    TextField(
                      key: const ValueKey('staff-login-email'),
                      controller: emailController,
                      keyboardType: TextInputType.emailAddress,
                      autofocus: true,
                      textInputAction: TextInputAction.next,
                      autofillHints: const [AutofillHints.username],
                      decoration: const InputDecoration(
                        labelText: 'Correo electrónico',
                        prefixIcon: Icon(Icons.email_outlined),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      key: const ValueKey('staff-login-password'),
                      controller: passwordController,
                      obscureText: obscurePassword,
                      autofillHints: const [AutofillHints.password],
                      decoration: InputDecoration(
                        labelText: 'Contraseña',
                        prefixIcon: const Icon(Icons.lock_outline),
                        suffixIcon: IconButton(
                          onPressed: () => setDialogState(
                            () => obscurePassword = !obscurePassword,
                          ),
                          icon: Icon(
                            obscurePassword
                                ? Icons.visibility_outlined
                                : Icons.visibility_off_outlined,
                          ),
                        ),
                      ),
                      onSubmitted: (_) {
                        if (!isLoading) {
                          unawaited(
                              authenticate(setDialogState, dialogContext));
                        }
                      },
                    ),
                    if (errorMessage != null) ...[
                      const SizedBox(height: 12),
                      Text(
                        errorMessage!,
                        style: const TextStyle(color: Color(0xFFFF8A80)),
                        textAlign: TextAlign.center,
                      ),
                    ],
                    if (requestSuccessMessage != null) ...[
                      const SizedBox(height: 12),
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.all(10),
                        decoration: BoxDecoration(
                          color: green.withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(10),
                          border: Border.all(
                            color: green.withValues(alpha: 0.55),
                          ),
                        ),
                        child: Text(
                          requestSuccessMessage!,
                          key: const ValueKey('staff-request-success'),
                          style: const TextStyle(
                            color: green,
                            fontSize: 12,
                            height: 1.4,
                            fontWeight: FontWeight.w600,
                          ),
                          textAlign: TextAlign.center,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
              actions: [
                TextButton(
                  onPressed: isLoading
                      ? null
                      : () => Navigator.of(dialogContext).pop(),
                  child: const Text('CANCELAR'),
                ),
                if (requiredRole != 'admin')
                  TextButton(
                    onPressed: isLoading || requestSubmitted
                        ? null
                        : () => setDialogState(() {
                              isRequestingAccount = !isRequestingAccount;
                              errorMessage = null;
                              requestSuccessMessage = null;
                            }),
                    child: Text(
                      isRequestingAccount
                          ? 'YA TENGO CUENTA'
                          : 'SOLICITAR CUENTA',
                    ),
                  ),
                FilledButton.icon(
                  onPressed: isLoading || requestSubmitted
                      ? null
                      : () => unawaited(
                            authenticate(setDialogState, dialogContext),
                          ),
                  icon: isLoading
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: bg,
                          ),
                        )
                      : const Icon(Icons.login),
                  label: Text(
                    requestSubmitted
                        ? 'SOLICITUD ENVIADA'
                        : isRequestingAccount
                            ? 'ENVIAR SOLICITUD'
                            : 'INGRESAR',
                  ),
                  style: FilledButton.styleFrom(
                    backgroundColor: gold,
                    foregroundColor: bg,
                  ),
                ),
              ],
            ),
          );
        },
      );
      await staffDialogRoute?.completed;
      final staffUid = authenticatedStaffUid;
      final staffEmail = authenticatedStaffEmail;
      final staffRole = authenticatedStaffRole;
      if (staffUid != null &&
          staffEmail != null &&
          staffRole != null &&
          mounted) {
        final credential =
            await FirebaseAuth.instance.signInWithEmailAndPassword(
          email: staffEmail,
          password: passwordController.text,
        );
        final staffUser = credential.user;
        if (staffUser == null || staffUser.uid != staffUid) {
          await FirebaseAuth.instance.signOut();
          throw FirebaseAuthException(
            code: 'staff-account-mismatch',
            message: 'No se pudo confirmar la cuenta de personal.',
          );
        }
        await staffUser.reload();
        await staffUser.getIdToken(true);
        final refreshedStaffUser = FirebaseAuth.instance.currentUser;
        if (refreshedStaffUser == null || refreshedStaffUser.uid != staffUid) {
          await FirebaseAuth.instance.signOut();
          throw FirebaseAuthException(
            code: 'staff-account-mismatch',
            message: 'No se pudo refrescar la sesión de personal.',
          );
        }
        final primaryRole = await _readAuthorizedRole(refreshedStaffUser);
        final hasRequiredRole = requiredRole == 'personal'
            ? const {'barista', 'cajero'}.contains(primaryRole)
            : primaryRole == requiredRole;
        if (!refreshedStaffUser.emailVerified || !hasRequiredRole) {
          await FirebaseAuth.instance.signOut();
          final reason = !refreshedStaffUser.emailVerified
              ? 'Firebase todavía marca este correo como no verificado. '
                  'Cierra sesión en el correo y abre el enlace de verificación '
                  'más reciente; no enviaremos otro automáticamente.'
              : requiredRole == 'admin'
                  ? 'No se encontró un rol Gerencia en management/${refreshedStaffUser.uid} ni en el perfil anterior users/${refreshedStaffUser.uid}.'
                  : 'No se encontró el rol barista o cajero en pos_staff/${refreshedStaffUser.uid} ni en el perfil anterior users/${refreshedStaffUser.uid}.';
          throw FirebaseAuthException(
            code: 'staff-role-changed',
            message: reason,
          );
        }
        final staffName = authenticatedStaffName?.trim().isNotEmpty == true
            ? authenticatedStaffName!.trim()
            : (refreshedStaffUser.email?.split('@').first ?? 'Personal');
        unawaited(_cafeCatalogSubscription?.cancel());
        _cafeCatalogSubscription = null;
        _clearCafeOrders();
        _clearPassportProgress();
        setState(() {
          _firebaseUser = refreshedStaffUser;
          _userRole = primaryRole;
          _isLoadingRole = false;
          _authenticatedBarista = staffName;
          userName = staffName;
          _activePosBarista = null;
          _adminPosAccessEnabled = false;
          if (requiredRole == 'admin') {
            _prepareAdminSession();
            page = 'admin';
          } else {
            _adminFinanceUnlocked = false;
            page = 'pos';
          }
          _pageHistory.clear();
          previousPage = page;
        });
        _subscribeCafeCatalog();
        _subscribeCafeFamilies();
        _subscribeCafeOrders(refreshedStaffUser);
        if (requiredRole == 'admin') _resetAdminFinanceTimeout();
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo completar el acceso de personal: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (authenticatedStaffUid != null &&
          FirebaseAuth.instance.currentUser?.uid == authenticatedStaffUid) {
        try {
          await FirebaseAuth.instance.signOut();
        } catch (signOutError, signOutStackTrace) {
          debugPrint(
            'No se pudo cerrar la sesión tras fallar la validación: '
            '$signOutError',
          );
          debugPrintStack(stackTrace: signOutStackTrace);
        }
      }
      if (error is FirebaseAuthException) {
        completionMessage = switch (error.code) {
          'invalid-credential' ||
          'invalid-login-credentials' ||
          'wrong-password' ||
          'user-not-found' =>
            'Correo o contraseña incorrectos.',
          'staff-role-changed' ||
          'staff-account-mismatch' =>
            error.message ?? 'La cuenta no tiene acceso a esta sección.',
          'network-request-failed' =>
            'No hay conexión con Firebase. Revisa Internet y vuelve a intentar.',
          'operation-not-allowed' =>
            'Habilita Correo/contraseña en Firebase Authentication.',
          _ => 'Firebase no pudo completar el acceso (${error.code}).',
        };
      } else if (error is FirebaseException) {
        completionMessage = error.code == 'permission-denied'
            ? 'Firebase autenticó la cuenta, pero las reglas Firestore impiden leer o validar su rol. Despliega las reglas actualizadas.'
            : 'No se pudo validar el acceso (${error.code}).';
      } else {
        completionMessage = 'No se pudo validar el acceso: $error';
      }
    } finally {
      await staffDialogRoute?.completed;
      emailController.dispose();
      passwordController.dispose();
      firstNameController.dispose();
      lastNameController.dispose();
      usernameController.dispose();
      if (mounted) {
        setState(() {
          _staffLoginDialogOpen = false;
          _staffLoginDialogInitialUser = null;
        });
        if (completionMessage != null) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (!mounted) return;
            _showSnackBar(completionMessage!);
          });
        }
      }
    }
  }

  void _prepareAdminSession({bool demoMode = false}) {
    _adminFinanceUnlocked = true;
    if (demoMode) {
      _adminOrdersFuture = null;
      return;
    }
    _adminOrdersFuture = _loadRecentWolvesShopOrders();
  }

  Future<QuerySnapshot<Map<String, dynamic>>> _loadRecentWolvesShopOrders() {
    final oneWeekAgo = DateTime.now().subtract(const Duration(days: 7));
    return FirebaseFirestore.instance
        .collection('wolvesShopOrders')
        .where(
          'createdAt',
          isGreaterThanOrEqualTo: Timestamp.fromDate(oneWeekAgo),
        )
        .orderBy('createdAt', descending: true)
        .limit(50)
        .get();
  }

  void _openManagementAccess(BuildContext context) {
    unawaited(
      _showStaffLoginDialog(requiredRole: 'admin', hostContext: context),
    );
  }

  void _openStaffAccess(BuildContext context) {
    unawaited(
      _showStaffLoginDialog(requiredRole: 'personal', hostContext: context),
    );
  }

  Widget _staffAccessButton({
    required Key key,
    required String label,
    required IconData icon,
    required VoidCallback onPressed,
  }) {
    return OutlinedButton.icon(
      key: key,
      onPressed: onPressed,
      icon: WolvesIcon(icon: icon, size: 18),
      label: Text(label, maxLines: 1, overflow: TextOverflow.ellipsis),
      style: OutlinedButton.styleFrom(
        foregroundColor: gold,
        backgroundColor: card,
        side: BorderSide(color: gold.withValues(alpha: 0.45)),
        minimumSize: const Size.fromHeight(48),
        padding: const EdgeInsets.symmetric(horizontal: 8),
      ),
    );
  }

  void _resetAdminFinanceTimeout() {
    _adminFinanceTimeout?.cancel();
    if (!_adminFinanceUnlocked || !const {'admin', 'pos'}.contains(page)) {
      return;
    }
    _adminFinanceTimeout = Timer(const Duration(minutes: 2), () {
      if (!mounted || _userRole != 'admin') return;
      _adminFinanceUnlocked = false;
      unawaited(_signOut());
      setState(() {
        _pageHistory.clear();
        page = 'login';
        previousPage = 'login';
      });
      _showSnackBar('La sesión de gerencia se cerró por inactividad.');
    });
  }

  Future<void> _lockAdminFinance() async {
    _adminFinanceTimeout?.cancel();
    _adminFinanceUnlocked = false;
    setState(() {
      page = 'login';
      previousPage = 'login';
    });
    await _signOut();
  }

  void _applyOfficialCafeCatalogUpdates() {
    final renames = <String, String>{
      'Lasaña Boloñesa (2 personas)': 'Lasaña Bolognesa Duo (2 Personas)',
      'Charque’s Croissant': "Charque's Croissant",
      'Pesego Real': 'Pessego Real',
      'Crumble Cookies (pack 2)': 'Crumbles (Pack 2 Unid)',
      'Crumble Cookies (pack 4)': 'Crumbles (Pack 4 Unid)',
      'Crumble Cookies (pack 6)': 'Crumbles (Pack 6 Unid)',
      'Macarrons (pack 4)': 'Macarrons (Pack 4 Unid)',
      'Macarrons (pack 6)': 'Macarrons (Pack 6 Unid)',
      'Macarrons (pack 12)': 'Macarrons (Pack 12 Unid)',
      'Morango do Amor (pack 2)': 'Morangos do Amor (Pack 2 Unid)',
      'Morango do Amor (pack 4)': 'Morangos do Amor (Pack 4 Unid)',
      'Morango do Amor (pack 8)': 'Morangos do Amor (Pack 8 Unid)',
      'Mini Donuts (pack 6)': 'Mini Donuts (Pack 6 Unid)',
      'Cupcakes (pack 6)': 'Cupcakes (Pack 6 Unid)',
      'Cinnamon Roll (pack 4)': 'Cinnamon Roll (Pack 4 Unid)',
      'Alfajores (pack 6)': 'Alfajores (Pack 6 Unid)',
      'Cunapés (pack 6)': 'Cuñapés (Pack 6 Unid)',
      'Chocoberries (pack 6)': 'Chocoberries (Pack 6 Unid)',
      'Mousse (2 unidades)': 'Mousse (2 Unid)',
      'Coca Cola (500 ml)': 'Coca Cola (500ml)',
      'Coca Cola sin azúcar (500 ml)': 'Coca Cola Sin Azúcar (500ml)',
      'Fanta Naranja (500 ml)': 'Fanta Naranja (500ml)',
      'Fanta Mandarina (500 ml)': 'Fanta Mandarina (500ml)',
      'Fanta Limón (500 ml)': 'Fanta Limón (500ml)',
      'Fanta Papaya (500 ml)': 'Fanta Papaya (500ml)',
      'Sprite (500 ml)': 'Sprite (500ml)',
      'Sprite sin azúcar (500 ml)': 'Sprite Sin Azúcar (500ml)',
      'Agua (500 ml)': 'Agua (500ml)',
      'Agua con gas (500 ml)': 'Agua con Gas (500ml)',
      'Sandwich Francés & Ice Tea': 'Sandwich Frances & Ice Tea',
      'Pesego Real & Cheese Croissant': 'Pessego Real & Cheese Croissant',
      'Arroz con Leche & Cunapé': 'Arroz con Leche & Cuñape',
    };
    for (final item in _cafeMenuItems) {
      final updatedName = renames[item.name];
      if (updatedName != null) item.name = updatedName;
    }

    for (final product in _officialCafeProducts) {
      final acceptedNames = {
        _normalizeCafeProductName(product.name),
        ...?_officialCafeProductAliases[product.name]
            ?.map(_normalizeCafeProductName),
      };
      final existing = _cafeMenuItems
          .where(
            (item) => acceptedNames.contains(
              _normalizeCafeProductName(item.name),
            ),
          )
          .toList();
      if (existing.isEmpty) {
        _cafeMenuItems.add(
          CafeMenuItem(
              id: _catalogIdFromName(product.name),
              name: product.name,
              category: _canonicalCafeCategory(
                  product.category, product.name, product.description),
              description: product.description,
              price: product.price ?? 0,
              icon: product.category == 'Tortas grandes' ||
                      product.category == 'Postres'
                  ? Icons.cake
                  : product.category == 'Panadería'
                      ? Icons.bakery_dining
                      : Icons.local_cafe,
              stock: 0),
        );
      } else {
        final item = existing.first;
        item
          ..name = product.name
          ..category = _canonicalCafeCategory(
            product.category,
            product.name,
            product.description,
          )
          ..description = product.description
          ..price = product.price ?? 0;
        for (final duplicate in existing.skip(1)) {
          _cafeMenuItems.remove(duplicate);
        }
      }
    }

    const additionalMenuImages = <String, String>{
      'banatellacrepe': 'assets/images/desserts/banatella_crepe.webp',
      'banatellawaffle': 'assets/images/desserts/banatella_waffle.webp',
      'strawberriescreamcrepe':
          'assets/images/desserts/strawberry_cream_crepe.webp',
      'strawberriescreamwaffle':
          'assets/images/desserts/strawberry_cream_waffle.webp',
      'fluffypancake': 'assets/images/desserts/fluffy_pancake.webp',
      'pavlova': 'assets/images/desserts/pavlova.webp',
      'cremebrulee': 'assets/images/desserts/creme_brulee.webp',
      'strawberrymousse': 'assets/images/desserts/strawberry_mousse.webp',
      'lemonmousse': 'assets/images/desserts/lemon_mousse.webp',
      'passionfruitmousse': 'assets/images/desserts/passion_fruit_mousse.webp',
      'cinnamonroll': 'assets/images/desserts/cinnamon_roll.webp',
      'cunape': 'assets/images/desserts/cunape.webp',
      'hojaldrecookie': 'assets/images/desserts/hojaldre_cookie.webp',
      'mousse2unid': 'assets/images/desserts/cappuccino_mousse.webp',
      'mousse2unidades': 'assets/images/desserts/cappuccino_mousse.webp',
      'mintlatte': 'assets/images/presurizados/latte_mint.webp',
    };
    for (final item in _cafeMenuItems) {
      final image = additionalMenuImages[_normalizeCafeProductName(item.name)];
      if (item.imageAsset == null && image != null) {
        item.imageAsset = image;
      }
    }

    final hasSMorePlatter = _cafeMenuItems.any(
      (item) => item.name == "S'mores Ice Cream (Plato)",
    );
    if (!hasSMorePlatter) {
      _cafeMenuItems.add(
        CafeMenuItem(
            id: _catalogIdFromName("S'mores Ice Cream (Plato)"),
            name: "S'mores Ice Cream (Plato)",
            category: 'Helados',
            description:
