  Future<void> _openCafeCatalogItemEditor({
    required BuildContext context,
    CafeMenuItem? item,
  }) async {
    try {
      if (!_canEditCafeCatalogInCurrentSession) {
        _showSnackBar(
          'Inicia sesión con una cuenta verificada de Gerencia para editar el catálogo TPV.',
        );
        return;
      }
      await _showCafeCatalogItemEditor(context: context, item: item);
    } catch (error, stackTrace) {
      debugPrint('No se pudo abrir el editor del catálogo TPV: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo abrir el editor: $error');
      }
    }
  }

  Future<void> _showCafeCatalogItemEditor({
    required BuildContext context,
    CafeMenuItem? item,
  }) async {
    final authenticatedManager = _firebaseUser;
    if (!_canEditCafeCatalogInCurrentSession ||
        (!_debugRoleBypassActive &&
            (authenticatedManager == null ||
                FirebaseAuth.instance.currentUser?.uid !=
                    authenticatedManager.uid))) {
      _showSnackBar(
        'Inicia sesión con una cuenta verificada de Gerencia para editar el catálogo TPV.',
      );
      return;
    }
    final nameController = TextEditingController(text: item?.name ?? '');
    final stockController = TextEditingController(
      text: item?.stock.toString() ?? '0',
    );
    final priceController = TextEditingController(
      text: item?.price.toString() ?? '0',
    );
    final descriptionController = TextEditingController(
      text: item?.description ?? '',
    );
    final editorFamilies =
        _posFamilies.isEmpty ? _defaultPosFamilies : _posFamilies;
    var selectedFamilyId = item?.familyId ??
        _familyForCafeCategory(item?.category ?? '')?.id ??
        _selectedAdminPosFamilyId;
    if (!editorFamilies.any(
      (family) =>
          _cafeFamilyIdentity(family.id) ==
          _cafeFamilyIdentity(selectedFamilyId),
    )) {
      selectedFamilyId = editorFamilies.first.id;
    }
    Uint8List? selectedImageBytes;
    var imageUrl = item?.imageUrl;
    var isAvailable = item?.isAvailable ?? true;
    var isVisible = item?.isVisible ?? true;
    var stockTracked = item?.stockTracked ?? false;
    String? validationMessage;
    ModalRoute<dynamic>? editorRoute;
    try {
      final draft = await showDialog<_CafeCatalogItemDraft>(
        context: context,
        useRootNavigator: true,
        barrierDismissible: false,
        builder: (dialogContext) {
          editorRoute = ModalRoute.of(dialogContext);
          return StatefulBuilder(
            builder: (dialogContext, setDialogState) => Dialog(
              backgroundColor: card,
              insetPadding:
                  const EdgeInsets.symmetric(horizontal: 20, vertical: 16),
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  maxWidth: 560,
                  maxHeight: MediaQuery.sizeOf(dialogContext).height * 0.88,
                ),
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(24, 20, 24, 12),
                  child: Column(
                    children: [
                      Align(
                        alignment: Alignment.centerLeft,
                        child: Text(
                          item == null
                              ? 'Añadir producto TPV'
                              : 'Editar producto TPV',
                          style: const TextStyle(
                            color: white,
                            fontSize: 20,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                      const SizedBox(height: 12),
                      Expanded(
                        child: SingleChildScrollView(
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              const Align(
                                alignment: Alignment.centerLeft,
                                child: Padding(
                                  padding: EdgeInsets.only(bottom: 8),
                                  child: Text(
                                    'EDICIÓN DE GERENCIA · cambia los campos y pulsa GUARDAR',
                                    style: TextStyle(color: gold, fontSize: 10),
                                  ),
                                ),
                              ),
                              TextField(
                                key: const ValueKey('catalog-item-name'),
                                controller: nameController,
                                decoration:
                                    const InputDecoration(labelText: 'Nombre'),
                              ),
                              const SizedBox(height: 10),
                              TextField(
                                key: const ValueKey('catalog-item-price'),
                                controller: priceController,
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                  decimal: true,
                                ),
                                decoration: const InputDecoration(
                                  labelText: 'Precio',
                                  prefixText: 'Bs ',
                                  helperText:
                                      'Usa 0 mientras Gerencia confirma el precio.',
                                ),
                              ),
                              const SizedBox(height: 10),
                              Container(
                                width: double.infinity,
                                height: 150,
                                decoration: BoxDecoration(
                                  color: card2,
                                  borderRadius: BorderRadius.circular(10),
                                  border: Border.all(color: brownDark),
                                ),
                                clipBehavior: Clip.antiAlias,
                                child: selectedImageBytes != null
                                    ? Image.memory(selectedImageBytes!,
                                        fit: BoxFit.cover)
                                    : imageUrl != null
                                        ? Image.network(
                                            imageUrl,
                                            fit: BoxFit.cover,
                                            errorBuilder: (_, __, ___) =>
                                                const Center(
                                              child: Icon(
                                                  Icons.broken_image_outlined,
                                                  color: muted),
                                            ),
                                          )
                                        : item != null
                                            ? _menuProductImage(item)
                                            : const Center(
                                                child: Icon(
                                                    Icons.add_a_photo_outlined,
                                                    color: muted,
                                                    size: 32),
                                              ),
                              ),
                              const SizedBox(height: 8),
                              OutlinedButton.icon(
                                key: const ValueKey('catalog-item-pick-image'),
                                onPressed: () async {
                                  try {
                                    final photo =
                                        await _cafeImagePicker.pickImage(
                                      source: ImageSource.gallery,
                                      imageQuality: 85,
                                      maxWidth: 1600,
                                      maxHeight: 1600,
                                    );
                                    if (photo == null) return;
                                    final sourceBytes =
                                        await photo.readAsBytes();
                                    final bytes = await compute(
                                      _compressCafeImageBytes,
                                      sourceBytes,
                                    );
                                    setDialogState(() {
                                      selectedImageBytes = bytes;
                                    });
                                  } catch (error, stackTrace) {
                                    debugPrint(
                                        'No se pudo seleccionar la foto del producto: $error');
                                    debugPrintStack(stackTrace: stackTrace);
                                    setDialogState(() {
                                      validationMessage =
                                          'No se pudo seleccionar la imagen.';
                                    });
                                  }
                                },
                                icon: const Icon(Icons.photo_library_outlined),
                                label: const Text('CAMBIAR FOTO'),
                              ),
                              const SizedBox(height: 10),
                              const Align(
                                alignment: Alignment.centerLeft,
                                child: Text(
                                  'Para mover este producto, elige la familia correcta y pulsa GUARDAR.',
                                  style: TextStyle(
                                    color: muted,
                                    fontSize: 10,
                                  ),
                                ),
                              ),
                              DropdownButtonFormField<String>(
                                value: editorFamilies
                                    .firstWhere(
                                      (family) =>
                                          _cafeFamilyIdentity(family.id) ==
                                          _cafeFamilyIdentity(selectedFamilyId),
                                      orElse: () => editorFamilies.first,
                                    )
                                    .id,
                                dropdownColor: card2,
                                decoration: const InputDecoration(
                                  labelText: 'Familia del menú',
                                ),
                                items: editorFamilies
                                    .map(
                                      (family) => DropdownMenuItem(
                                        value: family.id,
                                        child: Text(family.name),
                                      ),
                                    )
                                    .toList(),
                                onChanged: (value) {
                                  if (value != null) {
                                    setDialogState(
                                        () => selectedFamilyId = value);
                                  }
                                },
                              ),
                              const SizedBox(height: 10),
                              TextField(
                                key: const ValueKey('catalog-item-description'),
                                controller: descriptionController,
                                enabled: true,
                                style: const TextStyle(color: cream),
                                minLines: 2,
                                maxLines: 4,
                                textCapitalization:
                                    TextCapitalization.sentences,
                                decoration: const InputDecoration(
                                  labelText: 'Descripción editable',
                                  helperText:
                                      'La descripción se guarda al pulsar GUARDAR.',
                                ),
                              ),
                              const SizedBox(height: 10),
                              TextField(
                                key: const ValueKey('catalog-item-stock'),
                                controller: stockController,
                                enabled: true,
                                style: const TextStyle(color: cream),
                                keyboardType: TextInputType.number,
                                textInputAction: TextInputAction.done,
                                onChanged: (_) {
                                  if (!stockTracked) {
                                    setDialogState(() => stockTracked = true);
                                  }
                                },
                                decoration: const InputDecoration(
                                  labelText: 'Unidades que se sacan a tienda',
                                  helperText:
                                      'El TPV descontará una unidad por cada venta.',
                                ),
                              ),
                              SwitchListTile(
                                key: const ValueKey('catalog-item-track-stock'),
                                contentPadding: EdgeInsets.zero,
                                title: const Text(
                                  'Controlar stock y descontar ventas',
                                  style: TextStyle(color: cream, fontSize: 12),
                                ),
                                subtitle: const Text(
                                  'Actívalo para que el menú muestre las unidades '
                                  'y avise a Gerencia cuando llegue a cero.',
                                  style: TextStyle(color: muted, fontSize: 10),
                                ),
                                value: stockTracked,
                                onChanged: (value) =>
                                    setDialogState(() => stockTracked = value),
                              ),
                              SwitchListTile(
                                contentPadding: EdgeInsets.zero,
                                title: const Text(
                                  'Visible en TPV',
                                  style: TextStyle(color: cream, fontSize: 12),
                                ),
                                subtitle: const Text(
                                  'Ocúltalo del catálogo sin borrar el producto ni su inventario.',
                                  style: TextStyle(color: muted, fontSize: 10),
                                ),
                                value: isVisible,
                                onChanged: (value) =>
                                    setDialogState(() => isVisible = value),
                              ),
                              SwitchListTile(
                                contentPadding: EdgeInsets.zero,
                                title: const Text(
                                  'Disponible para venta',
                                  style: TextStyle(color: cream, fontSize: 12),
                                ),
                                value: isAvailable,
                                onChanged: (value) =>
                                    setDialogState(() => isAvailable = value),
                              ),
                              if (validationMessage != null) ...[
                                const SizedBox(height: 10),
                                Text(
                                  validationMessage!,
                                  style:
                                      const TextStyle(color: Color(0xFFE6A296)),
                                ),
                              ],
                            ],
                          ),
                        ),
                      ),
                      const SizedBox(height: 8),
                      Row(
                        mainAxisAlignment: MainAxisAlignment.end,
                        children: [
                          TextButton(
                            onPressed: () => Navigator.pop(dialogContext),
                            child: const Text('CANCELAR'),
                          ),
                          const SizedBox(width: 8),
                          FilledButton(
                            onPressed: () {
                              final name = nameController.text.trim();
                              final description =
                                  descriptionController.text.trim();
                              final priceText = priceController.text.trim();
                              final price = double.tryParse(
                                priceText.replaceAll(',', '.'),
                              );
                              final stockText = stockController.text.trim();
                              final stock = int.tryParse(stockText);
                              final duplicateName = _cafeMenuItems.any(
                                (existing) =>
                                    existing.id != item?.id &&
                                    existing.name.toLowerCase() ==
                                        name.toLowerCase(),
                              );
                              if (name.isEmpty ||
                                  price == null ||
                                  !price.isFinite ||
                                  price < 0 ||
                                  stock == null ||
                                  stock < 0 ||
                                  duplicateName) {
                                setDialogState(
                                  () => validationMessage = duplicateName
                                      ? 'Ya existe un producto con ese nombre.'
                                      : 'Completa nombre, precio y cantidad válida.',
                                );
                                return;
                              }
                              final selectedFamily = editorFamilies.firstWhere(
                                (family) =>
                                    _cafeFamilyIdentity(family.id) ==
                                    _cafeFamilyIdentity(selectedFamilyId),
                                orElse: () => editorFamilies.first,
                              );
                              Navigator.pop(
                                dialogContext,
                                _CafeCatalogItemDraft(
                                  name: name,
                                  description: description,
                                  price: price,
                                  stock: stock,
                                  family: selectedFamily,
                                  imageUrl: imageUrl,
                                  hasImage: (item?.hasImage ?? false) ||
                                      selectedImageBytes != null,
                                  imageBytes: selectedImageBytes,
                                  isAvailable: isAvailable,
                                  isVisible: isVisible,
                                  stockTracked: stockTracked,
                                ),
                              );
                            },
                            child: Text(item == null ? 'AÑADIR' : 'GUARDAR'),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      );
      final route = editorRoute;
      if (route != null) await route.completed;
      if (draft == null || !mounted) return;

      final productId = item?.id ?? _catalogIdFromName(draft.name);
      final manager = _firebaseUser;
      if (!_debugRoleBypassActive) {
        if (manager == null ||
            FirebaseAuth.instance.currentUser?.uid != manager.uid) {
          _showSnackBar(
            'La sesión autenticada cambió. Vuelve a iniciar sesión.',
          );
          return;
        }
        try {
          await _businessOperationsService.saveCatalogProduct(
            productId: productId,
            name: draft.name,
            category: draft.family.name,
            familyId: draft.family.id,
            familyName: draft.family.name,
            description: draft.description,
            price: draft.price,
            stock: draft.stock,
            isAvailable: draft.isAvailable,
            isVisible: draft.isVisible,
            isDeleted: false,
            managerUid: manager.uid,
            stockTracked: draft.stockTracked,
            imageUrl: draft.imageUrl,
            hasImage: draft.hasImage,
            imageBytes: draft.imageBytes,
            updateExisting: _firestoreCafeProductIds.contains(productId),
            inventorySource: _inventoryCatalogMode,
          );
        } on FirebaseException catch (error, stackTrace) {
          debugPrint(
            'No se pudo guardar el producto (${error.code}).',
          );
          debugPrintStack(stackTrace: stackTrace);
          if (mounted) {
            _showSnackBar(
              error.code == 'permission-denied'
                  ? 'Firebase rechazó el cambio: esta cuenta necesita rol Gerencia y reglas actualizadas.'
                  : 'No se pudo guardar el producto (${error.code}).',
            );
          }
          return;
        } catch (error, stackTrace) {
          debugPrint('Error al guardar el producto: $error');
          debugPrintStack(stackTrace: stackTrace);
          if (mounted) {
            _showSnackBar('No se pudo guardar el producto: $error');
          }
          return;
        }
      }

      if (!mounted) return;
      if (draft.imageBytes != null) {
        _cafeMenuImageCache[productId] = Future.value(draft.imageBytes);
      }
      setState(() {
        if (item == null) {
          _cafeMenuItems.add(
            CafeMenuItem(
              id: productId,
              name: draft.name,
              category: draft.family.name,
              familyId: draft.family.id,
              description: draft.description,
              icon: Icons.local_cafe,
              price: draft.price,
              stock: draft.stock,
              stockTracked: draft.stockTracked,
              imageUrl: draft.imageUrl,
              imageBytes: draft.imageBytes,
              hasImage: draft.hasImage,
              isAvailable: draft.isAvailable,
              isVisible: draft.isVisible,
            ),
          );
        } else {
          item
            ..id = productId
            ..name = draft.name
            ..category = draft.family.name
            ..familyId = draft.family.id
            ..description = draft.description
            ..price = draft.price
            ..stock = draft.stock
            ..stockTracked = draft.stockTracked
            ..imageUrl = draft.imageUrl
            ..imageBytes = draft.imageBytes
            ..hasImage = draft.hasImage
            ..isAvailable = draft.isAvailable
            ..isVisible = draft.isVisible;
        }
        if (!draft.isVisible) {
          cart.removeWhere(
            (cartItem) => cartItem['catalogId'] == productId,
          );
        }
      });
      _showSnackBar(
        '${draft.name} se guardó con descripción, cantidad y foto actualizadas.',
      );
    } finally {
      nameController.dispose();
      stockController.dispose();
      priceController.dispose();
      descriptionController.dispose();
    }
  }

  Future<void> _confirmDeleteCafeMenuItem(
    BuildContext dialogParentContext,
    CafeMenuItem item,
  ) async {
    final authenticatedManager = _firebaseUser;
    if (authenticatedManager == null ||
        FirebaseAuth.instance.currentUser?.uid != authenticatedManager.uid) {
      _showSnackBar('Inicia sesión para eliminar productos del catálogo TPV.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: dialogParentContext,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text(
          'Eliminar producto',
          style: TextStyle(color: white),
        ),
        content: Text(
          '¿Quieres eliminar «${item.name}» del catálogo del TPV?',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    if (!_debugRoleBypassActive) {
      final manager = _firebaseUser;
      if (manager == null ||
          FirebaseAuth.instance.currentUser?.uid != manager.uid) {
        _showSnackBar('La sesión autenticada cambió. Vuelve a iniciar sesión.');
        return;
      }
      var imageCleanupFailed = false;
      try {
        await _businessOperationsService.saveCatalogProduct(
          productId: item.id,
          name: item.name,
          category: item.category,
          description: item.description,
          price: item.price,
          stock: item.stock,
          isAvailable: item.isAvailable,
          isVisible: item.isVisible,
          isDeleted: true,
          managerUid: manager.uid,
          hasImage: false,
        );
      } on FirebaseException catch (error, stackTrace) {
        debugPrint('No se pudo eliminar el producto (${error.code}).');
        debugPrintStack(stackTrace: stackTrace);
        _showSnackBar('No se pudo eliminar el producto (${error.code}).');
        return;
      } catch (error) {
        _showSnackBar('No se pudo eliminar el producto: $error');
        return;
      }
      if (item.hasImage) {
        try {
          await FirebaseFirestore.instance
              .collection('cafeMenuImages')
              .doc(item.id)
              .delete();
        } on FirebaseException catch (error, stackTrace) {
          imageCleanupFailed = true;
          debugPrint(
              'No se pudo limpiar la foto del producto (${error.code}).');
          debugPrintStack(stackTrace: stackTrace);
        } catch (error, stackTrace) {
          imageCleanupFailed = true;
          debugPrint('No se pudo limpiar la foto del producto: $error');
          debugPrintStack(stackTrace: stackTrace);
        }
      }
      _cafeMenuImageCache.remove(item.id);
      if (imageCleanupFailed) {
        _showSnackBar(
          'Producto eliminado; no se pudo limpiar su foto guardada.',
        );
      }
    }
    setState(() {
      _cafeMenuItems.remove(item);
      _unavailableItems.remove(item.name);
      cart.removeWhere(
        (cartItem) =>
            cartItem['name'] == item.name && cartItem['shopProductId'] == null,
      );
      if (identical(selectedMenuItem, item)) selectedMenuItem = null;
    });
  }

  Future<void> _exitPosToCustomerHome() async {
    final staff = _firebaseUser;
    if (_canAccessPos &&
        staff != null &&
        !_debugRoleBypassActive &&
        _activePosBarista != null) {
      try {
        final date = DateTime.now();
        final dateKey = _businessOperationsService.dateKey(date);
        final attendanceRef = FirebaseFirestore.instance
            .collection('staffAttendance')
            .doc(_businessOperationsService.attendanceId(dateKey, staff.uid));
        final attendance = await attendanceRef.get();
        if (attendance.exists && attendance.data()?['clockOutAt'] == null) {
          _showSnackBar(
            'Cierra y arquea la caja, luego registra tu salida antes de salir del TPV.',
          );
          return;
        }
      } on FirebaseException catch (error, stackTrace) {
        debugPrint('No se pudo verificar el cierre de turno (${error.code}).');
        debugPrintStack(stackTrace: stackTrace);
        _showSnackBar(
          'No se pudo verificar el cierre de turno (${error.code}).',
        );
        return;
      }
    }
    if (_userRole == 'admin') {
      _activePosBarista = null;
      _adminPosAccessEnabled = false;
      if (!mounted) return;
      setState(() {
        _pageHistory.clear();
        page = 'admin';
        previousPage = 'admin';
      });
      _resetAdminFinanceTimeout();
      return;
    }
    _activePosBarista = null;
    _adminFinanceUnlocked = false;
    _adminFinanceTimeout?.cancel();
    await FirebaseAuth.instance.signOut();
    if (!mounted) return;
    setState(() {
      page = 'login';
      previousPage = 'login';
    });
  }

  Future<void> _reservePosTable(PosTable table) async {
    final nameController = TextEditingController(
      text: table.reservationName ?? '',
    );
    final timeController = TextEditingController(
      text: table.reservationTime ?? '',
    );
    String? validationMessage;
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              'Reservar Mesa ${table.number}',
              style: const TextStyle(color: gold),
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: nameController,
                  autofocus: true,
                  decoration: const InputDecoration(
                    labelText: 'Nombre del cliente',
                    prefixIcon: Icon(Icons.person_outline),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: timeController,
                  decoration: const InputDecoration(
                    labelText: 'Hora (HH:MM)',
                    hintText: '19:30',
                    prefixIcon: Icon(Icons.schedule),
                  ),
                ),
                if (validationMessage != null) ...[
                  const SizedBox(height: 10),
                  Text(
                    validationMessage!,
                    style: const TextStyle(color: Color(0xFFE6A296)),
                  ),
                ],
              ],
            ),
            actions: [
              if (table.status == PosTableStatus.reserved)
                TextButton(
                  onPressed: () {
                    setState(() {
                      table
                        ..status = PosTableStatus.free
                        ..reservationName = null
                        ..reservationTime = null;
                    });
                    Navigator.pop(dialogContext);
                  },
                  child: const Text('CANCELAR RESERVA'),
                ),
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('CERRAR'),
              ),
              FilledButton(
                onPressed: () {
                  final name = nameController.text.trim();
                  final time = timeController.text.trim();
                  final validTime =
                      RegExp(r'^([01]\d|2[0-3]):[0-5]\d$').hasMatch(time);
                  if (name.isEmpty || !validTime) {
                    setDialogState(() {
                      validationMessage =
                          'Escribe el nombre y una hora válida (HH:MM).';
                    });
                    return;
                  }
                  setState(() {
                    table
                      ..status = PosTableStatus.reserved
                      ..reservationName = name
                      ..reservationTime = time;
                  });
                  Navigator.pop(dialogContext);
                },
                child: const Text('GUARDAR RESERVA'),
              ),
            ],
          ),
        ),
      );
    } finally {
      nameController.dispose();
      timeController.dispose();
    }
  }

  void _selectPosTable(PosTable table) {
    if (_activePosBarista == null) {
      _showSnackBar('Inicia el turno de un barista para gestionar mesas.');
      return;
    }
    if (table.status == PosTableStatus.free) {
      setState(() {
        table.status = PosTableStatus.occupied;
        _selectedPosTableNumber = table.number;
        _posShowingTables = false;
      });
      _showSnackBar('Comanda abierta para Mesa ${table.number}.');
      return;
    }
    if (table.status == PosTableStatus.reserved) {
      _showSnackBar(
        'Mesa ${table.number} reservada para ${table.reservationName} · ${table.reservationTime}.',
      );
      return;
    }
    setState(() {
      _selectedPosTableNumber = table.number;
      _posShowingTables = false;
    });
    _showSnackBar('Comanda de Mesa ${table.number} seleccionada.');
  }

  void _releaseSelectedPosTable() {
    final tableNumber = _selectedPosTableNumber;
    if (tableNumber == null) return;
    final table = _posTables.firstWhere((item) => item.number == tableNumber);
    setState(() {
      table
        ..status = PosTableStatus.free
        ..reservationName = null
        ..reservationTime = null;
      _selectedPosTableNumber = null;
    });
  }

  Future<void> _showPosPrintPreview() async {
    final lines = cart.map((item) {
      final quantity = item['qty'] as int;
      final size = item['size'] as String?;
      final notes = item['notes'] as String?;
      return '• $quantity × ${item['name']}'
          '${size == null ? '' : ' · $size'}'
          '${notes == null || notes.trim().isEmpty ? '' : '\n  Nota: ${notes.trim()}'}';
    }).join('\n');
    final now = DateTime.now();
    final time =
        '${now.day.toString().padLeft(2, '0')}/${now.month.toString().padLeft(2, '0')}/${now.year} '
        '${now.hour.toString().padLeft(2, '0')}:${now.minute.toString().padLeft(2, '0')}';
    final total = cart.fold<double>(
      0,
      (sum, item) =>
          sum + (item['price'] as num).toDouble() * (item['qty'] as int),
    );
    setState(() => _isShowingPrintPreview = true);
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          backgroundColor: card,
          title: const Text(
            'Vista previa de comanda',
            style: TextStyle(color: gold),
          ),
          content: SingleChildScrollView(
            child: SelectableText(
              'WOLVES CLUB - COMANDA\n'
              'Fecha: $time\n'
              'Barista: ${_activePosBarista ?? _cartBaristaName ?? '—'}\n'
              'Mesa: ${_selectedPosTableNumber == null ? 'Barra' : 'Mesa $_selectedPosTableNumber'}\n'
              '--------------------------------\n'
              '${lines.isEmpty ? 'Sin productos' : lines}\n'
              '--------------------------------\n'
              'TOTAL: ${_formatPrice(total)}\n\n'
              'Simulación de impresión. Conecta una impresora compatible para imprimir el ticket.',
              style: const TextStyle(
                color: cream,
                height: 1.5,
                fontFamily: 'monospace',
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('CERRAR'),
            ),
            FilledButton.icon(
              onPressed: () {
                Navigator.pop(dialogContext);
                _showSnackBar('Vista previa de comanda lista para imprimir.');
              },
              icon: const Icon(Icons.print),
              label: const Text('LISTO'),
            ),
          ],
        ),
      );
    } finally {
      if (mounted) setState(() => _isShowingPrintPreview = false);
    }
  }

  void _generateBaristaQr() {
    _baristaQrTimer?.cancel();
    _issueBaristaQr();
    _baristaQrTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (_baristaQrSecondsRemaining <= 1) {
        _issueBaristaQr();
        return;
      }
      if (mounted) {
        setState(() {
          _baristaQrSecondsRemaining--;
        });
      }
    });
  }

  void _issueBaristaQr() {
    final expiresAt = DateTime.now().add(const Duration(seconds: 30));
    final qrId = List<int>.generate(
      16,
      (_) => _secureRandom.nextInt(256),
      growable: false,
    );
    final payload =
        'coffee-wolves:cold-brew:${base64UrlEncode(qrId)}:${expiresAt.microsecondsSinceEpoch}';

    setState(() {
      _baristaQrGeneration++;
      _activeBaristaQr = payload;
      _baristaQrExpiresAt = expiresAt;
      _baristaQrSecondsRemaining = 30;
    });
  }

  Future<void> _simulateBaristaScan({
    required String customerId,
    required String figureId,
    required double distanceMeters,
  }) async {
    if (_isProcessingBaristaCanje) return;
    final qrId = _activeBaristaQr;
    final expiresAt = _baristaQrExpiresAt;
    if (qrId == null ||
        expiresAt == null ||
        _baristaQrSecondsRemaining <= 0 ||
        !expiresAt.isAfter(DateTime.now())) {
      setState(() {
        _activeBaristaQr = null;
        _baristaQrExpiresAt = null;
        _baristaQrSecondsRemaining = 0;
      });
      _showBaristaMessage('El QR venció. Genera uno nuevo para continuar.');
      return;
    }
    if (distanceMeters > 50) {
      _showBaristaMessage(
        'Validación simulada rechazada: el cliente está a más de 50 m.',
      );
      return;
    }

    setState(() => _isProcessingBaristaCanje = true);
    if (!_debugRoleBypassActive) {
      final employee = _firebaseUser;
      if (employee == null ||
          employee.emailVerified != true ||
          customerId.trim().isEmpty) {
        setState(() => _isProcessingBaristaCanje = false);
        _showBaristaMessage(
          'Se requiere un cliente identificado y una cuenta de personal '
          'verificada.',
        );
        return;
      }
      try {
        await _rewardAuditService.redeemColdBrewStamp(
          customerUid: customerId.trim(),
          employeeUid: employee.uid,
          employeeEmail: employee.email ?? '',
          qrId: qrId,
          figureId: figureId,
          distanceMeters: distanceMeters,
        );
      } on FirebaseException catch (error, stackTrace) {
        debugPrint('No se pudo guardar el canje Cold Brew: ${error.code}');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          setState(() => _isProcessingBaristaCanje = false);
        }
        _showBaristaMessage(
          'No se confirmó el canje. Firestore rechazó la operación '
          '(${error.code}); no se asignó la figurita.',
        );
        return;
      } on StateError catch (error) {
        if (mounted) {
          setState(() => _isProcessingBaristaCanje = false);
        }
        _showBaristaMessage(error.message);
        return;
      } catch (error, stackTrace) {
        debugPrint('No se pudo confirmar el canje Cold Brew: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          setState(() => _isProcessingBaristaCanje = false);
        }
        _showBaristaMessage(
          'No se confirmó el canje. No se asignó la figurita.',
        );
        return;
      }
    }

    _baristaQrTimer?.cancel();
    setState(() {
      _baristaAuditLog.insert(
        0,
        BaristaAuditEntry(
          scannedAt: DateTime.now(),
          baristaName: _authenticatedBarista,
          customerId: customerId,
          qrId: qrId,
          distanceMeters: distanceMeters,
        ),
      );
      _coldBrewAlbumCounts.update(
        customerId.trim(),
        (count) => count + 1,
        ifAbsent: () => 1,
      );
      _activeBaristaQr = null;
      _baristaQrExpiresAt = null;
      _baristaQrSecondsRemaining = 0;
      _isProcessingBaristaCanje = false;
    });
    await _signalSuccessfulCanje();
    final figureName =
        coldBrewFigures.firstWhere((figure) => figure.id == figureId).name;
    _showBaristaMessage(
      'Figurita $figureName registrada para ${customerId.trim()}.',
    );
  }

  Future<void> _signalSuccessfulCanje() async {
    try {
      await _musicPlayer.playRedemptionSuccess();
    } catch (error, stackTrace) {
      debugPrint(
        'El canje quedó confirmado, pero no se pudo reproducir la señal: $error',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showBaristaMessage(
          'Canje confirmado, pero no se pudo reproducir el sonido. '
          'Revisa el volumen del dispositivo.',
        );
      }
    }
  }

  void _showBaristaMessage(String message) {
    _scaffoldMessengerKey.currentState?.showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

  void _seedDemoCollectibles() {
    for (final entry in wolvesOriginalCharacters.entries) {
      _createCollectible(entry.key, entry.value);
    }
  }

  CollectiblePlush _createCollectible(String modelCode, String character) {
    final serial = (_demoCollectibleSequences[modelCode] ?? 0) + 1;
    _demoCollectibleSequences[modelCode] = serial;
    final plush = CollectiblePlush(
      serial: serial,
      character: character,
      modelCode: modelCode,
      code: '$modelCode-${serial.toString().padLeft(4, '0')}',
    );
    _collectiblePlushes.add(plush);
    return plush;
  }

  void _checkInactivityReminder() {
    if (!mounted ||
        _absenceReminderShown ||
        DateTime.now().difference(_lastPassportVisitAt) <
            const Duration(days: 14)) {
      return;
    }
    _absenceReminderShown = true;
    _scaffoldMessengerKey.currentState?.showSnackBar(
      const SnackBar(
        content: Text(
          'La manada te extraña, tu lugar en el refugio te está esperando',
        ),
        duration: Duration(seconds: 6),
      ),
    );
  }

  String _generateGiftCardCode() {
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    String code;
    do {
      final groups = List.generate(
        3,
        (_) => List.generate(
          4,
          (_) => alphabet[_secureRandom.nextInt(alphabet.length)],
        ).join(),
      );
      code = 'WOLF-${groups[0]}-${groups[1]}-${groups[2]}';
    } while (_giftCards.containsKey(code));
    return code;
  }

