  Future<void> _redeemGiftCard(String enteredCode) async {
    final code = enteredCode.trim().toUpperCase();
    final giftCard = _giftCards[code];
    if (_debugRoleBypassActive) {
      if (giftCard == null) {
        _showBaristaMessage('No encontramos ese código de prueba.');
        return;
      }
      if (giftCard.redeemedBy != null) {
        _showBaristaMessage('Este código ya fue canjeado.');
        return;
      }
      setState(() {
        giftCard.redeemedBy = userName;
        _walletBalance += giftCard.balance;
        giftCard.balance = 0;
      });
      _showBaristaMessage(
        'Canje de prueba completado. El saldo solo existe en esta sesión.',
      );
      return;
    }

    final customer = _firebaseUser;
    if (customer == null) {
      _showBaristaMessage('Inicia sesión para canjear la Gift Card.');
      return;
    }
    try {
      final balance = await _rewardAuditService.redeemGiftCard(
        code: code,
        customerUid: customer.uid,
      );
      if (!mounted) return;
      setState(() {
        if (giftCard != null) {
          giftCard
            ..redeemedBy = customer.uid
            ..balance = 0;
        }
        _walletBalance = balance;
      });
      _showBaristaMessage(
        'Gift Card canjeada. Tu saldo disponible es ${_formatPrice(balance)}.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo canjear la Gift Card: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
      _showBaristaMessage(
        'No se canjeó la Gift Card (${error.code}). No se modificó el saldo.',
      );
    } on StateError catch (error) {
      _showBaristaMessage(error.message);
    }
  }

  Future<void> _refreshWalletBalance(String customerUid) async {
    try {
      final balance = await _rewardAuditService.getWalletBalance(customerUid);
      if (!mounted || _firebaseUser?.uid != customerUid) return;
      setState(() => _walletBalance = balance);
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cargar la billetera: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
    } on StateError catch (error, stackTrace) {
      debugPrint('No se pudo validar la billetera: $error');
      debugPrintStack(stackTrace: stackTrace);
    }
  }

