    final quantityController = TextEditingController(text: '1');
    String? errorMessage;
    var isSaving = false;
    try {
      await showDialog<void>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: const Text(
              'Registrar unidad · Wolves Original Collection',
              style: TextStyle(color: white),
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                DropdownButtonFormField<String>(
                  value: selectedModel,
                  dropdownColor: card2,
                  decoration: const InputDecoration(labelText: 'Personaje'),
                  items: wolvesOriginalCharacters.entries
                      .map(
                        (entry) => DropdownMenuItem(
                          value: entry.key,
                          child: Text('${entry.value} · ${entry.key}'),
                        ),
                      )
                      .toList(),
                  onChanged: isSaving
                      ? null
                      : (value) {
                          if (value != null) {
                            setDialogState(() => selectedModel = value);
                          }
                        },
                ),
                const SizedBox(height: 10),
                TextField(
                  key: const ValueKey('plush-registration-quantity'),
                  controller: quantityController,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Cantidad de unidades',
                    helperText:
                        'Hasta 100; cada unidad recibe su propia serie.',
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  'Código del modelo: $selectedModel\n'
                  'Código individual: $selectedModel-0001 (asignación automática)\n'
                  'Edición: Original Collection · Estado: DISPONIBLE PARA ADOPCIÓN\n'
                  'El sistema crea un QR y una ficha pública de autenticidad por unidad.',
                  style: const TextStyle(
                    color: muted,
                    fontSize: 10,
                    height: 1.5,
                  ),
                ),
                if (errorMessage != null) ...[
                  const SizedBox(height: 10),
                  Text(
                    errorMessage!,
                    style: const TextStyle(color: Color(0xFFE6A296)),
                  ),
                ],
              ],
            ),
            actions: [
              TextButton(
                onPressed: isSaving ? null : () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                key: const ValueKey('confirm-register-plush'),
                onPressed: isSaving
                    ? null
                    : () async {
                        final quantity =
                            int.tryParse(quantityController.text.trim());
                        if (quantity == null ||
                            quantity < 1 ||
                            quantity > 100) {
                          setDialogState(
                            () => errorMessage =
                                'Ingresa una cantidad entre 1 y 100.',
                          );
                          return;
                        }
                        final employee = _firebaseUser;
                        if (!_debugRoleBypassActive &&
                            (employee == null ||
                                employee.emailVerified != true)) {
                          setDialogState(
                            () => errorMessage =
                                'Inicia sesión con una cuenta de personal verificada.',
                          );
                          return;
                        }
                        setDialogState(() {
                          isSaving = true;
                          errorMessage = null;
                        });
                        try {
                          final character =
                              wolvesOriginalCharacters[selectedModel]!;
                          late final List<CollectibleUnitRegistration> units;
                          if (_debugRoleBypassActive) {
                            units = List.generate(quantity, (_) {
                              final plush =
                                  _createCollectible(selectedModel, character);
                              return CollectibleUnitRegistration(
                                modelCode: selectedModel,
                                character: character,
                                serial: plush.serial,
                                code: plush.code,
                              );
                            }, growable: false);
                          } else {
                            units =
                                await _rewardAuditService.registerCollectible(
                              modelCode: selectedModel,
                              character: character,
                              quantity: quantity,
                              employeeUid: employee!.uid,
                            );
                            for (final unit in units) {
                              _collectiblePlushes.add(
                                CollectiblePlush(
                                  serial: unit.serial,
                                  character: unit.character,
                                  modelCode: unit.modelCode,
                                  code: unit.code,
                                ),
                              );
                            }
                          }
                          if (!mounted || !dialogContext.mounted) return;
                          Navigator.pop(dialogContext);
                          setState(() {});
                          await _showRegisteredPlushLabels(units);
                        } on FirebaseException catch (error, stackTrace) {
                          debugPrint(
                            'No se pudo registrar el lote de peluches (${error.code}).',
                          );
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSaving = false;
                            errorMessage =
                                'No se pudo registrar el lote (${error.code}).';
                          });
                        } catch (error, stackTrace) {
                          debugPrint('No se pudo registrar el lote: $error');
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSaving = false;
                            errorMessage = error.toString();
                          });
                        }
                      },
                child: isSaving
                    ? const SizedBox.square(
                        dimension: 18,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Text('REGISTRAR Y GENERAR QRS'),
              ),
            ],
          ),
        ),
      );
    } finally {
      quantityController.dispose();
    }
  }

