  String _plushAuthenticityUrl(String code) =>
      'https://wolves-club-fb24a.web.app/?authenticity=$code';

  Future<void> _claimCollectible(String enteredCode) async {
    final scanned = enteredCode.trim();
    final code =
        (Uri.tryParse(scanned)?.queryParameters['authenticity'] ?? scanned)
            .trim()
            .toUpperCase();
    if (!isValidCollectibleModelUnit(code)) {
      _showBaristaMessage(
          'El QR no contiene un código de unidad Wolves válido.');
      return;
    }
    final plush = _collectiblePlushes.where((item) => item.code == code);
    if (_debugRoleBypassActive) {
      if (plush.isEmpty) {
        _showBaristaMessage('El código no pertenece a un peluche registrado.');
        return;
      }
      final collectible = plush.first;
      if (collectible.claimedBy != null) {
        _showBaristaMessage(
          'Este certificado ya fue reclamado por ${collectible.claimedBy}.',
        );
        return;
      }
      setState(() {
        collectible
          ..claimedBy = userName
          ..claimedAt = DateTime.now();
        _selectedCollectibleCode = collectible.code;
      });
      go('collectibleCertificate');
      return;
    }

    try {
      final publicRecord = await FirebaseFirestore.instance
          .collection('plushAuthenticity')
          .doc(code)
          .get();
      if (!publicRecord.exists) {
        _showBaristaMessage('Esta unidad no está registrada como original.');
        return;
      }
      final customerUid = _firebaseUser?.uid;
      if (customerUid != null) {
        final certificate = await FirebaseFirestore.instance
            .collection('plushCertificates')
            .doc(code)
            .get();
        if (certificate.data()?['ownerUid'] == customerUid) {
          setState(() => _selectedCollectibleCode = code);
          go('collectibleCertificate');
          return;
        }
      }
      setState(() {
        _recordCurrentPageForBack('plushAuthenticity');
        _publicAuthenticityCode = code;
        previousPage = page;
        page = 'plushAuthenticity';
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo verificar la autenticidad del peluche (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      _showBaristaMessage(
        'No se pudo consultar el registro (${error.code}). Inténtalo de nuevo.',
      );
    } catch (error, stackTrace) {
      debugPrint('No se pudo verificar el peluche: $error');
      debugPrintStack(stackTrace: stackTrace);
      _showBaristaMessage('No se pudo verificar la autenticidad del peluche.');
    }
  }

  Widget _plushAuthenticityPage() {
    final code = _publicAuthenticityCode;
    if (code == null) {
      return _authenticityResultCard(
        valid: false,
        title: 'CÓDIGO NO VÁLIDO',
        message: 'No se recibió un código individual válido.',
      );
    }
    return FutureBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      key: ValueKey('public-plush-authenticity-$code'),
      future: FirebaseFirestore.instance
          .collection('plushAuthenticity')
          .doc(code)
          .get(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _authenticityResultCard(
            valid: false,
            title: 'VERIFICACIÓN NO DISPONIBLE',
            message:
                'No se pudo consultar el registro central. Inténtalo nuevamente.',
          );
        }
        if (!snapshot.hasData) {
          return Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                _topBar(title: 'VERIFICACIÓN DE AUTENTICIDAD'),
                const CircularProgressIndicator(color: gold),
              ],
            ),
          );
        }
        final record = snapshot.data!;
        if (!record.exists) {
          return _authenticityResultCard(
            valid: false,
            title: 'UNIDAD NO ENCONTRADA',
            message: '$code no figura en el registro oficial de Coffee Wolves.',
            code: code,
          );
        }
        final data = record.data()!;
        final serial =
            data['serial'] is String ? data['serial'] as String : '----';
        final modelCode = data['modelCode'] is String
            ? data['modelCode'] as String
            : 'CW-PLUSH-???';
        final statusLabel = switch (data['status']) {
          'available' => 'ORIGINAL REGISTRADO',
          'adopted' => 'ENTREGADO · UNIDAD ADOPTADA OFICIALMENTE',
          'reserved' => 'UNIDAD RESERVADA',
          'review' => 'UNIDAD EN REVISIÓN',
          'retired' => 'UNIDAD RETIRADA DEL CATÁLOGO',
          _ => 'ORIGINAL REGISTRADO · ESTADO NO DISPONIBLE',
        };
        final adoptedAt = data['adoptedAt'];
        final dateLabel = adoptedAt is Timestamp
            ? _formatCertificateDate(adoptedAt.toDate())
            : null;
        return _authenticityResultCard(
          valid: true,
          title: statusLabel,
          message: '${data['character'] ?? 'Personaje Wolves'}\n'
              'Modelo: $modelCode\n'
              'Número de serie: $serial\n'
              'Edición: ${data['edition'] ?? 'Original Collection'}'
              '${dateLabel == null ? '' : '\nFecha de adopción: $dateLabel'}',
          code: code,
          modelCode: modelCode,
          isAdopted: data['status'] == 'adopted',
        );
      },
    );
  }

