  String? _collectibleFigureAsset(String modelCode) {
    final assetNumber = switch (modelCode) {
      'CW-PLUSH-001' => 1,
      'CW-PLUSH-002' => 2,
      'CW-PLUSH-003' => 3,
      'CW-PLUSH-004' => 4,
      'CW-PLUSH-005' => 5,
      'CW-PLUSH-006' || 'CW-PLUSH-007' => 6,
      'CW-PLUSH-008' => 4,
      'CW-PLUSH-009' => 2,
      _ => null,
    };
    return assetNumber == null
        ? null
        : 'assets/images/wolves/wolf_$assetNumber.png';
  }

  Widget _collectibleFigureImage({
    required String modelCode,
    required bool inColor,
    double size = 64,
  }) {
    final asset = _collectibleFigureAsset(modelCode);
    if (asset == null) {
      return SizedBox(
        width: size,
        height: size,
        child: const WolvesIcon(icon: BrandIcons.garra, color: gold),
      );
    }

    final image = Image.asset(
      asset,
      width: size,
      height: size,
      fit: BoxFit.contain,
      errorBuilder: (context, error, stackTrace) => WolvesIcon(
        icon: BrandIcons.garra,
        color: gold,
        size: size * 0.55,
      ),
    );
    return Container(
      width: size,
      height: size,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: const Color(0xFF171411),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: const Color(0xFF51483F)),
      ),
      child: inColor
          ? image
          : ColorFiltered(
              colorFilter: const ColorFilter.matrix([
                0.2126,
                0.7152,
                0.0722,
                0,
                0,
                0.2126,
                0.7152,
                0.0722,
                0,
                0,
                0.2126,
                0.7152,
                0.0722,
                0,
                0,
                0,
                0,
                0,
                1,
                0,
              ]),
              child: image,
            ),
    );
  }

