  Future<void> _showCollectibleAdoptionDialog() async {
    final memberController = TextEditingController();
    final ownerNameController = TextEditingController();
    final saleIdController = TextEditingController(text: _lastPosSaleId ?? '');
    String? selectedCode;
    String? errorMessage;
    var isSaving = false;
    final localDemo = _debugRoleBypassActive;
    List<Map<String, dynamic>> availableUnits = [];
    if (localDemo) {
      availableUnits = _collectiblePlushes
          .where((unit) => unit.claimedBy == null)
          .map(
            (unit) => {
              'code': unit.code,
              'character': unit.character,
              'modelCode': unit.modelCode,
              'serial': unit.formattedSerial,
            },
          )
          .toList(growable: false);
    } else {
      final employee = _firebaseUser;
      if (employee == null || employee.emailVerified != true) {
        _showBaristaMessage(
          'Se requiere una cuenta de personal verificada para registrar adopciones.',
        );
        return;
      }
      try {
        final snapshot = await FirebaseFirestore.instance
            .collection('collectiblePlushes')
            .where('claimedBy', isNull: true)
            .limit(200)
            .get();
        availableUnits = snapshot.docs
            .where(
              (doc) =>
                  isValidCollectibleModelUnit(doc.id) &&
                  (doc.data()['inventoryStatus'] == null ||
                      doc.data()['inventoryStatus'] == 'IN_STOCK'),
            )
            .map(
              (doc) => {
                'code': doc.id,
                'character': doc.data()['character'] as String? ?? '',
                'modelCode': doc.data()['modelCode'] as String? ?? '',
                'serial': doc.data()['serial'] as String? ?? '',
              },
            )
            .toList(growable: false)
          ..sort((first, second) => first['code']!.compareTo(second['code']!));
      } on FirebaseException catch (error, stackTrace) {
        debugPrint(
            'No se pudo cargar el inventario de peluches (${error.code}).');
        debugPrintStack(stackTrace: stackTrace);
        _showBaristaMessage(
          'No se pudo cargar el inventario (${error.code}).',
        );
        return;
      }
    }
    if (availableUnits.isEmpty) {
      _showBaristaMessage('No hay unidades disponibles para adopción.');
      return;
    }
    selectedCode = availableUnits.first['code'] as String;
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: const Text(
              'Registrar adopción de unidad vendida',
              style: TextStyle(color: white),
            ),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const Text(
                    'Selecciona la unidad física que ya se vendió. La adopción '
                    'no sustituye ni modifica el registro de venta.',
                    style: TextStyle(color: muted, fontSize: 11, height: 1.4),
                  ),
                  const SizedBox(height: 12),
                  DropdownButtonFormField<String>(
                    value: selectedCode,
                    dropdownColor: card2,
                    decoration: const InputDecoration(
                      labelText: 'Unidad disponible',
                    ),
                    items: availableUnits
                        .map(
                          (unit) => DropdownMenuItem(
                            value: unit['code'] as String,
                            child: Text(
                              '${unit['character']} · ${unit['serial']}',
                            ),
                          ),
                        )
                        .toList(growable: false),
                    onChanged: isSaving
                        ? null
                        : (value) => setDialogState(() => selectedCode = value),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: ownerNameController,
                    textCapitalization: TextCapitalization.words,
                    decoration: const InputDecoration(
                      labelText: 'Nombre del titular (opcional)',
                    ),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: memberController,
                    decoration: const InputDecoration(
                      labelText: 'Wolves Member Card (opcional)',
                      hintText: 'CW-000001 o UID',
                    ),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: saleIdController,
                    decoration: const InputDecoration(
                      labelText: 'ID de venta del TPV (opcional)',
                      hintText: 'Se completa con la última venta local',
                    ),
                  ),
                  if (errorMessage != null) ...[
                    const SizedBox(height: 10),
                    Text(
                      errorMessage!,
                      style: const TextStyle(color: Color(0xFFE6A296)),
                    ),
                  ],
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: isSaving ? null : () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                key: const ValueKey('confirm-plush-adoption'),
                onPressed: isSaving
                    ? null
                    : () async {
                        final code = selectedCode;
                        if (code == null) {
                          setDialogState(
                            () => errorMessage = 'Selecciona una unidad.',
                          );
                          return;
                        }
                        final memberInput = memberController.text.trim();
                        final ownerName = ownerNameController.text.trim();
                        final employee = _firebaseUser;
                        if (!localDemo &&
                            (employee == null ||
                                employee.emailVerified != true)) {
                          setDialogState(
                            () => errorMessage =
                                'Se requiere una cuenta de personal verificada.',
                          );
                          return;
                        }
                        setDialogState(() {
                          isSaving = true;
                          errorMessage = null;
                        });
                        try {
                          String? ownerUid;
                          if (memberInput.isNotEmpty) {
                            ownerUid = await _memberCardService
                                .resolveUserUid(memberInput);
                            final profile = await FirebaseFirestore.instance
                                .collection('users')
                                .doc(ownerUid)
                                .get();
                            if (!profile.exists) {
                              throw StateError(
                                'No existe una Wolves Member Card para ese código.',
                              );
                            }
                          }
                          if (localDemo) {
                            final unit = _collectiblePlushes.firstWhere(
                              (item) => item.code == code,
                            );
                            unit
                              ..claimedByUid = ownerUid
                              ..claimedBy =
                                  ownerName.isEmpty ? 'Adoptado' : ownerName
                              ..claimedAt = DateTime.now();
                          } else {
                            await _rewardAuditService.adoptCollectible(
                              code: code,
                              employeeUid: employee!.uid,
                              employeeEmail: employee.email ?? '',
                              ownerUid: ownerUid,
                              ownerName: ownerName.isEmpty ? null : ownerName,
                              saleId: saleIdController.text.trim().isEmpty
                                  ? null
                                  : saleIdController.text.trim(),
                            );
                          }
                          if (!mounted || !dialogContext.mounted) return;
                          await _signalSuccessfulCanje();
                          if (!mounted || !dialogContext.mounted) return;
                          Navigator.pop(dialogContext);
                          setState(() => _selectedCollectibleCode = code);
                          go('collectibleCertificate');
                        } on FirebaseException catch (error, stackTrace) {
                          debugPrint(
                            'No se pudo registrar la adopción (${error.code}).',
                          );
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSaving = false;
                            errorMessage =
                                'No se pudo registrar la adopción (${error.code}).';
                          });
                        } catch (error, stackTrace) {
                          debugPrint(
                              'No se pudo registrar la adopción: $error');
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSaving = false;
                            errorMessage = error.toString();
                          });
                        }
                      },
                child: isSaving
                    ? const SizedBox.square(
                        dimension: 18,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Text('CONFIRMAR ADOPCIÓN Y CERTIFICAR'),
              ),
            ],
          ),
        ),
      );
    } finally {
      memberController.dispose();
      ownerNameController.dispose();
      saleIdController.dispose();
    }
  }

