  Future<void> _validateSelectedPassportMethod(String customerUid) async {
    final employee = _firebaseUser;
    final methodName = _selectedPassportValidationMethod;
    if (customerUid.contains('/')) {
      setState(() {
        _passportValidationError =
            'El ID de Member Card no puede contener “/”.';
      });
      return;
    }
    if (_debugRoleBypassActive ||
        employee == null ||
        employee.emailVerified != true) {
      setState(() {
        _passportValidationError =
            'Valida métodos con una cuenta de personal verificada.';
      });
      return;
    }

    setState(() {
      _isValidatingPassportMethod = true;
      _passportValidationError = null;
    });
    try {
      final resolvedUid =
          await _memberCardService.resolveMemberCardUserUid(customerUid);
      final progress = await FirebaseFirestore.instance
          .collection('passportProgress')
          .doc(resolvedUid)
          .get();
      final completedMethods =
          (progress.data()?['completedMethods'] as List<dynamic>? ??
                  const <dynamic>[])
              .whereType<String>()
              .toSet();
      if (completedMethods.contains(methodName)) {
        setState(() {
          _passportValidationError =
              '$methodName ya está completado para este usuario.';
        });
        return;
      }

      final confirmed = await showDialog<bool>(
        context: context,
        builder: (confirmationContext) => AlertDialog(
          backgroundColor: card,
          title: const Text(
            'Confirmar validación',
            style: TextStyle(color: cream),
          ),
          content: SelectableText(
            'Método exacto: $methodName\n'
            'Wolves Member Card: $customerUid\n'
            'ID de usuario: $resolvedUid\n'
            'Validado por: ${_authenticatedBarista.isNotEmpty ? _authenticatedBarista : employee.email ?? employee.uid}',
            style: const TextStyle(color: cream2, height: 1.5),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(confirmationContext, false),
              child: const Text('VOLVER'),
            ),
            FilledButton(
              key: const ValueKey('confirm-passport-method-audit'),
              onPressed: () => Navigator.pop(confirmationContext, true),
              child: const Text('CONFIRMAR Y REGISTRAR'),
            ),
          ],
        ),
      );
      if (confirmed != true || !mounted) return;

      await _rewardAuditService.stampPassportMethod(
        customerUid: resolvedUid,
        employeeUid: employee.uid,
        employeeEmail: employee.email ?? '',
        methodName: methodName,
        validMethodNames: methods.map((method) => method.name).toList(),
      );
      if (!mounted) return;
      _showBaristaMessage(
        'Método "$methodName" validado para la Member Card $customerUid.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo validar el método Passport (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        setState(() {
          _passportValidationError =
              'No se pudo validar el método (${error.code}).';
        });
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo validar el método Passport: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        setState(() {
          _passportValidationError = error.toString();
        });
      }
    } finally {
      if (mounted) {
        setState(() => _isValidatingPassportMethod = false);
      }
    }
  }

  Widget _passportValidationMethodPicker({
    required String customerUid,
    required String selectedMethod,
    required bool isSaving,
    required ValueChanged<String> onSelect,
  }) {
    if (customerUid.isEmpty) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const Text(
            'Ingresa el ID CW-XXXXXX o el contenido del QR de la Member Card para ver el avance.',
            style: TextStyle(color: muted, fontSize: 10),
          ),
          const SizedBox(height: 8),
          _passportValidationGrid(
            completedMethods: const {},
            selectedMethod: selectedMethod,
            isSaving: isSaving,
            onSelect: onSelect,
          ),
        ],
      );
    }
    if (customerUid.contains('/')) {
      return const Padding(
        padding: EdgeInsets.symmetric(vertical: 12),
        child: Text(
          'El ID de Member Card no puede contener “/”.',
          style: TextStyle(color: Color(0xFFE6A296), fontSize: 11),
        ),
      );
    }
    return FutureBuilder<String>(
      key: ValueKey('passport-card-lookup-$customerUid'),
      future: _memberCardService.resolveMemberCardUserUid(customerUid),
      builder: (context, lookupSnapshot) {
        if (lookupSnapshot.hasError) {
          return _managementStatusCard(
            'No se pudo identificar la Member Card: ${lookupSnapshot.error}',
            error: true,
          );
        }
        if (!lookupSnapshot.hasData) {
          return const LinearProgressIndicator(color: gold);
        }
        return _passportProgressPickerForUid(
          lookupSnapshot.data!,
          selectedMethod: selectedMethod,
          isSaving: isSaving,
          onSelect: onSelect,
        );
      },
    );
  }

  Widget _passportProgressPickerForUid(
    String customerUid, {
    required String selectedMethod,
    required bool isSaving,
    required ValueChanged<String> onSelect,
  }) {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      key: ValueKey('passport-progress-picker-$customerUid'),
      stream: FirebaseFirestore.instance
          .collection('passportProgress')
          .doc(customerUid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _managementStatusCard(
            'No se pudo leer el Passport de este usuario: ${snapshot.error}',
            error: true,
          );
        }
        final completedMethods =
            (snapshot.data?.data()?['completedMethods'] as List<dynamic>? ??
                    const <dynamic>[])
                .whereType<String>()
                .toSet();
        final pending = methods
            .where((method) => !completedMethods.contains(method.name))
            .map((method) => method.name)
            .toList(growable: false);
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (!snapshot.hasData)
              const LinearProgressIndicator(color: gold)
            else
              Text(
                'AVANCE DEL PASSPORT · ${completedMethods.intersection(methods.map((method) => method.name).toSet()).length}/9 COMPLETADOS',
                style: const TextStyle(
                  color: gold,
                  fontSize: 9,
                  letterSpacing: 0.8,
                  fontWeight: FontWeight.w600,
                ),
              ),
            if (snapshot.hasData && pending.isNotEmpty) ...[
              const SizedBox(height: 5),
              Text(
                'Le faltan: ${pending.join(' · ')}',
                style: const TextStyle(
                  color: muted,
                  fontSize: 9,
                  height: 1.35,
                ),
              ),
            ],
            if (snapshot.hasData && pending.isEmpty) ...[
              const SizedBox(height: 5),
              const Text(
                'Completó los 9 métodos. Ya puede reclamar la taza legendaria.',
                style: TextStyle(color: green, fontSize: 10),
              ),
            ],
            const SizedBox(height: 8),
            _passportValidationGrid(
              completedMethods: completedMethods,
              selectedMethod: selectedMethod,
              isSaving: isSaving,
              onSelect: onSelect,
            ),
          ],
        );
      },
    );
  }

  Widget _passportValidationGrid({
    required Set<String> completedMethods,
    required String selectedMethod,
    required bool isSaving,
    required ValueChanged<String> onSelect,
  }) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 420;
        return GridView.builder(
          key: const ValueKey('passport-method-validation-grid'),
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: methods.length,
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 3,
            crossAxisSpacing: compact ? 5 : 8,
            mainAxisSpacing: compact ? 5 : 8,
            childAspectRatio: compact ? 0.72 : 0.95,
          ),
          itemBuilder: (context, index) {
            final method = methods[index];
            final completed = completedMethods.contains(method.name);
            final selected = selectedMethod == method.name;
            return InkWell(
              key: ValueKey('passport-method-option-${method.name}'),
              onTap: isSaving || completed ? null : () => onSelect(method.name),
              borderRadius: BorderRadius.circular(9),
              child: Container(
                padding: EdgeInsets.all(compact ? 4 : 6),
                decoration: BoxDecoration(
                  color: completed ? const Color(0xFF263027) : card2,
                  borderRadius: BorderRadius.circular(9),
                  border: Border.all(
                    color: completed
                        ? green
                        : selected
                            ? gold
                            : brownDark,
                    width: selected || completed ? 1.5 : 1,
                  ),
                ),
                child: Column(
                  children: [
                    Expanded(
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(6),
                        child: Stack(
                          fit: StackFit.expand,
                          children: [
                            Image.asset(
                              method.imageAsset,
                              fit: BoxFit.cover,
                              errorBuilder: (context, error, stackTrace) =>
                                  Container(
                                color: card,
                                alignment: Alignment.center,
                                child: Icon(
                                  method.icon,
                                  color: gold,
                                  size: compact ? 22 : 30,
                                ),
                              ),
                            ),
                            if (completed)
                              Container(
                                color: Colors.black.withValues(alpha: 0.42),
                                alignment: Alignment.center,
                                child: const Icon(
                                  Icons.check_circle,
                                  color: green,
                                  size: 26,
                                ),
                              ),
                          ],
                        ),
                      ),
                    ),
                    SizedBox(height: compact ? 3 : 5),
                    Text(
                      method.name,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: completed ? green : cream,
                        fontSize: compact ? 8 : 10,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      completed
                          ? 'COMPLETADO'
                          : selected
                              ? 'SELECCIONADO'
                              : 'PENDIENTE',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: completed
                            ? green
                            : selected
                                ? gold
                                : muted,
                        fontSize: compact ? 6 : 7,
                        letterSpacing: 0.3,
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  Future<void> _showLegendaryMugRedemptionDialog() async {
    final customerController = TextEditingController();
    final codeController = TextEditingController();
    String? errorMessage;
    var isSaving = false;
