  Widget _rootPage() {
    final user =
        _staffLoginDialogOpen ? _staffLoginDialogInitialUser : _firebaseUser;
    if (page == 'plushAuthenticity' || page == 'splash') {
      return _authenticatedAppScaffold();
    }
    if (kDebugMode && _debugRoleBypassActive && _firebaseUser == null) {
      return _authenticatedAppScaffold();
    }
    if (!_staffLoginDialogOpen && _authStateError != null) {
      return _authenticationGate(null, authError: _authStateError);
    }
    if (!_staffLoginDialogOpen && !_authStateReady) {
      return Scaffold(
        backgroundColor: bg,
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const CircularProgressIndicator(color: gold),
              const SizedBox(height: 18),
              Text(
                'Conectando con Coffee Wolves…',
                style: TextStyle(
                  color: cream.withValues(alpha: 0.85),
                  fontSize: 14,
                ),
              ),
            ],
          ),
        ),
      );
    }
    if (user != null && _isLoadingRole) {
      return const Scaffold(
        backgroundColor: bg,
        body: Center(child: CircularProgressIndicator(color: gold)),
      );
    }
    if (user != null && _canAccessPos) {
      return _authenticatedAppScaffold();
    }
    if (user == null) {
      return _authenticationGate(user);
    }
    return _authenticatedAppScaffold();
  }

