                  const Text(
                    'COFFEE WOLVES',
                    style: TextStyle(
                      color: gold,
                      fontSize: 13,
                      letterSpacing: 3,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 24),
                  if (authError != null) ...[
                    const Text(
                      'No pudimos restaurar la sesión. Puedes volver a '
                      'iniciar sesión.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: cream),
                    ),
                    const SizedBox(height: 8),
                    SelectableText(
                      authError.toString(),
                      textAlign: TextAlign.center,
                      style: const TextStyle(color: muted, fontSize: 11),
                    ),
                    const SizedBox(height: 12),
                  ],
                  ProfileAuthForm(
                    key: const ValueKey('required-account-registration'),
                    initialMode: ProfileAuthMode.signIn,
                    onAuthenticated: _onAuthenticated,
                    onAvatarSelected: _onProfilePhotoSelected,
                  ),
                  const SizedBox(height: 24),
                  const Text(
                    'ACCESO DE PERSONAL',
                    style: TextStyle(
                      color: gold,
                      fontSize: 11,
                      letterSpacing: 1.5,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 10),
                  Builder(
                    builder: (buttonContext) => Row(
                      children: [
                        Expanded(
                          child: _staffAccessButton(
                            key: const ValueKey('staff-pos-login'),
                            label: 'TPV · Personal',
                            icon: Icons.point_of_sale_outlined,
                            onPressed: () => _openStaffAccess(buttonContext),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: _staffAccessButton(
                            key: const ValueKey('staff-management-login'),
