  Widget _authenticatedAppScaffold() {
    return LayoutBuilder(
      builder: (context, constraints) {
        if (_userRole == 'admin' && _adminFinanceUnlocked && page == 'admin') {
          return _adminWorkspaceShell(
            desktop: constraints.maxWidth >= 1000,
            compactRail:
                constraints.maxWidth >= 720 && constraints.maxWidth < 1000,
          );
        }
        return Scaffold(
          backgroundColor:
              page == 'splash' || page == 'barista' || page == 'baristaAudit'
                  ? Colors.black
                  : bg,
          floatingActionButton: _showCartFloatingActionButton
              ? FloatingActionButton(
                  key: const ValueKey('customer-cart-floating-action'),
                  heroTag: 'customer-cart',
                  tooltip: 'Abrir carrito',
                  backgroundColor: gold,
                  foregroundColor: bg,
                  onPressed: () => go('cart'),
                  child: Badge(
                    key: const ValueKey('customer-cart-badge'),
                    isLabelVisible: _cartQuantity > 0,
                    backgroundColor: Colors.red,
                    textColor: white,
                    label: Text(
                      _cartQuantity > 99 ? '99+' : '$_cartQuantity',
                    ),
                    child: const Icon(Icons.shopping_cart),
                  ),
                )
              : null,
          floatingActionButtonLocation: FloatingActionButtonLocation.endFloat,
          body: SafeArea(
            child: Listener(
              behavior: HitTestBehavior.translucent,
              onPointerDown: (_) {
                if (page == 'admin' ||
                    (page == 'pos' && _userRole == 'admin')) {
                  _resetAdminFinanceTimeout();
                }
              },
              child: Column(
                children: [
                  Expanded(
                    child: page == 'mischiefWall' || page == 'lostPet'
                        ? _screen()
                        : SingleChildScrollView(child: _screen()),
                  ),
                  if (_showBottomBar()) _bottomBar(),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  bool get _showCartFloatingActionButton =>
      !_isStaffRole &&
      cart.isNotEmpty &&
      const {'shop', 'cafeMenu', 'shopProductDetail', 'product'}.contains(page);

