  bool _showBottomBar() {
    if (_isStaffRole || _userRole == 'admin') return false;

    const hidden = {
      'splash',
      'login',
      'register',
      'barista',
      'baristaAudit',
      'pos',
      'coldBrewAlbum',
      'product',
      'passportDetail',
      'eventDetail',
      'cart',
      'payment',
      'success',
      'chat',
      'match',
      'matchWelcome',
      'matchProfiles',
      'matchCelebration',
      'wolvesMatch',
      'dateConfirmation',
      'menu',
      'collectibleCertificate',
      'plushAuthenticity',
      'shopProductDetail',
      'admin',
    };

    return !hidden.contains(page);
  }

  // ==========================================================
  // SCREEN ROUTER
  // ==========================================================

  Widget _screen() {
    if (page == 'plushAuthenticity') return _plushAuthenticityPage();
    final authenticatedUser = _firebaseUser;
    if (authenticatedUser != null &&
        !authenticatedUser.isAnonymous &&
        !authenticatedUser.emailVerified) {
      return _emailVerificationPage();
    }
    if (page == 'pos' && !_canAccessPos) {
      return const Center(
        child: Text(
          'No tienes permiso para acceder a esta pantalla.',
          style: TextStyle(color: cream),
        ),
      );
    }
    if (const {'barista', 'baristaAudit'}.contains(page) && !_isStaffRole) {
      return const Center(
        child: Text(
          'No tienes permiso para acceder a esta pantalla.',
          style: TextStyle(color: cream),
        ),
      );
    }
    if (_isStaffRole && page != 'pos' && page != 'splash') {
      if (page == 'profile') {
        return _profile();
      }
      return const Center(
        child: Text(
          'Las cuentas de barra y caja solo pueden operar en el TPV.',
          style: TextStyle(color: cream),
        ),
      );
    }
    if (_userRole == 'admin' &&
        !const {'admin', 'pos', 'profile', 'splash'}.contains(page)) {
      return const Center(
        child: Text(
          'La cuenta de gerencia solo puede acceder a administración o al TPV.',
          style: TextStyle(color: cream),
        ),
      );
    }
    if (page == 'admin' && (_userRole != 'admin' || !_adminFinanceUnlocked)) {
      return const Center(
        child: Text(
          'Acceso reservado a gerencia.',
          style: TextStyle(color: cream),
        ),
      );
    }
    switch (page) {
      case 'splash':
        return _splash();

      case 'login':
        return _login();

      case 'register':
        return _register();

      case 'emailVerification':
        return _emailVerificationPage();

      case 'barista':
        return _baristaMode();

      case 'pos':
        return _posScreen();

      case 'baristaAudit':
        return _baristaAuditReport();

      case 'admin':
        return _adminDashboard();

      case 'wallet':
        return _wallet();

      case 'collectibles':
        return _collectibles();

      case 'collectibleCertificate':
        return _collectibleCertificate();

      case 'plushAuthenticity':
        return _plushAuthenticityPage();

      case 'home':
        return _home();

      case 'pack':
        return _pack();

      case 'match':
        return _match();

      case 'matchWelcome':
        return _matchWelcome();

      case 'matchProfiles':
        return _matchProfilesScreen();

      case 'matchCelebration':
        return _matchCelebration();

      case 'wolvesMatch':
        return WolvesMatchScreen(
          onClose: back,
          onCompleteProfile: () => go('profile'),
        );

      case 'mischiefWall':
        return MischiefWallScreen(onClose: back);

      case 'lostPet':
        return LostPetScreen(
          onBack: back,
          initialMissionId: _sharedLostPetMissionId,
          onSharedMissionConsumed: () => _sharedLostPetMissionOpened = true,
        );

      case 'legacy':
        return PackLegacyScreen(onBack: back);

      case 'dateConfirmation':
        return _dateConfirmation();

      case 'chat':
        return _chat();

      case 'experience':
        return _experience();

      case 'passport':
        return _passport();

      case 'passportDetail':
        return _passportDetail();

      case 'events':
        return _events();

      case 'eventDetail':
        return _eventDetail();

      case 'challenges':
        return _challenges();

      case 'rewards':
        return _rewards();

      case 'shop':
        return _shop();

      case 'cafeMenu':
        return _cafeMenu();

      case 'shopProductDetail':
        return _shopProductDetail();

      case 'product':
        return _product();

      case 'cart':
        return _cart();

      case 'payment':
        return _payment();

      case 'success':
        return _success();

      case 'orders':
        return _orders();

      case 'pets':
        return _pets();

      case 'profile':
        return _profile();

      case 'journal':
        return _journalScreen();

      case 'memberCard':
        return _memberCard();

      case 'coldBrewAlbum':
        return _coldBrewAlbum();

      case 'badges':
        return _badges();

      case 'stats':
        return _stats();

      case 'menu':
        return _sideMenu();

      default:
        return _home();
    }
  }

