  // ==========================================================
  // SPLASH
  // ==========================================================

  Widget _splash() {
    return SizedBox(
      height: MediaQuery.sizeOf(context).height,
      child: AnimatedBuilder(
        animation: _splashController,
        builder: (context, _) {
          return LayoutBuilder(
            builder: (context, constraints) {
              final center = Offset(
                constraints.maxWidth / 2,
                constraints.maxHeight / 2,
              );
              final garraSize = min(50.0, constraints.maxWidth * 0.13);
              final logoSize = min(142.0, constraints.maxWidth * 0.34);
              final runProgress =
                  (_splashController.value / 0.68).clamp(0.0, 1.0);

              return ColoredBox(
                color: Colors.black,
                child: Stack(
                  children: [
                    for (var i = 0; i < _wolfMotions.length; i++) ...[
                      Builder(
                        builder: (context) {
                          final bounce = sin(
                                runProgress * 8 * pi + i * pi,
                              ) *
                              7 *
                              (1 - runProgress);
                          final stride = sin(
                                runProgress * 8 * pi + i * pi,
                              ) *
                              0.045 *
                              (1 - runProgress);
                          return Positioned(
                            left: center.dx -
                                garraSize / 2 +
                                _wolfMotions[i].value.dx * constraints.maxWidth,
                            top: center.dy -
                                garraSize / 2 +
                                _wolfMotions[i].value.dy *
                                    constraints.maxHeight,
                            child: Transform.translate(
                              offset: Offset(0, bounce),
                              child: Transform.rotate(
                                angle: stride,
                                child: Transform.scale(
                                  scale: 0.82 + runProgress * 0.18,
                                  child: WolvesIcon(
                                    icon: BrandIcons.garra,
                                    key: ValueKey('wolf-splash-$i'),
                                    color: gold,
                                    size: garraSize,
                                    shadows: const [
                                      Shadow(
                                        color: Color(0x66C6A06A),
                                        blurRadius: 14,
                                      ),
                                    ],
                                  ),
                                ),
                              ),
                            ),
                          );
                        },
                      ),
                    ],
                    Center(
                      child: FadeTransition(
                        opacity: _splashLogoFade,
                        child: ScaleTransition(
                          scale: _splashLogoScale,
                          child: Image.asset(
                            'assets/images/coffee_wolves_logo.webp',
                            key: const ValueKey('splash-coffee-wolves-logo'),
                            width: logoSize,
                            height: logoSize,
                            fit: BoxFit.contain,
                          ),
                        ),
                      ),
                    ),
                    Positioned(
                      bottom: max(28.0, constraints.maxHeight * 0.09),
                      left: 0,
                      right: 0,
                      child: _splashNeedsGesture
                          ? Center(
                              child: TweenAnimationBuilder<double>(
                                tween: Tween(
                                  begin: 0.58,
                                  end: _splashPulseForward ? 1.0 : 0.58,
                                ),
                                duration: const Duration(milliseconds: 1100),
                                curve: Curves.easeInOut,
                                onEnd: () {
                                  if (mounted) {
                                    setState(() {
                                      _splashPulseForward =
                                          !_splashPulseForward;
                                    });
                                  }
                                },
                                builder: (context, glow, child) {
                                  return Container(
                                    decoration: BoxDecoration(
                                      borderRadius: BorderRadius.circular(30),
                                      boxShadow: [
                                        BoxShadow(
                                          color: gold.withValues(
                                            alpha: 0.12 + glow * 0.16,
                                          ),
                                          blurRadius: 12 + glow * 10,
                                          spreadRadius: glow * 1.2,
                                        ),
                                      ],
                                    ),
                                    child: child,
                                  );
                                },
                                child: OutlinedButton.icon(
                                  key: const ValueKey(
                                    'join-the-pack-splash-button',
                                  ),
                                  onPressed: _splashAudioStarting
                                      ? null
                                      : () => unawaited(
                                            _startSplashSequence(),
                                          ),
                                  icon: const WolvesIcon(
                                    icon: BrandIcons.garra,
                                    color: gold,
                                    size: 18,
                                  ),
                                  label: const Text('UNIRSE A LA MANADA'),
                                  style: OutlinedButton.styleFrom(
                                    foregroundColor: gold,
                                    side: const BorderSide(
                                      color: gold,
                                      width: 1.4,
                                    ),
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 26,
                                      vertical: 15,
                                    ),
                                    textStyle: const TextStyle(
                                      fontSize: 13,
                                      fontWeight: FontWeight.w500,
                                      letterSpacing: 1.5,
                                    ),
                                    shape: const StadiumBorder(),
                                  ),
                                ),
                              ),
                            )
                          : const Text(
                              'COFFEE WOLVES',
                              textAlign: TextAlign.center,
                              style: TextStyle(
                                color: gold,
                                fontSize: 12,
                                fontWeight: FontWeight.w300,
                                letterSpacing: 4,
                              ),
                            ),
                    ),
                  ],
                ),
              );
            },
          );
        },
      ),
    );
  }

