  Widget _posWolvesShopCatalog() {
    return StreamBuilder<List<Product>>(
      stream: _productCatalogService.getWolvesShopItems(includeHidden: true),
      builder: (context, snapshot) {
        if (!snapshot.hasData && !snapshot.hasError) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 16),
            child: LinearProgressIndicator(color: gold),
          );
        }
        final firestoreProducts =
            snapshot.hasData ? snapshot.data! : const <Product>[];
        return StreamBuilder<Set<String>>(
          stream: _watchWolvesShopFallbackExclusions(),
          builder: (context, exclusionsSnapshot) {
            if (exclusionsSnapshot.hasError) {
              return _managementStatusCard(
                'No se pudo cargar el catálogo de Wolves Shop.',
                error: true,
              );
            }
            final excludedIds = exclusionsSnapshot.data ?? const <String>{};
            final firestoreById = {
              for (final product in firestoreProducts) product.id: product,
            };
            final cards = <Widget>[];
            for (final localProduct in _shopProducts) {
              if (localProduct.category == 'Coleccionables' ||
                  excludedIds.contains(localProduct.id)) {
                continue;
              }
              final firestoreProduct = firestoreById.remove(localProduct.id);
              if (_canAccessPos && firestoreProduct == null) continue;
              if (firestoreProduct != null && !firestoreProduct.isVisible) {
                continue;
              }
              cards.add(
                _wolvesShopProductCard(
                  localProduct: localProduct,
                  firestoreProduct: firestoreProduct,
                ),
              );
            }
            for (final firestoreProduct in firestoreById.values) {
              if (!firestoreProduct.isVisible) continue;
              cards.add(
                _wolvesShopProductCard(firestoreProduct: firestoreProduct),
              );
            }
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (snapshot.hasError)
                  _managementStatusCard(
                    'No se pudo sincronizar Firestore: ${snapshot.error}. '
                    'No se podrán cobrar artículos de Wolves Shop.',
                    error: true,
                  ),
                if (snapshot.hasError) const SizedBox(height: 8),
                if (cards.isEmpty)
                  const Padding(
                    padding: EdgeInsets.all(20),
                    child: Text(
                      'No hay productos cargados en Wolves Shop.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: muted),
                    ),
                  )
                else
                  LayoutBuilder(
                    builder: (context, constraints) {
                      final columns = constraints.maxWidth >= 960
                          ? 4
                          : constraints.maxWidth >= 620
                              ? 3
                              : 2;
                      return GridView(
                        key: const ValueKey('pos-wolves-shop-products-grid'),
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: columns,
                          crossAxisSpacing: 10,
                          mainAxisSpacing: 10,
                          childAspectRatio:
                              constraints.maxWidth < 620 ? 0.68 : 0.82,
                        ),
                        children: cards,
                      );
                    },
                  ),
              ],
            );
          },
        );
      },
    );
  }

  Widget _wolvesShopProductImage({
    required String productId,
    required String? imageUrl,
    required String? imageAsset,
    required IconData fallbackIcon,
    required BoxFit fit,
    double? width,
    double? height,
  }) {
    var resolvedImageAsset = imageAsset;
    if (resolvedImageAsset == null) {
      for (final product in _shopProducts) {
        if (product.id == productId) {
          resolvedImageAsset = product.imageAsset;
          break;
        }
      }
    }

    Widget fallback() {
      if (imageUrl?.isNotEmpty == true) {
        return Image.network(
          imageUrl!,
          width: width,
          height: height,
          fit: fit,
          errorBuilder: (context, error, stackTrace) =>
              WolvesIcon(icon: fallbackIcon, color: gold),
        );
      }
      if (resolvedImageAsset != null) {
        return Image.asset(
          resolvedImageAsset,
          width: width,
          height: height,
          fit: fit,
          errorBuilder: (context, error, stackTrace) =>
              WolvesIcon(icon: fallbackIcon, color: gold),
        );
      }
      return WolvesIcon(icon: fallbackIcon, color: gold);
    }

    final imageDocumentId = 'wolves-shop-$productId';
    final imageFuture = _wolvesShopImageCache.putIfAbsent(
      imageDocumentId,
      () async {
        final snapshot = await FirebaseFirestore.instance
            .collection('cafeMenuImages')
            .doc(imageDocumentId)
            .get();
        if (!snapshot.exists) return null;
        final encoded = snapshot.data()?['imageBase64'];
        if (encoded is! String || encoded.isEmpty) {
          throw FormatException(
            'La foto guardada para el producto $productId no es válida.',
          );
        }
        try {
          return base64Decode(encoded);
        } on FormatException catch (error, stackTrace) {
          debugPrint(
            'No se pudo decodificar la foto de Wolves Shop ($productId): $error',
          );
          debugPrintStack(stackTrace: stackTrace);
          rethrow;
        }
      },
    );

    return FutureBuilder<Uint8List?>(
      future: imageFuture,
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          debugPrint(
            'No se pudo cargar la foto de Wolves Shop ($productId): '
            '${snapshot.error}',
          );
          return fallback();
        }
        final bytes = snapshot.data;
        if (bytes == null) return fallback();
        return Image.memory(
          bytes,
          width: width,
          height: height,
          fit: fit,
          errorBuilder: (context, error, stackTrace) =>
              WolvesIcon(icon: fallbackIcon, color: gold),
        );
      },
    );
  }

  Widget _wolvesShopProductCard({
    ShopProduct? localProduct,
    Product? firestoreProduct,
  }) {
    final name = firestoreProduct?.name ?? localProduct!.name;
    final category = firestoreProduct?.category ?? localProduct!.category;
    final description =
        firestoreProduct?.description ?? localProduct!.description;
    final price = firestoreProduct?.price ?? localProduct!.price;
    final stock = firestoreProduct?.stock ?? localProduct!.stock;
    final isPersisted = firestoreProduct != null;
    final available = isPersisted
        ? firestoreProduct.isVisible && price > 0 && stock > 0
        : localProduct!.effectiveStatus == ShopItemStatus.available &&
            price > 0 &&
            stock > 0;
    final categoryAndName = _normalizeCafeLabel('$category $name');
    final icon = _wolvesShopProductIcon(categoryAndName);
    final imageAsset =
        localProduct?.imageAsset ?? _wolvesShopFallbackImageAsset;
    final persistedSizeProduct = firestoreProduct;
    final sizeStockLabel = persistedSizeProduct != null &&
            persistedSizeProduct.hasSizes
        ? wolvesShopSizes
            .where(persistedSizeProduct.stockBySize.containsKey)
            .map((size) {
            final units = persistedSizeProduct.stockBySize[size]!;
            return '$size: ${units > 0 ? units : 'Agotado'}';
          }).join(' · ')
        : localProduct?.hasSizes == true
            ? localProduct!.variants.values
                .map((variant) =>
                    '${variant.size}: ${variant.stock > 0 ? variant.stock : 'Agotado'}')
                .join(' · ')
            : null;
    return InkWell(
      key: ValueKey(
          'pos-shop-product-${firestoreProduct?.id ?? localProduct!.id}'),
      onTap: _activePosBarista == null
          ? null
          : isPersisted && available
              ? () {
                  if (firestoreProduct.hasSizes) {
                    unawaited(_selectPosShopSize(firestoreProduct));
                  } else {
                    _addCatalogProductToPosCart(firestoreProduct);
                  }
                }
              : () => _showSnackBar(
                    isPersisted
                        ? 'No hay existencias o precio configurado para $name.'
                        : '$name aún no está sincronizado con Firestore y no se puede cobrar desde el TPV.',
                  ),
      borderRadius: BorderRadius.circular(13),
      child: Container(
        padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: card,
          borderRadius: BorderRadius.circular(13),
          border: Border.all(
            color: available
                ? const Color(0xFF39312A)
                : brownDark.withValues(alpha: 0.7),
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(
              child: Container(
                width: double.infinity,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(10),
                  gradient: const LinearGradient(
                    colors: [Color(0xFF35291F), Color(0xFF191613)],
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                  ),
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(10),
                  child: Padding(
                    padding: const EdgeInsets.all(10),
                    child: _wolvesShopProductImage(
                      productId: firestoreProduct?.id ?? localProduct!.id,
                      imageUrl:
                          firestoreProduct?.imageUrl ?? localProduct?.imageUrl,
                      imageAsset: imageAsset,
                      fallbackIcon: icon,
                      fit: BoxFit.contain,
                      width: double.infinity,
                      height: double.infinity,
                    ),
                  ),
                ),
              ),
            ),
            const SizedBox(height: 8),
            Text(
              category.toUpperCase().replaceAll('_', ' '),
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: cream2,
                fontSize: 8,
                letterSpacing: 0.7,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              name,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: white,
                fontSize: 12,
                fontWeight: FontWeight.w500,
              ),
            ),
            if (description.isNotEmpty) ...[
              const SizedBox(height: 4),
              Text(
                description,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: muted,
                  fontSize: 9,
                  height: 1.2,
                ),
              ),
            ],
            const SizedBox(height: 6),
            Text(
              price > 0 ? _formatPrice(price) : 'Precio pendiente',
              style: const TextStyle(
                color: gold,
                fontSize: 12,
                fontWeight: FontWeight.w600,
              ),
            ),
            const SizedBox(height: 3),
            Text(
              stock > 0 ? 'Disponibles: $stock' : 'Agotado',
              style: TextStyle(
                color: available ? green : muted,
                fontSize: 10,
              ),
            ),
            if (sizeStockLabel != null) ...[
              const SizedBox(height: 3),
              Text(
                sizeStockLabel,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: muted, fontSize: 8),
              ),
            ],
            if (!isPersisted)
              const Padding(
                padding: EdgeInsets.only(top: 3),
                child: Text(
                  'LOCAL · DEMO',
                  style: TextStyle(color: muted, fontSize: 8),
                ),
              ),
          ],
        ),
      ),
    );
  }

  Future<void> _selectPosShopSize(Product product) async {
    final selectedSize = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: Text(
          'Selecciona talla · ${product.name}',
          style: const TextStyle(color: cream),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final size in wolvesShopSizes)
              if (product.stockBySize.containsKey(size))
                ListTile(
                  key: ValueKey('pos-size-${product.id}-$size'),
                  contentPadding: EdgeInsets.zero,
                  title: Text(
                    'Talle $size',
                    style: const TextStyle(color: cream),
                  ),
                  subtitle: Text(
                    product.stockBySize[size]! > 0
                        ? '${product.stockBySize[size]} unidades disponibles'
                        : 'Agotado',
                    style: const TextStyle(color: muted, fontSize: 11),
                  ),
                  trailing: Icon(
                    product.stockBySize[size]! > 0
                        ? Icons.add_circle_outline
                        : Icons.remove_circle_outline,
                    color: product.stockBySize[size]! > 0 ? gold : muted,
                  ),
                  enabled: product.stockBySize[size]! > 0,
                  onTap: product.stockBySize[size]! > 0
                      ? () => Navigator.pop(dialogContext, size)
                      : null,
                ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CANCELAR'),
          ),
        ],
      ),
    );
    if (selectedSize != null) {
      _addCatalogProductToPosCart(product, size: selectedSize);
    }
  }

  IconData _wolvesShopProductIcon(String category) {
    if (category.contains('hoodie') ||
        category.contains('polera') ||
        category.contains('moda') ||
        category.contains('ropa')) {
      return Icons.checkroom_outlined;
    }
    if (category.contains('taza') || category.contains('vaso')) {
      return Icons.local_cafe_outlined;
    }
    if (category.contains('gorra')) return Icons.sports_baseball_outlined;
    if (category.contains('peluche')) return Icons.toys_outlined;
    if (category.contains('termo') || category.contains('tomatodo')) {
      return Icons.water_drop_outlined;
    }
    return Icons.storefront_outlined;
  }

  void _addCatalogProductToPosCart(Product product, {String? size}) {
    if (product.hasSizes &&
        (size == null || !product.stockBySize.containsKey(size))) {
      _showSnackBar('Selecciona una talla disponible para ${product.name}.');
      return;
    }
    if (!product.hasSizes && size != null) {
      _showSnackBar('${product.name} no tiene stock configurado por talla.');
      return;
    }
    final existingIndex = cart.indexWhere(
      (item) =>
          item['catalogCollection'] == 'products' &&
          item['catalogId'] == product.id &&
          item['size'] == size,
    );
    final existingQuantity =
        existingIndex < 0 ? 0 : cart[existingIndex]['qty'] as int;
    final availableStock =
        size == null ? product.stock : product.stockBySize[size]!;
    if (existingQuantity >= availableStock) {
      _showSnackBar(
        size == null
            ? 'No hay más unidades disponibles de ${product.name}.'
            : 'No hay más unidades disponibles de ${product.name}, talle $size.',
      );
      return;
    }
    setState(() {
      if (existingIndex == -1) {
        cart.add({
          'name': product.name,
          'price': product.price,
          'qty': 1,
          'category': product.category,
          'catalogId': product.id,
          'catalogCollection': 'products',
          'stockTracked': true,
          if (size != null) 'size': size,
          if (_activePosBarista != null) 'barista': _activePosBarista,
        });
      } else {
        cart[existingIndex]['qty'] = existingQuantity + 1;
      }
    });
    _showSnackBar('${product.name} agregado a la comanda.');
  }

  Widget _posScreen() {
    final selectedFamily = _posFamilies.firstWhere(
      (family) =>
          _cafeFamilyIdentity(family.id) ==
          _cafeFamilyIdentity(_selectedPosFamilyId),
      orElse: () => _posFamilies.first,
    );
    final searchQuery = _posSearchController.text.trim().toLowerCase();
    final selectedCategories =
        selectedFamily.categories.map(_normalizeCafeLabel).toSet();
    final familyProducts = _cafeMenuItems.where((item) {
      if (!item.isVisible) return false;
      if (_canAccessPos && !_firestoreCafeProductIds.contains(item.id)) {
        return false;
      }
      if (searchQuery.isNotEmpty) {
        return item.name.toLowerCase().contains(searchQuery) ||
            item.category.toLowerCase().contains(searchQuery) ||
            item.description.toLowerCase().contains(searchQuery);
      }
      final category = _canonicalCafeCategory(
        item.category,
        item.name,
        item.description,
      );
      return _cafeFamilyIdentity(_familyForCafeItem(item)?.id ?? '') ==
              _cafeFamilyIdentity(selectedFamily.id) ||
          selectedCategories.contains(_normalizeCafeLabel(category));
    }).toList();
    final total = cart.fold<double>(
      0,
      (sum, item) =>
          sum + (item['price'] as num).toDouble() * (item['qty'] as int),
    );
    final amountReceived = _selectedPaymentMethod == 'cash'
        ? double.tryParse(_posPaymentReceivedController.text.trim()) ?? 0
        : 0.0;
    final change = amountReceived >= total ? amountReceived - total : 0.0;
    return Padding(
      padding: const EdgeInsets.all(18),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              IconButton(
