  Widget _posAttendanceAndCashPanel() {
    final user = _firebaseUser;
    if (user == null) return const SizedBox.shrink();
    if (_debugRoleBypassActive) {
      return _debugRoleBanner(
        'asistencia, caja y ventas no se persisten en modo de demostración',
      );
    }
    final date = DateTime.now();
    final dateKey = _businessOperationsService.dateKey(date);
    final assignmentId =
        _businessOperationsService.assignmentId(dateKey, user.uid);

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('staffShifts')
          .doc(assignmentId)
          .snapshots(),
      builder: (context, assignmentSnapshot) {
        if (assignmentSnapshot.hasError) {
          return _managementStatusCard(
            'No se pudo verificar tu turno asignado.',
            error: true,
          );
        }
        if (!assignmentSnapshot.hasData) {
          return _managementStatusCard('Verificando turno asignado...');
        }
        final assignment = assignmentSnapshot.data!;
        if (!assignment.exists) {
          _cachedStaffShift = null;
          return _managementStatusCard(
            'Gerencia aún no te asignó un turno para hoy.',
          );
        }
        final shift = assignment.data()?['shift'] as String?;
        if (shift == null ||
            !{'morning', 'afternoon', 'night'}.contains(shift)) {
          return _managementStatusCard(
            'La asignación de turno tiene un valor no válido.',
            error: true,
          );
        }
        _cachedStaffShift = shift;
        final attendanceId =
            _businessOperationsService.attendanceId(dateKey, user.uid);

        return Card(
          key: const ValueKey('pos-attendance-cash-controls'),
          color: card,
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  'TURNO ${_staffShiftLabel(shift).toUpperCase()} · '
                  '${_formatCertificateDate(date)}',
                  style: const TextStyle(
                    color: gold,
                    fontSize: 11,
                    letterSpacing: 1,
                  ),
                ),
                const SizedBox(height: 8),
                StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                  stream: FirebaseFirestore.instance
                      .collection('staffAttendance')
                      .doc(attendanceId)
                      .snapshots(),
                  builder: (context, attendanceSnapshot) {
                    if (attendanceSnapshot.hasError) {
                      return _managementStatusCard(
                        'No se pudo consultar la asistencia.',
                        error: true,
                      );
                    }
                    if (!attendanceSnapshot.hasData) {
                      return const LinearProgressIndicator(color: gold);
                    }
                    final attendance = attendanceSnapshot.data!;
                    if (!attendance.exists) {
                      return OutlinedButton.icon(
                        key: const ValueKey('staff-clock-in'),
                        onPressed: () => unawaited(_clockInForShift(shift)),
                        icon: const Icon(Icons.login),
                        label: const Text('REGISTRAR ENTRADA'),
                      );
                    }
                    final clockOutAt = attendance.data()?['clockOutAt'];
                    if (clockOutAt != null) {
                      return _managementStatusCard(
                        'La salida de este turno ya fue registrada.',
                      );
                    }
                    final sessionId = _businessOperationsService.cashSessionId(
                        dateKey, user.uid, shift);
                    return StreamBuilder<
                        DocumentSnapshot<Map<String, dynamic>>>(
                      stream: FirebaseFirestore.instance
                          .collection('cashSessions')
                          .doc(sessionId)
                          .snapshots(),
                      builder: (context, cashSnapshot) {
                        if (cashSnapshot.hasError) {
                          return _managementStatusCard(
                            'No se pudo consultar la caja del turno.',
                            error: true,
                          );
                        }
                        if (!cashSnapshot.hasData) {
                          return const LinearProgressIndicator(color: gold);
                        }
                        final cash = cashSnapshot.data!;
                        if (!cash.exists) {
                          return OutlinedButton.icon(
                            key: const ValueKey('open-cash-session'),
                            onPressed: () =>
                                unawaited(_openCashForShift(shift)),
                            icon: const Icon(Icons.point_of_sale),
                            label: const Text('ABRIR CAJA'),
                          );
                        }
                        if (cash.data()?['status'] == 'open') {
                          return Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              Text(
                                'Caja abierta · Fondo inicial ${_formatPrice((cash.data()?['openingAmount'] as num?)?.toDouble() ?? 0)}',
                                style: const TextStyle(
                                  color: cream,
                                  fontSize: 11,
                                ),
                              ),
                              const SizedBox(height: 8),
                              OutlinedButton.icon(
                                key: const ValueKey('close-cash-session'),
                                onPressed: () =>
                                    unawaited(_closeCashForShift(shift)),
                                icon: const Icon(Icons.lock_clock),
                                label: const Text('CONTAR Y CERRAR CAJA'),
                              ),
                            ],
                          );
                        }
                        return OutlinedButton.icon(
                          key: const ValueKey('staff-clock-out'),
                          onPressed: () async {
                            await _clockOutForShift();
                          },
                          icon: const Icon(Icons.logout),
                          label: const Text('REGISTRAR SALIDA'),
                        );
                      },
                    );
                  },
                ),
              ],
            ),
          ),
        );
      },
    );
  }

