  Widget _baristaLocalTools({bool includeCanjePanel = true}) {
    final giftCards = _giftCards.values.toList()
      ..sort((first, second) => first.code.compareTo(second.code));
    final plushes = _collectiblePlushes
        .where((plush) => plush.claimedBy == null)
        .toList()
      ..sort((first, second) => first.serial.compareTo(second.serial));
    final menuItemsByFamily = <String, List<CafeMenuItem>>{};
    for (final item in _cafeMenuItems) {
      if (_isMerchInventoryCategory(item.category)) continue;
      final category = _canonicalCafeCategory(
        item.category,
        item.name,
        item.description,
      );
      var familyLabel = category.isEmpty ? 'OTROS' : category;
      for (final family in _posFamilies) {
        if (family.categories.any(
          (candidate) =>
              _normalizeCafeLabel(candidate) == _normalizeCafeLabel(category),
        )) {
          familyLabel = family.name;
          break;
        }
      }
      familyLabel = _familyForCafeCategory(category)?.name ?? familyLabel;
      menuItemsByFamily.putIfAbsent(familyLabel, () => []).add(item);
    }
    final orderedMenuFamilies = <String, List<CafeMenuItem>>{};
    for (final family in _posFamilies) {
      final items = menuItemsByFamily.remove(family.name);
      if (items != null) orderedMenuFamilies[family.name] = items;
    }
    final otherFamilies = menuItemsByFamily.keys.toList()..sort();
    for (final family in otherFamilies) {
      orderedMenuFamilies[family] = menuItemsByFamily[family]!;
    }
    final availabilityQuery = _normalizeCafeLabel(_availabilitySearch);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        const Text(
          'OPERACIONES LOCALES',
          style: TextStyle(
            color: gold,
            fontSize: 12,
            letterSpacing: 2,
            fontWeight: FontWeight.w600,
          ),
        ),
        const SizedBox(height: 12),
        if (includeCanjePanel) _baristaCanjePanel(),
        const SizedBox(height: 8),
        _passportMemberCardOperations(),
        const SizedBox(height: 8),
        OutlinedButton.icon(
          key: const ValueKey('register-member-card-holder'),
          onPressed: _showMemberCardRegistrationDialog,
          icon: const Icon(Icons.credit_card_outlined),
          label: const Text('MEMBER CARD'),
          style: OutlinedButton.styleFrom(
            foregroundColor: gold,
            side: BorderSide(color: gold.withValues(alpha: 0.65)),
            minimumSize: const Size.fromHeight(48),
          ),
        ),
        const Padding(
          padding: EdgeInsets.only(top: 4, bottom: 8),
          child: Text(
            'Después de validar la compra, invita al cliente a registrar su perfil de sabor en Mi Bitácora para recordar su favorito.',
            style: TextStyle(color: muted, fontSize: 11, height: 1.4),
          ),
        ),
        const SizedBox(height: 8),
        if (_userRole == 'admin')
          OutlinedButton.icon(
            key: const ValueKey('create-gift-card'),
            onPressed: _showCreateGiftCardDialog,
            icon: const Icon(Icons.card_giftcard),
            label: const Text('GENERAR GIFT CARD'),
            style: OutlinedButton.styleFrom(
              foregroundColor: gold,
              side: BorderSide(color: gold.withValues(alpha: 0.65)),
              minimumSize: const Size.fromHeight(48),
            ),
          ),
        if (giftCards.isNotEmpty) ...[
          const SizedBox(height: 10),
          ...giftCards.map(
            (giftCard) => Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: card,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: const Color(0xFF494139)),
              ),
              child: Row(
                children: [
                  Container(
                    padding: const EdgeInsets.all(4),
                    color: Colors.white,
                    child: QrImageView(
                      data: giftCard.code,
                      size: 58,
                      backgroundColor: Colors.white,
                      padding: EdgeInsets.zero,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(giftCard.code,
                            style: const TextStyle(color: white, fontSize: 11)),
                        const SizedBox(height: 4),
