  Future<void> _replaceCafeCatalogWithInventory() async {
    if (!_canManageCafeCatalog || _isLinkingCafeCatalog) return;
    final manager = _firebaseUser;
    if (manager == null ||
        FirebaseAuth.instance.currentUser?.uid != manager.uid) {
      _showSnackBar('La sesión de gerencia ya no está activa.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text(
          'Reemplazar productos de las familias',
          style: TextStyle(color: cream),
        ),
        content: const Text(
          'Se moverán al TPV los productos visibles de comida, bebidas y '
          'métodos que están en el inventario. Se eliminarán los productos '
          'anteriores del catálogo y los registros de origen después de '
          'copiarlos. Se organizarán en las familias del menú. Wolves Shop '
          'y las unidades serializadas de colección no se modificarán.',
          style: TextStyle(color: cream2, height: 1.4),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('REEMPLAZAR PRODUCTOS'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;

    setState(() => _isLinkingCafeCatalog = true);
    try {
      final firestore = FirebaseFirestore.instance;
      final sourceCollection = firestore.collection('products');
      final catalogCollection = firestore.collection('cafeCatalog');
      final sourceSnapshot = await sourceCollection.get();
      final catalogSnapshot = await catalogCollection.get();
      final sourceDocuments = sourceSnapshot.docs.where((document) {
        final data = document.data();
        final category = data['category'];
        final family = data['family'];
        final name = data['name'];
        final description = data['description'];
        if (category is! String ||
            name is! String ||
            data['isVisible'] != true ||
            family == wolvesShopRootFamily ||
            family == 'Wolves Shop' ||
            _isMerchInventoryCategory(category) ||
            _isMerchInventoryCategory(family is String ? family : '')) {
          return false;
        }
        final normalizedCategory = _normalizeCafeLabel(category);
        final menuFamily = family is String
            ? _familyForCafeFamilyId(family) ?? _familyForCafeCategory(family)
            : null;
        final categoryFamily = _familyForCafeCategory(
          _canonicalCafeCategory(
            category,
            name,
            description is String ? description : '',
          ),
        );
        return normalizedCategory == 'metodos' ||
            foodAndBeverageCategories.any(
              (candidate) =>
                  _normalizeCafeLabel(candidate) == normalizedCategory,
            ) ||
            menuFamily != null ||
            categoryFamily != null ||
            _officialCafeProductForName(name) != null;
      }).toList(growable: false);
      final previouslyMoved = catalogSnapshot.docs
          .where(
            (document) => document.data()['inventorySource'] == 'products',
          )
          .toList(growable: false);

      if (sourceDocuments.isEmpty) {
        if (previouslyMoved.isNotEmpty) {
          if (mounted) {
            setState(() => _inventoryCatalogMode = true);
            _showSnackBar('El inventario ya está trasladado al catálogo TPV.');
          }
        } else if (mounted) {
          _showSnackBar(
            'No se encontraron productos visibles de comida, bebidas o métodos en el inventario.',
          );
        }
        return;
      }

      final sourceProducts = sourceDocuments
          .map((document) => Product.fromFirestore(document))
          .toList(growable: false);
      final sourceDataById = {
        for (final document in sourceDocuments) document.id: document.data(),
      };
      final seenIdentities = <String, String>{};
      for (final document in previouslyMoved) {
        final name = document.data()['name'];
        if (name is String) {
          final identity = _cafeProductIdentity(name);
          final previousId = seenIdentities[identity];
          if (previousId != null && previousId != document.id) {
            throw StateError(
              'Ya hay productos repetidos en el catálogo TPV: $name. '
              'Corrige los registros duplicados antes de sincronizar.',
            );
          }
          seenIdentities[identity] = document.id;
        }
      }
      final familyByProductId = <String, PosFamily>{};
      for (final product in sourceProducts) {
        final identity = _cafeProductIdentity(product.name);
        final existingId = seenIdentities[identity];
        if (existingId != null && existingId != product.id) {
          throw StateError(
            'Hay productos repetidos en el inventario: ${product.name}. '
            'Corrige los registros duplicados antes de mover el catálogo.',
          );
        }
        seenIdentities[identity] = product.id;

        final officialCategory =
            _officialCafeProductForName(product.name)?.category;
        final canonicalCategory = _canonicalCafeCategory(
          product.category,
          product.name,
          product.description,
        );
        final family = _familyForCafeFamilyId(product.family) ??
            _familyForCafeCategory(product.family) ??
            _familyForCafeCategory(canonicalCategory) ??
            (officialCategory == null
                ? null
                : _familyForCafeCategory(officialCategory)) ??
            (_normalizeCafeLabel(product.category) == 'metodos'
                ? _familyForCafeFamilyId('speciality-coffee')
                : null);
        if (family == null) {
          throw StateError(
            'No se encontró una familia del menú para ${product.name}. '
            'Asigna una familia antes de moverlo.',
          );
        }
        familyByProductId[product.id] = family;
      }

      if (FirebaseAuth.instance.currentUser?.uid != manager.uid) {
        throw StateError(
          'La sesión autenticada cambió. Vuelve a iniciar sesión.',
        );
      }

      for (var start = 0; start < sourceProducts.length; start += 400) {
        final end = start + 400 < sourceProducts.length
            ? start + 400
            : sourceProducts.length;
        final batch = firestore.batch();
        for (final product in sourceProducts.sublist(start, end)) {
          final family = familyByProductId[product.id]!;
          final sourceData = sourceDataById[product.id]!;
          batch.set(catalogCollection.doc(product.id), {
            'name': product.name,
            'category': family.name,
            'familyId': family.id,
            'familyName': family.name,
            'description': product.description,
            'price': product.price,
            'stock': product.stock,
            'stockTracked': sourceData['stockTracked'] == true,
            'isAvailable': sourceData['isAvailable'] is bool
                ? sourceData['isAvailable'] as bool
                : true,
            'isVisible': product.isVisible,
            'isDeleted': false,
            'inventorySource': 'products',
            if (product.imageUrl != null && product.imageUrl!.isNotEmpty)
              'imageUrl': product.imageUrl,
            'hasImage': sourceData['hasImage'] == true ||
                (product.imageUrl?.isNotEmpty ?? false),
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
        await batch.commit();
      }

      final importedIds = sourceProducts.map((product) => product.id).toSet();
      final obsoleteCatalogDocuments = catalogSnapshot.docs.where((document) {
        final data = document.data();
        final category = data['category'];
        final isShopProduct = data['family'] == wolvesShopRootFamily ||
            data['family'] == 'Wolves Shop' ||
            _isMerchInventoryCategory(
              category is String ? category : '',
            );
        return !isShopProduct && !importedIds.contains(document.id);
      }).toList(growable: false);
      for (var start = 0;
          start < obsoleteCatalogDocuments.length;
          start += 400) {
        final end = start + 400 < obsoleteCatalogDocuments.length
            ? start + 400
            : obsoleteCatalogDocuments.length;
        final batch = firestore.batch();
        for (final document in obsoleteCatalogDocuments.sublist(start, end)) {
          batch.delete(document.reference);
        }
        await batch.commit();
      }

      for (var start = 0; start < sourceDocuments.length; start += 400) {
        final end = start + 400 < sourceDocuments.length
            ? start + 400
            : sourceDocuments.length;
        final batch = firestore.batch();
        for (final document in sourceDocuments.sublist(start, end)) {
          batch.delete(document.reference);
        }
        await batch.commit();
      }

      if (mounted) {
        setState(() {
          _inventoryCatalogMode = true;
          _firestoreCafeProductIds.addAll(importedIds);
        });
        _showSnackBar(
          '${sourceProducts.length} productos del inventario se organizaron por familia en el catálogo TPV. No se crearon duplicados.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo reemplazar el catálogo TPV con el inventario (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo completar el traslado (${error.code}). Si hubo cambios parciales, vuelve a intentarlo; el proceso conserva los productos ya trasladados.',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error reemplazando el catálogo TPV: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo reemplazar el catálogo: $error');
      }
    } finally {
      if (mounted) setState(() => _isLinkingCafeCatalog = false);
    }
  }

  Future<void> _linkDefaultCafeCatalogToFirestore() async {
    if (!_canManageCafeCatalog || _isLinkingCafeCatalog) return;
    if (_inventoryCatalogMode) {
      _showSnackBar(
        'El catálogo está usando los productos del inventario; no se volverán a agregar productos base.',
      );
      return;
    }
    final manager = _firebaseUser;
    if (manager == null) {
      _showSnackBar('La sesión de gerencia ya no está activa.');
      return;
    }

    setState(() => _isLinkingCafeCatalog = true);
    try {
      final collection = FirebaseFirestore.instance.collection('cafeCatalog');
      final existingSnapshot = await collection.get();
      final existingIds =
          existingSnapshot.docs.map((document) => document.id).toSet();
      final existingProductIdentities = existingSnapshot.docs
          .map((document) => document.data()['name'])
          .whereType<String>()
          .map(_cafeProductIdentity)
          .toSet();
      final catalogItemsById = <String, CafeMenuItem>{
        for (final item in _cafeMenuItems) item.id: item,
      };
      final missingItems = catalogItemsById.values
          .where(
            (item) =>
                !existingIds.contains(item.id) &&
                !existingProductIdentities
                    .contains(_cafeProductIdentity(item.name)),
          )
          .toList(growable: false);

      for (var start = 0; start < missingItems.length; start += 400) {
        final end = start + 400 < missingItems.length
            ? start + 400
            : missingItems.length;
        final batch = FirebaseFirestore.instance.batch();
        for (final item in missingItems.sublist(start, end)) {
          final price = item.price > 0
              ? item.price
              : _knownCafeMenuPrice(item.name, productId: item.id) ?? 0;
          PosFamily? family;
          for (final candidate in _posFamilies) {
            if (candidate.id == item.familyId) {
              family = candidate;
              break;
            }
          }
          family ??=
              _familyForCafeCategory(item.category) ?? _posFamilies.first;
          batch.set(collection.doc(item.id), {
            'name': item.name,
            'category': family.name,
            'familyId': family.id,
            'familyName': family.name,
            'description': item.description,
            'price': price,
            'stock': item.stock,
            'stockTracked': item.stockTracked,
            'isAvailable': true,
            'isVisible': true,
            'isDeleted': false,
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
        await batch.commit();
      }

      if (!mounted) return;
      setState(() {
        _firestoreCafeProductIds.addAll(
          missingItems.map((item) => item.id),
        );
      });
      _showSnackBar(
        missingItems.isEmpty
            ? 'Todos los productos base ya están guardados en Firestore.'
            : 'Se guardaron ${missingItems.length} productos del menú base. '
                'Gerencia ya puede editarlos desde el catálogo.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudieron guardar los productos del menú (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudieron guardar los productos (${error.code}). '
          'Verifica que las reglas Firestore estén desplegadas.',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error guardando los productos del menú base: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudieron guardar los productos del menú.');
      }
    } finally {
      if (mounted) setState(() => _isLinkingCafeCatalog = false);
    }
  }

  Future<void> _publishAndActivateCafeMenu() async {
    if (!_canManageCafeCatalog || _isLinkingCafeCatalog) return;
    final manager = _firebaseUser;
    if (manager == null) {
      _showSnackBar('La sesión de gerencia ya no está activa.');
      return;
    }

    setState(() => _isLinkingCafeCatalog = true);
    try {
      final familiesCollection =
          FirebaseFirestore.instance.collection('cafeFamilies');
      final existingFamilies = await familiesCollection.get();
      final existingFamiliesById = {
        for (final document in existingFamilies.docs) document.id: document,
      };
      final familiesToRestore = _defaultPosFamilies.where((family) {
        final existing = existingFamiliesById[family.id];
        return existing == null || existing.data()['isDeleted'] == true;
      }).toList(growable: false);
      for (var start = 0; start < familiesToRestore.length; start += 400) {
        final end = start + 400 < familiesToRestore.length
            ? start + 400
            : familiesToRestore.length;
        final batch = FirebaseFirestore.instance.batch();
        for (final family in familiesToRestore.sublist(start, end)) {
          batch.set(familiesCollection.doc(family.id), {
            'name': family.name,
            'isDeleted': false,
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
        await batch.commit();
      }

      final collection = FirebaseFirestore.instance.collection('cafeCatalog');
      final snapshot = await collection.get();
      final inventoryCatalogMode = snapshot.docs.any(
        (document) => document.data()['inventorySource'] == 'products',
      );
      final baseItemsById = inventoryCatalogMode
          ? <String, CafeMenuItem>{}
          : <String, CafeMenuItem>{
              for (final item in _defaultCafeMenuItems)
                if (!_isMerchInventoryCategory(item.category)) item.id: item,
              for (final item in _cafeMenuItems)
                if (!_isMerchInventoryCategory(item.category)) item.id: item,
            };
      final baseItemsByIdentity = <String, CafeMenuItem>{
        for (final item in baseItemsById.values)
          _cafeProductIdentity(item.name): item,
      };
      final baseProductIdentities = baseItemsByIdentity.keys.toSet();
      final products = snapshot.docs.where((document) {
        final data = document.data();
        final name = data['name'];
        final isDefaultMenuProduct = name is String &&
            baseProductIdentities.contains(_cafeProductIdentity(name));
        return (data['family'] != wolvesShopRootFamily ||
                isDefaultMenuProduct) &&
            (!_isMerchInventoryCategory(data['category'] as String? ?? '') ||
                baseItemsById.containsKey(document.id) ||
                isDefaultMenuProduct) &&
            (data['isDeleted'] != true ||
                baseItemsById.containsKey(document.id) ||
                isDefaultMenuProduct);
      }).toList(growable: false);
      final existingIds = snapshot.docs.map((document) => document.id).toSet();
      final existingProductIdentities = snapshot.docs
          .map((document) => document.data()['name'])
          .whereType<String>()
          .map(_cafeProductIdentity)
          .toSet();
      final menuItems = baseItemsById.values.toList(growable: false);
      var activatedCount = 0;
      var missingPriceCount = 0;

      for (var start = 0; start < products.length; start += 400) {
        final end =
            start + 400 < products.length ? start + 400 : products.length;
        final batch = FirebaseFirestore.instance.batch();
        for (final document in products.sublist(start, end)) {
          final data = document.data();
          final rawDocumentName = document.data()['name'];
          final baseItem = baseItemsById[document.id] ??
              (rawDocumentName is String
                  ? baseItemsByIdentity[_cafeProductIdentity(rawDocumentName)]
                  : null);
          final restoreDeleted = data['isDeleted'] == true;
          final rawName = data['name'];
          final storedName = rawName is String ? rawName : '';
          final name = restoreDeleted
              ? baseItem?.name ??
                  (storedName.isNotEmpty ? storedName : document.id)
              : storedName.isNotEmpty
                  ? storedName
                  : baseItem?.name ?? document.id;
          final rawDescription = data['description'];
          final storedDescription =
              rawDescription is String ? rawDescription : '';
          final description = restoreDeleted
              ? baseItem?.description ?? storedDescription
              : storedDescription.isNotEmpty
                  ? storedDescription
                  : baseItem?.description ?? '';
          final rawPrice = data['price'];
          final storedPrice = rawPrice is num ? rawPrice.toDouble() : 0.0;
          final price = storedPrice > 0
              ? storedPrice
              : _knownCafeMenuPrice(name, productId: document.id) ??
                  baseItem?.price ??
                  0;
          final rawCategory = data['category'];
          final storedCategory = rawCategory is String ? rawCategory : '';
          final category = restoreDeleted
              ? baseItem?.category ?? storedCategory
              : storedCategory.isNotEmpty
                  ? storedCategory
                  : baseItem?.category ?? '';
          final officialCategory = _officialCafeProductForName(name)?.category;
          final categoryFamily = _familyForCafeCategory(
            _canonicalCafeCategory(category, name, description),
          );
          final officialFamily = officialCategory == null
              ? null
              : _familyForCafeCategory(
                  _canonicalCafeCategory(
                    officialCategory,
                    name,
                    description,
                  ),
                );
          final rawFamilyId = data['familyId'];
          final storedFamilyId =
              restoreDeleted || rawFamilyId is! String ? null : rawFamilyId;
          PosFamily? family = officialFamily;
          family ??= categoryFamily;
          family ??= _familyForCafeFamilyId(storedFamilyId);
          for (final candidate in _posFamilies) {
            if (candidate.id == storedFamilyId) {
              family ??= candidate;
              break;
            }
          }
          family ??= _familyForCafeCategory(baseItem?.category ?? '');
          final familyId = family?.id;
          final storedStock = data['stock'];
          final stock = restoreDeleted || storedStock is! int || storedStock < 0
              ? baseItem?.stock ?? 0
              : storedStock;
          final stockTracked = data['stockTracked'] == true;
          if (price <= 0) missingPriceCount++;
          batch.update(document.reference, {
            'name': name,
            'description': description,
            'category': family?.name ?? category,
            'price': price,
            'stock': stock,
            'stockTracked': stockTracked,
            'isDeleted': false,
            if (familyId != null) 'familyId': familyId,
            if (data['family'] == wolvesShopRootFamily)
              'family': FieldValue.delete(),
            if (family != null) ...{
              'familyName': family.name,
              'category': family.name,
            },
            'isAvailable': true,
            'isVisible': true,
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
          activatedCount++;
        }
        await batch.commit();
      }

      final missingItems = menuItems
          .where(
            (item) =>
                !existingIds.contains(item.id) &&
                !existingProductIdentities
                    .contains(_cafeProductIdentity(item.name)),
          )
          .toList(growable: false);
      for (var start = 0; start < missingItems.length; start += 400) {
        final end = start + 400 < missingItems.length
            ? start + 400
            : missingItems.length;
        final batch = FirebaseFirestore.instance.batch();
        for (final item in missingItems.sublist(start, end)) {
          final price = item.price > 0
              ? item.price
              : _knownCafeMenuPrice(item.name, productId: item.id) ?? 0;
          final family = _familyForCafeCategory(item.category) ??
              _familyForCafeCategory(
                _officialCafeProductForName(item.name)?.category ?? '',
              );
          if (price <= 0) missingPriceCount++;
          batch.set(collection.doc(item.id), {
            'name': item.name,
            'category': family?.name ?? item.category,
            if (family != null) 'familyName': family.name,
            'description': item.description,
            'price': price,
            'stock': item.stock,
            'stockTracked': false,
            if (family != null) 'familyId': family.id,
            'isAvailable': true,
            'isVisible': true,
            'isDeleted': false,
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
          activatedCount++;
        }
        await batch.commit();
      }

      if (!mounted) return;
      _showSnackBar(
        activatedCount == 0
            ? 'No hay productos del menú para publicar.'
            : 'Se publicaron y activaron $activatedCount productos. Los existentes '
                'conservan su control de stock; configura el stock de los nuevos '
                'si quieres descontar las ventas. '
                '${missingPriceCount > 0 ? '$missingPriceCount requieren que Gerencia configure su precio antes de cobrar. ' : ''}'
                'Gerencia puede ocultar o desactivar productos cuando sea necesario.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo publicar el menú (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudieron actualizar los productos (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo publicar el menú: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudieron actualizar los productos del menú.');
      }
    } finally {
      if (mounted) setState(() => _isLinkingCafeCatalog = false);
    }
  }

  Future<void> _showCafeFamilyEditor({
    required BuildContext dialogParentContext,
    PosFamily? family,
  }) async {
    if (!_canEditCafeCatalogInCurrentSession) {
      _showSnackBar('Solo Gerencia puede editar las familias del TPV.');
      return;
    }
    final nameController = TextEditingController(text: family?.name ?? '');
    String? errorMessage;
    var isSaving = false;
    try {
      await showDialog<void>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              family == null ? 'Añadir familia TPV' : 'Editar familia TPV',
              style: const TextStyle(color: white),
            ),
            content: TextField(
              controller: nameController,
              autofocus: true,
              decoration: InputDecoration(
                labelText: 'Nombre de la familia',
                errorText: errorMessage,
              ),
            ),
            actions: [
              TextButton(
                onPressed: isSaving ? null : () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: isSaving
                    ? null
                    : () async {
                        final name = nameController.text.trim();
                        final duplicate = _posFamilies.any(
                          (candidate) =>
                              candidate.id != family?.id &&
                              _normalizeCafeLabel(candidate.name) ==
                                  _normalizeCafeLabel(name),
                        );
                        if (name.isEmpty || duplicate) {
                          setDialogState(
                            () => errorMessage = duplicate
                                ? 'Ya existe una familia con ese nombre.'
                                : 'Escribe un nombre para la familia.',
                          );
                          return;
                        }
                        final familyId = family?.id ??
                            _normalizeCafeProductName(name)
                                .replaceAll(' ', '-');
                        if (familyId.isEmpty) {
                          setDialogState(
                            () => errorMessage =
                                'El nombre debe incluir letras o números para crear el identificador.',
                          );
                          return;
                        }
                        final manager = _firebaseUser;
                        if (!_debugRoleBypassActive &&
                            (manager == null ||
                                FirebaseAuth.instance.currentUser?.uid !=
                                    manager.uid)) {
                          setDialogState(
                            () => errorMessage =
                                'La sesión de gerencia ya no está activa.',
                          );
                          return;
                        }
                        setDialogState(() {
                          isSaving = true;
                          errorMessage = null;
                        });
                        try {
                          if (!_debugRoleBypassActive) {
                            await FirebaseFirestore.instance
                                .collection('cafeFamilies')
                                .doc(familyId)
                                .set({
                              'name': name,
                              'isDeleted': false,
                              'updatedBy': manager!.uid,
                              'updatedAt': FieldValue.serverTimestamp(),
                            }, SetOptions(merge: true));
                          }
                          if (family != null) {
                            final productsToRename = _cafeMenuItems
                                .where((item) => item.familyId == familyId)
                                .toList(growable: false);
                            for (var start = 0;
                                start < productsToRename.length;
                                start += 400) {
                              final batch = FirebaseFirestore.instance.batch();
                              final end = start + 400 < productsToRename.length
                                  ? start + 400
                                  : productsToRename.length;
                              for (final product
                                  in productsToRename.sublist(start, end)) {
                                if (_debugRoleBypassActive) {
                                  product.category = name;
                                  continue;
                                }
                                batch.update(
                                  FirebaseFirestore.instance
                                      .collection('cafeCatalog')
                                      .doc(product.id),
                                  {
                                    'category': name,
                                    'familyName': name,
                                    'updatedBy': manager!.uid,
                                    'updatedAt': FieldValue.serverTimestamp(),
                                  },
                                );
                              }
                              if (!_debugRoleBypassActive) await batch.commit();
                            }
                          }
                          if (mounted) {
                            setState(() {
                              final replacement = PosFamily(
                                id: familyId,
                                name: name,
                                icon: family?.icon ?? Icons.category_outlined,
                                categories: [name],
                              );
                              final index = _posFamilies.indexWhere(
                                (candidate) => candidate.id == familyId,
                              );
                              if (index < 0) {
                                _posFamilies.add(replacement);
                              } else {
                                _posFamilies[index] = replacement;
                              }
                              _selectedAdminPosFamilyId = familyId;
                              _selectedPosFamilyId = familyId;
                            });
                          }
                          if (dialogContext.mounted) {
                            Navigator.pop(dialogContext);
                          }
                          if (mounted) {
                            _showSnackBar(
                              family == null
                                  ? 'Familia "$name" creada y guardada.'
                                  : 'Familia "$name" actualizada.',
                            );
                          }
                        } on FirebaseException catch (error, stackTrace) {
                          debugPrint(
                              'No se pudo guardar la familia (${error.code}).');
                          debugPrintStack(stackTrace: stackTrace);
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              isSaving = false;
                              errorMessage = error.code == 'permission-denied'
                                  ? 'Firebase rechazó el guardado por permisos. Verifica las reglas desplegadas y que la cuenta tenga rol Gerencia.'
                                  : 'No se pudo guardar la familia (${error.code}).';
                            });
                          }
                        } catch (error, stackTrace) {
                          debugPrint(
                              'Error guardando la familia "$name": $error');
                          debugPrintStack(stackTrace: stackTrace);
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              isSaving = false;
                              errorMessage =
                                  'No se pudo guardar la familia: $error';
                            });
                          }
                        }
                      },
                child: isSaving
                    ? const SizedBox(
                        width: 18,
                        height: 18,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Text('GUARDAR'),
              ),
            ],
          ),
        ),
      );
    } finally {
      nameController.dispose();
    }
  }

  Future<void> _setCafeProductEnabled(
    CafeMenuItem item,
    bool enabled,
  ) async {
    final manager = _firebaseUser;
    if (manager == null ||
        FirebaseAuth.instance.currentUser?.uid != manager.uid) {
      _showSnackBar('Inicia sesión para cambiar la disponibilidad del menú.');
      return;
    }
    try {
      await FirebaseFirestore.instance
          .collection('cafeCatalog')
          .doc(item.id)
          .update({
        'isAvailable': enabled,
        'isVisible': enabled,
        'updatedBy': manager.uid,
        'updatedAt': FieldValue.serverTimestamp(),
      });
      if (!mounted) return;
      setState(() {
        item
          ..isAvailable = enabled
          ..isVisible = enabled;
        if (enabled) {
          _unavailableItems.remove(item.name);
        } else {
          _unavailableItems.add(item.name);
          cart.removeWhere((cartItem) => cartItem['catalogId'] == item.id);
        }
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cambiar el estado de ${item.name}: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          error.code == 'permission-denied'
              ? 'Firebase rechazó el cambio: esta cuenta no tiene permisos de Gerencia.'
              : 'No se pudo actualizar ${item.name} (${error.code}).',
        );
      }
    }
  }

  Future<void> _deleteCafeFamily(
    BuildContext dialogParentContext,
    PosFamily family,
  ) async {
    if (!_canEditCafeCatalogInCurrentSession) {
      _showSnackBar('Solo Gerencia puede editar las familias del TPV.');
      return;
    }
    final hasProducts = _cafeMenuItems.any(
      (item) =>
          _cafeFamilyIdentity(item.familyId ?? '') ==
              _cafeFamilyIdentity(family.id) ||
          _cafeFamilyIdentity(
                _familyForCafeCategory(item.category)?.id ?? '',
              ) ==
              _cafeFamilyIdentity(family.id),
    );
    if (hasProducts) {
      _showSnackBar(
        'Mueve o elimina primero los productos de esta familia.',
      );
      return;
    }
    final confirmed = await showDialog<bool>(
      context: dialogParentContext,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text('Eliminar familia', style: TextStyle(color: white)),
        content: Text(
          '¿Eliminar la familia «${family.name}» del catálogo TPV?',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    try {
      if (!_debugRoleBypassActive) {
        final manager = _firebaseUser;
        if (manager == null) {
          _showSnackBar('La sesión de gerencia ya no está activa.');
          return;
        }
        await FirebaseFirestore.instance
            .collection('cafeFamilies')
            .doc(family.id)
            .set({
          'name': family.name,
          'isDeleted': true,
          'updatedBy': manager.uid,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      setState(() {
        _posFamilies.removeWhere((candidate) => candidate.id == family.id);
        if (_posFamilies.isEmpty) _posFamilies.addAll(_defaultPosFamilies);
        if (_selectedAdminPosFamilyId == family.id) {
          _selectedAdminPosFamilyId = _posFamilies.first.id;
        }
        if (_selectedPosFamilyId == family.id) {
          _selectedPosFamilyId = _posFamilies.first.id;
        }
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo eliminar la familia (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) _showSnackBar('No se pudo eliminar la familia.');
    }
  }

  Widget _cafeCatalogAdminSection() {
    if (_firebaseUser == null) return const SizedBox.shrink();
    final selectedFamily = _posFamilies.firstWhere(
      (family) =>
          _cafeFamilyIdentity(family.id) ==
          _cafeFamilyIdentity(_selectedAdminPosFamilyId),
      orElse: () => _posFamilies.first,
    );
    final familyCategories =
        selectedFamily.categories.map(_normalizeCafeLabel).toSet();
    final products = _cafeMenuItems.where((item) {
      final category = _canonicalCafeCategory(
        item.category,
        item.name,
        item.description,
      );
      return _cafeFamilyIdentity(_familyForCafeItem(item)?.id ?? '') ==
              _cafeFamilyIdentity(selectedFamily.id) ||
          familyCategories.contains(_normalizeCafeLabel(category));
    }).toList();
    _sortCafeMenuItemsByMenuOrder(products);
    final unlinkedProductCount = _inventoryCatalogMode
        ? 0
        : _cafeMenuItems
            .where((item) => !_firestoreCafeProductIds.contains(item.id))
            .length;
    return Card(
      color: card,
      child: ExpansionTile(
        key: const ValueKey('barista-cafe-catalog-admin'),
        initiallyExpanded: true,
        leading: const Icon(Icons.edit_note, color: gold),
        title: const Text(
          'ADMINISTRAR CATÁLOGO TPV',
          style: TextStyle(
            color: gold,
            fontSize: 11,
            letterSpacing: 1,
            fontWeight: FontWeight.w600,
          ),
        ),
        subtitle: Text(
          '${_cafeMenuItems.length} productos · '
          '${_firestoreCafeProductIds.length} guardados en Firestore · '
          '${_debugRoleBypassActive ? 'solo esta demo' : 'edición de Gerencia'}',
          style: const TextStyle(color: muted, fontSize: 10),
        ),
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (unlinkedProductCount > 0 && !_inventoryCatalogMode) ...[
                  Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: card2,
                      borderRadius: BorderRadius.circular(9),
                      border: Border.all(color: brownDark),
                    ),
                    child: Text(
                      '$unlinkedProductCount productos del menú base aún no '
                      'están guardados en Firestore. Guárdalos una vez para '
                      'que aparezcan en el TPV; después podrás editarlos '
                      'individualmente.',
                      style: const TextStyle(
                        color: cream2,
                        fontSize: 10,
                        height: 1.4,
                      ),
                    ),
                  ),
                  const SizedBox(height: 8),
                  OutlinedButton.icon(
                    key: const ValueKey('link-default-cafe-catalog'),
                    onPressed: _isLinkingCafeCatalog || _debugRoleBypassActive
                        ? null
                        : _linkDefaultCafeCatalogToFirestore,
                    icon: _isLinkingCafeCatalog
                        ? const SizedBox(
                            width: 16,
                            height: 16,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          )
                        : const Icon(Icons.cloud_upload_outlined),
                    label: Text(
                      _isLinkingCafeCatalog
                          ? 'GUARDANDO PRODUCTOS…'
                          : 'GUARDAR PRODUCTOS BASE EN FIRESTORE',
                    ),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: gold,
                      side: BorderSide(color: gold.withValues(alpha: 0.6)),
                    ),
                  ),
                ],
                OutlinedButton.icon(
                  key: const ValueKey('activate-priced-cafe-products'),
                  onPressed: _isLinkingCafeCatalog || _debugRoleBypassActive
                      ? null
                      : _publishAndActivateCafeMenu,
                  icon: _isLinkingCafeCatalog
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Icon(Icons.store_mall_directory_outlined),
                  label: const Text(
                    'PUBLICAR / ACTUALIZAR TODO EL MENÚ',
                  ),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: gold,
                    side: BorderSide(color: gold.withValues(alpha: 0.6)),
                  ),
                ),
                const SizedBox(height: 8),
                OutlinedButton.icon(
                  key: const ValueKey('activate-stock-shortage-notifications'),
                  onPressed:
                      !_canManageCafeCatalog || _isEnablingStockNotifications
                          ? null
                          : _activateStockNotifications,
                  icon: _isEnablingStockNotifications
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : Icon(
                          _stockNotificationsUid == _firebaseUser?.uid
                              ? Icons.notifications_active_outlined
                              : Icons.notifications_outlined,
                        ),
                  label: Text(
