  Widget _wolvesShopAdminCatalog() {
    return StreamBuilder<List<Product>>(
      stream: _productCatalogService.getAdminWolvesShopItems(),
      builder: (context, snapshot) {
        if (!snapshot.hasData && !snapshot.hasError) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 16),
            child: LinearProgressIndicator(color: gold),
          );
        }
        final cloudProducts =
            snapshot.hasData ? snapshot.data! : const <Product>[];
        final cloudById = {
          for (final product in cloudProducts) product.id: product,
        };
        return StreamBuilder<Set<String>>(
          stream: _watchWolvesShopFallbackExclusions(),
          builder: (context, exclusionsSnapshot) {
            if (exclusionsSnapshot.hasError) {
              return _managementStatusCard(
                'No se pudo cargar el estado de los productos locales: '
                '${exclusionsSnapshot.error}',
                error: true,
              );
            }
            final excludedIds = exclusionsSnapshot.data ?? const <String>{};
            final localProducts = _shopProducts
                .where(
                  (product) =>
                      !cloudById.containsKey(product.id) &&
                      !excludedIds.contains(product.id),
                )
                .toList(growable: false);
            final persistedCards = cloudProducts
                .map((product) => _wolvesShopAdminProductCard(context, product))
                .toList(growable: false);
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (snapshot.hasError)
                  _managementStatusCard(
                    'No se pudo cargar Wolves Shop desde Firestore: '
                    '${snapshot.error}',
                    error: true,
                  ),
                if (snapshot.hasError) const SizedBox(height: 8),
                if (_debugRoleBypassActive)
                  _debugRoleBanner(
                    'CATÁLOGO LOCAL DE PRUEBA · Los cambios se conservan solo durante esta sesión y no se guardan en Firestore.',
                  ),
                OutlinedButton.icon(
                  key: const ValueKey('admin-add-wolves-shop-product'),
                  onPressed: () => unawaited(_createWolvesShopProduct(context)),
                  icon: const Icon(Icons.add),
                  label: Text(
                    _debugRoleBypassActive
                        ? 'AÑADIR PRODUCTO LOCAL'
                        : 'AÑADIR PRODUCTO',
                  ),
                  style: OutlinedButton.styleFrom(
                    foregroundColor: gold,
                    side: BorderSide(color: gold.withValues(alpha: 0.65)),
                    minimumSize: const Size.fromHeight(44),
                  ),
                ),
                if (persistedCards.isNotEmpty) ...[
                  const Padding(
                    padding: EdgeInsets.symmetric(vertical: 10),
                    child: Text(
                      'PRODUCTOS EN FIRESTORE',
                      style: TextStyle(
                        color: gold,
                        fontSize: 10,
                        letterSpacing: 1.2,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  GridView(
                    key: const ValueKey('admin-wolves-shop-products-grid'),
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      crossAxisSpacing: 8,
                      mainAxisSpacing: 8,
                      childAspectRatio: 0.72,
                    ),
                    children: persistedCards,
                  ),
                ],
                if (localProducts.isNotEmpty) ...[
                  Padding(
                    padding: const EdgeInsets.only(top: 16, bottom: 8),
                    child: Text(
                      _debugRoleBypassActive
                          ? 'CATÁLOGO LOCAL DE PRUEBA'
                          : 'PRODUCTOS DISPONIBLES PARA EDITAR',
                      style: const TextStyle(
                        color: gold,
                        fontSize: 10,
                        letterSpacing: 1.1,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  Text(
                    _debugRoleBypassActive
                        ? 'Los cambios de esta sesión son de prueba y no se sincronizan.'
                        : 'Edita el producto para guardar directamente sus cambios en Wolves Shop.',
                    style: const TextStyle(
                      color: muted,
                      fontSize: 10,
                      height: 1.35,
                    ),
                  ),
                  const SizedBox(height: 8),
                  GridView(
                    key:
                        const ValueKey('admin-wolves-shop-local-products-grid'),
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    gridDelegate:
                        const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      crossAxisSpacing: 8,
                      mainAxisSpacing: 8,
                      childAspectRatio: 0.72,
                    ),
                    children: localProducts
                        .map(
                          (product) => _localWolvesShopAdminProductCard(
                              context, product),
                        )
                        .toList(growable: false),
                  ),
                ],
                if (persistedCards.isEmpty && localProducts.isEmpty)
                  const Padding(
                    padding: EdgeInsets.all(18),
                    child: Text(
                      'Aún no hay productos en Wolves Shop.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: muted, fontSize: 11),
                    ),
                  ),
              ],
            );
          },
        );
      },
    );
  }

  Stream<Set<String>> _watchWolvesShopFallbackExclusions() {
    return FirebaseFirestore.instance
        .collection('wolvesShopFallbackExclusions')
        .snapshots()
        .map(
            (snapshot) => snapshot.docs.map((document) => document.id).toSet());
  }

  Widget _wolvesShopAdminProductCard(
    BuildContext context,
    Product product,
  ) {
    final available =
        product.isVisible && product.price > 0 && product.stock > 0;
    return Container(
      key: ValueKey('admin-wolves-shop-product-${product.id}'),
      padding: const EdgeInsets.all(9),
      decoration: BoxDecoration(
        color: card,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: const Color(0xFF39312A)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Container(
              width: double.infinity,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(9),
                gradient: const LinearGradient(
                  colors: [Color(0xFF35291F), Color(0xFF191613)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: _wolvesShopProductImage(
                productId: product.id,
                imageUrl: product.imageUrl,
                imageAsset: null,
                fallbackIcon: _wolvesShopProductIcon(
                  _normalizeCafeLabel('${product.category} ${product.name}'),
                ),
                fit: BoxFit.cover,
                width: double.infinity,
                height: double.infinity,
              ),
            ),
          ),
          const SizedBox(height: 6),
          Text(
            product.name,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: white,
              fontSize: 11,
              fontWeight: FontWeight.w500,
            ),
          ),
          if (product.sku.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 3),
              child: Text(
                'Código: ${product.sku}',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(color: muted, fontSize: 9),
              ),
            ),
          const SizedBox(height: 3),
          Text(
            product.price > 0
                ? _formatPrice(product.price)
                : 'Precio pendiente',
            style: const TextStyle(color: gold, fontSize: 11),
          ),
          Text(
            'Stock: ${product.stock} · '
            '${product.isVisible ? 'Visible' : 'Oculto'}'
            '${available ? '' : product.stock == 0 ? ' · Agotado' : ''}',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: muted, fontSize: 9),
          ),
          if (!_debugRoleBypassActive)
            Row(
              mainAxisAlignment: MainAxisAlignment.end,
              children: [
                IconButton(
                  key: ValueKey('edit-wolves-shop-${product.id}'),
                  tooltip: 'Editar producto',
                  visualDensity: VisualDensity.compact,
                  onPressed: () =>
                      unawaited(_editWolvesShopProduct(context, product)),
                  icon: const Icon(Icons.edit_outlined, color: gold, size: 18),
                ),
                Switch(
                  key: ValueKey('visibility-wolves-shop-${product.id}'),
                  value: product.isVisible,
                  activeColor: gold,
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  onChanged: (visible) => unawaited(
                    _setProductShopVisibility(product, visible),
                  ),
                ),
                IconButton(
                  key: ValueKey('delete-wolves-shop-${product.id}'),
                  tooltip: 'Eliminar producto',
                  visualDensity: VisualDensity.compact,
                  onPressed: () =>
                      unawaited(_deleteWolvesShopProduct(context, product)),
                  icon: const Icon(
                    Icons.delete_outline,
                    color: Color(0xFFE6A296),
                    size: 18,
                  ),
                ),
              ],
            ),
        ],
      ),
    );
  }

  Widget _localWolvesShopAdminProductCard(
    BuildContext context,
