    final sizeStock = product.hasSizes
        ? product.variants.values
            .map((variant) => '${variant.size}:${variant.stock}')
            .join(' · ')
        : null;
    return Container(
      key: ValueKey('admin-local-wolves-shop-${product.id}'),
      padding: const EdgeInsets.all(9),
      decoration: BoxDecoration(
        color: card,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: brownDark),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Container(
              width: double.infinity,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(9),
                gradient: const LinearGradient(
                  colors: [Color(0xFF35291F), Color(0xFF191613)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: _wolvesShopProductImage(
                productId: product.id,
                imageUrl: product.imageUrl,
                imageAsset: product.imageAsset,
                fallbackIcon: product.icon,
                fit: BoxFit.cover,
                width: double.infinity,
                height: double.infinity,
              ),
            ),
          ),
          const SizedBox(height: 6),
          Text(
            product.name,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: white, fontSize: 11),
          ),
          const SizedBox(height: 3),
          Text(
            '${_formatPrice(product.price)} · Stock ${product.stock}',
            style: const TextStyle(color: gold, fontSize: 10),
          ),
          if (product.sku.isNotEmpty)
            Text(
              'Código: ${product.sku}',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: muted, fontSize: 9),
            ),
          if (sizeStock != null)
            Text(
              sizeStock,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(color: muted, fontSize: 8),
            ),
          Row(
            mainAxisAlignment: MainAxisAlignment.end,
            children: [
              IconButton(
                key: ValueKey('edit-local-wolves-shop-${product.id}'),
                tooltip: 'Editar artículo y existencias',
                visualDensity: VisualDensity.compact,
                onPressed: () => unawaited(
                  _editLocalWolvesShopProduct(context, product),
                ),
                icon: const Icon(Icons.edit_outlined, color: gold, size: 18),
              ),
              IconButton(
                key: ValueKey('delete-local-wolves-shop-${product.id}'),
                tooltip: 'Eliminar artículo',
                visualDensity: VisualDensity.compact,
                onPressed: () => unawaited(
                  _deleteLocalWolvesShopProduct(context, product),
                ),
                icon: const Icon(
                  Icons.delete_outline,
                  color: Color(0xFFE6A296),
                  size: 18,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _baristaAuditReport() {
    return Padding(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _topBar(
            title: 'REGISTRO COLD BREW',
            backButton: true,
            menuButton: false,
          ),
          const SizedBox(height: 18),
          Text(
            'Figuritas asignadas: ${_baristaAuditLog.length}',
            style: const TextStyle(color: gold, fontSize: 16),
          ),
          const SizedBox(height: 5),
          Text(
            'Álbum de Cold Brew · ${_coldBrewAlbumCounts.length} clientes',
            style: const TextStyle(color: muted, fontSize: 12),
          ),
          const SizedBox(height: 18),
          ..._coldBrewAlbumCounts.entries.map(
            (entry) => ListTile(
              dense: true,
              leading: const Icon(Icons.local_cafe, color: gold),
              title: Text(
                entry.key,
                style: const TextStyle(color: white),
              ),
              trailing: Text(
                '${entry.value} figurita${entry.value == 1 ? '' : 's'}',
                style: const TextStyle(color: cream2),
              ),
            ),
          ),
          if (_baristaAuditLog.isEmpty)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 32),
              child: Text(
                'Todavía no hay validaciones en esta sesión.',
                textAlign: TextAlign.center,
                style: TextStyle(color: muted),
              ),
            )
          else
            ..._baristaAuditLog.map((entry) {
              final time = entry.scannedAt.toLocal();
              final dateLabel = '${time.year.toString().padLeft(4, '0')}-'
                  '${time.month.toString().padLeft(2, '0')}-'
                  '${time.day.toString().padLeft(2, '0')} '
                  '${time.hour.toString().padLeft(2, '0')}:'
                  '${time.minute.toString().padLeft(2, '0')}:'
                  '${time.second.toString().padLeft(2, '0')}';
              return Card(
                key: ValueKey('barista-audit-${entry.qrId}'),
                color: card,
                child: ListTile(
                  leading: const Icon(Icons.verified, color: gold),
                  title: Text(
                    '${entry.baristaName} → ${entry.customerId}',
                    style: const TextStyle(color: white),
                  ),
                  subtitle: Text(
                    '$dateLabel · ${entry.distanceMeters.toStringAsFixed(0)} m',
                    style: const TextStyle(color: muted, fontSize: 12),
                  ),
                ),
              );
            }),
          const SizedBox(height: 12),
          const Text(
            'Este reporte se conserva solo mientras la app permanece abierta.',
            textAlign: TextAlign.center,
            style: TextStyle(color: muted, fontSize: 11),
          ),
        ],
      ),
    );
  }

  Widget _adminDashboard() {
    return _adminWorkspaceContent();
  }

  Widget _adminWorkspaceContent() {
    switch (_selectedAdminWorkspaceSection) {
      case 'sales':
        return _adminSalesAnalyticsSection();
      case 'orders':
        return _adminShopOrdersSection();
      case 'inventory':
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _cafeCatalogAdminSection(),
            const SizedBox(height: 16),
            _adminInventoryOverviewSection(),
            const SizedBox(height: 12),
            _wolvesShopCatalogAdminSection(),
          ],
        );
      case 'team':
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _adminUsersSection(),
            const SizedBox(height: 16),
            _adminStaffAccessRequestsSection(),
            const SizedBox(height: 16),
            _adminStaffOperationsSection(),
            const SizedBox(height: 16),
            _adminCashSessionsSection(),
          ],
        );
      case 'promotions':
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _adminAnnouncementsSection(),
            const SizedBox(height: 24),
            const Divider(color: Color(0xFF433A34)),
            const SizedBox(height: 16),
            const PackLegacyScreen(canManage: true, showBackButton: false),
          ],
        );
      case 'customers':
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _adminCustomerRewardsSection(),
          ],
        );
      case 'support':
        return _adminComplaintsSection();
      case 'messages':
        return _adminInternalMessagesSection();
      case 'reports':
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _adminSalesAnalyticsSection(),
            const SizedBox(height: 16),
            _adminRewardRedemptionsSection(),
          ],
        );
      case 'management':
        return _adminFullManagementView();
      case 'account':
        return _adminAccountView();
      case 'settings':
        return _adminBusinessSettingsView();
      case 'overview':
      default:
        return _adminOverviewView();
    }
  }

  Widget _adminOverviewView() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Text(
          'Bienvenida, ${userName.isEmpty ? 'Gerencia' : userName}',
          style: const TextStyle(
            color: cream,
            fontSize: 22,
            fontWeight: FontWeight.w500,
          ),
        ),
        const SizedBox(height: 6),
        const Text(
          'Indicadores disponibles en esta sesión. Abre un módulo para consultar sus registros.',
          style: TextStyle(color: muted, fontSize: 12, height: 1.5),
        ),
        const SizedBox(height: 20),
        LayoutBuilder(
          builder: (context, constraints) {
            final columns = constraints.maxWidth >= 900
                ? 4
                : constraints.maxWidth >= 540
                    ? 2
                    : 1;
            return GridView.count(
              crossAxisCount: columns,
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              crossAxisSpacing: 12,
              mainAxisSpacing: 12,
              childAspectRatio: columns == 1 ? 3.2 : 1.7,
              children: [
                _adminMetricCard(
                  Icons.inventory_2_outlined,
                  '${_cafeMenuItems.length}',
                  'Productos de menú cargados',
