  Future<void> _configureManagementUsername({
    required BuildContext dialogParentContext,
  }) async {
    final user = _firebaseUser;
    if (user == null ||
        !_canUseManagementTools ||
        !dialogParentContext.mounted) {
      return;
    }
    final controller = TextEditingController();
    String? errorMessage;
    var saving = false;
    try {
      await showDialog<void>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (context, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: const Text(
              'Configurar Username',
              style: TextStyle(color: cream),
            ),
            content: TextField(
              controller: controller,
              autocorrect: false,
              decoration: InputDecoration(
                labelText: 'Username',
                helperText: 'Único en la app; 3 a 20 caracteres.',
                errorText: errorMessage,
              ),
            ),
            actions: [
              TextButton(
                onPressed:
                    saving ? null : () => Navigator.of(dialogContext).pop(),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: saving
                    ? null
                    : () async {
                        final username = controller.text.trim();
                        final validation =
                            UsernameRegistryService.validate(username);
                        if (validation != null) {
                          setDialogState(() => errorMessage = validation);
                          return;
                        }
                        setDialogState(() {
                          saving = true;
                          errorMessage = null;
                        });
                        try {
                          final firestore = FirebaseFirestore.instance;
                          final managementReference =
                              firestore.collection('management').doc(user.uid);
                          await firestore
                              .runTransaction<void>((transaction) async {
                            final profile =
                                await transaction.get(managementReference);
                            if (!profile.exists) {
                              throw StateError(
                                'No existe la cuenta administrativa '
                                'preconfigurada.',
                              );
                            }
                            await UsernameRegistryService.reserveInTransaction(
                              transaction: transaction,
                              firestore: firestore,
                              uid: user.uid,
                              username: username,
                              role: 'management',
                              previousUsername:
                                  profile.data()?['username'] as String?,
                            );
                            transaction.update(managementReference, {
                              'username': username,
                            });
                          });
                          if (dialogContext.mounted) {
                            Navigator.of(dialogContext).pop();
                          }
                          if (mounted) {
                            _showSnackBar('Username de Gerencia guardado.');
                          }
                        } on UsernameAlreadyTakenException catch (error) {
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              saving = false;
                              errorMessage = error.toString();
                            });
                          }
                        } on FirebaseException catch (error, stackTrace) {
                          debugPrint(
                            'No se pudo guardar el Username de Gerencia '
                            '(${error.code}).',
                          );
                          debugPrintStack(stackTrace: stackTrace);
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              saving = false;
                              errorMessage =
                                  'No se pudo guardar (${error.code}).';
                            });
                          }
                        } on StateError catch (error) {
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              saving = false;
                              errorMessage = error.message;
                            });
                          }
                        } catch (error, stackTrace) {
                          debugPrint(
                            'Error inesperado guardando el Username de Gerencia: $error',
                          );
                          debugPrintStack(stackTrace: stackTrace);
                          if (dialogContext.mounted) {
                            setDialogState(() {
                              saving = false;
                              errorMessage =
                                  'No se pudo guardar el Username. Inténtalo de nuevo.';
                            });
                          }
                        }
                      },
                child: saving
                    ? const SizedBox(
                        width: 18,
                        height: 18,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Text('GUARDAR'),
              ),
            ],
          ),
        ),
      );
    } finally {
      controller.dispose();
    }
  }

