  Widget _adminSalesAnalyticsSection() {
    if (_debugRoleBypassActive) {
      return _adminDemoDataSection(
        icon: Icons.analytics_outlined,
        title: 'DASHBOARD DE VENTAS · DEMO',
        rows: const [
          ListTile(
            dense: true,
            title: Text(
              'Las ventas de prueba no se cuentan como ingresos.',
              style: TextStyle(color: cream),
            ),
          ),
        ],
      );
    }
    return Card(
      color: card,
      child: ExpansionTile(
        leading: const Icon(Icons.analytics_outlined, color: gold),
        title: const Text(
          'DASHBOARD DE VENTAS',
          style: TextStyle(color: cream, fontSize: 11),
        ),
        subtitle: const Text(
          'Hasta las 500 ventas más recientes',
          style: TextStyle(color: muted, fontSize: 10),
        ),
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(14, 0, 14, 14),
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance
                  .collection('cafeSales')
                  .orderBy('paidAt', descending: true)
                  .limit(500)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return _managementStatusCard(
                    'No se pudieron cargar las ventas: ${snapshot.error}',
                    error: true,
                  );
                }
                if (!snapshot.hasData) {
                  return const Center(
                    child: CircularProgressIndicator(color: gold),
                  );
                }
                final sales = snapshot.data!.docs;
                if (sales.isEmpty) {
                  return const Text(
                    'Aún no hay cobros registrados en el TPV.',
                    style: TextStyle(color: muted, fontSize: 11),
                  );
                }
                final selectedFamily = _posFamilies.firstWhere(
                  (family) => family.name == _selectedAdminSalesCategory,
                  orElse: () => _posFamilies.first,
                );
                final categoryFilter = _selectedAdminSalesCategory == 'Todas'
                    ? null
                    : selectedFamily.categories.first;
                var totalRevenue = 0.0;
                var peakHour = -1;
                var peakCount = 0;
                var filteredSaleCount = 0;
                final byPayment = <String, double>{};
                final byStaff = <String, double>{};
                final byCategory = <String, double>{};
                final unitsByCategory = <String, int>{};
                final unitsByProduct = <String, int>{};
                final byHour = <int, int>{};
                for (final sale in sales) {
                  final data = sale.data();
                  final items = (data['items'] as List<dynamic>? ?? const [])
                      .whereType<Map<String, dynamic>>()
                      .toList();
                  for (final item in items) {
                    final category =
                        item['category'] as String? ?? 'SIN CATEGORÍA';
                    final lineTotal =
                        (item['lineTotal'] as num?)?.toDouble() ?? 0;
                    byCategory.update(
                      category,
                      (value) => value + lineTotal,
                      ifAbsent: () => lineTotal,
                    );
                    final quantity = (item['quantity'] as num?)?.toInt() ?? 0;
                    unitsByCategory.update(
                      category,
                      (value) => value + quantity,
                      ifAbsent: () => quantity,
                    );
                    final productName = item['name'] as String? ??
                        item['productId'] as String? ??
                        '';
                    unitsByProduct.update(
                      productName,
                      (value) => value + quantity,
                      ifAbsent: () => quantity,
                    );
                  }
                  final saleTotal = (data['total'] as num?)?.toDouble() ?? 0;
                  final total = categoryFilter == null
                      ? saleTotal
                      : items
                          .where((item) => item['category'] == categoryFilter)
                          .fold<double>(
                            0,
                            (subtotal, item) =>
                                subtotal +
                                ((item['lineTotal'] as num?)?.toDouble() ?? 0),
                          );
                  if (total <= 0) continue;
                  totalRevenue += total;
                  filteredSaleCount++;
                  final method = data['paymentMethod'] as String? ?? 'otro';
                  byPayment.update(method, (value) => value + total,
                      ifAbsent: () => total);
                  final staff =
                      '${data['employeeEmail'] ?? data['employeeUid'] ?? 'Personal'} · ${data['shift'] ?? '-'}';
                  byStaff.update(staff, (value) => value + total,
                      ifAbsent: () => total);
                  final paidAt = data['paidAt'];
                  if (paidAt is Timestamp) {
                    final hour = paidAt.toDate().toLocal().hour;
                    final count = byHour.update(
                      hour,
                      (value) => value + 1,
                      ifAbsent: () => 1,
                    );
                    if (count > peakCount) {
                      peakHour = hour;
                      peakCount = count;
                    }
                  }
                }
                final average = filteredSaleCount == 0
                    ? 0.0
                    : totalRevenue / filteredSaleCount;
                final peakLabel = peakHour < 0
                    ? 'Sin hora disponible'
                    : '${peakHour.toString().padLeft(2, '0')}:00–'
                        '${(peakHour + 1).toString().padLeft(2, '0')}:00';
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    DropdownButtonFormField<String>(
                      value: _selectedAdminSalesCategory,
                      dropdownColor: card2,
                      decoration: const InputDecoration(
                        labelText: 'Filtrar por familia',
                      ),
                      items: [
                        const DropdownMenuItem(
                          value: 'Todas',
                          child: Text('Todas las familias'),
                        ),
                        ..._posFamilies.map(
                          (family) => DropdownMenuItem(
                            value: family.name,
                            child: Text(family.name),
                          ),
                        ),
                      ],
                      onChanged: (category) {
                        if (category != null) {
                          setState(
                            () => _selectedAdminSalesCategory = category,
                          );
                        }
                      },
                    ),
                    const SizedBox(height: 10),
                    Text(
                      'Ingresos registrados: ${_formatPrice(totalRevenue)}',
                      style: const TextStyle(color: white, fontSize: 13),
                    ),
                    Text(
                      'Ticket promedio: ${_formatPrice(average)} · '
                      'Hora pico: $peakLabel ($peakCount ventas) · '
                      '$filteredSaleCount tickets',
                      style: const TextStyle(color: muted, fontSize: 10),
                    ),
                    const SizedBox(height: 10),
                    ...byPayment.entries.map(
                      (entry) => Text(
                        'Pago ${entry.key.toUpperCase()}: ${_formatPrice(entry.value)}',
                        style: const TextStyle(color: cream2, fontSize: 10),
                      ),
                    ),
                    const Divider(color: brownDark),
                    ...byStaff.entries.map(
                      (entry) => Text(
                        '${entry.key}: ${_formatPrice(entry.value)}',
                        style: const TextStyle(color: cream, fontSize: 10),
                      ),
                    ),
                    const Divider(color: brownDark),
                    ...byCategory.entries.map(
                      (entry) => Text(
                        '${entry.key}: ${unitsByCategory[entry.key] ?? 0} unidades · '
                        '${_formatPrice(entry.value)}',
                        style: const TextStyle(color: cream2, fontSize: 9),
                      ),
                    ),
                    const Divider(color: brownDark),
                    ...const [
                      'Pomi Barista',
                      'Samoyedo Barista',
                      'Husky Barista',
                    ].map(
                      (name) => Text(
                        '$name: ${unitsByProduct[name] ?? 0} vendidas en los últimos ${sales.length} cobros',
                        style: const TextStyle(color: cream2, fontSize: 9),
                      ),
                    ),
                  ],
                );
              },
            ),
          ),
        ],
      ),
    );
  }

