                        final safeStatus = const {
                          'new',
                          'reviewing',
                          'resolved'
                        }.contains(status)
                            ? status!
                            : 'new';
                        return Container(
                          key: ValueKey('customer-feedback-${complaint.id}'),
                          margin: const EdgeInsets.only(top: 8),
                          padding: const EdgeInsets.all(10),
                          decoration: BoxDecoration(
                            color: card2,
                            borderRadius: BorderRadius.circular(10),
                            border: Border.all(color: brownDark),
                          ),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              Text(
                                '$feedbackType · '
                                '${data['supportCategory'] ?? data['incident'] ?? 'Otro'} · '
                                'Turno ${_staffShiftLabel(data['shift'] as String?).toLowerCase()}',
                                style: const TextStyle(
                                  color: cream,
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              const SizedBox(height: 5),
                              if ((data['subject'] as String?)?.isNotEmpty ==
                                  true)
                                Text(
                                  data['subject'] as String,
                                  style: const TextStyle(
                                    color: cream,
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              if ((data['subject'] as String?)?.isNotEmpty ==
                                  true)
                                const SizedBox(height: 5),
                              Text(
                                data['details'] as String? ?? '',
                                style: const TextStyle(
                                  color: muted,
                                  fontSize: 10,
                                ),
                              ),
                              if ((data['autoReply'] as String?)
                                      ?.trim()
                                      .isNotEmpty ==
                                  true) ...[
                                const SizedBox(height: 7),
                                Text(
                                  'RESPUESTA AUTOMÁTICA ENVIADA\n'
                                  '${data['autoReply']}',
                                  style: const TextStyle(
                                    color: cream2,
                                    fontSize: 9,
                                    height: 1.4,
