  Widget _customerComplaintStatusChip(
    DocumentReference<Map<String, dynamic>> complaint,
    String value,
    String label,
    String selectedStatus,
  ) {
    return ChoiceChip(
      label: Text(label, style: const TextStyle(fontSize: 9)),
      selected: selectedStatus == value,
      showCheckmark: false,
      visualDensity: VisualDensity.compact,
      padding: const EdgeInsets.symmetric(horizontal: 2),
      selectedColor: gold.withValues(alpha: 0.24),
      backgroundColor: card,
      side: BorderSide(
        color: selectedStatus == value ? gold : brownDark,
      ),
      labelStyle: TextStyle(
        color: selectedStatus == value ? gold : cream2,
      ),
      onSelected: selectedStatus == value
          ? null
          : (_) => unawaited(
                _setCustomerComplaintStatus(complaint, value),
              ),
    );
  }

  Future<void> _openComplaintCustomerProfile(
    String customerUid,
    String? fallbackEmail,
  ) async {
    try {
      final customer = await FirebaseFirestore.instance
          .collection('users')
          .doc(customerUid)
          .get();
      if (!mounted) return;
      final profile = customer.data() ?? const <String, dynamic>{};
      final name = (profile['displayName'] as String?)?.trim();
      final email = (profile['email'] as String?)?.trim();
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => AlertDialog(
          backgroundColor: card,
          title: const Text(
            'Datos del cliente',
            style: TextStyle(color: cream),
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                name?.isNotEmpty == true ? name! : 'Cliente',
                style: const TextStyle(color: cream),
              ),
              const SizedBox(height: 8),
              SelectableText(
                email?.isNotEmpty == true
                    ? email!
                    : fallbackEmail ?? 'Sin correo registrado',
                style: const TextStyle(color: gold),
              ),
              const SizedBox(height: 8),
              SelectableText(
                customerUid,
                style: const TextStyle(color: muted),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('CERRAR'),
            ),
          ],
        ),
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo abrir el perfil del cliente (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo cargar el perfil del cliente.');
      }
    }
  }

  Future<void> _emailComplaintCustomer(
    String email,
    String? orderId,
  ) async {
    final uri = Uri(
      scheme: 'mailto',
      path: email.trim(),
      queryParameters: {
        'subject': 'Wolves Club · Seguimiento de tu mensaje',
        if (orderId?.trim().isNotEmpty == true)
          'body': 'Seguimiento del pedido/ticket ${orderId!.trim()}.',
      },
    );
    try {
      if (!await launchUrl(uri)) {
        _showSnackBar('No se pudo abrir una aplicación de correo.');
      }
    } catch (error, stackTrace) {
      debugPrint('No se pudo abrir el correo de atención: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo abrir una aplicación de correo.');
      }
    }
  }

  Future<void> _setCustomerComplaintStatus(
    DocumentReference<Map<String, dynamic>> complaint,
    String status,
  ) async {
    try {
      await complaint.update({
        'status': status,
        'statusMessage': customerComplaintStatusMessage(status),
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo actualizar el estado del mensaje (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo actualizar el estado (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error inesperado actualizando el mensaje: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo actualizar el estado del mensaje.');
      }
    }
  }

  Widget _productInventoryStreamSection(
    Stream<List<Product>> stream, {
    bool manageShopVisibility = false,
  }) {
    return StreamBuilder<List<Product>>(
      stream: stream,
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _managementStatusCard(
            'No se pudo cargar esta familia de productos: ${snapshot.error}',
            error: true,
          );
        }
        if (!snapshot.hasData) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 8),
            child: LinearProgressIndicator(color: gold),
          );
        }
        final groupedProducts = <String, List<Product>>{};
        for (final product in snapshot.data!) {
          final family = isWolvesShopProduct(product)
              ? wolvesShopRootFamily.toUpperCase()
              : product.family.isNotEmpty
                  ? product.family.toUpperCase()
                  : _inventoryFamilyLabel(product.category);
          groupedProducts.putIfAbsent(family, () => []).add(product);
        }
        if (groupedProducts.isEmpty) return const SizedBox.shrink();
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: groupedProducts.entries.map((group) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(
                    vertical: 12,
                    horizontal: 4,
                  ),
                  child: Text(
                    group.key,
                    style: const TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                      color: gold,
                      letterSpacing: 1.2,
                    ),
                  ),
                ),
                ...group.value.map((product) {
                  final available = product.isVisible &&
                      product.stock > 0 &&
                      product.price > 0;
                  return ListTile(
                    dense: true,
                    contentPadding: const EdgeInsets.symmetric(horizontal: 4),
                    title: Text(
                      product.name,
                      style: const TextStyle(
                        color: cream,
                        fontWeight: FontWeight.w500,
                        fontSize: 12,
                      ),
                    ),
                    subtitle: Text(
                      [
                        available
                            ? 'Disponible (${product.stock} un.)'
                            : !product.isVisible
                                ? 'No disponible para venta'
                                : product.price <= 0
                                    ? 'Precio pendiente'
                                    : 'Agotado',
                        'Precio: ${product.price > 0 ? _formatPrice(product.price) : 'Pendiente'}',
                        if (product.hasSizes)
                          'Tallas: ${wolvesShopSizes.where(product.stockBySize.containsKey).map((size) {
                            final units = product.stockBySize[size]!;
                            return '$size ${units > 0 ? units : 'Agotado'}';
                          }).join(' · ')}',
                        if (manageShopVisibility)
                          product.isVisible
                              ? 'Visible en Wolves Shop'
                              : 'Oculto en Wolves Shop',
                        if (manageShopVisibility && product.sku.isNotEmpty)
                          'Código: ${product.sku}',
                        if (manageShopVisibility &&
                            product.description.isNotEmpty)
                          product.description,
                      ].join(' · '),
                      style: const TextStyle(color: muted, fontSize: 12),
                    ),
                    trailing: manageShopVisibility
                        ? Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              IconButton(
                                key: ValueKey(
                                  'edit-wolves-shop-${product.id}',
                                ),
                                tooltip: 'Editar producto Wolves Shop',
                                onPressed: () => unawaited(
                                  _editWolvesShopProduct(context, product),
                                ),
                                icon: const Icon(
                                  Icons.edit_outlined,
                                  color: gold,
                                  size: 20,
                                ),
                              ),
                              Switch(
                                value: product.isVisible,
                                activeColor: gold,
                                onChanged: (visible) => unawaited(
                                  _setProductShopVisibility(product, visible),
                                ),
                              ),
                            ],
                          )
                        : null,
                  );
                }),
                const Divider(color: brownDark),
              ],
            );
          }).toList(),
        );
      },
    );
  }

  Future<void> _createWolvesShopProduct(
      BuildContext dialogParentContext) async {
    if (_debugRoleBypassActive) {
      if (_userRole != 'admin' || !_adminFinanceUnlocked) {
        _showSnackBar('Se requiere una sesión activa de gerencia.');
        return;
      }
      await _showLocalWolvesShopProductDialog(
        dialogParentContext: dialogParentContext,
      );
      return;
    }
    if (_debugRoleBypassActive ||
        _userRole != 'admin' ||
        !_adminFinanceUnlocked) {
      _showSnackBar('Se requiere una sesión activa de gerencia.');
      return;
    }
    final nameController = TextEditingController();
    final idController = TextEditingController();
    final skuController = TextEditingController();
    final descriptionController = TextEditingController();
    final priceController = TextEditingController();
    final stockController = TextEditingController(text: '0');
    final sizeStockControllers = {
      for (final size in wolvesShopSizes)
        size: TextEditingController(text: '0'),
    };
    final categories = [...wolvesShopProductCategories]..sort();
    var category = categories.first;
    var isVisible = false;
    var idWasEdited = false;
    String? validationMessage;
    try {
      final shouldCreate = await showDialog<bool>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: const Text(
              'Añadir producto a Wolves Shop',
              style: TextStyle(color: cream),
            ),
            content: SizedBox(
              width: 420,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    TextField(
                      controller: nameController,
                      textCapitalization: TextCapitalization.sentences,
                      decoration: const InputDecoration(labelText: 'Nombre'),
                      onChanged: (value) {
                        if (!idWasEdited) {
                          idController.text = _wolvesShopSlug(value);
                        }
                      },
                    ),
                    TextField(
                      controller: idController,
                      decoration: const InputDecoration(
                        labelText: 'ID del producto',
                        helperText: 'Se usará también como ID del documento.',
                      ),
                      onChanged: (_) => idWasEdited = true,
                    ),
                    TextField(
                      controller: skuController,
                      textCapitalization: TextCapitalization.characters,
                      decoration: const InputDecoration(
                        labelText: 'Código del producto (SKU)',
                        helperText: 'Opcional; identifica este artículo.',
                      ),
                    ),
                    const SizedBox(height: 8),
                    DropdownButtonFormField<String>(
                      value: category,
                      dropdownColor: card2,
                      decoration: const InputDecoration(
                        labelText: 'Categoría',
                        prefixIcon: Icon(Icons.category_outlined, color: gold),
                      ),
                      items: categories
                          .map(
                            (value) => DropdownMenuItem(
                              value: value,
                              child: Text(value),
                            ),
                          )
                          .toList(growable: false),
                      onChanged: (value) {
                        if (value != null) {
                          setDialogState(() => category = value);
                        }
                      },
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: descriptionController,
                      textCapitalization: TextCapitalization.sentences,
                      minLines: 2,
                      maxLines: 4,
                      decoration: const InputDecoration(
                        labelText: 'Descripción',
                        alignLabelWithHint: true,
                      ),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: priceController,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: 'Precio',
                        prefixText: 'Bs ',
                      ),
                    ),
                    if (_normalizeCafeLabel(category) == 'modaalfa')
                      for (final size in wolvesShopSizes)
                        TextField(
                          key: ValueKey('new-shop-stock-$size'),
                          controller: sizeStockControllers[size],
                          keyboardType: TextInputType.number,
                          decoration: InputDecoration(
                            labelText: 'Existencias talla $size',
                            suffixText: 'unidades',
                          ),
                        )
                    else
                      TextField(
                        controller: stockController,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(
                          labelText: 'Existencias',
                        ),
                      ),
                    SwitchListTile(
                      contentPadding: EdgeInsets.zero,
                      title: const Text(
                        'Visible en Wolves Shop',
                        style: TextStyle(color: cream, fontSize: 13),
                      ),
                      subtitle: const Text(
                        'Se recomienda dejarlo oculto hasta revisar precio y stock.',
                        style: TextStyle(color: muted, fontSize: 10),
                      ),
                      value: isVisible,
                      activeColor: gold,
                      onChanged: (value) =>
                          setDialogState(() => isVisible = value),
                    ),
                    if (validationMessage != null) ...[
                      const SizedBox(height: 10),
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Color(0xFFE6A296)),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  final id = idController.text.trim();
                  final price = double.tryParse(
                    priceController.text.trim().replaceAll(',', '.'),
                  );
                  final stock = int.tryParse(stockController.text.trim());
                  final hasSizeStock =
                      _normalizeCafeLabel(category) == 'modaalfa';
                  final sizeStocks = {
                    for (final size in wolvesShopSizes)
                      size: int.tryParse(
                        sizeStockControllers[size]!.text.trim(),
                      ),
                  };
                  if (nameController.text.trim().isEmpty ||
                      !RegExp(r'^[a-z0-9][a-z0-9_-]*$').hasMatch(id) ||
                      price == null ||
                      !price.isFinite ||
                      price < 0 ||
                      (!hasSizeStock && (stock == null || stock < 0)) ||
                      (hasSizeStock &&
                          sizeStocks.values.any(
                            (units) => units == null || units < 0,
                          )) ||
                      skuController.text.trim().length > 64) {
                    setDialogState(
                      () => validationMessage =
                          'Revisa el nombre, el ID, el código y que el precio y el stock sean válidos.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, true);
                },
                child: const Text('CREAR'),
              ),
            ],
          ),
        ),
      );
      if (shouldCreate != true) return;

      final id = idController.text.trim();
      final name = nameController.text.trim();
      final price = double.parse(
        priceController.text.trim().replaceAll(',', '.'),
      );
      final hasSizeStock = _normalizeCafeLabel(category) == 'modaalfa';
      final stockBySize = hasSizeStock
          ? {
              for (final size in wolvesShopSizes)
                size: int.parse(sizeStockControllers[size]!.text.trim()),
            }
          : null;
      final stock = stockBySize == null
          ? int.parse(stockController.text.trim())
          : stockBySize.values.fold<int>(
              0,
              (total, units) => total + units,
            );
      await FirebaseFirestore.instance.runTransaction((transaction) async {
        final reference =
            FirebaseFirestore.instance.collection('products').doc(id);
        final existing = await transaction.get(reference);
        if (existing.exists) {
          throw StateError('Ya existe un producto con el ID "$id".');
        }
        transaction.set(reference, {
          'id': id,
          'name': name,
          'category': category,
          'family': wolvesShopRootFamily,
          'description': descriptionController.text.trim(),
          'price': price,
          'stock': stock,
          if (stockBySize != null) 'stockBySize': stockBySize,
          'isVisible': isVisible,
          if (skuController.text.trim().isNotEmpty)
            'sku': skuController.text.trim(),
        });
      });
      if (mounted) {
        _showSnackBar(
          '$name se añadió a Wolves Shop${isVisible ? '' : ' oculto para revisión'}.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo crear el producto Wolves Shop (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo crear el producto (${error.code}). Verifica los permisos de gerencia.',
        );
      }
    } on StateError catch (error) {
      if (mounted) _showSnackBar(error.message);
    } catch (error, stackTrace) {
      debugPrint('Error inesperado creando producto Wolves Shop: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo crear el producto Wolves Shop.');
      }
    } finally {
      nameController.dispose();
      idController.dispose();
      skuController.dispose();
      descriptionController.dispose();
      priceController.dispose();
      stockController.dispose();
      for (final controller in sizeStockControllers.values) {
        controller.dispose();
      }
    }
  }

  String _wolvesShopSlug(String value) {
    return _normalizeCafeLabel(value)
        .replaceAll(' ', '-')
        .replaceAll(RegExp(r'[^a-z0-9_-]'), '');
  }

  Future<void> _editLocalWolvesShopProduct(
    BuildContext dialogParentContext,
    ShopProduct product,
  ) async {
    if (_userRole != 'admin' || !_adminFinanceUnlocked) {
      _showSnackBar('Se requiere una sesión activa de gerencia.');
      return;
    }
    if (!_debugRoleBypassActive &&
        (_firebaseUser == null || !_firebaseUser!.emailVerified)) {
      _showSnackBar('Se requiere una cuenta de Gerencia verificada.');
      return;
    }
    await _showLocalWolvesShopProductDialog(
      dialogParentContext: dialogParentContext,
      product: product,
    );
  }

  Future<void> _showLocalWolvesShopProductDialog({
    required BuildContext dialogParentContext,
    ShopProduct? product,
  }) async {
    final isNewProduct = product == null;
    final nameController = TextEditingController(text: product?.name ?? '');
    final descriptionController =
        TextEditingController(text: product?.description ?? '');
    final skuController = TextEditingController(text: product?.sku ?? '');
    final priceController =
        TextEditingController(text: product?.price.toString() ?? '');
    final stockController =
        TextEditingController(text: product?.stock.toString() ?? '0');
    final sizeStockControllers = {
      for (final size in wolvesShopSizes)
        size: TextEditingController(
          text: (product?.variants[size]?.stock ?? 0).toString(),
        ),
    };
    Uint8List? selectedImageBytes;
    final categories = [...wolvesShopProductCategories]..sort();
    var category = product?.category ?? categories.first;
    String? validationMessage;
    try {
      final shouldSave = await showDialog<bool>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              isNewProduct ? 'Añadir producto' : 'Editar producto',
              style: const TextStyle(color: cream),
            ),
            content: SizedBox(
              width: 420,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    TextField(
                      controller: nameController,
                      textCapitalization: TextCapitalization.sentences,
                      decoration: const InputDecoration(labelText: 'Nombre'),
                    ),
                    const SizedBox(height: 8),
                    DropdownButtonFormField<String>(
                      value: category,
                      dropdownColor: card2,
                      decoration: const InputDecoration(
                        labelText: 'Categoría',
                        prefixIcon: Icon(Icons.category_outlined, color: gold),
                      ),
                      items: categories
                          .map(
                            (value) => DropdownMenuItem(
                              value: value,
                              child: Text(value),
                            ),
                          )
                          .toList(growable: false),
                      onChanged: (value) {
                        if (value != null) {
                          setDialogState(() => category = value);
                        }
                      },
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: descriptionController,
                      textCapitalization: TextCapitalization.sentences,
                      minLines: 2,
                      maxLines: 4,
                      decoration: const InputDecoration(
                        labelText: 'Descripción',
                        alignLabelWithHint: true,
                      ),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: skuController,
                      textCapitalization: TextCapitalization.characters,
                      decoration: const InputDecoration(
                        labelText: 'Código del producto (SKU)',
                        helperText: 'Opcional; identifica este artículo.',
                      ),
                    ),
                    const SizedBox(height: 8),
                    if (product != null) ...[
                      SizedBox(
                        width: double.infinity,
                        height: 130,
                        child: selectedImageBytes != null
                            ? Image.memory(
                                selectedImageBytes!,
                                fit: BoxFit.cover,
                              )
                            : _wolvesShopProductImage(
                                productId: product.id,
                                imageUrl: product.imageUrl,
                                imageAsset: product.imageAsset,
                                fallbackIcon: product.icon,
                                fit: BoxFit.cover,
                                width: double.infinity,
                                height: 130,
                              ),
                      ),
                      OutlinedButton.icon(
                        key: ValueKey('edit-local-wolves-image-${product.id}'),
                        onPressed: () async {
                          try {
                            final photo = await _cafeImagePicker.pickImage(
                              source: ImageSource.gallery,
                              imageQuality: 85,
                              maxWidth: 1600,
                              maxHeight: 1600,
                            );
                            if (photo == null) return;
                            final sourceBytes = await photo.readAsBytes();
                            final bytes = await compute(
                              _compressCafeImageBytes,
                              sourceBytes,
                            );
                            setDialogState(() {
                              selectedImageBytes = bytes;
                              validationMessage = null;
                            });
                          } catch (error, stackTrace) {
                            debugPrint(
                              'No se pudo seleccionar la foto del producto: $error',
                            );
                            debugPrintStack(stackTrace: stackTrace);
                            setDialogState(
                              () => validationMessage =
                                  'No se pudo seleccionar la imagen.',
                            );
                          }
                        },
                        icon: const Icon(Icons.photo_library_outlined),
                        label: const Text('CAMBIAR FOTO'),
                      ),
                      const SizedBox(height: 8),
                    ],
                    TextField(
                      controller: priceController,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: 'Precio',
                        prefixText: 'Bs ',
                      ),
                    ),
                    if (_normalizeCafeLabel(category) == 'modaalfa' ||
                        (product?.hasSizes ?? false))
                      for (final size in wolvesShopSizes)
                        TextField(
                          key: ValueKey('local-shop-stock-$size'),
                          controller: sizeStockControllers[size],
                          keyboardType: TextInputType.number,
                          decoration: InputDecoration(
                            labelText: 'Existencias talla $size',
                            suffixText: 'unidades',
                          ),
                        )
                    else
                      TextField(
                        controller: stockController,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(
                          labelText: 'Existencias disponibles',
                          helperText: 'Ingresa la cantidad total actual.',
                        ),
                      ),
                    if (validationMessage != null) ...[
                      const SizedBox(height: 10),
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Color(0xFFE6A296)),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  final price = double.tryParse(
                    priceController.text.trim().replaceAll(',', '.'),
                  );
                  final stock = int.tryParse(stockController.text.trim());
                  final hasSizeStock =
                      _normalizeCafeLabel(category) == 'modaalfa' ||
                          (product?.hasSizes ?? false);
                  final sizeStocks = {
                    for (final size in wolvesShopSizes)
                      size: int.tryParse(
                        sizeStockControllers[size]!.text.trim(),
                      ),
                  };
                  if (nameController.text.trim().isEmpty ||
                      price == null ||
                      !price.isFinite ||
                      price < 0 ||
                      (!hasSizeStock && stock == null) ||
                      skuController.text.trim().length > 64 ||
                      (!hasSizeStock && stock! < 0) ||
                      (hasSizeStock &&
                          sizeStocks.values.any(
                            (units) => units == null || units < 0,
                          ))) {
                    setDialogState(
                      () => validationMessage =
                          'Ingresa nombre, código válido, precio y existencias enteras no negativas.',
                    );
                    return;
                  }
                  if (isNewProduct && price <= 0) {
                    setDialogState(
                      () => validationMessage =
                          'El precio debe ser mayor que cero.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, true);
                },
                child: const Text('GUARDAR'),
              ),
            ],
          ),
        ),
      );
      if (shouldSave != true) return;

      final name = nameController.text.trim();
      final price = double.parse(
        priceController.text.trim().replaceAll(',', '.'),
      );
      final hasSizeStock = _normalizeCafeLabel(category) == 'modaalfa' ||
          (product?.hasSizes ?? false);
      final sizes = hasSizeStock
          ? {
              for (final size in wolvesShopSizes)
                size: int.parse(sizeStockControllers[size]!.text.trim()),
            }
          : const <String, int>{};
      final stock = hasSizeStock
          ? sizes.values.fold<int>(0, (total, units) => total + units)
          : int.parse(stockController.text.trim());
      final sku = skuController.text.trim();
      if (!_debugRoleBypassActive) {
        final firestore = FirebaseFirestore.instance;
        final document = <String, dynamic>{
          'id': product?.id ?? _wolvesShopSlug(name),
          'name': name,
          'category': _normalizeCafeLabel(category).replaceAll(' ', '_'),
          'family': wolvesShopRootFamily,
          'description': descriptionController.text.trim(),
          'price': price,
          'stock': stock,
          'isVisible': true,
          if (sku.isNotEmpty) 'sku': sku,
          if (sizes.isNotEmpty) 'stockBySize': sizes,
        };
        final productId = document['id'] as String;
        if (productId.isEmpty) {
          throw StateError('El nombre debe generar un ID de producto válido.');
        }
        final batch = firestore.batch();
        batch.set(firestore.collection('products').doc(productId), document);
        batch.delete(
          firestore.collection('wolvesShopFallbackExclusions').doc(productId),
        );
        final imageDocumentId = 'wolves-shop-$productId';
        if (selectedImageBytes != null) {
          final manager = _firebaseUser!;
          batch.set(
            firestore.collection('cafeMenuImages').doc(imageDocumentId),
            {
              'imageBase64': base64Encode(selectedImageBytes!),
              'contentType': 'image/jpeg',
              'updatedBy': manager.uid,
              'updatedAt': FieldValue.serverTimestamp(),
            },
          );
        }
        await batch.commit();
        if (selectedImageBytes != null) {
          _wolvesShopImageCache[imageDocumentId] =
              Future.value(selectedImageBytes);
        }
      }
      setState(() {
        if (product == null) {
          final baseId = _wolvesShopSlug(name).isEmpty
              ? 'wolves-shop-item'
              : _wolvesShopSlug(name);
          var id = baseId;
          var suffix = 2;
          while (_shopProducts.any((item) => item.id == id)) {
            id = '$baseId-$suffix';
            suffix++;
          }
          _shopProducts.add(
            ShopProduct(
              id: id,
              category: category,
              name: name,
              sku: sku,
              description: descriptionController.text.trim(),
              icon: _wolvesShopProductIcon(
                _normalizeCafeLabel('$category $name'),
              ),
              price: price,
              stock: stock,
              sizes: sizes,
            ),
          );
        } else {
          product
            ..category = category
            ..name = name
            ..description = descriptionController.text.trim()
            ..sku = sku
            ..icon = _wolvesShopProductIcon(
              _normalizeCafeLabel('$category $name'),
            )
            ..price = price;
          if (sizes.isNotEmpty) {
            product.variants
              ..clear()
              ..addAll({
                for (final entry in sizes.entries)
                  entry.key: ShopVariant(
                    size: entry.key,
                    stock: entry.value,
                  ),
              });
            product.stock = stock;
          } else {
            _setLocalShopProductStock(product, stock);
          }
        }
      });
      if (mounted) {
        _showSnackBar(
          isNewProduct
              ? _debugRoleBypassActive
                  ? '$name se añadió al catálogo local de prueba.'
                  : '$name se añadió a Wolves Shop.'
              : '$name se actualizó con $stock unidades disponibles.',
        );
      }
    } finally {
      nameController.dispose();
      descriptionController.dispose();
      skuController.dispose();
      priceController.dispose();
      stockController.dispose();
      for (final controller in sizeStockControllers.values) {
        controller.dispose();
      }
    }
  }

  void _setLocalShopProductStock(ShopProduct product, int totalStock) {
    if (!product.hasSizes) {
      product.stock = totalStock;
      return;
    }
    final variants = product.variants.values.toList(growable: false);
    final baseStock = totalStock ~/ variants.length;
    final remainder = totalStock % variants.length;
    for (var index = 0; index < variants.length; index++) {
      variants[index].stock = baseStock + (index < remainder ? 1 : 0);
    }
  }

  Future<void> _deleteLocalWolvesShopProduct(
    BuildContext dialogParentContext,
    ShopProduct product,
  ) async {
    if (_userRole != 'admin' || !_adminFinanceUnlocked) {
      _showSnackBar('Se requiere una sesión activa de gerencia.');
      return;
    }
    if (!_debugRoleBypassActive &&
        (_firebaseUser == null || !_firebaseUser!.emailVerified)) {
      _showSnackBar('Se requiere una cuenta de Gerencia verificada.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: dialogParentContext,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text('Eliminar artículo', style: TextStyle(color: cream)),
        content: Text(
          _debugRoleBypassActive
              ? '¿Quitar "${product.name}" de este catálogo local de prueba?'
              : '¿Quitar "${product.name}" de Wolves Shop? Ya no aparecerá en el catálogo ni en el TPV.',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFF8B3A32),
            ),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    if (!_debugRoleBypassActive) {
      try {
        await FirebaseFirestore.instance
            .collection('wolvesShopFallbackExclusions')
            .doc(product.id)
            .set({
          'isExcluded': true,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      } on FirebaseException catch (error, stackTrace) {
        debugPrint(
          'No se pudo quitar el producto local (${error.code}).',
        );
        debugPrintStack(stackTrace: stackTrace);
        if (mounted) {
          _showSnackBar('No se pudo quitar el producto (${error.code}).');
        }
        return;
      }
    }
    setState(() => _shopProducts.removeWhere((item) => item.id == product.id));
    if (mounted) {
      _showSnackBar(
        _debugRoleBypassActive
            ? '${product.name} se quitó del catálogo local de prueba.'
            : '${product.name} se quitó de Wolves Shop.',
      );
    }
  }

  Future<void> _deleteWolvesShopProduct(
    BuildContext dialogParentContext,
    Product product,
  ) async {
    if (_debugRoleBypassActive ||
        _userRole != 'admin' ||
        !_adminFinanceUnlocked) {
      _showSnackBar('Se requiere una sesión activa de gerencia.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: dialogParentContext,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text(
          'Eliminar producto',
          style: TextStyle(color: cream),
        ),
        content: Text(
          '¿Eliminar "${product.name}" de Wolves Shop? Esta acción no se puede deshacer.',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFF8B3A32),
            ),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      final firestore = FirebaseFirestore.instance;
      final batch = firestore.batch();
      batch.delete(firestore.collection('products').doc(product.id));
      if (_shopProducts.any((fallback) => fallback.id == product.id)) {
        batch.set(
          firestore.collection('wolvesShopFallbackExclusions').doc(product.id),
          {
            'isExcluded': true,
            'updatedAt': FieldValue.serverTimestamp(),
          },
        );
      }
      await batch.commit();
      if (mounted) _showSnackBar('${product.name} se eliminó de Wolves Shop.');
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo eliminar el producto Wolves Shop (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo eliminar el producto (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error inesperado eliminando Wolves Shop: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo eliminar el producto Wolves Shop.');
      }
    }
  }

  Future<void> _editWolvesShopProduct(
    BuildContext dialogParentContext,
    Product product,
  ) async {
    final manager = _firebaseUser;
    if (_debugRoleBypassActive ||
        _userRole != 'admin' ||
        !_adminFinanceUnlocked ||
        manager == null ||
        !manager.emailVerified) {
      _showSnackBar(
        'Para editar este producto, inicia sesión con una cuenta de Gerencia verificada.',
      );
      return;
    }
    final nameController = TextEditingController(text: product.name);
    final skuController = TextEditingController(text: product.sku);
    final descriptionController =
        TextEditingController(text: product.description);
    final priceController =
        TextEditingController(text: product.price.toString());
    final stockController =
        TextEditingController(text: product.stock.toString());
    final sizeStockControllers = {
      for (final size in wolvesShopSizes)
        size: TextEditingController(
          text: (product.stockBySize[size] ?? 0).toString(),
        ),
    };
    final categories = <String>{
      ...wolvesShopProductCategories,
      product.category,
    }.toList()
      ..sort();
    var category = product.category;
    var isVisible = product.isVisible;
    Uint8List? selectedImageBytes;
    String? validationMessage;
    try {
      final shouldSave = await showDialog<bool>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              'Editar Wolves Shop · ${product.name}',
              style: const TextStyle(color: cream),
            ),
            content: SizedBox(
              width: 420,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    TextField(
                      controller: nameController,
                      textCapitalization: TextCapitalization.sentences,
                      decoration: const InputDecoration(labelText: 'Nombre'),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: skuController,
                      textCapitalization: TextCapitalization.characters,
                      decoration: const InputDecoration(
                        labelText: 'Código del producto (SKU)',
                        helperText: 'Opcional; identifica este artículo.',
                      ),
                    ),
                    const SizedBox(height: 8),
                    DropdownButtonFormField<String>(
                      value: category,
                      dropdownColor: card2,
                      decoration: const InputDecoration(
                        labelText: 'Categoría',
                        prefixIcon: Icon(Icons.category_outlined, color: gold),
                      ),
                      items: categories
                          .map(
                            (value) => DropdownMenuItem(
                              value: value,
                              child: Text(value),
                            ),
                          )
                          .toList(growable: false),
                      onChanged: (value) {
                        if (value != null) {
                          setDialogState(() => category = value);
                        }
                      },
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: descriptionController,
                      textCapitalization: TextCapitalization.sentences,
                      minLines: 2,
                      maxLines: 4,
                      decoration: const InputDecoration(
                        labelText: 'Descripción',
                        alignLabelWithHint: true,
                      ),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: priceController,
                      keyboardType:
                          const TextInputType.numberWithOptions(decimal: true),
                      decoration: const InputDecoration(
                        labelText: 'Precio',
                        prefixText: 'Bs ',
                      ),
                    ),
                    const SizedBox(height: 10),
                    Container(
                      width: double.infinity,
                      height: 150,
                      clipBehavior: Clip.antiAlias,
                      decoration: BoxDecoration(
                        color: card2,
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(color: brownDark),
                      ),
                      child: selectedImageBytes != null
                          ? Image.memory(
                              selectedImageBytes!,
                              fit: BoxFit.cover,
                            )
                          : _wolvesShopProductImage(
                              productId: product.id,
                              imageUrl: product.imageUrl,
                              imageAsset: null,
                              fallbackIcon: Icons.add_a_photo_outlined,
                              fit: BoxFit.cover,
                              width: double.infinity,
                              height: 150,
                            ),
                    ),
                    const SizedBox(height: 8),
                    OutlinedButton.icon(
                      key: ValueKey('edit-wolves-shop-image-${product.id}'),
                      onPressed: () async {
                        try {
                          final photo = await _cafeImagePicker.pickImage(
                            source: ImageSource.gallery,
                            imageQuality: 85,
                            maxWidth: 1600,
                            maxHeight: 1600,
                          );
                          if (photo == null) return;
                          final sourceBytes = await photo.readAsBytes();
                          final bytes = await compute(
                            _compressCafeImageBytes,
                            sourceBytes,
                          );
                          setDialogState(() {
                            selectedImageBytes = bytes;
                            validationMessage = null;
                          });
                        } catch (error, stackTrace) {
                          debugPrint(
                            'No se pudo seleccionar la foto de Wolves Shop: $error',
                          );
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            validationMessage =
                                'No se pudo seleccionar la imagen.';
                          });
                        }
                      },
                      icon: const Icon(Icons.photo_library_outlined),
                      label: const Text('CAMBIAR FOTO'),
                    ),
                    if (product.hasSizes)
                      for (final size in wolvesShopSizes)
                        TextField(
                          key: ValueKey('edit-shop-stock-${product.id}-$size'),
                          controller: sizeStockControllers[size],
                          keyboardType: TextInputType.number,
                          decoration: InputDecoration(
                            labelText: 'Existencias talla $size',
                            suffixText: 'unidades',
                          ),
                        )
                    else
                      TextField(
                        controller: stockController,
                        keyboardType: TextInputType.number,
                        decoration: const InputDecoration(
                          labelText: 'Existencias',
                          helperText: 'Unidades disponibles actualmente.',
                        ),
                      ),
                    SwitchListTile(
                      contentPadding: EdgeInsets.zero,
                      title: const Text(
                        'Visible en Wolves Shop',
                        style: TextStyle(color: cream, fontSize: 13),
                      ),
                      value: isVisible,
                      activeColor: gold,
                      onChanged: (value) =>
                          setDialogState(() => isVisible = value),
                    ),
                    if (validationMessage != null) ...[
                      const SizedBox(height: 10),
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Color(0xFFE6A296)),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  final price = double.tryParse(
                    priceController.text.trim().replaceAll(',', '.'),
                  );
                  final stock = int.tryParse(stockController.text.trim());
                  final sizeStocks = {
                    for (final size in wolvesShopSizes)
                      size:
                          int.tryParse(sizeStockControllers[size]!.text.trim()),
                  };
                  if (nameController.text.trim().isEmpty ||
                      price == null ||
                      !price.isFinite ||
                      price < 0 ||
                      (!product.hasSizes && (stock == null || stock < 0)) ||
                      (product.hasSizes &&
                          sizeStocks.values.any(
                            (units) => units == null || units < 0,
                          )) ||
                      skuController.text.trim().length > 64) {
                    setDialogState(
                      () => validationMessage =
                          'Revisa el nombre, código, precio y stock.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, true);
                },
                child: const Text('GUARDAR'),
              ),
            ],
          ),
        ),
      );
      if (shouldSave != true) return;
      final name = nameController.text.trim();
      final description = descriptionController.text.trim();
      final price = double.parse(
        priceController.text.trim().replaceAll(',', '.'),
      );
      final updatedStockBySize = product.hasSizes
          ? {
              for (final size in wolvesShopSizes)
                size: int.parse(sizeStockControllers[size]!.text.trim()),
            }
          : null;
      final stock = updatedStockBySize == null
          ? int.parse(stockController.text.trim())
          : updatedStockBySize.values.fold<int>(
              0,
              (total, units) => total + units,
            );
      final firestore = FirebaseFirestore.instance;
      final batch = firestore.batch();
      batch.update(firestore.collection('products').doc(product.id), {
        'name': name,
        'sku': skuController.text.trim(),
        'category': category,
        'family': wolvesShopRootFamily,
        'description': description,
        'price': price,
        'stock': stock,
        if (updatedStockBySize != null) 'stockBySize': updatedStockBySize,
        'isVisible': isVisible,
      });
      final imageDocumentId = 'wolves-shop-${product.id}';
      if (selectedImageBytes != null) {
        batch.set(
          firestore.collection('cafeMenuImages').doc(imageDocumentId),
          {
            'imageBase64': base64Encode(selectedImageBytes!),
            'contentType': 'image/jpeg',
            'updatedBy': manager.uid,
            'updatedAt': FieldValue.serverTimestamp(),
          },
        );
      }
      await batch.commit();
      if (selectedImageBytes != null) {
        _wolvesShopImageCache[imageDocumentId] =
            Future.value(selectedImageBytes);
      }
      if (mounted) {
        _showSnackBar(
          selectedImageBytes == null
              ? '${product.name} se actualizó en Wolves Shop.'
              : 'Producto, cantidad y foto de ${product.name} actualizados.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo actualizar el inventario Wolves Shop (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          error.code == 'permission-denied'
              ? 'Firestore rechazó el cambio. Verifica que esta cuenta tenga rol Gerencia y que las reglas estén actualizadas.'
              : 'No se pudo actualizar el inventario (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error inesperado actualizando Wolves Shop: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo actualizar Wolves Shop: $error');
      }
    } finally {
      nameController.dispose();
      skuController.dispose();
      descriptionController.dispose();
      priceController.dispose();
      stockController.dispose();
      for (final controller in sizeStockControllers.values) {
        controller.dispose();
      }
    }
  }

  Future<void> _setProductShopVisibility(
    Product product,
    bool isVisible,
  ) async {
    if (_debugRoleBypassActive ||
        _userRole != 'admin' ||
        !_adminFinanceUnlocked) {
      _showSnackBar('Se requiere una sesión activa de gerencia.');
      return;
    }
    try {
      await FirebaseFirestore.instance
          .collection('products')
          .doc(product.id)
          .update({'isVisible': isVisible});
      if (mounted) {
        _showSnackBar(
          isVisible
              ? '${product.name} ahora es visible en Wolves Shop.'
              : '${product.name} se ocultó de Wolves Shop.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo cambiar la visibilidad de Wolves Shop (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo cambiar la visibilidad (${error.code}).',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error inesperado cambiando visibilidad: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo cambiar la visibilidad del producto.');
      }
    }
  }

