  Widget _adminPassportRewardStatsSection() {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('passportProgress')
            .snapshots(),
        builder: (context, progressSnapshot) {
          if (progressSnapshot.hasError) {
            return _managementStatusCard(
              'No se pudo cargar la estadística de Passport.',
              error: true,
            );
          }
          if (!progressSnapshot.hasData) {
            return const LinearProgressIndicator(color: gold);
          }
          final completedPassports = progressSnapshot.data!.docs
              .where(
                (document) =>
                    (document.data()['completedCount'] as num?)?.toInt() ==
                    methods.length,
              )
              .length;
          return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('legendaryMugRedemptions')
                .orderBy('redeemedAt', descending: true)
                .snapshots(),
            builder: (context, redemptionsSnapshot) {
              if (redemptionsSnapshot.hasError) {
                return _managementStatusCard(
                  'No se pudieron cargar las entregas de taza legendaria.',
                  error: true,
                );
              }
              if (!redemptionsSnapshot.hasData) {
                return const LinearProgressIndicator(color: gold);
              }
              final redemptions = redemptionsSnapshot.data!.docs;
              return Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    'PASSPORT · $completedPassports completados de ${progressSnapshot.data!.docs.length} · '
                    '${redemptions.length} tazas legendarias entregadas',
                    style: const TextStyle(color: gold, fontSize: 10),
                  ),
                  ...redemptions.take(10).map((redemption) {
                    final data = redemption.data();
                    final redeemedAt = data['redeemedAt'];
                    final timeLabel = redeemedAt is Timestamp
                        ? _formatManagementTime(redeemedAt.toDate())
                        : 'Hora pendiente';
                    return ListTile(
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                      title: Text(
                        'Taza ${data['mugCode'] ?? redemption.id} · Cliente ${data['customerUid'] ?? '-'}',
                        style: const TextStyle(color: cream, fontSize: 9),
                      ),
                      subtitle: Text(
                        '${data['employeeEmail'] ?? data['employeeUid'] ?? '-'} · $timeLabel',
                        style: const TextStyle(color: muted, fontSize: 9),
                      ),
                    );
                  }),
                  const Divider(color: brownDark),
                ],
              );
            },
          );
        },
      ),
    );
  }

