  Widget _adminInventoryOverviewSection() {
    if (_debugRoleBypassActive) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _adminDemoDataSection(
            icon: Icons.inventory_2_outlined,
