                                  subtitle: Text(
                                    '${item.category} · '
                                    '${item.price > 0 ? _formatPrice(item.price) : 'Precio pendiente'} · '
                                    'Stock: ${item.stock} · Plantilla local, pulsa editar para guardar',
                                    style: const TextStyle(
                                      color: muted,
                                      fontSize: 10,
                                    ),
                                  ),
                                  trailing: IconButton(
                                    key: ValueKey(
                                      'inventory-edit-unlinked-${item.id}',
                                    ),
                                    tooltip: 'Editar y guardar en Firestore',
                                    onPressed: () => unawaited(
                                      _openCafeCatalogItemEditor(
                                        context: context,
                                        item: item,
