                const Text(
                  'PELUCHES Y COLECCIONABLES',
                  style: TextStyle(color: gold, fontSize: 10),
                ),
                const SizedBox(height: 6),
                const Text(
                  'Los códigos de colección ya adoptados se conservan como historial de autenticidad. Gerencia puede ingresar nuevas unidades desde aquí.',
                  style: TextStyle(color: muted, fontSize: 10, height: 1.4),
                ),
                const SizedBox(height: 8),
                Builder(
                  builder: (buttonContext) => OutlinedButton.icon(
                    key: const ValueKey('admin-register-collectible-units'),
                    onPressed: () => _showRegisterCollectibleDialog(
                      buttonContext,
                    ),
                    icon: const Icon(Icons.add_box_outlined),
                    label: const Text('AGREGAR UNIDADES DE COLECCIÓN'),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: gold,
                      minimumSize: const Size.fromHeight(44),
                    ),
                  ),
                ),
                StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                  stream: FirebaseFirestore.instance
                      .collection('collectiblePlushes')
                      .limit(200)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (snapshot.hasError) {
                      return _managementStatusCard(
                        'No se pudo cargar el stock de peluches.',
                        error: true,
                      );
                    }
                    if (!snapshot.hasData) {
                      return const LinearProgressIndicator(color: gold);
                    }
                    final docs = snapshot.data!.docs;
                    final available = docs
                        .where((doc) => doc.data()['claimedBy'] == null)
                        .length;
                    final claimed = docs.length - available;
                    return Text(
                      'Registrados: ${docs.length} · Disponibles: $available · Entregados: $claimed',
                      style: const TextStyle(color: cream, fontSize: 10),
                    );
                  },
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _adminAnnouncementsSection() {
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: card,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: gold.withValues(alpha: 0.35)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              const Icon(Icons.campaign_outlined, color: gold, size: 20),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'PROMOCIONES Y ANUNCIOS DE EVENTOS',
                  style: TextStyle(
                    color: cream,
                    fontSize: 11,
                    letterSpacing: 0.8,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
              Builder(
                builder: (context) => IconButton(
                  key: const ValueKey('add-management-announcement'),
                  tooltip: 'Crear promoción o anuncio de evento',
                  onPressed: () =>
                      unawaited(_editManagementAnnouncement(context)),
                  icon: const Icon(Icons.add_circle_outline, color: gold),
                ),
              ),
            ],
          ),
          const Text(
            'Crea y edita promociones o anuncios de eventos. Usa el interruptor para publicarlos u ocultarlos.',
            style: TextStyle(color: muted, fontSize: 10, height: 1.4),
          ),
          const SizedBox(height: 10),
          StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('managementAnnouncements')
                .orderBy('updatedAt', descending: true)
                .limit(100)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return _managementStatusCard(
                  'No se pudieron cargar las promociones y eventos: ${snapshot.error}',
                  error: true,
                );
              }
              if (!snapshot.hasData) {
                return const LinearProgressIndicator(color: gold);
              }
              if (snapshot.data!.docs.isEmpty) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 16),
                  child: Text(
                    'Todavía no hay promociones ni anuncios. Usa + para crear el primero.',
                    style: TextStyle(color: muted, fontSize: 11),
                    textAlign: TextAlign.center,
                  ),
                );
              }
              return Column(
                children: snapshot.data!.docs.map((document) {
                  final data = document.data();
                  final isActive = data['isActive'] == true;
                  final type = data['type'] == 'event' ? 'EVENTO' : 'PROMOCIÓN';
                  final title = data['title'] is String
                      ? data['title'] as String
                      : document.id;
                  final description = data['description'] is String
                      ? data['description'] as String
                      : '';
                  final dateLabel = data['dateLabel'] is String
                      ? (data['dateLabel'] as String).trim()
                      : '';
                  return ListTile(
                    key: ValueKey('management-announcement-${document.id}'),
                    contentPadding: EdgeInsets.zero,
                    title: Text(
                      '$type · $title',
                      style: const TextStyle(color: cream, fontSize: 12),
                    ),
                    subtitle: Text(
                      [
                        if (dateLabel.isNotEmpty) dateLabel,
                        if (description.isNotEmpty) description,
                        isActive ? 'Publicado' : 'Oculto',
                      ].join(' · '),
                      style: const TextStyle(color: muted, fontSize: 10),
                    ),
                    trailing: Wrap(
                      crossAxisAlignment: WrapCrossAlignment.center,
                      children: [
                        Switch(
                          key: ValueKey(
                            'announcement-active-${document.id}',
                          ),
                          value: isActive,
                          activeColor: gold,
                          onChanged: (active) => unawaited(
                            _setManagementAnnouncementActive(
                              document,
                              active,
                            ),
                          ),
                        ),
                        IconButton(
                          key: ValueKey(
                            'edit-announcement-${document.id}',
                          ),
                          tooltip: 'Editar anuncio',
                          onPressed: () => unawaited(
                            _editManagementAnnouncement(context, document),
                          ),
                          icon: const Icon(
                            Icons.edit_outlined,
                            color: gold,
                            size: 19,
                          ),
                        ),
                        IconButton(
                          key: ValueKey(
                            'delete-announcement-${document.id}',
                          ),
                          tooltip: 'Eliminar anuncio',
                          onPressed: () => unawaited(
                            _deleteManagementAnnouncement(context, document),
                          ),
                          icon: const Icon(
                            Icons.delete_outline,
                            color: Color(0xFFE6A296),
                            size: 19,
                          ),
                        ),
                      ],
                    ),
                  );
                }).toList(growable: false),
              );
            },
          ),
        ],
      ),
    );
  }

  bool get _canEditManagementAnnouncements {
    final manager = _firebaseUser;
    return !_debugRoleBypassActive &&
        _userRole == 'admin' &&
        _adminFinanceUnlocked &&
        manager != null &&
        manager.emailVerified;
  }

  Future<void> _editManagementAnnouncement(
    BuildContext dialogParentContext, [
    QueryDocumentSnapshot<Map<String, dynamic>>? announcement,
  ]) async {
    if (!_canEditManagementAnnouncements) {
      _showSnackBar('Se requiere una cuenta de Gerencia verificada.');
      return;
    }
    final data = announcement?.data();
    final titleController = TextEditingController(
      text: data?['title'] is String ? data!['title'] as String : '',
    );
    final descriptionController = TextEditingController(
      text:
          data?['description'] is String ? data!['description'] as String : '',
    );
    final dateLabelController = TextEditingController(
      text: data?['dateLabel'] is String ? data!['dateLabel'] as String : '',
    );
    var type = data?['type'] == 'event' ? 'event' : 'promotion';
    var isActive = data == null ? true : data['isActive'] == true;
    String? validationMessage;
    try {
      final shouldSave = await showDialog<bool>(
        context: dialogParentContext,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              announcement == null ? 'Crear anuncio' : 'Editar anuncio',
              style: const TextStyle(color: cream),
            ),
            content: SizedBox(
              width: 440,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    DropdownButtonFormField<String>(
                      value: type,
                      dropdownColor: card2,
                      decoration: const InputDecoration(labelText: 'Tipo'),
                      items: const [
                        DropdownMenuItem(
                          value: 'promotion',
                          child: Text('Promoción'),
                        ),
                        DropdownMenuItem(
                          value: 'event',
                          child: Text('Anuncio de evento'),
                        ),
                      ],
                      onChanged: (value) {
                        if (value != null) {
                          setDialogState(() => type = value);
                        }
                      },
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: titleController,
                      maxLength: 120,
                      decoration: const InputDecoration(labelText: 'Título'),
                    ),
                    TextField(
                      controller: dateLabelController,
                      maxLength: 80,
                      decoration: const InputDecoration(
                        labelText: 'Fecha u horario (opcional)',
                        hintText: 'Ej.: 25 OCT · 16:00',
                      ),
                    ),
                    TextField(
                      controller: descriptionController,
                      maxLength: 2000,
                      minLines: 2,
                      maxLines: 5,
                      decoration: const InputDecoration(
                        labelText: 'Descripción',
                        alignLabelWithHint: true,
                      ),
                    ),
                    SwitchListTile(
                      contentPadding: EdgeInsets.zero,
                      title: const Text(
                        'Publicar ahora',
                        style: TextStyle(color: cream, fontSize: 13),
                      ),
                      value: isActive,
                      activeColor: gold,
                      onChanged: (value) =>
                          setDialogState(() => isActive = value),
                    ),
                    if (validationMessage != null)
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Color(0xFFE6A296)),
                      ),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  if (titleController.text.trim().isEmpty) {
                    setDialogState(
                      () => validationMessage = 'Escribe un título.',
                    );
                    return;
                  }
                  Navigator.pop(dialogContext, true);
                },
                child: const Text('GUARDAR'),
              ),
            ],
          ),
        ),
      );
      if (shouldSave != true) return;
      final manager = _firebaseUser!;
      final reference = FirebaseFirestore.instance
          .collection('managementAnnouncements')
          .doc(announcement?.id);
      final values = <String, dynamic>{
        'type': type,
        'title': titleController.text.trim(),
        'description': descriptionController.text.trim(),
        'dateLabel': dateLabelController.text.trim(),
        'isActive': isActive,
        'updatedAt': FieldValue.serverTimestamp(),
        'updatedBy': manager.uid,
        if (announcement == null) 'createdAt': FieldValue.serverTimestamp(),
      };
      if (announcement == null) {
        await reference.set(values);
      } else {
        await reference.update(values);
      }
      if (mounted) {
        _showSnackBar(
          isActive
              ? 'El anuncio se guardó y está publicado.'
              : 'El anuncio se guardó oculto.',
        );
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo guardar el anuncio (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo guardar el anuncio (${error.code}).');
      }
    } catch (error, stackTrace) {
      debugPrint('Error inesperado guardando el anuncio: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) _showSnackBar('No se pudo guardar el anuncio.');
    } finally {
      titleController.dispose();
      descriptionController.dispose();
      dateLabelController.dispose();
    }
  }

  Future<void> _setManagementAnnouncementActive(
    QueryDocumentSnapshot<Map<String, dynamic>> announcement,
    bool isActive,
  ) async {
    if (!_canEditManagementAnnouncements) {
      _showSnackBar('Se requiere una cuenta de Gerencia verificada.');
      return;
    }
    try {
      await announcement.reference.update({
        'isActive': isActive,
        'updatedAt': FieldValue.serverTimestamp(),
        'updatedBy': _firebaseUser!.uid,
      });
      if (mounted) {
        _showSnackBar(isActive ? 'Anuncio publicado.' : 'Anuncio ocultado.');
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo cambiar el estado del anuncio: ${error.code}');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo cambiar el estado (${error.code}).');
      }
    }
  }

  Future<void> _deleteManagementAnnouncement(
    BuildContext dialogParentContext,
    QueryDocumentSnapshot<Map<String, dynamic>> announcement,
  ) async {
    if (!_canEditManagementAnnouncements) {
      _showSnackBar('Se requiere una cuenta de Gerencia verificada.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: dialogParentContext,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text('Eliminar anuncio', style: TextStyle(color: cream)),
        content: Text(
          '¿Eliminar "${announcement.data()['title'] ?? 'este anuncio'}"?',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      await announcement.reference.delete();
      if (mounted) _showSnackBar('Anuncio eliminado.');
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo eliminar el anuncio (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo eliminar el anuncio (${error.code}).');
      }
    }
  }

  CafeMenuItem _cafeMenuItemFromInventoryDocument(
    QueryDocumentSnapshot<Map<String, dynamic>> document,
  ) {
    for (final item in _cafeMenuItems) {
      if (item.id == document.id) return item;
    }
    final data = document.data();
    final name = data['name'] is String ? data['name'] as String : document.id;
    final category =
        data['category'] is String ? data['category'] as String : '';
    final description =
        data['description'] is String ? data['description'] as String : '';
    final familyId = data['familyId'] as String?;
    final imageSource = _cafeImageSourceFor(document.id, name);
    PosFamily? family;
    for (final candidate in _posFamilies) {
      if (candidate.id == familyId) {
        family = candidate;
        break;
      }
    }
    return CafeMenuItem(
      id: document.id,
      name: name,
      category:
          family?.name ?? _canonicalCafeCategory(category, name, description),
      description: description,
      icon: imageSource?.icon ?? Icons.local_cafe,
      price: data['price'] is num ? (data['price'] as num).toDouble() : 0,
      stock: data['stock'] is int ? data['stock'] as int : 0,
      imageAsset: imageSource?.imageAsset,
      imageUrl: data['imageUrl'] as String?,
      hasImage: data['hasImage'] == true,
      familyId: familyId ?? _familyForCafeCategory(category)?.id,
      isAvailable: data['isAvailable'] == true,
      isVisible: data['isVisible'] != false,
    );
  }

  String _formatManagementTime(DateTime date) {
    final local = date.toLocal();
    final datePart = '${local.year.toString().padLeft(4, '0')}-'
        '${local.month.toString().padLeft(2, '0')}-'
        '${local.day.toString().padLeft(2, '0')}';
    final timePart = '${local.hour.toString().padLeft(2, '0')}:'
        '${local.minute.toString().padLeft(2, '0')}:'
        '${local.second.toString().padLeft(2, '0')}';
    return '$datePart $timePart';
  }

