  Future<void> _deleteRejectedStaffRequest(
    String uid, {
    required String email,
  }) async {
    if (!_canUseManagementTools || _reviewingStaffRequestUids.contains(uid)) {
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text(
          'Eliminar solicitud rechazada',
          style: TextStyle(color: cream),
        ),
        content: Text(
          '¿Eliminar la solicitud de $email? Esta acción no se puede deshacer.',
          style: const TextStyle(color: muted),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('CANCELAR'),
          ),
          FilledButton(
            style: FilledButton.styleFrom(
              backgroundColor: const Color(0xFF8B3A32),
            ),
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('ELIMINAR'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;

    setState(() => _reviewingStaffRequestUids.add(uid));
    try {
      final firestore = FirebaseFirestore.instance;
      final requestReference =
          firestore.collection('staffAccessRequests').doc(uid);
      await firestore.runTransaction<void>((transaction) async {
        final request = await transaction.get(requestReference);
        if (!request.exists || request.data()?['status'] != 'rejected') {
          throw StateError('La solicitud ya no está rechazada.');
        }
        final username = request.data()?['username'];
        if (username is String && username.trim().isNotEmpty) {
          final reservationReference = firestore
              .collection('usernameRegistry')
              .doc(UsernameRegistryService.normalize(username));
          final reservation = await transaction.get(reservationReference);
          if (reservation.data()?['uid'] == uid) {
            transaction.delete(reservationReference);
          }
        }
        transaction.delete(requestReference);
      });
      if (mounted) {
        _showSnackBar('Se eliminó la solicitud rechazada de $email.');
      }
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo eliminar la solicitud rechazada (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          error.code == 'permission-denied'
              ? 'Firestore no autorizó eliminarla. Actualiza las reglas de seguridad.'
              : 'No se pudo eliminar la solicitud (${error.code}).',
        );
      }
    } on StateError catch (error) {
      if (mounted) _showSnackBar(error.message);
    } finally {
      if (mounted) setState(() => _reviewingStaffRequestUids.remove(uid));
    }
  }

  Future<void> _reviewStaffAccessRequest(
    String uid,
    String requestedRole, {
    required bool approve,
  }) async {
    if (!_canUseManagementTools || _reviewingStaffRequestUids.contains(uid)) {
      return;
    }
    if (!const {'barista', 'cajero'}.contains(requestedRole)) {
      _showSnackBar('La solicitud contiene un rol no válido.');
      return;
    }
    setState(() => _reviewingStaffRequestUids.add(uid));
    final requestReference =
        FirebaseFirestore.instance.collection('staffAccessRequests').doc(uid);
    final staffReference =
        FirebaseFirestore.instance.collection('pos_staff').doc(uid);
    try {
      await FirebaseFirestore.instance
          .runTransaction<void>((transaction) async {
        final requestSnapshot = await transaction.get(requestReference);
        final staffSnapshot = await transaction.get(staffReference);
        if (!requestSnapshot.exists ||
            requestSnapshot.data()?['status'] != 'pending') {
          throw StateError('La solicitud ya fue revisada o no existe.');
        }
        if (approve) {
          final requestData = requestSnapshot.data()!;
          final staffData = {
            'email': requestData['email'] as String,
            'displayName': requestData['displayName'] as String? ??
                (requestData['email'] as String).split('@').first,
            if (requestData['username'] is String)
              'username': requestData['username'] as String,
            'birthDate': requestData['birthDate'] as String,
            'role': requestedRole,
            'approvedAt': FieldValue.serverTimestamp(),
          };
          if (staffSnapshot.exists) {
            transaction.set(staffReference, staffData, SetOptions(merge: true));
          } else {
            transaction.set(staffReference, {
              ...staffData,
              'createdAt': FieldValue.serverTimestamp(),
            });
          }
        }
        transaction.update(requestReference, {
          'status': approve ? 'approved' : 'rejected',
          'reviewedAt': FieldValue.serverTimestamp(),
          'reviewedBy': _firebaseUser!.uid,
        });
      });
      _showSnackBar(
        approve
            ? 'Solicitud aprobada. El rol $requestedRole quedó asignado en el perfil de personal.'
            : 'Solicitud de acceso rechazada.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo revisar la solicitud de personal (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      _showSnackBar(
        'No se pudo revisar la solicitud (${error.code}). '
        'Verifica que las reglas Firestore estén actualizadas.',
      );
    } on StateError catch (error) {
      _showSnackBar(error.message);
    } finally {
      if (mounted) setState(() => _reviewingStaffRequestUids.remove(uid));
    }
  }

