      decoration: BoxDecoration(
        color: card,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: gold.withValues(alpha: 0.35)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const Row(
            children: [
              Icon(Icons.manage_accounts_outlined, color: gold, size: 20),
              SizedBox(width: 8),
              Text(
                'PERSONAL Y PERMISOS',
                style: TextStyle(
                  color: cream,
                  fontSize: 11,
                  letterSpacing: 0.8,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          const Text(
            'Aquí solo aparece personal con acceso aprobado. Los cambios de '
            'rol se guardan en su perfil de personal.',
            style: TextStyle(color: muted, fontSize: 11, height: 1.4),
          ),
          const SizedBox(height: 8),
          StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('pos_staff')
                .limit(100)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return Text(
                  'No se pudo cargar el personal. Verifica el permiso '
                  'de gerencia.\n${snapshot.error}',
                  style: const TextStyle(color: Color(0xFFFF8A80)),
                );
              }
              if (!snapshot.hasData) {
                return const Padding(
                  padding: EdgeInsets.all(16),
                  child: Center(
                    child: CircularProgressIndicator(color: gold),
                  ),
                );
              }
              final staff = snapshot.data!.docs.where((employee) {
                final data = employee.data();
                final role = data['role'] ?? data['rol'];
                return role is String &&
                    const {'barista', 'cajero'}.contains(
                      normalizeUserRole(role),
                    );
              }).toList()
                ..sort((left, right) {
                  final leftEmail = left.data()['email'];
                  final rightEmail = right.data()['email'];
                  return (leftEmail is String ? leftEmail : '')
                      .compareTo(rightEmail is String ? rightEmail : '');
                });
              if (staff.isEmpty) {
                return const Text(
                  'No hay personal con acceso aprobado todavía.',
                  style: TextStyle(color: muted, fontSize: 12),
                );
              }
              return Column(
                children: staff.map((employee) {
                  final data = employee.data();
                  final email = data['email'] is String
                      ? data['email'] as String
                      : employee.id;
                  final displayName = data['displayName'] is String
                      ? data['displayName'] as String
                      : email;
                  final storedRole = data['role'] ?? data['rol'];
                  final role =
                      storedRole is String ? normalizeUserRole(storedRole) : '';
                  return ListTile(
                    dense: true,
                    contentPadding: EdgeInsets.zero,
                    title: Text(
                      displayName,
                      style: const TextStyle(color: cream, fontSize: 12),
                    ),
                    subtitle: Text(
                      email,
                      style: const TextStyle(color: muted, fontSize: 10),
                    ),
                    trailing: DropdownButton<String>(
                      value: role,
                      dropdownColor: card,
                      style: const TextStyle(color: cream, fontSize: 11),
                      items: const ['barista', 'cajero']
                          .map(
                            (itemRole) => DropdownMenuItem(
                              value: itemRole,
                              child: Text(itemRole.toUpperCase()),
                            ),
                          )
                          .toList(),
                      onChanged: (newRole) {
                        if (newRole == null || newRole == role) return;
                        unawaited(
                          _updateStaffRole(
                            employee.id,
                            newRole,
                            email,
                          ),
                        );
                      },
                    ),
                  );
                }).toList(),
              );
            },
          ),
        ],
      ),
    );
  }

  Future<void> _updateStaffRole(
    String uid,
    String role,
    String email,
  ) async {
    try {
      await FirebaseFirestore.instance
          .collection('pos_staff')
          .doc(uid)
          .update({'role': role});
      _showSnackBar('Rol de $email actualizado a $role.');
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo actualizar el rol (${error.code}): $email');
      debugPrintStack(stackTrace: stackTrace);
      _showSnackBar('No se pudo cambiar el rol (${error.code}).');
    }
  }

