                final documents = snapshot.data?.docs ?? [];
                final grossTotal = documents.fold<double>(
                  0,
                  (sum, document) {
                    final amount = document.data()['total'];
                    return sum + (amount is num ? amount.toDouble() : 0);
                  },
                );
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      '${documents.length} pedidos recientes · '
                      'total registrado ${_formatPrice(grossTotal)}',
                      style: const TextStyle(color: cream2, fontSize: 12),
                    ),
                    if (documents.isEmpty)
                      const Padding(
                        padding: EdgeInsets.symmetric(vertical: 16),
                        child: Text(
                          'Aún no hay pedidos persistidos en esta colección.',
                          style: TextStyle(color: muted),
                        ),
                      )
                    else
                      ...documents.map((document) {
                        final data = document.data();
                        final createdAt = data['createdAt'];
                        final dateText = createdAt is Timestamp
                            ? createdAt.toDate().toLocal().toString().substring(
                                  0,
                                  16,
                                )
                            : 'Fecha no disponible';
                        final orderId = document.id;
                        final shortId = orderId.length > 10
                            ? orderId.substring(0, 10)
                            : orderId;
                        final amount = data['total'];
                        final status = data['status'] is String
                            ? data['status'] as String
                            : 'sin estado';
                        return ListTile(
                          dense: true,
                          contentPadding: EdgeInsets.zero,
                          leading: const Icon(
                            Icons.receipt_long_outlined,
                            color: gold,
                            size: 19,
                          ),
                          title: Text(
                            'Pedido $shortId · $status',
                            style: const TextStyle(color: white, fontSize: 12),
                          ),
                          subtitle: Text(
                            dateText,
                            style: const TextStyle(color: muted, fontSize: 10),
                          ),
                          trailing: Text(
                            _formatPrice(amount is num ? amount.toDouble() : 0),
                            style: const TextStyle(color: cream, fontSize: 11),
                          ),
                        );
                      }),
                  ],
                );
              },
            ),
        ],
      ),
    );
  }

