  Widget _publicAnnouncementsPreview() {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('managementAnnouncements')
          .where('isActive', isEqualTo: true)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return const Text(
            'No se pudieron cargar las novedades.',
            style: TextStyle(color: muted, fontSize: 11),
          );
        }
        if (!snapshot.hasData) {
          return const LinearProgressIndicator(color: gold);
        }
        final announcements = snapshot.data!.docs.toList()
          ..sort((first, second) {
            final firstTime = first.data()['updatedAt'];
            final secondTime = second.data()['updatedAt'];
            if (firstTime is Timestamp && secondTime is Timestamp) {
              return secondTime.compareTo(firstTime);
            }
            return 0;
          });
        if (announcements.isEmpty) {
          return const Text(
            'Próximamente nuevas promociones y eventos.',
            style: TextStyle(color: muted, fontSize: 11),
          );
        }
        return Column(
          children: announcements.take(3).map((document) {
            final data = document.data();
            final isEvent = data['type'] == 'event';
            final title = data['title'] is String
                ? data['title'] as String
                : 'Novedad Wolves Club';
            final description = data['description'] is String
                ? data['description'] as String
                : '';
            final dateLabel = data['dateLabel'] is String
                ? (data['dateLabel'] as String).trim()
                : '';
            return Container(
              width: double.infinity,
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: card,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: gold.withValues(alpha: 0.35)),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(
                    isEvent ? Icons.event_outlined : Icons.local_offer_outlined,
                    color: gold,
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          isEvent ? 'EVENTO' : 'PROMOCIÓN',
                          style: const TextStyle(
                            color: gold,
                            fontSize: 9,
                            letterSpacing: 1,
                          ),
                        ),
                        const SizedBox(height: 3),
                        Text(
                          title,
                          style: const TextStyle(
                            color: cream,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        if (dateLabel.isNotEmpty)
                          Text(
                            dateLabel,
                            style: const TextStyle(color: gold, fontSize: 11),
                          ),
                        if (description.isNotEmpty)
                          Text(
                            description,
                            style: const TextStyle(
                              color: muted,
                              fontSize: 11,
                              height: 1.4,
                            ),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          }).toList(growable: false),
        );
      },
    );
  }

