  void _startMatch() {
    setState(() {
      _recordCurrentPageForBack('wolvesMatch');
      previousPage = page;
      page = 'wolvesMatch';
    });
  }

  void _beginMatchQuiz(String intent) {
    setState(() {
      _recordCurrentPageForBack('match');
      _matchIntent = intent;
      page = 'match';
      quizAnswers.clear();
      quizStep = 0;
      selectedMatchIndex = 0;
      sentIcebreakers.clear();
    });
  }

  void _advanceIcebreaker() {
    if (!quizAnswers.containsKey(quizStep)) {
      _showSnackBar('Elige una respuesta para continuar.');
      return;
    }

    if (quizStep == 0) {
      setState(() => quizStep = 1);
      return;
    }

    setState(() {
      selectedMatchIndex = _recommendedMatchIndex();
      _recordCurrentPageForBack('matchProfiles');
      previousPage = page;
      page = 'matchProfiles';
    });
  }

  int _recommendedMatchIndex() {
    final preferredDate = quizAnswers[0];
    final preferredPower = quizAnswers[1];
    var bestIndex = 0;
    var bestScore = -1;

    for (var index = 0; index < matchProfiles.length; index++) {
      final profile = matchProfiles[index];
      var score = 0;
      if (profile['date'] == preferredDate) score += 2;
      if (profile['power'] == preferredPower) score++;
      if (score > bestScore) {
        bestIndex = index;
        bestScore = score;
      }
    }

    return bestIndex;
  }

  void _changeMatchProfile(int direction) {
    setState(() {
      selectedMatchIndex =
          (selectedMatchIndex + direction + matchProfiles.length) %
              matchProfiles.length;
    });
  }

  void _proposeFirstDate() {
    final rewardGranted = !matchRewardGranted;

    setState(() {
      if (rewardGranted) {
        xp += 150;
      }
      matchRewardGranted = true;
      currentMatchRewardGranted = rewardGranted;
      _recordCurrentPageForBack('matchCelebration');
      previousPage = page;
      page = 'matchCelebration';
    });
  }

