  double _playCompatibility(Map<String, Object> profile) {
    if (petProfiles.isEmpty) return 0.6;
    final kiara = petProfiles.firstWhere((pet) => pet.name == 'Kiara');
    final otherInterests = (profile['interests'] as List<String>).toSet();
    final kiaraInterests = kiara.interests.toSet();
    final sharedInterests = kiaraInterests.intersection(otherInterests).length;
    final allInterests = kiaraInterests.union(otherInterests).length;
    final interestScore =
        allInterests == 0 ? 0.0 : sharedInterests / allInterests;

    final sizeDistance = (_petSizes.indexOf(kiara.size) -
            _petSizes.indexOf(profile['size'] as String))
        .abs();
    final sizeScore = sizeDistance == 0
        ? 1.0
        : sizeDistance == 1
            ? 0.7
            : 0.4;
    final energyScore = kiara.energyLevel == profile['energyLevel'] ? 1.0 : 0.6;

    return sizeScore * 0.35 + energyScore * 0.3 + interestScore * 0.35;
  }

  Widget _playCompatibilityMeter(Map<String, Object> profile) {
    final compatibility = _playCompatibility(profile);
    final percentage = (compatibility * 100).round();

    return Container(
