  void _openMatchChat() {
    setState(() {
      previousPage = page;
      page = 'chat';
      _messageCredits = null;
      _chatCreditsLoading = true;
      _chatQuotaBlocked = false;
      _chatCreditStatus = null;
    });
    unawaited(_refreshChatCredits());
  }

  Future<void> _refreshChatCredits() async {
    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) throw StateError('Inicia sesión para continuar.');
      final credits = await _chatCreditService.loadCredits(uid: user.uid);
      if (!mounted) return;
      setState(() {
        _messageCredits = credits;
        _chatCreditsLoading = false;
        _chatQuotaBlocked = false;
        _chatCreditStatus = null;
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudieron consultar los créditos (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted) return;
      setState(() {
        _chatCreditsLoading = false;
        _chatQuotaBlocked = error.code == 'resource-exhausted';
        _chatCreditStatus = _chatFirestoreErrorMessage(error);
      });
    } on StateError catch (error) {
      if (!mounted) return;
      setState(() {
        _chatCreditsLoading = false;
        _chatCreditStatus = error.message;
      });
    } catch (error, stackTrace) {
      debugPrint('No se pudo consultar el saldo de mensajes: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted) return;
      setState(() {
        _chatCreditsLoading = false;
        _chatCreditStatus =
            'No se pudo consultar tu saldo. Inténtalo de nuevo.';
      });
    }
  }

  Future<void> _sendIcebreaker(String message) => _sendChatMessage(message);

  Future<void> _sendChatMessage(String message) async {
    final text = message.trim();
    if (text.isEmpty || _chatMessageSending) return;
    if (_chatQuotaBlocked) {
      setState(() {
        _chatCreditStatus =
            'Se alcanzó la cuota gratuita de Firestore. Los envíos están pausados.';
      });
      return;
    }
    if (_messageCredits == null || _messageCredits == 0) {
      setState(() {
        _chatCreditStatus = _messageCredits == 0
            ? 'No tienes créditos de mensaje disponibles.'
            : 'Espera a que se consulte tu saldo antes de enviar.';
      });
      return;
    }

    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      setState(() {
        _chatCreditStatus = 'Inicia sesión para enviar mensajes.';
      });
      return;
    }

    setState(() {
      _chatMessageSending = true;
      _chatCreditStatus = null;
    });
    final profile = matchProfiles[selectedMatchIndex];
    final messageId =
        '${DateTime.now().microsecondsSinceEpoch}_${Random.secure().nextInt(1 << 32).toRadixString(16)}';

    try {
      final result = await _chatCreditService.sendMessage(
        uid: user.uid,
        messageId: messageId,
        text: text,
        matchProfileId: profile['id'].toString(),
        matchName: profile['name'] as String,
      );
      if (!mounted) return;
      setState(() {
        _messageCredits = result.credits;
        if (!sentIcebreakers.contains(text)) sentIcebreakers.add(text);
        _chatCreditStatus = null;
      });
      if (_chatMessageController.text.trim() == text) {
        _chatMessageController.clear();
      }
    } on ChatCreditsExhaustedException catch (error) {
      if (!mounted) return;
      setState(() {
        _messageCredits = 0;
        _chatCreditStatus = error.toString();
      });
    } on FirebaseException catch (error, stackTrace) {
      debugPrint('No se pudo guardar el mensaje (${error.code}).');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted) return;
      setState(() {
        _chatCreditStatus = _chatFirestoreErrorMessage(error);
        if (error.code == 'resource-exhausted') _chatQuotaBlocked = true;
      });
    } catch (error, stackTrace) {
      debugPrint('No se pudo enviar el mensaje: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (!mounted) return;
      setState(() {
        _chatCreditStatus = 'No se pudo enviar el mensaje. Inténtalo de nuevo.';
      });
    } finally {
      if (mounted) {
        setState(() {
          _chatMessageSending = false;
        });
      }
    }
  }

  String _chatFirestoreErrorMessage(FirebaseException error) {
    return switch (error.code) {
      'resource-exhausted' =>
        'Se alcanzó la cuota gratuita de Firestore. Los envíos están pausados; '
            'inténtalo después de que se restablezca la cuota.',
      'permission-denied' =>
        'Firestore no autorizó la operación. Actualiza las reglas de seguridad.',
      'unavailable' ||
      'deadline-exceeded' =>
        'Firestore no está disponible ahora. Revisa tu conexión e inténtalo de nuevo.',
      _ => error.message?.trim().isNotEmpty == true
          ? error.message!.trim()
          : 'No se pudo completar la operación del chat (${error.code}).',
    };
  }

