  Widget _passport() {
    final completed = methods.where((method) => method.completed).length;

    return Padding(
      padding: const EdgeInsets.all(18),
      child: Column(
        children: [
          _topBar(title: 'COFFEE PASSPORT'),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: card,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: const Color(0xFF51483F)),
            ),
            child: const Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'RITUAL DEL CAFÉ',
                  style: TextStyle(
                    color: cream,
                    fontSize: 11,
                    letterSpacing: 2,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 8),
                Text(
                  'Cada café tiene una historia. Cada método, un carácter.',
                  style: TextStyle(
                    color: white,
                    fontSize: 17,
                    height: 1.35,
                    fontWeight: FontWeight.w600,
                  ),
                ),
                SizedBox(height: 7),
                Text(
                  'Descubre cómo cambia el aroma, la intensidad y el cuerpo del café con cada preparación.',
                  style: TextStyle(color: muted, height: 1.4, fontSize: 12),
                ),
              ],
            ),
          ),
          const SizedBox(height: 18),
          const SizedBox(height: 5),
          Text(
            '$completed/${methods.length} métodos completados',
            style: const TextStyle(color: muted),
          ),
          const SizedBox(height: 10),
          ClipRRect(
            borderRadius: BorderRadius.circular(10),
            child: LinearProgressIndicator(
              value: completed / methods.length,
              minHeight: 7,
              backgroundColor: const Color(0xFF312C28),
              valueColor: const AlwaysStoppedAnimation(cream),
            ),
          ),
          if (completed < methods.length) ...[
            const SizedBox(height: 14),
            Align(
              alignment: Alignment.centerLeft,
              child: Text(
                'TE FALTAN ${methods.length - completed} MÉTODOS',
                style: const TextStyle(
                  color: gold,
                  fontSize: 10,
                  letterSpacing: 1,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            const SizedBox(height: 7),
            Align(
              alignment: Alignment.centerLeft,
              child: Wrap(
                spacing: 6,
                runSpacing: 6,
                children: methods
                    .where((method) => !method.completed)
                    .map(
                      (method) => Chip(
                        avatar: const Icon(
                          Icons.hourglass_empty,
                          color: gold,
                          size: 14,
                        ),
                        label: Text(
                          method.name,
                          style: const TextStyle(
                            color: cream2,
                            fontSize: 9,
                          ),
                        ),
                        backgroundColor: card2,
                        side: const BorderSide(color: brownDark),
                        visualDensity: VisualDensity.compact,
                        materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                      ),
                    )
                    .toList(growable: false),
              ),
            ),
          ] else
            const Padding(
              padding: EdgeInsets.only(top: 12),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  '¡Completaste los 9 métodos!',
                  style: TextStyle(
                    color: green,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
            ),
          const SizedBox(height: 20),
          LayoutBuilder(
            builder: (context, constraints) {
              final columns = constraints.maxWidth >= 700 ? 4 : 2;
              return GridView.builder(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: methods.length,
                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: columns,
                  crossAxisSpacing: 10,
                  mainAxisSpacing: 10,
                  childAspectRatio: 1.25,
                ),
                itemBuilder: (_, index) {
                  final method = methods[index];

                  return InkWell(
                    onTap: () async {
                      setState(
                        () {
                          selectedPassportMethodName = method.name;
                          _passportTastingNoteMessage = null;
                        },
                      );
                      await _loadPassportTastingNote(method);
                      if (!mounted) return;
                      go('passportDetail');
                    },
                    borderRadius: BorderRadius.circular(14),
                    child: Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: card,
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                          color: method.completed
                              ? const Color(0xFF766253)
                              : const Color(0xFF302C29),
                        ),
                      ),
                      child: Row(
                        children: [
                          ClipRRect(
                            borderRadius: BorderRadius.circular(8),
                            child: Image.asset(
                              method.imageAsset,
                              width: 54,
                              height: 54,
                              fit: BoxFit.cover,
                              errorBuilder: (context, error, stackTrace) =>
                                  Container(
                                width: 54,
                                height: 54,
                                color: card2,
                                alignment: Alignment.center,
                                child: Icon(
                                  method.icon,
                                  color: method.completed ? cream : muted,
                                  size: 25,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(width: 9),
                          Expanded(
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  method.name,
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: white,
                                    fontSize: 11,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  method.personality,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: muted,
                                    fontSize: 9,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          const SizedBox(width: 4),
                          Icon(
                            method.completed
                                ? Icons.check_circle
                                : Icons.arrow_forward_ios,
                            color: method.completed ? green : muted,
                            size: 14,
                          ),
                        ],
                      ),
                    ),
                  );
                },
              );
            },
          ),
          const SizedBox(height: 20),
          _legendaryCard(),
        ],
      ),
    );
  }

