  // ==========================================================
  // EVENTS
  // ==========================================================

  Widget _events() {
    return Padding(
      padding: const EdgeInsets.all(18),
      child: Column(
        children: [
          _topBar(title: 'EVENTS'),
          Row(
            children: [
              Expanded(
                child: _tabButton(
                  'Próximos',
                  !_showMyEvents,
                  () => setState(() => _showMyEvents = false),
                ),
              ),
              Expanded(
                child: _tabButton(
                  'Mis eventos',
                  _showMyEvents,
                  () => setState(() => _showMyEvents = true),
                ),
              ),
            ],
          ),
          const SizedBox(height: 20),
          if (_showMyEvents)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 38, horizontal: 18),
              child: Text(
                'Todavía no tienes eventos guardados. Explora los próximos encuentros y encuentra tu plan.',
                textAlign: TextAlign.center,
                style: TextStyle(color: muted, height: 1.5),
              ),
            )
          else
            StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance
                  .collection('managementAnnouncements')
                  .where('isActive', isEqualTo: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return const Text(
                    'No se pudieron cargar los eventos.',
                    style: TextStyle(color: Color(0xFFFF8A80)),
                  );
                }
                if (!snapshot.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(18),
                    child: CircularProgressIndicator(color: gold),
                  );
                }
                final events = snapshot.data!.docs
                    .where((document) => document.data()['type'] == 'event')
                    .toList(growable: false);
                if (events.isEmpty) {
                  return const Padding(
                    padding: EdgeInsets.symmetric(vertical: 38, horizontal: 18),
                    child: Text(
                      'No hay eventos publicados por el momento. Vuelve pronto para ver las novedades.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: muted, height: 1.5),
                    ),
                  );
                }
                return Column(
                  children: events.map((document) {
                    final data = document.data();
                    final title = data['title'] is String
                        ? data['title'] as String
                        : 'Evento Wolves Club';
                    final description = data['description'] is String
                        ? data['description'] as String
                        : '';
                    final dateLabel = data['dateLabel'] is String
                        ? (data['dateLabel'] as String).trim()
                        : '';
                    return _eventCard(
                      title,
                      description,
                      dateLabel.isEmpty ? 'PRÓXIMAMENTE' : dateLabel,
                      Icons.event,
                      () {
                        setState(() => _selectedPublicEvent = data);
                        go('eventDetail');
                      },
                    );
                  }).toList(growable: false),
                );
              },
            ),
        ],
      ),
    );
  }

