    final event = _selectedPublicEvent;
    final title =
        event?['title'] is String ? event!['title'] as String : 'EVENTO';
    final description =
        event?['description'] is String ? event!['description'] as String : '';
    final dateLabel = event?['dateLabel'] is String
        ? event!['dateLabel'] as String
        : 'Fecha pendiente';
    return Padding(
      padding: const EdgeInsets.all(20),
      child: Column(
        children: [
          _topBar(
            title: 'EVENTO',
            backButton: true,
            menuButton: false,
          ),
          _coffeeImage(height: 240),
          const SizedBox(height: 20),
          Align(
            alignment: Alignment.centerLeft,
            child: Text(
              title,
              style: const TextStyle(
                color: white,
                fontSize: 28,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
          const SizedBox(height: 7),
          Align(
            alignment: Alignment.centerLeft,
            child: Text(
              dateLabel,
              style: const TextStyle(color: muted),
            ),
          ),
          const SizedBox(height: 25),
          Text(
            description,
            style: const TextStyle(
              color: white,
              height: 1.5,
            ),
          ),
          const SizedBox(height: 25),
          _primaryButton(
            'QUIERO IR',
            () {
              setState(() => xp += 150);
              _showSnackBar('¡Te registraste al evento! +150 XP');
            },
          ),
        ],
      ),
    );
  }

