  Widget _shop() {
    return StreamBuilder<List<Product>>(
      stream: _productCatalogService.getWolvesShopItems(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _managementStatusCard(
            'No se pudo cargar Wolves Shop: ${snapshot.error}',
            error: true,
          );
        }
        return StreamBuilder<Set<String>>(
          stream: _watchWolvesShopFallbackExclusions(),
          builder: (context, exclusionsSnapshot) {
            if (exclusionsSnapshot.hasError) {
              return _managementStatusCard(
                'No se pudo cargar el catálogo de Wolves Shop.',
                error: true,
              );
            }
            final excludedIds = exclusionsSnapshot.data ?? const <String>{};
            final products = _shopProducts
                .where((product) => !excludedIds.contains(product.id))
                .toList();
            for (final product in snapshot.data ?? const <Product>[]) {
              final index =
                  products.indexWhere((item) => item.id == product.id);
              if (!product.isVisible) {
                if (index >= 0) products.removeAt(index);
                continue;
              }
              final category = _shopCategoryLabel(product.category);
              final shopProduct = ShopProduct(
                id: product.id,
                category: category,
                name: product.name,
                description: product.description,
                sku: product.sku,
                icon: category == 'Coleccionables'
                    ? Icons.local_cafe
                    : Icons.storefront_outlined,
                price: product.price,
                stock: product.stock,
                sizes: product.stockBySize,
                imageAsset: index >= 0 ? products[index].imageAsset : null,
                imageUrl: product.imageUrl,
                status: product.stock > 0
                    ? ShopItemStatus.available
                    : ShopItemStatus.soldOut,
              );
              if (index == -1) {
                products.add(shopProduct);
              } else {
                products[index] = shopProduct;
              }
            }
            return _shopContent(products);
          },
        );
      },
    );
  }

