                      decoration:
                          const InputDecoration(labelText: 'Nivel de energía'),
                      items: _energyLevels
                          .map(
                            (energy) => DropdownMenuItem(
                              value: energy,
                              child: Text(energy),
                            ),
                          )
                          .toList(),
                      onChanged: (value) =>
                          setDialogState(() => selectedEnergy = value),
                      validator: (value) => value == null
                          ? 'Selecciona su nivel de energía.'
                          : null,
                    ),
                    const SizedBox(height: 16),
                    const Text(
                      'Intereses',
                      style: TextStyle(
                        color: cream,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Wrap(
                      spacing: 6,
                      runSpacing: 2,
                      children: _petInterestOptions.map((interest) {
                        final isSelected = selectedInterests.contains(interest);
                        return FilterChip(
                          label: Text(interest),
                          selected: isSelected,
                          selectedColor: brownDark,
                          checkmarkColor: gold,
                          labelStyle: TextStyle(
                            color: isSelected ? cream : muted,
                            fontSize: 11,
                          ),
                          onSelected: (selected) {
                            setDialogState(() {
                              if (selected) {
                                selectedInterests.add(interest);
                              } else {
                                selectedInterests.remove(interest);
                              }
                              interestsError = null;
                            });
                          },
                        );
                      }).toList(),
                    ),
                    if (interestsError != null) ...[
                      const SizedBox(height: 4),
                      Text(
                        interestsError!,
                        style: TextStyle(
                          color: Theme.of(dialogContext).colorScheme.error,
                          fontSize: 12,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(),
                child: const Text('CANCELAR'),
              ),
              ElevatedButton(
                onPressed: () {
                  final isValid = formKey.currentState?.validate() ?? false;
                  if (!isValid || selectedInterests.isEmpty) {
                    setDialogState(() {
                      interestsError = selectedInterests.isEmpty
                          ? 'Selecciona al menos un interés.'
                          : null;
                    });
                    return;
                  }

                  setState(() {
                    petProfiles.add(
                      PetProfile(
                        name: nameController.text.trim(),
                        breed: breedController.text.trim(),
                        age: ageController.text.trim(),
                        size: selectedSize!,
                        energyLevel: selectedEnergy!,
                        interests: List<String>.unmodifiable(selectedInterests),
                      ),
                    );
                    xp += 50;
                  });
                  Navigator.of(dialogContext).pop();
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        '¡Perfil de mascota completado! +50 XP para $userName 🎉',
                      ),
                    ),
                  );
                },
                child: const Text('GUARDAR PERFIL · +50 XP'),
              ),
            ],
          ),
        ),
      );
    } finally {
      nameController.dispose();
      breedController.dispose();
      ageController.dispose();
    }
  }

