  Future<void> _showMyCustomerComplaintHistory(String customerUid) async {
    await showDialog<void>(
      context: _navigatorKey.currentContext ?? context,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: card,
        title: const Text(
          'MIS MENSAJES A SOPORTE',
          style: TextStyle(color: cream, fontSize: 14),
        ),
        content: SizedBox(
          width: 440,
          height: 420,
          child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
            stream: FirebaseFirestore.instance
                .collection('customerComplaints')
                .where('customerUid', isEqualTo: customerUid)
                .limit(50)
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.hasError) {
                return _managementStatusCard(
                  'No se pudo cargar tu historial (${snapshot.error}).',
                  error: true,
                );
              }
              if (!snapshot.hasData) {
                return const Center(
                  child: CircularProgressIndicator(color: gold),
                );
              }
              final cases = snapshot.data!.docs.toList()
                ..sort((first, second) {
                  final firstAt = first.data()['createdAt'];
                  final secondAt = second.data()['createdAt'];
                  final firstDate =
                      firstAt is Timestamp ? firstAt.toDate() : DateTime(1970);
                  final secondDate = secondAt is Timestamp
                      ? secondAt.toDate()
                      : DateTime(1970);
                  return secondDate.compareTo(firstDate);
                });
              if (cases.isEmpty) {
                return const Center(
                  child: Text(
                    'Todavía no has enviado mensajes a soporte.',
                    textAlign: TextAlign.center,
                    style: TextStyle(color: muted, fontSize: 12),
                  ),
                );
              }
              return ListView.separated(
                itemCount: cases.length,
                separatorBuilder: (_, __) => const Divider(color: brownDark),
                itemBuilder: (context, index) {
                  final document = cases[index];
                  final data = document.data();
                  final status = data['status'] as String? ?? 'new';
                  final statusLabel = switch (status) {
                    'reviewing' => 'EN REVISIÓN',
                    'resolved' => 'RESUELTO',
                    _ => 'PENDIENTE',
                  };
                  final feedbackLabel = switch (data['feedbackType']) {
                    'suggestion' => 'SUGERENCIA',
                    'compliment' => 'FELICITACIÓN',
                    'complaint' => 'RECLAMO',
                    _ => 'MENSAJE',
                  };
                  return Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: card2,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Text(
                          '$feedbackLabel · '
                          '${data['supportCategory'] ?? 'General'} · '
                          '$statusLabel',
                          style: const TextStyle(
                            color: gold,
                            fontSize: 10,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                        const SizedBox(height: 5),
                        if ((data['subject'] as String?)?.isNotEmpty == true)
                          Text(
                            data['subject'] as String,
                            style: const TextStyle(
                              color: cream,
                              fontSize: 12,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        const SizedBox(height: 5),
                        Text(
                          data['details'] as String? ?? '',
                          style: const TextStyle(color: cream, fontSize: 11),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          data['statusMessage'] as String? ??
                              data['autoReply'] as String? ??
                              'Tu mensaje fue recibido por el equipo de Coffee Wolves.',
                          style: const TextStyle(
                            color: cream2,
                            fontSize: 10,
                            height: 1.4,
                          ),
                        ),
                        if ((data['orderId'] as String?)?.trim().isNotEmpty ==
                            true)
                          Padding(
                            padding: const EdgeInsets.only(top: 4),
                            child: Text(
                              'Pedido: ${data['orderId']}',
                              style: const TextStyle(
                                color: muted,
                                fontSize: 9,
                              ),
                            ),
                          ),
                      ],
                    ),
                  );
                },
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('CERRAR'),
          ),
        ],
      ),
    );
  }

