  Future<void> _showSupportScreenshot(
    String base64Image,
    String? imageName,
  ) async {
    try {
      final bytes = base64Decode(base64Image);
      await showDialog<void>(
        context: _navigatorKey.currentContext ?? context,
        builder: (dialogContext) => AlertDialog(
          backgroundColor: card,
          title: Text(
            imageName?.isNotEmpty == true ? imageName! : 'Captura adjunta',
            style: const TextStyle(color: cream, fontSize: 14),
          ),
          content: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 640, maxHeight: 520),
            child: InteractiveViewer(
              child: Image.memory(
                bytes,
                fit: BoxFit.contain,
                errorBuilder: (context, error, stackTrace) => const Text(
                  'No se pudo mostrar la imagen adjunta.',
                  style: TextStyle(color: muted),
                ),
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('CERRAR'),
            ),
          ],
        ),
      );
    } on FormatException catch (error, stackTrace) {
      debugPrint(
          'La captura de soporte no tiene formato Base64 válido: $error');
      debugPrintStack(stackTrace: stackTrace);
      _showSnackBar('No se pudo abrir la captura adjunta.');
    }
  }

  Future<void> _showCustomerComplaintForm() async {
    final user = FirebaseAuth.instance.currentUser ?? _firebaseUser;
    final detailsController = TextEditingController();
    final subjectController = TextEditingController();
    final memberCardIdController = TextEditingController();
    final orderController = TextEditingController();
    var selectedShift = 'morning';
    var selectedFeedbackType = 'complaint';
    var selectedIncident = 'Atención';
    var selectedSupportCategory = 'Mi Bitácora';
    Uint8List? screenshotBytes;
    String? screenshotName;
    var isSubmitting = false;
    String? errorMessage;

    Future<void> selectSupportScreenshot(
      BuildContext dialogContext,
      StateSetter setDialogState,
    ) async {
      try {
        final selectedImage = await _cafeImagePicker.pickImage(
          source: ImageSource.gallery,
          imageQuality: 90,
          maxWidth: 1600,
          maxHeight: 1600,
        );
        if (selectedImage == null || !dialogContext.mounted) return;
        final originalBytes = await selectedImage.readAsBytes();
        final compressedBytes =
            await compute(_compressSupportScreenshotBytes, originalBytes);
        if (!dialogContext.mounted) return;
        setDialogState(() {
          screenshotBytes = compressedBytes;
          screenshotName = selectedImage.name;
          errorMessage = null;
        });
      } catch (error, stackTrace) {
        debugPrint('No se pudo adjuntar la captura de soporte: $error');
        debugPrintStack(stackTrace: stackTrace);
        if (dialogContext.mounted) {
          setDialogState(() {
            errorMessage =
                'No se pudo preparar la captura. Elige una imagen más pequeña.';
          });
        }
      }
    }

    try {
      await showDialog<void>(
        context: _navigatorKey.currentContext ?? context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: const Text(
              'Soporte y Feedback de Clientes',
              style: TextStyle(color: cream),
            ),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  OutlinedButton.icon(
                    key: const ValueKey('customer-support-history'),
                    onPressed: isSubmitting || user == null
                        ? null
                        : () => unawaited(
                              _showMyCustomerComplaintHistory(user.uid),
                            ),
                    icon: const Icon(Icons.inbox_outlined, size: 16),
                    label: const Text('VER MIS MENSAJES Y RESPUESTAS'),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: gold,
                      side: BorderSide(color: gold.withValues(alpha: 0.5)),
                    ),
                  ),
                  const SizedBox(height: 6),
                  const Text(
                    'Al enviar recibirás una confirmación automática. Gerencia podrá revisar y actualizar el estado de tu caso.',
                    textAlign: TextAlign.center,
                    style: TextStyle(color: muted, fontSize: 10, height: 1.4),
                  ),
                  if (user?.emailVerified != true) ...[
                    const SizedBox(height: 8),
                    Text(
                      user == null
                          ? 'Puedes completar el formulario. Para enviarlo, inicia sesión y verifica el correo de tu cuenta.'
                          : 'Puedes completar el formulario. Para enviarlo, primero verifica el correo de tu cuenta.',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: Color(0xFFFFCC80),
                        fontSize: 11,
                        height: 1.4,
                      ),
                    ),
                  ],
                  const SizedBox(height: 10),
                  DropdownButtonFormField<String>(
                    value: selectedSupportCategory,
                    dropdownColor: card2,
                    decoration: const InputDecoration(
                      labelText: 'Sección relacionada',
                    ),
                    items: const [
                      'Mi Bitácora',
                      'Wolves Member Card',
                      'Billetera',
                      'Mis Colecciones',
                      'Álbum Cold Brew',
                      'Wolves Match',
                      'Hoy nos falta uno',
                      'Mis Mascotas',
                      'Mis Pedidos',
                      'Otro',
                    ]
                        .map(
                          (category) => DropdownMenuItem(
                            value: category,
                            child: Text(category),
                          ),
                        )
                        .toList(),
                    onChanged: isSubmitting
                        ? null
                        : (value) {
                            if (value != null) {
                              setDialogState(
                                () => selectedSupportCategory = value,
                              );
                            }
                          },
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: subjectController,
                    enabled: !isSubmitting,
                    maxLength: 120,
                    decoration: const InputDecoration(
                      labelText: 'Asunto',
                      hintText: 'Resume tu consulta en una frase',
                    ),
                  ),
                  const SizedBox(height: 4),
                  TextField(
                    controller: memberCardIdController,
                    enabled: !isSubmitting,
                    maxLength: 120,
                    decoration: const InputDecoration(
                      labelText: 'ID de Wolves Member Card (opcional)',
                      hintText: 'Solo si tienes una Member Card',
                      prefixIcon: Icon(Icons.badge_outlined),
                    ),
                  ),
                  const SizedBox(height: 10),
                  DropdownButtonFormField<String>(
                    value: selectedShift,
                    dropdownColor: card2,
                    decoration: const InputDecoration(
                      labelText: '¿En qué turno ocurrió?',
                    ),
                    items: const [
                      DropdownMenuItem(
                        value: 'morning',
                        child: Text('Mañana'),
                      ),
                      DropdownMenuItem(
                        value: 'afternoon',
                        child: Text('Tarde'),
                      ),
                    ],
                    onChanged: isSubmitting
                        ? null
                        : (value) {
                            if (value != null) {
                              setDialogState(() => selectedShift = value);
                            }
                          },
                  ),
                  const SizedBox(height: 10),
                  DropdownButtonFormField<String>(
                    value: selectedFeedbackType,
                    dropdownColor: card2,
                    decoration: const InputDecoration(
                      labelText: 'Tipo de mensaje',
                    ),
                    items: const [
                      DropdownMenuItem(
                        value: 'suggestion',
                        child: Text('Sugerencia'),
                      ),
                      DropdownMenuItem(
                        value: 'compliment',
                        child: Text('Felicitación'),
                      ),
                      DropdownMenuItem(
                        value: 'complaint',
                        child: Text('Reclamo'),
                      ),
                    ],
                    onChanged: isSubmitting
                        ? null
                        : (value) {
                            if (value != null) {
                              setDialogState(
                                () => selectedFeedbackType = value,
                              );
                            }
                          },
                  ),
                  const SizedBox(height: 10),
                  DropdownButtonFormField<String>(
                    value: selectedIncident,
                    dropdownColor: card2,
                    decoration: const InputDecoration(
                      labelText: 'Tipo de inconveniente',
                    ),
                    items: const [
                      'Atención',
                      'Demora',
                      'Cobro',
                      'Producto',
                      'Otro',
                    ]
                        .map(
                          (incident) => DropdownMenuItem(
                            value: incident,
                            child: Text(incident),
                          ),
                        )
                        .toList(),
                    onChanged: isSubmitting
                        ? null
                        : (value) {
                            if (value != null) {
                              setDialogState(() => selectedIncident = value);
                            }
                          },
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    controller: orderController,
                    enabled: !isSubmitting,
                    maxLength: 100,
                    decoration: const InputDecoration(
                      labelText: 'ID de pedido (opcional)',
                    ),
                  ),
                  const SizedBox(height: 10),
                  OutlinedButton.icon(
                    onPressed: isSubmitting
                        ? null
                        : () => selectSupportScreenshot(
                              dialogContext,
                              setDialogState,
                            ),
                    icon: const Icon(Icons.attach_file),
                    label: Text(
                      screenshotName == null
                          ? 'Adjuntar captura opcional'
                          : 'Cambiar captura · $screenshotName',
                    ),
                  ),
                  if (screenshotBytes != null) ...[
                    const SizedBox(height: 8),
                    ClipRRect(
                      borderRadius: BorderRadius.circular(10),
                      child: Image.memory(
                        screenshotBytes!,
                        height: 130,
                        fit: BoxFit.contain,
                      ),
                    ),
                    TextButton.icon(
                      onPressed: isSubmitting
                          ? null
                          : () => setDialogState(() {
                                screenshotBytes = null;
                                screenshotName = null;
                              }),
                      icon: const Icon(Icons.delete_outline, size: 16),
                      label: const Text('Quitar captura'),
                    ),
                  ],
                  const SizedBox(height: 10),
                  TextField(
                    controller: detailsController,
                    enabled: !isSubmitting,
                    minLines: 3,
                    maxLines: 6,
                    maxLength: 2000,
                    decoration: const InputDecoration(
                      labelText: 'Cuéntanos qué ocurrió',
                      alignLabelWithHint: true,
                    ),
                  ),
                  if (errorMessage != null)
                    Text(
                      errorMessage!,
                      style: const TextStyle(color: Color(0xFFE6A296)),
                    ),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed:
                    isSubmitting ? null : () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: isSubmitting
                    ? null
                    : () async {
                        final details = detailsController.text.trim();
                        final subject = subjectController.text.trim();
                        if (subject.length < 4) {
                          setDialogState(
                            () => errorMessage =
                                'Escribe un asunto de al menos 4 caracteres.',
                          );
                          return;
                        }
                        if (details.length < 10) {
                          setDialogState(
                            () => errorMessage =
                                'Describe el inconveniente en al menos 10 caracteres.',
                          );
                          return;
                        }
                        setDialogState(() {
                          isSubmitting = true;
                          errorMessage = null;
                        });
                        try {
                          final activeUser = FirebaseAuth.instance.currentUser;
                          if (activeUser == null ||
                              (user != null && activeUser.uid != user.uid)) {
                            throw StateError(
                              'Inicia sesión con una cuenta de correo para enviar tu caso.',
                            );
                          }
                          await activeUser.reload();
                          final verifiedUser =
                              FirebaseAuth.instance.currentUser;
                          if (verifiedUser == null ||
                              (user != null && verifiedUser.uid != user.uid)) {
                            throw StateError(
                              'La sesión terminó. Inicia sesión nuevamente.',
                            );
                          }
                          await verifiedUser.getIdToken(true);
                          if (!verifiedUser.emailVerified ||
                              verifiedUser.email == null) {
                            throw StateError(
                              'Verifica tu correo antes de enviar el caso.',
                            );
                          }
                          final caseId =
                              await _businessOperationsService.submitComplaint(
                            customerUid: verifiedUser.uid,
                            customerEmail: verifiedUser.email!,
                            shift: selectedShift,
                            feedbackType: selectedFeedbackType,
                            incident: selectedIncident,
                            supportCategory: selectedSupportCategory,
                            subject: subject,
                            details: details,
                            memberCardId: memberCardIdController.text,
                            orderId: orderController.text,
                            attachmentBase64: screenshotBytes == null
                                ? null
                                : base64Encode(screenshotBytes!),
                            attachmentName: screenshotName == null
                                ? null
                                : '${screenshotName!.substring(
                                    0,
                                    min(screenshotName!.length, 116),
                                  )}.jpg',
                          );
                          final autoReply =
                              customerComplaintAutoReply(selectedFeedbackType);
                          if (!dialogContext.mounted) return;
                          Navigator.pop(dialogContext);
                          await _showCustomerComplaintReceipt(
                            caseId,
                            autoReply,
                          );
                        } on FirebaseException catch (error, stackTrace) {
                          debugPrint(
                              'No se pudo enviar el mensaje (${error.code}).');
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSubmitting = false;
                            errorMessage = error.code == 'permission-denied'
                                ? 'Firestore rechazó el envío. Verifica tu '
                                    'correo e inténtalo de nuevo; si persiste, '
                                    'contacta a soporte.'
                                : 'No se pudo enviar el caso '
                                    '(${error.code}).';
                          });
                        } catch (error, stackTrace) {
                          debugPrint('No se pudo enviar el mensaje: $error');
                          debugPrintStack(stackTrace: stackTrace);
                          setDialogState(() {
                            isSubmitting = false;
                            errorMessage = 'No se pudo enviar: $error';
                          });
                        }
                      },
                child: isSubmitting
                    ? const SizedBox.square(
                        dimension: 16,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : const Text('ENVIAR A GERENCIA'),
              ),
            ],
          ),
        ),
      );
    } finally {
      detailsController.dispose();
      subjectController.dispose();
      memberCardIdController.dispose();
      orderController.dispose();
    }
  }

  void _openCustomerComplaintForm() {
