        (Object error, StackTrace stackTrace) {
          debugPrint('No se pudo abrir el formulario de soporte: $error');
          debugPrintStack(stackTrace: stackTrace);
          if (mounted) {
            _showSnackBar(
              'No se pudo abrir Soporte y Feedback. Inténtalo de nuevo.',
            );
          }
        },
      ),
    );
  }

