  static const _coldBrewFlavorProfiles = {
    'chocolate': 'Chocolate y cacao',
    'fruity': 'Frutal',
    'citrus': 'Cítrico',
    'floral': 'Floral',
    'nutty': 'Nuez y caramelo',
    'smooth': 'Suave y achocolatado',
  };

  Future<void> _showColdBrewTastingDialog({
    required String initialProfile,
    required int initialRating,
  }) async {
    final user = _firebaseUser;
    if (user == null) {
      _showSnackBar('Inicia sesión para guardar tu bitácora de cata.');
      return;
    }
    var selectedProfile = initialProfile;
    var selectedRating = initialRating;
    var isSaving = false;
    String? errorMessage;

    await showDialog<void>(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          backgroundColor: card,
          title: const Text(
            'Mi Bitácora Cold Brew',
            style: TextStyle(color: cream),
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text(
                '¿Qué perfil disfrutaste más? Guardaremos tu favorito para tu próxima visita.',
                style: TextStyle(color: muted),
              ),
              const SizedBox(height: 12),
              DropdownButtonFormField<String>(
                value: selectedProfile,
                dropdownColor: card2,
                decoration: const InputDecoration(labelText: 'Perfil de sabor'),
                items: _coldBrewFlavorProfiles.entries
                    .map(
                      (entry) => DropdownMenuItem(
                        value: entry.key,
                        child: Text(entry.value),
                      ),
                    )
                    .toList(),
                onChanged: isSaving
                    ? null
                    : (value) {
                        if (value != null) {
                          setDialogState(() => selectedProfile = value);
                        }
                      },
              ),
              const SizedBox(height: 14),
              const Text(
                '¿Cuánto te gustó?',
                style: TextStyle(color: cream),
              ),
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: List.generate(
                  5,
                  (index) => IconButton(
                    tooltip: '${index + 1} de 5',
                    onPressed: isSaving
                        ? null
                        : () => setDialogState(
                              () => selectedRating = index + 1,
                            ),
                    icon: Icon(
                      index < selectedRating ? Icons.star : Icons.star_border,
                      color: gold,
                    ),
                  ),
                ),
              ),
              if (errorMessage != null) ...[
                const SizedBox(height: 8),
                Text(
                  errorMessage!,
                  style: const TextStyle(color: Color(0xFFFF8A80)),
                ),
              ],
            ],
          ),
          actions: [
            TextButton(
              onPressed: isSaving ? null : () => Navigator.pop(dialogContext),
              child: const Text('CANCELAR'),
            ),
            FilledButton(
              onPressed: isSaving
                  ? null
                  : () async {
                      setDialogState(() {
                        isSaving = true;
                        errorMessage = null;
                      });
                      try {
                        await _businessOperationsService
                            .saveColdBrewTastingNote(
                          customerUid: user.uid,
                          flavorProfile: selectedProfile,
                          rating: selectedRating,
                        );
                        if (!dialogContext.mounted) return;
                        Navigator.pop(dialogContext);
                        _showSnackBar(
                          'Tu perfil favorito quedó guardado en Mi Bitácora.',
                        );
                      } on FirebaseException catch (error, stackTrace) {
                        debugPrint(
                          'No se pudo guardar la bitácora Cold Brew (${error.code}).',
                        );
                        debugPrintStack(stackTrace: stackTrace);
                        setDialogState(() {
                          isSaving = false;
                          errorMessage =
                              'No se pudo guardar tu cata (${error.code}).';
                        });
                      }
                    },
              child: isSaving
                  ? const SizedBox.square(
                      dimension: 16,
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : const Text('GUARDAR CATA'),
            ),
          ],
        ),
      ),
    );
  }

  Widget _coldBrewTastingJournal({required bool hasValidatedConsumption}) {
    final customerUid = _firebaseUser?.uid;
    if (customerUid == null) {
      return const Card(
        color: card,
        child: ListTile(
          leading: Icon(Icons.menu_book_outlined, color: gold),
          title: Text('MI BITÁCORA', style: TextStyle(color: cream)),
          subtitle: Text(
            'Inicia sesión para guardar y recordar tu perfil Cold Brew favorito.',
            style: TextStyle(color: muted),
          ),
        ),
      );
    }
    if (!hasValidatedConsumption) {
      return const Card(
        color: card,
        child: ListTile(
          leading: Icon(Icons.menu_book_outlined, color: muted),
          title: Text('MI BITÁCORA', style: TextStyle(color: cream)),
          subtitle: Text(
            'Registra un consumo Cold Brew con el QR del TPV para activar tu bitácora de cata.',
            style: TextStyle(color: muted),
          ),
        ),
      );
    }

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('coldBrewTastingNotes')
          .where('customerUid', isEqualTo: customerUid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _managementStatusCard(
            'No se pudo cargar Mi Bitácora.',
            error: true,
          );
        }
        if (!snapshot.hasData) {
          return const LinearProgressIndicator(color: gold);
        }
        final notes = snapshot.data!.docs.toList()
          ..sort((left, right) {
            final leftTime = left.data()['createdAt'];
            final rightTime = right.data()['createdAt'];
            final leftDate =
                leftTime is Timestamp ? leftTime.toDate() : DateTime(0);
            final rightDate =
                rightTime is Timestamp ? rightTime.toDate() : DateTime(0);
            return rightDate.compareTo(leftDate);
          });
        final profileRatings = <String, List<int>>{};
        for (final note in notes) {
          final data = note.data();
          final profileKey = data['flavorProfile'] as String?;
          final rating = (data['rating'] as num?)?.toInt();
          if (profileKey == null || rating == null) continue;
          profileRatings.putIfAbsent(profileKey, () => []).add(rating);
        }
        final favoriteEntry =
            profileRatings.entries.fold<MapEntry<String, List<int>>?>(
          null,
          (favorite, entry) {
            if (favorite == null) return entry;
            final candidateAverage =
                entry.value.reduce((a, b) => a + b) / entry.value.length;
            final favoriteAverage =
                favorite.value.reduce((a, b) => a + b) / favorite.value.length;
            return candidateAverage > favoriteAverage ? entry : favorite;
          },
        );
        final profileKey = favoriteEntry?.key ?? 'chocolate';
        final profile =
            _coldBrewFlavorProfiles[profileKey] ?? 'Perfil sin definir';
        final rating = favoriteEntry == null
            ? 0
            : (favoriteEntry.value.reduce((a, b) => a + b) /
                    favoriteEntry.value.length)
                .round();
        return Card(
          color: card,
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Row(
                  children: [
                    Icon(Icons.menu_book_outlined, color: gold),
                    SizedBox(width: 8),
                    Text(
                      'MI BITÁCORA',
                      style: TextStyle(
                        color: cream,
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Text(
                  notes.isEmpty
                      ? 'Registra tu primera cata para recordar qué perfil te gusta.'
                      : 'Tu favorito: $profile · ${favoriteEntry!.value.length} cata(s)',
                  style: const TextStyle(color: cream),
                ),
                if (notes.isNotEmpty) ...[
                  const SizedBox(height: 4),
                  Row(
                    children: List.generate(
                      5,
                      (index) => Icon(
                        index < rating ? Icons.star : Icons.star_border,
                        color: gold,
                        size: 18,
                      ),
                    ),
                  ),
                ],
                if (notes.isNotEmpty) ...[
                  const SizedBox(height: 10),
                  const Text(
                    'Últimas catas',
                    style: TextStyle(color: muted, fontSize: 11),
                  ),
                  ...notes.take(3).map((note) {
                    final data = note.data();
                    final key = data['flavorProfile'] as String? ?? '';
                    final tasteRating = (data['rating'] as num?)?.toInt() ?? 0;
                    return Padding(
                      padding: const EdgeInsets.only(top: 4),
                      child: Text(
                        '${_coldBrewFlavorProfiles[key] ?? 'Perfil'} · $tasteRating/5',
                        style: const TextStyle(color: muted, fontSize: 12),
                      ),
                    );
                  }),
                ],
                const SizedBox(height: 8),
                Align(
                  alignment: Alignment.centerRight,
                  child: TextButton.icon(
                    onPressed: () => _showColdBrewTastingDialog(
                      initialProfile: profileKey,
                      initialRating: rating == 0 ? 5 : rating,
                    ),
                    icon: const Icon(Icons.rate_review_outlined),
                    label: const Text('REGISTRAR NUEVA CATA'),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _coldBrewAlbum() {
    final customerUid = _firebaseUser?.uid;
    if (customerUid == null) {
      final demoStamps = _coldBrewAlbumCounts[userName] ??
          _coldBrewAlbumCounts[userHandle] ??
          0;
      final demoFigures = coldBrewFigures
          .take(demoStamps.clamp(0, coldBrewFigures.length).toInt())
          .map((figure) => figure.id)
          .toSet();
      return _coldBrewAlbumContent(
        demoStamps,
        collectedFigureIds: demoFigures,
      );
    }

    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('coldBrewAlbums')
          .doc(customerUid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _coldBrewAlbumContent(
            0,
            errorMessage:
                'No se pudo cargar tu álbum. Inténtalo de nuevo más tarde.',
          );
        }
        if (!snapshot.hasData) {
          return const Center(
            child: CircularProgressIndicator(color: gold),
          );
        }
        final album = snapshot.data?.data();
        final value = album?['stamps'];
        final stamps = value is num ? value.toInt() : 0;
        final rawFigures = album?['figures'];
        final validFigureIds =
            coldBrewFigures.map((figure) => figure.id).toSet();
        final collectedFigures = rawFigures is List
            ? rawFigures
                .whereType<String>()
                .where(validFigureIds.contains)
                .toSet()
            : <String>{};
        return _coldBrewAlbumContent(
          stamps,
          collectedFigureIds: collectedFigures,
        );
      },
    );
  }

