  Widget _bottomBar() {
    final destinations = ['home', 'pack', 'experience', 'shop', 'profile'];
    var selectedIndex = 0;
    if (page == 'pack' ||
        page.startsWith('match') ||
        page == 'mischiefWall' ||
        page == 'lostPet') {
      selectedIndex = 1;
    } else if (page == 'experience' ||
        page == 'passport' ||
        page == 'legacy' ||
        page == 'events' ||
        page == 'challenges' ||
        page == 'rewards') {
      selectedIndex = 2;
