  Widget _menuProductImage(CafeMenuItem item, {double? height}) {
    final asset = item.imageAsset;
    final placeholder = Container(
      width: double.infinity,
      height: height,
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Color(0xFF403127), Color(0xFF211A16)],
        ),
      ),
      child: Stack(
        alignment: Alignment.center,
        children: [
          Positioned(
            right: 12,
            top: 10,
            child: WolvesIcon(
              icon: BrandIcons.garra,
              color: cream.withValues(alpha: 0.08),
              size: height == null ? 42 : height * 0.45,
            ),
          ),
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              WolvesIcon(
                icon: item.icon,
                color: cream,
                size: height == null ? 42 : 58,
              ),
              const SizedBox(height: 8),
              const Text(
                'FOTO PRÓXIMAMENTE',
                style: TextStyle(
                  color: cream2,
                  fontSize: 9,
                  letterSpacing: 1.1,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ],
      ),
    );

    Widget imagePlaceholder() {
      if (asset == null) return placeholder;
      return Image.asset(
        asset,
        width: double.infinity,
        height: height,
        fit: BoxFit.cover,
        errorBuilder: (context, error, stackTrace) => placeholder,
      );
    }

    Widget storedImage() {
      final future = _cafeMenuImageCache.putIfAbsent(
        item.id,
        () async {
          final snapshot = await FirebaseFirestore.instance
              .collection('cafeMenuImages')
              .doc(item.id)
              .get();
          if (!snapshot.exists) {
            throw StateError('No existe la imagen guardada para ${item.name}.');
          }
          final encoded = snapshot.data()?['imageBase64'];
          if (encoded is! String) {
            throw StateError(
                'La imagen guardada para ${item.name} está vacía.');
          }
          try {
            return base64Decode(encoded);
          } on FormatException catch (error, stackTrace) {
            debugPrint(
                'La foto de ${item.name} tiene formato inválido: $error');
            debugPrintStack(stackTrace: stackTrace);
            rethrow;
          }
        },
      );
      return FutureBuilder<Uint8List?>(
        future: future,
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            debugPrint('No se pudo cargar la foto de ${item.name}: '
                '${snapshot.error}');
            return imagePlaceholder();
          }
          final bytes = snapshot.data;
          if (bytes == null) return imagePlaceholder();
          return Image.memory(
            bytes,
            key: ValueKey('menu-firestore-image-${item.id}'),
            width: double.infinity,
            height: height,
            fit: BoxFit.cover,
            errorBuilder: (context, error, stackTrace) => imagePlaceholder(),
          );
        },
      );
    }

    return Container(
      width: double.infinity,
      height: height,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: card2,
        borderRadius: BorderRadius.circular(10),
      ),
      child: item.imageBytes != null
          ? Image.memory(
              item.imageBytes!,
              key: ValueKey('menu-local-image-${item.id}'),
              width: double.infinity,
              height: height,
              fit: BoxFit.cover,
            )
          : item.hasImage
              ? storedImage()
              : item.imageUrl != null && item.imageUrl!.isNotEmpty
                  ? Image.network(
                      item.imageUrl!,
                      key: ValueKey('menu-network-image-${item.id}'),
                      width: double.infinity,
                      height: height,
                      fit: BoxFit.cover,
                      errorBuilder: (context, error, stackTrace) =>
                          asset == null
                              ? placeholder
                              : Image.asset(
                                  asset,
                                  width: double.infinity,
                                  height: height,
                                  fit: BoxFit.cover,
                                  errorBuilder: (context, error, stackTrace) =>
                                      placeholder,
                                ),
                    )
                  : imagePlaceholder(),
    );
  }

