  Widget _challengeRow({
    required String id,
    required String title,
    required String reward,
    required int points,
  }) {
    final user = _firebaseUser;
    if (user == null) {
      return ListTile(
        contentPadding: EdgeInsets.zero,
        leading: const Icon(Icons.flag_outlined, color: gold),
        title: Text(title, style: const TextStyle(color: white, fontSize: 13)),
        trailing: Text(
          reward,
          style: const TextStyle(color: cream, fontWeight: FontWeight.bold),
        ),
      );
    }
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .collection('challengeProgress')
          .doc(id)
          .snapshots(),
      builder: (context, snapshot) {
        final completed = snapshot.data?.data()?['status'] == 'self_reported';
        return ListTile(
          key: ValueKey('challenge-$id'),
          onTap: completed || snapshot.hasError
              ? null
              : () => unawaited(
                    _recordChallengeCompletion(
                      id: id,
                      title: title,
                      points: points,
                    ),
                  ),
          contentPadding: EdgeInsets.zero,
          leading: Icon(
            completed ? Icons.check_circle_outline : Icons.flag_outlined,
            color: completed ? green : gold,
          ),
          title:
              Text(title, style: const TextStyle(color: white, fontSize: 13)),
          subtitle: snapshot.hasError
              ? Text(
                  'No se pudo cargar el progreso (${snapshot.error}).',
                  style:
                      const TextStyle(color: Color(0xFFFF8A80), fontSize: 10),
                )
              : completed
                  ? const Text(
                      'Progreso marcado por ti',
                      style: TextStyle(color: green, fontSize: 10),
                    )
                  : null,
          trailing: Text(
            completed ? 'COMPLETADO' : reward,
            style: TextStyle(
              color: completed ? green : cream,
              fontSize: completed ? 9 : 12,
              fontWeight: FontWeight.bold,
            ),
          ),
        );
      },
    );
  }

  Future<void> _recordChallengeCompletion({
    required String id,
    required String title,
    required int points,
  }) async {
    final user = _firebaseUser;
    if (user == null) {
      _showSnackBar('Inicia sesión para guardar el progreso de este reto.');
      return;
    }
    final progressRef = FirebaseFirestore.instance
        .collection('users')
        .doc(user.uid)
        .collection('challengeProgress')
        .doc(id);
    try {
      final recorded = await FirebaseFirestore.instance
          .runTransaction<bool>((transaction) async {
        final existing = await transaction.get(progressRef);
        if (existing.exists) return false;
        final now = FieldValue.serverTimestamp();
        transaction.set(progressRef, {
          'challengeId': id,
          'title': title,
          'status': 'self_reported',
          'completedAt': now,
          'updatedAt': now,
        });
        return true;
      });
      if (!mounted) return;
      if (!recorded) {
        _showSnackBar('Este reto ya figura como completado en tu bitácora.');
        return;
      }
      setState(() => xp += points);
      _showSnackBar(
        'Progreso guardado en tu bitácora. La finalización es autodeclarada.',
      );
    } on FirebaseException catch (error, stackTrace) {
      debugPrint(
        'No se pudo guardar el progreso del reto (${error.code}).',
      );
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar(
          'No se pudo guardar el reto (${error.code}). Revisa las reglas '
          'de Firestore desplegadas.',
        );
      }
    } catch (error, stackTrace) {
      debugPrint('Error guardando el progreso del reto: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (mounted) {
        _showSnackBar('No se pudo guardar el progreso del reto.');
      }
    }
  }

