  Future<void> _showShopInventoryEditor(
    ShopProduct product, {
    ShopVariant? variant,
  }) async {
    final stockController = TextEditingController(
      text: (variant?.stock ?? product.stock).toString(),
    );
    var selectedStatus = variant?.status ?? product.effectiveStatus;
    String? validationMessage;
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) => StatefulBuilder(
          builder: (dialogContext, setDialogState) => AlertDialog(
            backgroundColor: card,
            title: Text(
              variant == null
                  ? product.name
                  : '${product.name} · Talle ${variant.size}',
              style: const TextStyle(color: white, fontSize: 17),
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  key: ValueKey(
                    'inventory-quantity-${product.id}-${variant?.size ?? 'all'}',
                  ),
                  controller: stockController,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Unidades en inventario',
                    prefixIcon: Icon(Icons.inventory_2_outlined),
                  ),
                ),
                const SizedBox(height: 14),
                DropdownButtonFormField<ShopItemStatus>(
                  value: selectedStatus,
                  dropdownColor: card2,
                  decoration: const InputDecoration(labelText: 'Estado'),
                  items: ShopItemStatus.values
                      .map(
                        (status) => DropdownMenuItem(
                          value: status,
                          child: Text(status.label),
                        ),
                      )
                      .toList(),
                  onChanged: (status) {
                    if (status != null) {
                      setDialogState(() => selectedStatus = status);
                    }
                  },
                ),
                if (validationMessage != null) ...[
                  const SizedBox(height: 10),
                  Text(
                    validationMessage!,
                    style: const TextStyle(color: Color(0xFFE6A296)),
                  ),
                ],
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext),
                child: const Text('CANCELAR'),
              ),
              FilledButton(
                onPressed: () {
                  final stock = int.tryParse(stockController.text.trim());
                  if (stock == null || stock < 0) {
                    setDialogState(
                      () => validationMessage =
                          'Ingresa una cantidad entera igual o mayor a cero.',
                    );
                    return;
                  }
                  final currentStock = variant?.stock ?? product.stock;
                  final statusToSave = stock == 0
                      ? ShopItemStatus.soldOut
                      : selectedStatus == ShopItemStatus.soldOut &&
                              currentStock == 0
                          ? ShopItemStatus.available
                          : selectedStatus;
                  setState(() {
                    if (variant == null) {
                      product.stock = stock;
                      product.status = statusToSave;
                      if (product.id == 'plush-alfa') {
                        _plushCollectionOutOfStock = product.stock == 0;
                      }
                    } else {
                      variant.stock = stock;
                      variant.status = statusToSave;
                    }
                  });
                  Navigator.pop(dialogContext);
                },
                child: const Text('GUARDAR INVENTARIO'),
              ),
            ],
          ),
        ),
      );
    } finally {
      stockController.dispose();
    }
  }

  void _addShopProductToCart(ShopProduct product, {String? size}) {
    if (product.price <= 0) {
      _showSnackBar(
          'El precio de ${product.name} está pendiente de configurar.');
      return;
    }
    if (product.category == 'Coleccionables' && !_showPlushes) {
      _showSnackBar('La sección de coleccionables no está disponible.');
      return;
    }
    final variant = size == null ? null : product.variants[size];
    final status = variant?.status ?? product.effectiveStatus;
    final stock = variant?.stock ?? product.stock;
    if (status != ShopItemStatus.available || stock <= 0) {
      _showSnackBar(
        status == ShopItemStatus.comingSoon
            ? 'Este artículo estará disponible próximamente.'
            : 'Este artículo o talle está agotado.',
      );
      return;
    }
    final cartKey = '${product.id}:${size ?? 'one-size'}';
    final existing = cart.indexWhere(
      (item) => item['shopCartKey'] == cartKey,
    );
    final quantityInCart = existing == -1 ? 0 : cart[existing]['qty'] as int;
    if (quantityInCart >= stock) {
      _showSnackBar('No hay más unidades disponibles de este talle.');
      return;
    }
    setState(() {
      if (existing == -1) {
        cart.add({
          'name': product.name,
          'price': product.price,
          'qty': 1,
          'shopProductId': product.id,
          'shopCartKey': cartKey,
          if (size != null) 'size': size,
        });
      } else {
        cart[existing]['qty'] = quantityInCart + 1;
      }
    });
    _showSnackBar(
      '${product.name}${size == null ? '' : ' · Talle $size'} agregado al carrito.',
    );
  }

