  String? _firstAvailableSize(ShopProduct product) {
    for (final variant in product.variants.values) {
      if (variant.status == ShopItemStatus.available) return variant.size;
    }
    for (final size in product.variants.keys) {
      return size;
    }
    return null;
  }

  Widget _shopStatusPill(ShopItemStatus status, {bool compact = false}) {
    final color = switch (status) {
      ShopItemStatus.available => green,
      ShopItemStatus.soldOut => const Color(0xFFE06A5F),
      ShopItemStatus.comingSoon => gold,
    };
    return Container(
      padding: EdgeInsets.symmetric(
        horizontal: compact ? 7 : 10,
        vertical: compact ? 4 : 6,
      ),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(30),
        border: Border.all(color: color.withValues(alpha: 0.55)),
      ),
      child: Text(
        status.label.toUpperCase(),
        style: TextStyle(
          color: color,
          fontSize: compact ? 7 : 9,
          letterSpacing: 0.6,
          fontWeight: FontWeight.w600,
        ),
      ),
    );
