  int get _cartQuantity => cart.fold<int>(
        0,
        (quantity, item) => quantity + (item['qty'] as int),
      );

  String? get _cartBaristaName {
    for (final item in cart) {
      final barista = item['barista'];
      if (barista is String) return barista;
    }
    return null;
  }

  String _formatPrice(double price) {
    final formatted = price == price.roundToDouble()
        ? price.toStringAsFixed(0)
        : price.toStringAsFixed(2);
    return 'Bs $formatted';
  }

  String _formatCertificateDate(DateTime date) {
    final day = date.day.toString().padLeft(2, '0');
    final month = date.month.toString().padLeft(2, '0');
    return '$day/$month/${date.year}';
  }

  void _addToCart(CafeMenuItem item) {
    if (!item.isAvailable ||
        !item.isVisible ||
        _unavailableItems.contains(item.name)) {
      _showBaristaMessage('${item.name} está agotado por el momento.');
      return;
    }
    final price = item.price;
    if (price <= 0) {
      _showBaristaMessage(
          'Gerencia debe configurar el precio de ${item.name}.');
      return;
    }

    final existingIndex = cart.indexWhere(
      (cartItem) => cartItem['name'] == item.name,
    );
    final existingQuantity =
        existingIndex < 0 ? 0 : cart[existingIndex]['qty'] as int;
    if (item.stockTracked && existingQuantity + productQuantity > item.stock) {
      _showBaristaMessage(
        item.stock <= existingQuantity
            ? '${item.name} está agotado.'
            : 'Solo quedan ${item.stock - existingQuantity} unidades de ${item.name}.',
      );
      return;
    }
    setState(() {
      if (existingIndex == -1) {
        cart.add({
          'name': item.name,
          'price': price,
          'qty': productQuantity,
          'category': item.category,
          'catalogId': item.id,
          'catalogCollection': 'cafeCatalog',
          'stockTracked': item.stockTracked,
          if (_activePosBarista != null) 'barista': _activePosBarista,
        });
      } else {
        cart[existingIndex]['qty'] = existingQuantity + productQuantity;
        cart[existingIndex]['category'] = item.category;
        cart[existingIndex]['catalogId'] = item.id;
        cart[existingIndex]['catalogCollection'] = 'cafeCatalog';
        cart[existingIndex]['stockTracked'] = item.stockTracked;
        if (_activePosBarista != null) {
          cart[existingIndex]['barista'] = _activePosBarista;
        }
      }
    });
    _showSnackBar('${item.name} agregado al carrito');
  }

  void _showSnackBar(String message) {
    _scaffoldMessengerKey.currentState!.showSnackBar(
      SnackBar(content: Text(message)),
    );
