  Future<void> _openWhatsApp(String message) async {
    final uri = Uri.https(
      'wa.me',
      '/message/B3UBUOB4ZOY5L1',
      {'text': message},
    );
    final opened = await launchUrl(uri);
    if (!opened && mounted) {
      _showSnackBar('No se pudo abrir WhatsApp.');
    }
  }

  Future<void> _openSocialLink(String url) async {
    final uri = Uri.parse(url);
    final opened = await launchUrl(
      uri,
      mode: LaunchMode.externalApplication,
    );
    if (!opened) {
      _showSnackBar('No se pudo abrir el enlace de Coffee Wolves.');
    }
  }

  Future<void> _sendCartToWhatsApp(double total) async {
    final lines = cart.map((item) {
      final quantity = item['qty'] as int;
      final price = (item['price'] as num).toDouble();
      return '• $quantity × ${item['name']} (${_formatPrice(price * quantity)})';
    }).join('\n');
    await _openWhatsApp(
      'Hola Coffee Wolves, quisiera hacer este pedido:\n$lines\nTotal: ${_formatPrice(total)}',
    );
  }

