  Widget _buildBitacora() {
    final ownerUid = _firebaseUser?.uid;
    if (ownerUid == null) {
      return const Text(
        'Inicia sesión para consultar tu bitácora de progreso.',
        style: TextStyle(color: muted),
      );
    }

    return Container(
      key: const ValueKey('customer-unified-journal'),
