  Widget _journalPassport(String ownerUid) {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('passportProgress')
          .doc(ownerUid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _journalSection(
            icon: Icons.coffee_outlined,
            title: 'COFFEE PASSPORT',
            child: _journalReadError('Passport', snapshot.error!),
            openLabel: 'ABRIR COFFEE PASSPORT',
            onOpen: () => go('passport'),
          );
        }
        if (!snapshot.hasData) {
          return _journalSection(
            icon: Icons.coffee_outlined,
            title: 'COFFEE PASSPORT',
            child: const LinearProgressIndicator(color: gold),
            openLabel: 'ABRIR COFFEE PASSPORT',
            onOpen: () => go('passport'),
          );
        }
        final data = snapshot.data?.data();
        final completed =
            (data?['completedMethods'] as List<dynamic>? ?? const <dynamic>[])
                .whereType<String>()
                .toSet()
                .intersection(methods.map((method) => method.name).toSet());
        final count = completed.length;
        return _journalSection(
          icon: Icons.coffee_outlined,
          title: 'COFFEE PASSPORT',
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                '$count de 9 métodos validados'
                '${data?['rewardClaimed'] == true ? ' · Taza legendaria canjeada' : ''}',
                style: const TextStyle(color: cream, fontSize: 12),
              ),
              const SizedBox(height: 7),
              LinearProgressIndicator(
                value: count / 9,
                minHeight: 5,
                backgroundColor: const Color(0xFF322D29),
                valueColor: const AlwaysStoppedAnimation(gold),
              ),
              if (completed.isNotEmpty) ...[
                const SizedBox(height: 6),
                Text(
                  completed.join(' · '),
                  style: const TextStyle(color: muted, fontSize: 10),
                ),
              ],
            ],
          ),
          openLabel: 'ABRIR COFFEE PASSPORT',
          onOpen: () => go('passport'),
        );
      },
    );
  }

  Widget _journalColdBrew(String ownerUid) {
    return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('coldBrewAlbums')
          .doc(ownerUid)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _journalSection(
            icon: Icons.local_cafe_outlined,
            title: 'ÁLBUM COLD BREW',
            child: _journalReadError('Cold Brew', snapshot.error!),
            openLabel: 'ABRIR ÁLBUM COLD BREW',
            onOpen: () => go('coldBrewAlbum'),
          );
        }
        if (!snapshot.hasData) {
          return _journalSection(
            icon: Icons.local_cafe_outlined,
            title: 'ÁLBUM COLD BREW',
            child: const LinearProgressIndicator(color: gold),
            openLabel: 'ABRIR ÁLBUM COLD BREW',
            onOpen: () => go('coldBrewAlbum'),
          );
        }
        final value = snapshot.data?.data()?['stamps'];
        final stamps = value is num ? value.toInt() : 0;
        final milestoneProgress = stamps % 16;
        final milestoneLabel = stamps > 0 && milestoneProgress == 0
            ? '16/16 · hito alcanzado'
            : '$milestoneProgress/16 para el siguiente hito';
        return _journalSection(
          icon: Icons.local_cafe_outlined,
          title: 'ÁLBUM COLD BREW',
          child: Row(
            children: [
              Expanded(
                child: Text(
                  '$stamps consumos registrados · $milestoneLabel',
                  style: const TextStyle(color: cream, fontSize: 12),
                ),
              ),
              Icon(
                stamps >= 16
                    ? Icons.verified_outlined
                    : Icons.local_fire_department_outlined,
                color: gold,
                size: 18,
              ),
            ],
          ),
          openLabel: 'ABRIR ÁLBUM COLD BREW',
          onOpen: () => go('coldBrewAlbum'),
        );
      },
    );
  }

  Widget _journalRewards(String ownerUid) {
    return _journalSection(
      icon: Icons.workspace_premium_outlined,
      title: 'HITOS Y RECOMPENSAS',
      child: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: FirebaseFirestore.instance
            .collection('passportProgress')
            .doc(ownerUid)
            .snapshots(),
        builder: (context, passportSnapshot) =>
            StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
          stream: FirebaseFirestore.instance
              .collection('coldBrewAlbums')
              .doc(ownerUid)
              .snapshots(),
          builder: (context, coldBrewSnapshot) {
            if (passportSnapshot.hasError || coldBrewSnapshot.hasError) {
              return _journalReadError(
                'Recompensas',
                passportSnapshot.error ?? coldBrewSnapshot.error!,
              );
            }
            if (!passportSnapshot.hasData || !coldBrewSnapshot.hasData) {
              return const LinearProgressIndicator(color: gold);
            }
            final passportData = passportSnapshot.data?.data();
            final completedMethods =
                (passportData?['completedMethods'] as List<dynamic>? ??
                        const <dynamic>[])
                    .whereType<String>()
                    .toSet()
                    .intersection(
                      methods.map((method) => method.name).toSet(),
                    );
            final completedMethodCount = completedMethods.length;
            final passportRewardClaimed =
                passportData?['rewardClaimed'] == true;
            final rawStamps = coldBrewSnapshot.data?.data()?['stamps'];
            final stamps = rawStamps is num ? rawStamps.toInt() : 0;
            final nextMilestoneProgress = stamps % 16;
            final nextMilestone = stamps > 0 && nextMilestoneProgress == 0
                ? 16
                : nextMilestoneProgress;
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  passportRewardClaimed
                      ? 'Coffee Passport · Taza legendaria canjeada'
                      : completedMethodCount == 9
                          ? 'Coffee Passport · Taza legendaria lista para validar en tienda'
                          : 'Coffee Passport · $completedMethodCount/9 métodos para desbloquear la taza legendaria',
                  style: const TextStyle(color: cream, fontSize: 11),
                ),
                const SizedBox(height: 5),
                Text(
                  'Cold Brew · $stamps consumos registrados · '
                  '${stamps > 0 && nextMilestoneProgress == 0 ? '16/16 · hito alcanzado' : '$nextMilestone/16 hacia el siguiente hito'}',
                  style: const TextStyle(color: cream, fontSize: 11),
                ),
                const SizedBox(height: 5),
                const Text(
                  'El canje se confirma en Coffee Wolves; los retos autodeclarados no acreditan recompensas.',
                  style: TextStyle(color: muted, fontSize: 9, height: 1.35),
                ),
              ],
            );
          },
        ),
      ),
      openLabel: 'VER WOLVES REWARDS',
      onOpen: () => go('rewards'),
    );
  }

  Widget _journalChallenges(String ownerUid) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection('users')
          .doc(ownerUid)
          .collection('challengeProgress')
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _journalSection(
            icon: Icons.flag_outlined,
            title: 'RETOS',
            child: _journalReadError('Retos', snapshot.error!),
            openLabel: 'VER TODOS LOS RETOS',
            onOpen: () => go('challenges'),
          );
        }
        if (!snapshot.hasData) {
          return _journalSection(
            icon: Icons.flag_outlined,
            title: 'RETOS',
            child: const LinearProgressIndicator(color: gold),
            openLabel: 'VER TODOS LOS RETOS',
            onOpen: () => go('challenges'),
          );
        }
        final records = snapshot.data!.docs
            .where((document) => document.data()['status'] == 'self_reported')
            .toList()
          ..sort((first, second) {
            final firstAt = first.data()['completedAt'];
            final secondAt = second.data()['completedAt'];
            final firstDate =
                firstAt is Timestamp ? firstAt.toDate() : DateTime(1970);
            final secondDate =
                secondAt is Timestamp ? secondAt.toDate() : DateTime(1970);
            return secondDate.compareTo(firstDate);
          });
        return _journalSection(
          icon: Icons.flag_outlined,
          title: 'RETOS',
          child: records.isEmpty
              ? const Text(
                  'Aún no has registrado retos.',
                  style: TextStyle(color: muted, fontSize: 11),
                )
              : Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      '${records.length} progreso${records.length == 1 ? '' : 's'} registrado${records.length == 1 ? '' : 's'} por ti',
                      style: const TextStyle(color: cream, fontSize: 12),
                    ),
                    const SizedBox(height: 5),
                    for (final record in records.take(3))
                      Padding(
                        padding: const EdgeInsets.only(top: 3),
                        child: Text(
                          '• ${record.data()['title'] ?? 'Reto'}',
                          style: const TextStyle(color: muted, fontSize: 10),
                        ),
                      ),
                    const SizedBox(height: 4),
                    const Text(
                      'Los retos se guardan como autodeclarados; no son validación de premios.',
                      style: TextStyle(color: muted, fontSize: 9),
                    ),
                  ],
                ),
          openLabel: 'VER TODOS LOS RETOS',
          onOpen: () => go('challenges'),
        );
      },
    );
  }

  Widget _journalCollectibles(String ownerUid) {
    return StreamBuilder<Bitacora>(
      stream: _watchBitacora(ownerUid),
      builder: (context, snapshot) {
        if (snapshot.hasError) {
          return _journalSection(
            icon: Icons.toys_outlined,
            title: 'COLECCIONABLES',
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _journalReadError('Coleccionables', snapshot.error!),
                const SizedBox(height: 4),
                const Text(
                  'Si aparece permission-denied, despliega las reglas actuales '
                  'de Firestore para habilitar la lectura de piezas propias.',
                  style: TextStyle(color: muted, fontSize: 9),
                ),
                TextButton.icon(
                  onPressed: () => _retryBitacora(ownerUid),
                  icon: const Icon(Icons.refresh, size: 15),
                  label: const Text('VOLVER A INTENTAR'),
                  style: TextButton.styleFrom(foregroundColor: gold),
                ),
              ],
            ),
            openLabel: 'VER COLECCIONABLES',
            onOpen: () => go('collectibles'),
          );
        }
        if (!snapshot.hasData) {
          return _journalSection(
            icon: Icons.toys_outlined,
            title: 'COLECCIONABLES',
            child: const LinearProgressIndicator(color: gold),
            openLabel: 'VER COLECCIONABLES',
            onOpen: () => go('collectibles'),
          );
        }

        final ownedByModel = <String, List<Coleccionable>>{};
        for (final collectible in snapshot.data!.coleccionables) {
          ownedByModel
              .putIfAbsent(collectible.modelCode, () => [])
              .add(collectible);
        }
        final collectibles = snapshot.data!.coleccionables;
        final entries = wolvesOriginalCharacters.entries;
        return _journalSection(
          icon: Icons.toys_outlined,
          title: 'COLECCIONABLES',
          child: Column(
            children: [
              Text(
                '${collectibles.length} pieza${collectibles.length == 1 ? '' : 's'} registradas oficialmente a tu nombre',
                style: const TextStyle(color: cream, fontSize: 12),
              ),
              const SizedBox(height: 5),
              ...entries.map((entry) {
                final owned = collectibles
                    .where((item) => item.modelCode == entry.key)
                    .toList();
                if (owned.isEmpty) return const SizedBox.shrink();
                final serials = owned
                    .map((item) => item.serial)
                    .where((serial) => serial.isNotEmpty)
                    .join(', ');
                final firstOwned = owned.isEmpty ? null : owned.first;
                return ListTile(
                  key: ValueKey('bitacora-${entry.key}'),
                  contentPadding: EdgeInsets.zero,
                  leading: Icon(
                    Icons.lock_open_outlined,
                    color: green,
                  ),
                  title: Text(
                    entry.value,
                    style: const TextStyle(color: cream, fontSize: 13),
                  ),
                  subtitle: Text(
                    'Original Collection · ${entry.key}'
                    '${serials.isEmpty ? '' : ' · Serie${owned.length == 1 ? '' : 's'}: $serials'}',
                    style: const TextStyle(
                      color: muted,
                      fontSize: 10,
                      height: 1.5,
                    ),
                  ),
                  isThreeLine: false,
                  trailing: const Icon(Icons.verified_outlined, color: green),
                  onTap: firstOwned == null
                      ? null
                      : () => _editBitacoraCollectible(firstOwned),
                );
              }),
            ],
          ),
          openLabel: 'VER COLECCIONABLES',
          onOpen: () => go('collectibles'),
        );
      },
    );
  }

